-- ══════════════════════════════════════════════════════════════════════════
-- Migration 102: reminder claim-lease + confirm-after-send (GV-254)
-- Mirror of supabase/migrations/102_reminder_claim_confirm.sql (function
-- bodies byte-identical for the GV-175 equivalence check).
-- ══════════════════════════════════════════════════════════════════════════

alter table public.settlement_requests add column if not exists reminder_claimed_at timestamptz;
alter table public.settlement_periods add column if not exists close_reminder_claimed_at timestamptz;

-- ── claim_due_close_reminders: lease-claim only (event moves to confirm) ────────────
create or replace function public.claim_due_close_reminders(
  batch_limit integer default 200
)
returns table (period_id uuid, ledger_id text, label text, admin_emails text[])
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select sp.id
    from public.settlement_periods sp
    join public.ledgers l on l.id = sp.ledger_id
    where sp.status = 'open'
      and l.close_reminder_enabled = true
      and sp.opened_at <= now() - interval '30 days'
      and (sp.close_reminder_claimed_at is null
           or sp.close_reminder_claimed_at <= now() - interval '15 minutes')
      and (sp.last_close_reminder_at is null
           or sp.last_close_reminder_at <= now() - interval '7 days')
    order by sp.opened_at
    limit greatest(coalesce(batch_limit, 200), 0)
    for update of sp skip locked
  ),
  claimed as (
    update public.settlement_periods sp
    set close_reminder_claimed_at = now(),
        updated_at = now()
    from target t
    where sp.id = t.id
    returning sp.id as period_id, sp.ledger_id as ledger_id, sp.label as label
  )
  select c.period_id,
         c.ledger_id,
         c.label,
         coalesce(
           array_agg(lower(lm.email)) filter (where lm.email is not null),
           array[]::text[]
         ) as admin_emails
  from claimed c
  left join public.ledger_members lm
    on lm.ledger_id = c.ledger_id
   and lm.role = 'admin'
   and lm.is_active = true
   and lm.email is not null
  group by c.period_id, c.ledger_id, c.label;
end;
$$;

revoke all on function public.claim_due_close_reminders(integer) from public;
revoke all on function public.claim_due_close_reminders(integer) from anon;
revoke all on function public.claim_due_close_reminders(integer) from authenticated;
grant execute on function public.claim_due_close_reminders(integer) to service_role;

-- ── claim_due_payment_reminders: lease-claim only (event moves to confirm) ──────────
create or replace function public.claim_due_payment_reminders(
  batch_limit integer default 200
)
returns table (request_id uuid, ledger_id text, debtor_email text, creditor_name text, amount numeric)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select sr.id
    from public.settlement_requests sr
    join public.ledger_members debtor on debtor.id = sr.from_member_id
    where sr.status = 'requested'
      and sr.reminder_count < 3
      and debtor.is_active = true
      and debtor.email is not null
      and (sr.reminder_claimed_at is null
           or sr.reminder_claimed_at <= now() - interval '15 minutes')
      and (
        (sr.reminder_count = 0
          and sr.requested_at is not null
          and sr.requested_at <= now() - interval '3 days')
        or (sr.reminder_count between 1 and 2
          and sr.last_reminder_at is not null
          and sr.last_reminder_at <= now() - interval '7 days')
      )
    order by sr.requested_at
    limit greatest(coalesce(batch_limit, 200), 0)
    for update of sr skip locked
  ),
  claimed as (
    update public.settlement_requests sr
    set reminder_claimed_at = now(),
        updated_at = now()
    from target t
    where sr.id = t.id
    returning sr.id as request_id,
              sr.ledger_id as ledger_id,
              sr.from_member_id as debtor_id,
              sr.to_member_id as creditor_id,
              sr.amount as amount
  )
  select c.request_id,
         c.ledger_id,
         lower(debtor.email) as debtor_email,
         creditor.name as creditor_name,
         c.amount
  from claimed c
  left join public.ledger_members debtor on debtor.id = c.debtor_id
  left join public.ledger_members creditor on creditor.id = c.creditor_id;
end;
$$;

revoke all on function public.claim_due_payment_reminders(integer) from public;
revoke all on function public.claim_due_payment_reminders(integer) from anon;
revoke all on function public.claim_due_payment_reminders(integer) from authenticated;
grant execute on function public.claim_due_payment_reminders(integer) to service_role;

-- ── confirm_close_reminders: advance cadence + log event after a successful send ────
create or replace function public.confirm_close_reminders(period_ids uuid[])
returns integer
language sql
security definer
set search_path = public
as $$
  with confirmed as (
    update public.settlement_periods sp
    set last_close_reminder_at = now(),
        close_reminder_claimed_at = null,
        updated_at = now()
    where sp.id = any(period_ids)
      and sp.close_reminder_claimed_at is not null
    returning sp.id as period_id, sp.ledger_id as ledger_id, sp.label as label
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    )
    select c.ledger_id, 'close_reminder_sent', 'Lukkepåmindelse sendt', '',
           null, null,
           jsonb_build_object(
             'period_id', c.period_id,
             'label', c.label
           )
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_close_reminders(uuid[]) from public;
revoke all on function public.confirm_close_reminders(uuid[]) from anon;
revoke all on function public.confirm_close_reminders(uuid[]) from authenticated;
grant execute on function public.confirm_close_reminders(uuid[]) to service_role;

-- ── confirm_payment_reminders: advance cadence + log event after a successful send ──
create or replace function public.confirm_payment_reminders(request_ids uuid[])
returns integer
language sql
security definer
set search_path = public
as $$
  with confirmed as (
    update public.settlement_requests sr
    set reminder_count = sr.reminder_count + 1,
        last_reminder_at = now(),
        reminder_claimed_at = null,
        updated_at = now()
    where sr.id = any(request_ids)
      and sr.reminder_claimed_at is not null
    returning sr.id as request_id,
              sr.ledger_id as ledger_id,
              sr.from_member_id as debtor_id,
              sr.to_member_id as creditor_id,
              sr.amount as amount,
              sr.reminder_count as reminder_count
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    )
    select c.ledger_id, 'payment_reminder_sent', 'Betalingspåmindelse sendt', '',
           null, null,
           jsonb_build_object(
             'settlement_request_id', c.request_id,
             'from_member_id', c.debtor_id,
             'to_member_id', c.creditor_id,
             'amount', c.amount,
             'reminder_count', c.reminder_count
           )
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_payment_reminders(uuid[]) from public;
revoke all on function public.confirm_payment_reminders(uuid[]) from anon;
revoke all on function public.confirm_payment_reminders(uuid[]) from authenticated;
grant execute on function public.confirm_payment_reminders(uuid[]) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('102_reminder_claim_confirm',
        'Reminder delivery two-phase claim lease (GV-254): claim_due_payment_reminders / claim_due_close_reminders re-declared off 091 to only stamp a *_claimed_at lease (15-min expiry) instead of advancing cadence counters or logging events, so a failed Expo send no longer burns a reminder slot or delays the next close nudge. New service_role-only confirm_payment_reminders(uuid[]) / confirm_close_reminders(uuid[]) advance the counters + insert the payment_reminder_sent / close_reminder_sent ledger_events row, called by the web hooks only after a successful send. At-least-once (rare duplicate on a confirm-call failure) over at-most-once. Return shapes unchanged.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 103 mirror: settlement/join-code/bootstrap/identity hardening (GV-244..GV-247) ──
-- GV-244: upsert_settlement_request_status (re-declared off 090) gains a
--   party-or-admin guard so only a party or a ledger admin may create/transition
--   a settlement request. GV-245: generate_workspace_join_code (off 045) uses a
--   6-char body; the data-only join-code regeneration is intentionally NOT mirrored
--   (the equivalence check compares schema objects, not data). GV-246:
--   is_ledger_bootstrap_open removed — 3 bootstrap policies dropped, 5 policies
--   re-created without the bootstrap disjunct, then the function dropped (bootstrap
--   trigger + column kept). GV-247: enforce_identity_reassignment (off 101) also
--   requires the identity party to be an active member; triggers recreated as
--   before insert or update. Last definition wins on replay.

-- ── GV-244: upsert_settlement_request_status — party-or-admin only ──────────
-- Re-declared off migration 090 (newest prior definition), full body, with only
-- the party-or-admin guard added immediately after the actor-null check.
create or replace function public.upsert_settlement_request_status(
  target_ledger_id text,
  target_open_period_id uuid,
  payer_member_id uuid,
  recipient_member_id uuid,
  amount_value numeric,
  currency_value text,
  next_status text,
  current_pair_keys text[] default array[]::text[]
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  saved_request_id uuid;
  prev_status_value text := null;
  requested_at_value timestamptz := null;
  requested_by_value uuid := null;
  paid_at_value timestamptz := null;
  cancelled_count integer := 0;
  normalized_status text := coalesce(nullif(next_status, ''), 'open');
  event_type_value text;
  event_title_value text;
  period_is_open boolean;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_open_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can save settlement requests' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- GV-244: a settlement request may only be created or transitioned by one of
  -- its two parties or a ledger admin. Without this any signed-in member could
  -- drive a request between two OTHER members (incl. marking it paid) through
  -- this SECURITY DEFINER RPC, bypassing the party-or-admin table RLS.
  if actor_member_id not in (payer_member_id, recipient_member_id)
    and not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only the payer, recipient, or a ledger admin can save this settlement request' using errcode = '42501';
  end if;

  -- Resolve the target period. Normally OPEN (request + pay on the live period).
  -- For a debt carried past a close, mobile acts on the request in its own CLOSED
  -- period (GVM-243): mark paid / remind / reopen are allowed there, but only
  -- against an existing request (guarded below). A missing/foreign period is
  -- rejected outright.
  select (sp.status = 'open' and sp.closed_at is null)
    into period_is_open
  from public.settlement_periods sp
  where sp.id = target_open_period_id
    and sp.ledger_id = target_ledger_id;

  if period_is_open is null then
    raise exception 'Settlement period was not found or does not belong to this ledger' using errcode = '22023';
  end if;

  if payer_member_id is null or recipient_member_id is null then
    raise exception 'Settlement request must include both payer and recipient members' using errcode = '23514';
  end if;

  if payer_member_id = recipient_member_id then
    raise exception 'Settlement request payer and recipient must be different members' using errcode = '23514';
  end if;

  if not public.member_belongs_to_ledger(payer_member_id, target_ledger_id)
    or not public.member_belongs_to_ledger(recipient_member_id, target_ledger_id) then
    raise exception 'Settlement request members must belong to the same ledger' using errcode = '23514';
  end if;

  if amount_value is null or amount_value < 0 then
    raise exception 'Settlement request amount must be zero or greater' using errcode = '23514';
  end if;

  if normalized_status not in ('open', 'requested', 'paid', 'paid_pending', 'cancelled') then
    raise exception 'Invalid settlement request status' using errcode = '23514';
  end if;

  -- A closed period can gain no NEW requests: only an existing (non-cancelled)
  -- request for the pair may transition. This blanket-guards paid / requested /
  -- open on a closed period; the insert branch + stale sweep below stay
  -- open-period-only.
  if not period_is_open then
    if not exists (
      select 1 from public.settlement_requests sr
      where sr.period_id = target_open_period_id
        and sr.from_member_id = payer_member_id
        and sr.to_member_id = recipient_member_id
        and sr.status <> 'cancelled'
    ) then
      raise exception 'No active settlement request for this pair in the closed period' using errcode = '22023';
    end if;
  end if;

  -- Bound the requested amount (GVM-112): no pair settlement can exceed the
  -- period's total fuel spend. Deliberately an upper bound, not equality —
  -- monthly/running request shapes (GVM-76) vary by design, and a false
  -- rejection would block a legitimate payment request. Open-period only: a
  -- closed period's fuel total is frozen and the amount already exists on the row.
  if normalized_status = 'requested' and period_is_open then
    if amount_value is null or amount_value <= 0 then
      raise exception 'Requested amount must be greater than zero' using errcode = '23514';
    end if;
    if amount_value > (
      select coalesce(sum(fp.amount), 0) + 1.0
      from public.fuel_payments fp
      where fp.ledger_id = target_ledger_id
        and fp.period_id = target_open_period_id
        and fp.deleted_at is null
    ) then
      raise exception 'Requested amount is larger than this period''s total fuel spend. Refresh the app and try again.' using errcode = '23514';
    end if;
  end if;

  -- Require an existing, non-cancelled request before claiming or confirming a
  -- payment (GVM-241, extended to paid_pending in GVM-213). Without this the
  -- pair upsert's on-conflict misses for a stale/foreign-period request and
  -- INSERTs a fresh row directly at a settled-ish status, which trips the 003
  -- trigger guard with the cryptic 'Request the payment before marking it paid'.
  -- Raise a clean, mappable error instead.
  if normalized_status in ('paid', 'paid_pending') then
    if not exists (
      select 1 from public.settlement_requests sr
      where sr.period_id = target_open_period_id
        and sr.from_member_id = payer_member_id
        and sr.to_member_id = recipient_member_id
        and sr.status <> 'cancelled'
    ) then
      raise exception 'No active payment request to mark as paid — refresh and try again' using errcode = '23514';
    end if;
  end if;

  if normalized_status = 'requested' then
    requested_at_value := now();
    requested_by_value := recipient_member_id;
  elsif normalized_status = 'paid' then
    paid_at_value := now();
  end if;

  perform pg_advisory_xact_lock(hashtext(target_ledger_id || ':settlement:' || target_open_period_id::text));

  -- Transition the pair's request via an explicit lookup + UPDATE, NOT
  -- INSERT ... ON CONFLICT. The 003 integrity trigger is BEFORE INSERT OR UPDATE,
  -- and a BEFORE INSERT trigger fires on an upsert's proposed row *before* the
  -- ON CONFLICT resolves to DO UPDATE — so an upsert to a settled status trips
  -- the trigger's INSERT guard even when a matching request exists (GVM-241).
  -- An explicit UPDATE fires BEFORE UPDATE, where the guard validates the
  -- transition as legal. Genuinely new rows still INSERT (open period only — a
  -- closed period was guaranteed an existing request above). prev_status drives
  -- the dispute event below (a paid_pending row sent back to 'requested').
  select sr.id, sr.status into saved_request_id, prev_status_value
  from public.settlement_requests sr
  where sr.period_id = target_open_period_id
    and sr.from_member_id = payer_member_id
    and sr.to_member_id = recipient_member_id
    and sr.status <> 'cancelled'
  for update;

  if saved_request_id is not null then
    update public.settlement_requests
       set amount = amount_value,
           currency = coalesce(nullif(currency_value, ''), 'DKK'),
           status = normalized_status,
           requested_at = requested_at_value,
           requested_by_member_id = requested_by_value,
           paid_at = paid_at_value,
           updated_at = now()
     where id = saved_request_id;
  elsif period_is_open then
    insert into public.settlement_requests (
      ledger_id,
      period_id,
      from_member_id,
      to_member_id,
      amount,
      currency,
      status,
      requested_at,
      requested_by_member_id,
      paid_at,
      updated_at
    ) values (
      target_ledger_id,
      target_open_period_id,
      payer_member_id,
      recipient_member_id,
      amount_value,
      coalesce(nullif(currency_value, ''), 'DKK'),
      normalized_status,
      requested_at_value,
      requested_by_value,
      paid_at_value,
      now()
    )
    returning id into saved_request_id;
  else
    raise exception 'No active settlement request for this pair in the closed period' using errcode = '22023';
  end if;

  -- Cancel stale requests whose pair is no longer valid this period. Open-period
  -- only: current_pair_keys is computed from the OPEN period's live settlements,
  -- so running it against a closed period would wrongly cancel that archived
  -- period's requests.
  if period_is_open then
    update public.settlement_requests sr
       set status = 'cancelled',
           updated_at = now(),
           requested_at = null,
           requested_by_member_id = null,
           paid_at = null
     where sr.ledger_id = target_ledger_id
       and sr.period_id = target_open_period_id
       and not ((sr.from_member_id::text || '->' || sr.to_member_id::text) = any(coalesce(current_pair_keys, array[]::text[])))
       and sr.status <> 'cancelled';
    get diagnostics cancelled_count = row_count;
  end if;

  -- Activity feed + realtime nudge (GVM-247): every status change writes a
  -- ledger_events row so the other member's client (subscribed to ledger_events)
  -- refetches immediately, and the change lands in the activity feed. The
  -- two-step confirmation (GVM-213) adds payment_claimed (debtor marked paid,
  -- awaiting confirmation) and payment_disputed (recipient sent a paid_pending
  -- debt back to 'requested'); payment_paid now means confirmed/received.
  event_type_value := case
    when normalized_status = 'requested' and prev_status_value = 'paid_pending' then 'payment_disputed'
    when normalized_status = 'requested' then 'payment_requested'
    when normalized_status = 'paid_pending' then 'payment_claimed'
    when normalized_status = 'paid' then 'payment_paid'
    else 'settlement_' || normalized_status
  end;
  event_title_value := case
    when normalized_status = 'requested' and prev_status_value = 'paid_pending' then 'Betaling afvist'
    when normalized_status = 'requested' then 'Betaling anmodet'
    when normalized_status = 'paid_pending' then 'Afventer bekræftelse'
    when normalized_status = 'paid' then 'Betaling bekræftet'
    when normalized_status = 'cancelled' then 'Betaling annulleret'
    else 'Betaling genåbnet'
  end;

  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id, event_type_value, event_title_value, '',
    actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
    jsonb_build_object(
      'settlement_request_id', saved_request_id,
      'from_member_id', payer_member_id,
      'to_member_id', recipient_member_id,
      'amount', amount_value
    )
  );

  return jsonb_build_object(
    'settlement_request_id', saved_request_id,
    'ledger_id', target_ledger_id,
    'period_id', target_open_period_id,
    'status', normalized_status,
    'cancelled_stale_count', cancelled_count
  );
end;
$$;

revoke execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[]) from public;
grant execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[]) to authenticated;

-- ── GV-245: workspace join code 4 -> 6 char body ────────────────────────────
-- Re-declared off migration 045 (newest prior definition): gen_random_bytes(6)
-- and six substr picks instead of four. Prefix, alphabet, uniqueness loop and
-- tries cap unchanged.
create or replace function public.generate_workspace_join_code()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Crockford-ish base32 without easily-confused chars (no I, O, 0, 1).
  code_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  rand_bytes bytea;
  candidate text;
  tries integer := 0;
begin
  loop
    tries := tries + 1;
    rand_bytes := extensions.gen_random_bytes(6);
    candidate := 'GV-'
      || substr(code_alphabet, 1 + (get_byte(rand_bytes, 0) % 32), 1)
      || substr(code_alphabet, 1 + (get_byte(rand_bytes, 1) % 32), 1)
      || substr(code_alphabet, 1 + (get_byte(rand_bytes, 2) % 32), 1)
      || substr(code_alphabet, 1 + (get_byte(rand_bytes, 3) % 32), 1)
      || substr(code_alphabet, 1 + (get_byte(rand_bytes, 4) % 32), 1)
      || substr(code_alphabet, 1 + (get_byte(rand_bytes, 5) % 32), 1);
    exit when not exists (select 1 from public.ledgers where join_code = candidate);
    if tries >= 20 then
      raise exception 'Could not generate a unique join code; please try again.' using errcode = 'P0001';
    end if;
  end loop;
  return candidate;
end;
$$;

revoke all on function public.generate_workspace_join_code() from public;
revoke all on function public.generate_workspace_join_code() from anon;
revoke all on function public.generate_workspace_join_code() from authenticated;

-- ── GV-246: remove the is_ledger_bootstrap_open trapdoor ────────────────────
-- Drop the three pure-bootstrap policies outright (no legitimate remainder).
drop policy if exists "Bootstrap users can update ledgers" on public.ledgers;
drop policy if exists "Bootstrap users can read members" on public.ledger_members;
drop policy if exists "Bootstrap users can update members" on public.ledger_members;

-- Re-create the five member/admin policies WITHOUT the bootstrap disjunct; the
-- rest of each policy is byte-preserved from migration 005.
drop policy if exists "Ledger members can read JSON ledger" on public.car_share_ledgers;
create policy "Ledger members can read JSON ledger" on public.car_share_ledgers for select to authenticated using (public.is_ledger_member(id));
drop policy if exists "Ledger admins can insert JSON ledger" on public.car_share_ledgers;
create policy "Ledger admins can insert JSON ledger" on public.car_share_ledgers for insert to authenticated with check (public.is_ledger_admin(id));
drop policy if exists "Ledger admins can update JSON ledger" on public.car_share_ledgers;
create policy "Ledger admins can update JSON ledger" on public.car_share_ledgers for update to authenticated using (public.is_ledger_admin(id)) with check (public.is_ledger_admin(id));
drop policy if exists "Ledger members can read ledgers" on public.ledgers;
create policy "Ledger members can read ledgers" on public.ledgers for select to authenticated using (public.is_ledger_member(id));
drop policy if exists "Ledger members can read members" on public.ledger_members;
create policy "Ledger members can read members" on public.ledger_members for select to authenticated using (public.is_ledger_member(ledger_id));

-- Prod drift discovered at first apply (2026-07-10): the live database carries
-- legacy-named copies of the car_share_ledgers write policies ("Ledger MEMBERS
-- can insert/update JSON ledger") that predate the 005 file's "admins" naming
-- and still reference the trapdoor, so the function drop below was blocked
-- (2BP01). Drop them by name, then sweep ANY remaining policy whose expression
-- still references the function, so no other unrecorded name drift can block
-- the drop. Both are no-ops on a fresh install.
drop policy if exists "Ledger members can insert JSON ledger" on public.car_share_ledgers;
drop policy if exists "Ledger members can update JSON ledger" on public.car_share_ledgers;

do $sweep$
declare
  leftover_policy record;
begin
  for leftover_policy in
    select pol.schemaname, pol.tablename, pol.policyname
    from pg_policies pol
    where coalesce(pol.qual, '') || ' ' || coalesce(pol.with_check, '')
          like '%is_ledger_bootstrap_open%'
  loop
    execute format('drop policy %I on %I.%I',
                   leftover_policy.policyname, leftover_policy.schemaname, leftover_policy.tablename);
  end loop;
end
$sweep$;

-- With no policy referencing it, drop the function. The
-- lock_ledger_bootstrap_when_admin_email_attached trigger and the
-- bootstrap_locked_at column are intentionally kept (no dependency, removing
-- them is churn not security).
drop function public.is_ledger_bootstrap_open(text);

-- ── GV-247: identity parties must be active members ─────────────────────────
-- Extends migration 101's enforce_identity_reassignment() (newest definition).
-- 101's admin-or-creator reassignment gate is preserved verbatim; two active-
-- member checks are added — an unconditional one on INSERT and one on UPDATE
-- whenever the identity actually changes. OLD is only read on the UPDATE path so
-- the same function is safe under the new `before insert or update` triggers.
create or replace function public.enforce_identity_reassignment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ledger_id text := new.ledger_id;
  v_actor_member_id uuid;
  v_old_identity uuid;
  v_new_identity uuid;
  v_creator_member_id uuid;
begin
  -- Identity-bearing member column per table (GV-253 / GV-247). Any other table
  -- falls straight through untouched.
  if tg_table_name = 'trips' then
    v_new_identity := new.driver_member_id;
  elsif tg_table_name = 'fuel_payments' then
    v_new_identity := new.payer_member_id;
  elsif tg_table_name = 'car_bookings' then
    v_new_identity := new.member_id;
  else
    return new;
  end if;

  -- GV-247: on INSERT the identity party must be an ACTIVE member of NEW's
  -- ledger. No admin/creator check here — that permission rule is UPDATE-only.
  if tg_op = 'INSERT' then
    if v_new_identity is not null and not exists (
      select 1 from public.ledger_members lm
      where lm.id = v_new_identity
        and lm.ledger_id = v_ledger_id
        and lm.is_active
    ) then
      raise exception 'Identity members must be active ledger members' using errcode = '23514';
    end if;
    return new;
  end if;

  -- UPDATE path: resolve the OLD identity + creator (safe now that INSERT has
  -- already returned above).
  if tg_table_name = 'trips' then
    v_old_identity := old.driver_member_id;
  elsif tg_table_name = 'fuel_payments' then
    v_old_identity := old.payer_member_id;
  elsif tg_table_name = 'car_bookings' then
    v_old_identity := old.member_id;
  end if;
  v_creator_member_id := old.created_by_member_id;

  -- Guard only an actual reassignment; an unchanged identity passes through so the
  -- driver / payer / booked member keeps editing every non-identity field.
  if v_new_identity is not distinct from v_old_identity then
    return new;
  end if;

  -- Reassignment is admin-or-creator only. The JWT helpers resolve the real actor
  -- even inside the SECURITY DEFINER upsert RPCs (auth.jwt() is request-scoped),
  -- mirroring how is_ledger_admin / current_ledger_member_id already work there.
  v_actor_member_id := public.current_ledger_member_id(v_ledger_id);
  if not (
    public.is_ledger_admin(v_ledger_id)
    or (v_creator_member_id is not null and v_creator_member_id = v_actor_member_id)
  ) then
    raise exception
      'Only the creator or a ledger admin can reassign who this entry belongs to.'
      using errcode = '42501';
  end if;

  -- GV-247: the reassigned identity must also be an ACTIVE member of the ledger.
  if v_new_identity is not null and not exists (
    select 1 from public.ledger_members lm
    where lm.id = v_new_identity
      and lm.ledger_id = v_ledger_id
      and lm.is_active
  ) then
    raise exception 'Identity members must be active ledger members' using errcode = '23514';
  end if;

  return new;
end;
$$;

revoke execute on function public.enforce_identity_reassignment() from public;

-- Recreate the three triggers as `before insert or update` (101's names kept).
drop trigger if exists enforce_identity_reassignment_trips on public.trips;
create trigger enforce_identity_reassignment_trips
before insert or update on public.trips
for each row execute function public.enforce_identity_reassignment();

drop trigger if exists enforce_identity_reassignment_fuel on public.fuel_payments;
create trigger enforce_identity_reassignment_fuel
before insert or update on public.fuel_payments
for each row execute function public.enforce_identity_reassignment();

drop trigger if exists enforce_identity_reassignment_bookings on public.car_bookings;
create trigger enforce_identity_reassignment_bookings
before insert or update on public.car_bookings
for each row execute function public.enforce_identity_reassignment();

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('103_security_hardening',
        'Security wave (GV-244..GV-247): upsert_settlement_request_status re-declared off 090 with a party-or-admin guard so only the payer, recipient or a ledger admin can create/transition a settlement request (closes the SECURITY DEFINER bypass of the party-or-admin table RLS). Join codes lengthened 4->6 char body (generate_workspace_join_code off 045, gen_random_bytes(6)); all existing codes regenerated (data-only). is_ledger_bootstrap_open trapdoor removed: 3 pure-bootstrap policies dropped, 5 policies re-created without the bootstrap disjunct, then the function dropped (bootstrap trigger + column kept). enforce_identity_reassignment extended (off 101) so trips.driver_member_id / fuel_payments.payer_member_id / car_bookings.member_id must reference an active member on INSERT and on identity-changing UPDATE; triggers recreated as before insert or update. Trade-offs: old join codes/links die at apply time; backfilling a removed member needs temporary reactivation.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 104: settlement amount integrity (GV-259, GV-260) ─────────────
-- current_pair_keys (the trailing parameter) is DEPRECATED and IGNORED as of this
-- migration: the stale-pair sweep now derives the valid settlement pairs
-- SERVER-SIDE from calculate_period_settlement. The parameter is kept in the
-- signature (byte-identical) so existing PostgREST callers that still pass it do
-- not break.
create or replace function public.upsert_settlement_request_status(
  target_ledger_id text,
  target_open_period_id uuid,
  payer_member_id uuid,
  recipient_member_id uuid,
  amount_value numeric,
  currency_value text,
  next_status text,
  current_pair_keys text[] default array[]::text[]
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  saved_request_id uuid;
  prev_status_value text := null;
  prev_amount_value numeric := null;
  prev_currency_value text := null;
  requested_at_value timestamptz := null;
  requested_by_value uuid := null;
  paid_at_value timestamptz := null;
  cancelled_count integer := 0;
  normalized_status text := coalesce(nullif(next_status, ''), 'open');
  event_type_value text;
  event_title_value text;
  period_is_open boolean;
  computed_settlement jsonb;
  valid_pair_keys text[] := array[]::text[];
  debtor_ids uuid[];
  debtor_amts numeric[];
  creditor_ids uuid[];
  creditor_amts numeric[];
  di integer := 1;
  ci integer := 1;
  pair_amount numeric;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_open_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can save settlement requests' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- GV-244: a settlement request may only be created or transitioned by one of
  -- its two parties or a ledger admin. Without this any signed-in member could
  -- drive a request between two OTHER members (incl. marking it paid) through
  -- this SECURITY DEFINER RPC, bypassing the party-or-admin table RLS.
  if actor_member_id not in (payer_member_id, recipient_member_id)
    and not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only the payer, recipient, or a ledger admin can save this settlement request' using errcode = '42501';
  end if;

  -- Resolve the target period. Normally OPEN (request + pay on the live period).
  -- For a debt carried past a close, mobile acts on the request in its own CLOSED
  -- period (GVM-243): mark paid / remind / reopen are allowed there, but only
  -- against an existing request (guarded below). A missing/foreign period is
  -- rejected outright.
  select (sp.status = 'open' and sp.closed_at is null)
    into period_is_open
  from public.settlement_periods sp
  where sp.id = target_open_period_id
    and sp.ledger_id = target_ledger_id;

  if period_is_open is null then
    raise exception 'Settlement period was not found or does not belong to this ledger' using errcode = '22023';
  end if;

  if payer_member_id is null or recipient_member_id is null then
    raise exception 'Settlement request must include both payer and recipient members' using errcode = '23514';
  end if;

  if payer_member_id = recipient_member_id then
    raise exception 'Settlement request payer and recipient must be different members' using errcode = '23514';
  end if;

  if not public.member_belongs_to_ledger(payer_member_id, target_ledger_id)
    or not public.member_belongs_to_ledger(recipient_member_id, target_ledger_id) then
    raise exception 'Settlement request members must belong to the same ledger' using errcode = '23514';
  end if;

  if amount_value is null or amount_value < 0 then
    raise exception 'Settlement request amount must be zero or greater' using errcode = '23514';
  end if;

  if normalized_status not in ('open', 'requested', 'paid', 'paid_pending', 'cancelled') then
    raise exception 'Invalid settlement request status' using errcode = '23514';
  end if;

  -- A closed period can gain no NEW requests: only an existing (non-cancelled)
  -- request for the pair may transition. This blanket-guards paid / requested /
  -- open on a closed period; the insert branch + stale sweep below stay
  -- open-period-only.
  if not period_is_open then
    if not exists (
      select 1 from public.settlement_requests sr
      where sr.period_id = target_open_period_id
        and sr.from_member_id = payer_member_id
        and sr.to_member_id = recipient_member_id
        and sr.status <> 'cancelled'
    ) then
      raise exception 'No active settlement request for this pair in the closed period' using errcode = '22023';
    end if;
  end if;

  -- Bound the requested amount (GVM-112): no pair settlement can exceed the
  -- period's total fuel spend. Deliberately an upper bound, not equality —
  -- monthly/running request shapes (GVM-76) vary by design, and a false
  -- rejection would block a legitimate payment request. Open-period only: a
  -- closed period's fuel total is frozen and the amount already exists on the row.
  if normalized_status = 'requested' and period_is_open then
    if amount_value is null or amount_value <= 0 then
      raise exception 'Requested amount must be greater than zero' using errcode = '23514';
    end if;
    if amount_value > (
      select coalesce(sum(fp.amount), 0) + 1.0
      from public.fuel_payments fp
      where fp.ledger_id = target_ledger_id
        and fp.period_id = target_open_period_id
        and fp.deleted_at is null
    ) then
      raise exception 'Requested amount is larger than this period''s total fuel spend. Refresh the app and try again.' using errcode = '23514';
    end if;
  end if;

  -- Require an existing, non-cancelled request before claiming or confirming a
  -- payment (GVM-241, extended to paid_pending in GVM-213). Without this the
  -- pair upsert's on-conflict misses for a stale/foreign-period request and
  -- INSERTs a fresh row directly at a settled-ish status, which trips the 003
  -- trigger guard with the cryptic 'Request the payment before marking it paid'.
  -- Raise a clean, mappable error instead.
  if normalized_status in ('paid', 'paid_pending') then
    if not exists (
      select 1 from public.settlement_requests sr
      where sr.period_id = target_open_period_id
        and sr.from_member_id = payer_member_id
        and sr.to_member_id = recipient_member_id
        and sr.status <> 'cancelled'
    ) then
      raise exception 'No active payment request to mark as paid — refresh and try again' using errcode = '23514';
    end if;
  end if;

  if normalized_status = 'requested' then
    requested_at_value := now();
    requested_by_value := recipient_member_id;
  elsif normalized_status = 'paid' then
    paid_at_value := now();
  end if;

  perform pg_advisory_xact_lock(hashtext(target_ledger_id || ':settlement:' || target_open_period_id::text));

  -- Transition the pair's request via an explicit lookup + UPDATE, NOT
  -- INSERT ... ON CONFLICT. The 003 integrity trigger is BEFORE INSERT OR UPDATE,
  -- and a BEFORE INSERT trigger fires on an upsert's proposed row *before* the
  -- ON CONFLICT resolves to DO UPDATE — so an upsert to a settled status trips
  -- the trigger's INSERT guard even when a matching request exists (GVM-241).
  -- An explicit UPDATE fires BEFORE UPDATE, where the guard validates the
  -- transition as legal. Genuinely new rows still INSERT (open period only — a
  -- closed period was guaranteed an existing request above). prev_status drives
  -- the dispute event below (a paid_pending row sent back to 'requested').
  select sr.id, sr.status, sr.amount, sr.currency
    into saved_request_id, prev_status_value, prev_amount_value, prev_currency_value
  from public.settlement_requests sr
  where sr.period_id = target_open_period_id
    and sr.from_member_id = payer_member_id
    and sr.to_member_id = recipient_member_id
    and sr.status <> 'cancelled'
  for update;

  -- GV-259: amount + currency are IMMUTABLE once a request has left 'open'. The
  -- single permitted adjustment is the creditor (recipient) or a ledger admin
  -- re-requesting a still-live 'requested' row when balances shift (the mobile
  -- re-request flow). Every other transition — anything touching
  -- paid_pending/paid/cancelled, or the payer acting — must carry the stored
  -- amount + currency unchanged, so a claimed/settled figure can never be
  -- rewritten under a status change. Creation ('open' or no row) sets the amount
  -- freely and is skipped here.
  if saved_request_id is not null and prev_status_value <> 'open' then
    if normalized_status = 'requested'
       and (actor_member_id = recipient_member_id
            or public.is_ledger_admin(target_ledger_id)) then
      null; -- creditor/admin may re-request a live request at a new amount
    elsif amount_value = prev_amount_value
          and coalesce(nullif(currency_value, ''), 'DKK') = prev_currency_value then
      null; -- amount + currency preserved
    else
      raise exception 'Settlement request amount is locked during status transitions' using errcode = '23514';
    end if;
  end if;

  if saved_request_id is not null then
    update public.settlement_requests
       set amount = amount_value,
           currency = coalesce(nullif(currency_value, ''), 'DKK'),
           status = normalized_status,
           requested_at = requested_at_value,
           requested_by_member_id = requested_by_value,
           paid_at = paid_at_value,
           updated_at = now()
     where id = saved_request_id;
  elsif period_is_open then
    insert into public.settlement_requests (
      ledger_id,
      period_id,
      from_member_id,
      to_member_id,
      amount,
      currency,
      status,
      requested_at,
      requested_by_member_id,
      paid_at,
      updated_at
    ) values (
      target_ledger_id,
      target_open_period_id,
      payer_member_id,
      recipient_member_id,
      amount_value,
      coalesce(nullif(currency_value, ''), 'DKK'),
      normalized_status,
      requested_at_value,
      requested_by_value,
      paid_at_value,
      now()
    )
    returning id into saved_request_id;
  else
    raise exception 'No active settlement request for this pair in the closed period' using errcode = '22023';
  end if;

  -- GV-259: cancel stale requests whose pair is no longer part of the live
  -- settlement. The set of valid pairs is computed SERVER-SIDE (current_pair_keys
  -- is ignored): calculate_period_settlement returns each member's net, and the
  -- valid (debtor -> creditor) pairs are derived from those nets with the same
  -- greedy min-cash-flow the client uses (settlement-calc.ts / buildSettlements).
  -- Open-period only, as before: a closed period's settlements are frozen. Only
  -- 'open'/'requested' rows are swept — a paid_pending/paid row is money already
  -- claimed or moved (history, not staleness) and is never cancelled here.
  if period_is_open then
    computed_settlement := public.calculate_period_settlement(target_ledger_id, target_open_period_id);

    -- Debtors carry net < 0 (owe money), creditors net > 0 (are owed). Each side
    -- is ordered by magnitude descending, matching the client's debtor/creditor
    -- sort; ties break on id for a deterministic server result. Amounts round to
    -- 2 dp (nets are already 2 dp; round is a defensive no-op).
    select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::uuid[]),
           coalesce(array_agg(round(-((p.value->>'net')::numeric), 2) order by (p.value->>'net')::numeric asc, (p.value->>'id') collate "C"), array[]::numeric[])
      into debtor_ids, debtor_amts
      from jsonb_array_elements(computed_settlement->'people') as p(value)
      where (p.value->>'net')::numeric < -0.005;

    select coalesce(array_agg((p.value->>'id')::uuid order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::uuid[]),
           coalesce(array_agg(round((p.value->>'net')::numeric, 2) order by (p.value->>'net')::numeric desc, (p.value->>'id') collate "C"), array[]::numeric[])
      into creditor_ids, creditor_amts
      from jsonb_array_elements(computed_settlement->'people') as p(value)
      where (p.value->>'net')::numeric > 0.005;

    -- Greedy min-cash-flow pairing (mirrors buildSettlements): match the largest
    -- debtor against the largest creditor, emit a 'fromId->toId' key when the
    -- matched amount rounds > 0, then advance whichever side is exhausted. Every
    -- matched amount is <= 0.005 => index advances, so the loop always terminates.
    while di <= coalesce(array_length(debtor_ids, 1), 0)
          and ci <= coalesce(array_length(creditor_ids, 1), 0) loop
      pair_amount := round(least(debtor_amts[di], creditor_amts[ci]), 2);
      if pair_amount > 0 then
        valid_pair_keys := valid_pair_keys
          || (debtor_ids[di]::text || '->' || creditor_ids[ci]::text);
      end if;
      debtor_amts[di] := round(debtor_amts[di] - pair_amount, 2);
      creditor_amts[ci] := round(creditor_amts[ci] - pair_amount, 2);
      if debtor_amts[di] <= 0.005 then di := di + 1; end if;
      if creditor_amts[ci] <= 0.005 then ci := ci + 1; end if;
    end loop;

    update public.settlement_requests sr
       set status = 'cancelled',
           updated_at = now(),
           requested_at = null,
           requested_by_member_id = null,
           paid_at = null
     where sr.ledger_id = target_ledger_id
       and sr.period_id = target_open_period_id
       and sr.status in ('open', 'requested')
       and not ((sr.from_member_id::text || '->' || sr.to_member_id::text) = any(valid_pair_keys));
    get diagnostics cancelled_count = row_count;
  end if;

  -- Activity feed + realtime nudge (GVM-247): every status change writes a
  -- ledger_events row so the other member's client (subscribed to ledger_events)
  -- refetches immediately, and the change lands in the activity feed. The
  -- two-step confirmation (GVM-213) adds payment_claimed (debtor marked paid,
  -- awaiting confirmation) and payment_disputed (recipient sent a paid_pending
  -- debt back to 'requested'); payment_paid now means confirmed/received.
  event_type_value := case
    when normalized_status = 'requested' and prev_status_value = 'paid_pending' then 'payment_disputed'
    when normalized_status = 'requested' then 'payment_requested'
    when normalized_status = 'paid_pending' then 'payment_claimed'
    when normalized_status = 'paid' then 'payment_paid'
    else 'settlement_' || normalized_status
  end;
  event_title_value := case
    when normalized_status = 'requested' and prev_status_value = 'paid_pending' then 'Betaling afvist'
    when normalized_status = 'requested' then 'Betaling anmodet'
    when normalized_status = 'paid_pending' then 'Afventer bekræftelse'
    when normalized_status = 'paid' then 'Betaling bekræftet'
    when normalized_status = 'cancelled' then 'Betaling annulleret'
    else 'Betaling genåbnet'
  end;

  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id, event_type_value, event_title_value, '',
    actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
    jsonb_build_object(
      'settlement_request_id', saved_request_id,
      'from_member_id', payer_member_id,
      'to_member_id', recipient_member_id,
      'amount', amount_value
    )
  );

  return jsonb_build_object(
    'settlement_request_id', saved_request_id,
    'ledger_id', target_ledger_id,
    'period_id', target_open_period_id,
    'status', normalized_status,
    'cancelled_stale_count', cancelled_count
  );
end;
$$;

revoke execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[]) from public;
grant execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[]) to authenticated;

-- ── GV-260: close_settlement_period (off 101) ──────────────────────────────
create or replace function public.close_settlement_period(
  target_ledger_id text,
  target_period_id uuid,
  period_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  snapshot_fingerprint text;
  server_fingerprint text;
  computed jsonb;
  computed_person jsonb;
  snapshot_person jsonb;
  snapshot_flow numeric;
  duplicate_period_id uuid;
  closed_period_id uuid;
  new_open_period_id uuid;
  requested_closed_at timestamptz;
  lock_acquired boolean;
  v_rule_require_requests boolean;
  v_settlement jsonb;
  v_missing_settlements integer := 0;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing open settlement period id' using errcode = '22023';
  end if;

  if period_snapshot is null or jsonb_typeof(period_snapshot) <> 'object' then
    raise exception 'Period snapshot must be a JSON object' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can close settlement periods' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- Guard before taking the advisory lock. Older frontend builds and health probes
  -- may call this RPC with a fake or already-closed period id. Reject those
  -- immediately so they cannot queue behind the lock and burn database CPU.
  if not exists (
    select 1
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
  ) then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '22023';
  end if;

  lock_acquired := pg_try_advisory_xact_lock(hashtext(target_ledger_id));
  if lock_acquired is not true then
    raise exception 'Another settlement close is already in progress for this ledger' using errcode = '55P03';
  end if;

  -- ── Integrity gate (GVM-112) ──────────────────────────────────────────────
  -- (a) Entry set: the snapshot's fingerprint must equal the one recomputed
  -- from the live rows. In-flight writers hold FOR SHARE on the period row, so
  -- by the time this runs the row set is stable for the transaction.
  snapshot_fingerprint := nullif(period_snapshot->>'entryFingerprint', '');
  server_fingerprint := public.calculate_period_entry_fingerprint(target_ledger_id, target_period_id);

  if snapshot_fingerprint is not null and snapshot_fingerprint <> server_fingerprint then
    raise exception 'Entries changed since this close was prepared. Refresh the app and try closing again.'
      using errcode = '23514';
  end if;

  -- (b) Amounts: per-member figures within 0.02 kr, totals within 0.05 kr.
  computed := public.calculate_period_settlement(target_ledger_id, target_period_id);

  if abs(coalesce((period_snapshot->>'totalKm')::numeric, 0) - (computed->>'totalKm')::numeric) > 0.05
     or abs(coalesce((period_snapshot->>'totalPaid')::numeric, 0) - (computed->>'totalPaid')::numeric) > 0.05 then
    raise exception 'Snapshot totals do not match the server calculation. Refresh the app and try closing again.'
      using errcode = '23514';
  end if;

  for computed_person in
    select value from jsonb_array_elements(computed->'people')
  loop
    select p.value
      into snapshot_person
      from jsonb_array_elements(coalesce(period_snapshot->'people', '[]'::jsonb)) as p(value)
      where p.value->>'id' = computed_person->>'id'
      limit 1;

    if abs(coalesce((snapshot_person->>'km')::numeric, 0) - (computed_person->>'km')::numeric) > 0.02
       or abs(coalesce((snapshot_person->>'fuelPaid')::numeric, 0) - (computed_person->>'fuelPaid')::numeric) > 0.02
       or abs(coalesce((snapshot_person->>'net')::numeric, 0) - (computed_person->>'net')::numeric) > 0.02 then
      raise exception 'Snapshot member amounts do not match the server calculation. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;

    -- (c) The archived settlements must actually move each member's net:
    -- outflow - inflow ~= -net for every member.
    select coalesce(sum((s.value->>'amount')::numeric) filter (where s.value->>'fromId' = computed_person->>'id'), 0)
         - coalesce(sum((s.value->>'amount')::numeric) filter (where s.value->>'toId' = computed_person->>'id'), 0)
      into snapshot_flow
      from jsonb_array_elements(coalesce(period_snapshot->'settlements', '[]'::jsonb)) as s(value);

    if abs(snapshot_flow + (computed_person->>'net')::numeric) > 0.05 then
      raise exception 'Snapshot settlements do not match the member balances. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;
  end loop;

  -- Snapshot-only members (left the ledger between fetch and close) must carry
  -- no money, otherwise the archive would hide a real balance.
  for snapshot_person in
    select value from jsonb_array_elements(coalesce(period_snapshot->'people', '[]'::jsonb))
  loop
    if not exists (
      select 1 from jsonb_array_elements(computed->'people') as c(value)
      where c.value->>'id' = snapshot_person->>'id'
    ) and abs(coalesce((snapshot_person->>'net')::numeric, 0)) > 0.02 then
      raise exception 'Snapshot includes a member the server no longer recognizes. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;
  end loop;
  -- ── End integrity gate ────────────────────────────────────────────────────

  -- ── FIX 2 (GV-253 / GVM-278): require requests before close ────────────────
  -- rule_require_requests_before_close (migration 098) shipped stored-only — this
  -- is its first database enforcement. When the workspace flag is NOT an explicit
  -- false, every settlement pair that moves money must already have a request row
  -- for this period in a requested-or-later state (status not 'open'/'cancelled').
  -- The period_snapshot settlements are safe to read here: integrity gate (c) just
  -- proved they reconcile each member's server-computed net, so they ARE the real
  -- outstanding pairs. A settlement_requests row is keyed by period + payer
  -- (from_member_id) + recipient (to_member_id), matching the snapshot fromId/toId.
  select l.rule_require_requests_before_close
    into v_rule_require_requests
    from public.ledgers l
    where l.id = target_ledger_id;

  if v_rule_require_requests is not false then
    for v_settlement in
      select value from jsonb_array_elements(coalesce(period_snapshot->'settlements', '[]'::jsonb))
    loop
      if coalesce((v_settlement->>'amount')::numeric, 0) > 0
         and not exists (
           select 1
           from public.settlement_requests sr
           where sr.period_id = target_period_id
             and sr.from_member_id = (v_settlement->>'fromId')::uuid
             and sr.to_member_id = (v_settlement->>'toId')::uuid
             and sr.status not in ('open', 'cancelled')
             and sr.amount = round((v_settlement->>'amount')::numeric, 2)
         ) then
        v_missing_settlements := v_missing_settlements + 1;
      end if;
    end loop;

    if v_missing_settlements > 0 then
      raise exception
        'All settlements must be requested at their current amounts before this period can be closed. Request or update the outstanding payments and try again.'
        using errcode = '42501';
    end if;
  end if;
  -- ── End require-requests-before-close ──────────────────────────────────────

  if snapshot_fingerprint is not null then
    select sp.id into duplicate_period_id
    from public.settlement_periods sp
    where sp.ledger_id = target_ledger_id
      and sp.status = 'closed'
      and sp.snapshot_json->>'entryFingerprint' = snapshot_fingerprint
    limit 1;

    if duplicate_period_id is not null then
      raise exception 'This settlement period snapshot has already been closed' using errcode = '23505';
    end if;
  end if;

  begin
    requested_closed_at := coalesce((period_snapshot->>'closedAt')::timestamptz, now());
  exception when others then
    requested_closed_at := now();
  end;

  update public.settlement_periods sp
  set status = 'closed',
      label = coalesce(nullif(period_snapshot->>'label', ''), sp.label, 'Closed period'),
      closed_at = requested_closed_at,
      closed_by_member_id = actor_member_id,
      snapshot_json = period_snapshot,
      updated_at = now()
  where sp.id = target_period_id
    and sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  returning sp.id into closed_period_id;

  if closed_period_id is null then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '40001';
  end if;

  -- FIX 3 (GV-253): label the freshly opened period in Danish to match the app's
  -- own period labels (client formats da-DK month+year; demo data uses 'Juni
  -- 2026'). to_char(..., 'Month') only speaks English, so index a Danish month
  -- array by the current month and capitalize, e.g. 'Juli 2026'. Deterministic and
  -- server-clock based; the client overwrites this with its own snapshot label when
  -- it later closes, so it only shows while this is the current period.
  insert into public.settlement_periods (ledger_id, status, label, opened_at)
  values (
    target_ledger_id,
    'open',
    (array['Januar','Februar','Marts','April','Maj','Juni','Juli','August','September','Oktober','November','December'])[extract(month from now())::int]
      || ' ' || to_char(now(), 'YYYY'),
    now()
  )
  returning id into new_open_period_id;

  -- Activity feed + realtime nudge (GVM-247): closing a period writes a
  -- ledger_events row so every other member's client (subscribed to
  -- ledger_events) refetches immediately — otherwise the close only reaches them
  -- on a manual refresh. metadata carries both period ids for the feed/routing.
  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id, 'period_closed', 'Periode lukket', 'En ny periode er klar.',
    actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
    jsonb_build_object('closed_period_id', closed_period_id, 'open_period_id', new_open_period_id)
  );

  return jsonb_build_object(
    'closed_period_id', closed_period_id,
    'open_period_id', new_open_period_id,
    'closed_by_member_id', actor_member_id,
    'closed_at', requested_closed_at,
    'entry_fingerprint', snapshot_fingerprint
  );
end;
$$;

revoke execute on function public.close_settlement_period(text, uuid, jsonb) from public;
grant execute on function public.close_settlement_period(text, uuid, jsonb) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('104_settlement_amount_integrity',
        'Settlement amount integrity (GV-259, GV-260). upsert_settlement_request_status re-declared off 103 (signature byte-identical): (A) amount + currency are immutable once a request leaves open — only a creditor/admin re-request of a live requested row may change them, every other transition must preserve the stored amount (23514); (B) the stale-pair sweep is now computed server-side from calculate_period_settlement nets via the same greedy min-cash-flow as the client, current_pair_keys is deprecated/ignored, and only open/requested rows are swept (never paid_pending/paid). close_settlement_period re-declared off 101: the require-requests-before-close coverage check now also requires each request to be at its current amount, with an updated operator message.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 105: vehicle_repairs.workshop + insert_repair workshop param (GVM-306).
alter table public.vehicle_repairs add column if not exists workshop text;

-- ── insert_repair: a member logs a maintenance/repair cost ──────────────────────
-- Mirrors the "Creators and admins can insert repairs" RLS policy: any active member
-- may log a repair, always attributed to themselves (created_by = the caller).
drop function public.insert_repair(text, date, text, numeric, integer);

create or replace function public.insert_repair(
  target_ledger_id text,
  repair_date_value date,
  description_value text,
  cost_dkk_value numeric,
  odo_km_value integer default null,
  workshop text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  result_id uuid;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can log repairs' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  if nullif(description_value, '') is null then
    raise exception 'Repair description is required' using errcode = '22023';
  end if;

  insert into public.vehicle_repairs (
    ledger_id, repair_date, description, cost_dkk, odo_km, workshop, created_by_member_id
  ) values (
    target_ledger_id,
    coalesce(repair_date_value, current_date),
    description_value,
    coalesce(cost_dkk_value, 0),
    odo_km_value,
    nullif(btrim(workshop), ''),
    actor_member_id
  )
  returning id into result_id;

  return jsonb_build_object('id', result_id);
end;
$$;

revoke all on function public.insert_repair(text, date, text, numeric, integer, text) from public;
revoke all on function public.insert_repair(text, date, text, numeric, integer, text) from anon;
grant execute on function public.insert_repair(text, date, text, numeric, integer, text) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('105_repair_workshop',
        'Add vehicle_repairs.workshop and thread it through insert_repair (dropped + recreated with a trailing workshop param) (GVM-306).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ══════════════════════════════════════════════════════════════════════════
-- Mirror of supabase/migrations/106_reminder_outcomes_claim_token.sql (GV-265;
-- function bodies byte-identical for the GV-175 equivalence check). Adds a
-- per-lease claim token to both claim RPCs and moves the confirm RPCs to a
-- (confirmations jsonb) = [{"id","token","outcome"}] signature that records the
-- delivery outcome in the ledger_events metadata. Last definition wins on
-- replay, so this drop+recreate leaves the same end state as a fresh install.
-- ══════════════════════════════════════════════════════════════════════════

alter table public.settlement_requests add column if not exists reminder_claim_token uuid;
alter table public.settlement_periods add column if not exists close_reminder_claim_token uuid;

-- ── claim_due_close_reminders: lease + claim token (return gains claim_token) ────────
drop function if exists public.claim_due_close_reminders(integer);
create or replace function public.claim_due_close_reminders(
  batch_limit integer default 200
)
returns table (period_id uuid, ledger_id text, label text, admin_emails text[], claim_token uuid)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select sp.id
    from public.settlement_periods sp
    join public.ledgers l on l.id = sp.ledger_id
    where sp.status = 'open'
      and l.close_reminder_enabled = true
      and sp.opened_at <= now() - interval '30 days'
      and (sp.close_reminder_claimed_at is null
           or sp.close_reminder_claimed_at <= now() - interval '15 minutes')
      and (sp.last_close_reminder_at is null
           or sp.last_close_reminder_at <= now() - interval '7 days')
    order by sp.opened_at
    limit greatest(coalesce(batch_limit, 200), 0)
    for update of sp skip locked
  ),
  claimed as (
    update public.settlement_periods sp
    set close_reminder_claimed_at = now(),
        close_reminder_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where sp.id = t.id
    returning sp.id as period_id,
              sp.ledger_id as ledger_id,
              sp.label as label,
              sp.close_reminder_claim_token as claim_token
  )
  select c.period_id,
         c.ledger_id,
         c.label,
         coalesce(
           array_agg(lower(lm.email)) filter (where lm.email is not null),
           array[]::text[]
         ) as admin_emails,
         c.claim_token
  from claimed c
  left join public.ledger_members lm
    on lm.ledger_id = c.ledger_id
   and lm.role = 'admin'
   and lm.is_active = true
   and lm.email is not null
  group by c.period_id, c.ledger_id, c.label, c.claim_token;
end;
$$;

revoke all on function public.claim_due_close_reminders(integer) from public;
revoke all on function public.claim_due_close_reminders(integer) from anon;
revoke all on function public.claim_due_close_reminders(integer) from authenticated;
grant execute on function public.claim_due_close_reminders(integer) to service_role;

-- ── claim_due_payment_reminders: lease + claim token (return gains claim_token) ──────
drop function if exists public.claim_due_payment_reminders(integer);
create or replace function public.claim_due_payment_reminders(
  batch_limit integer default 200
)
returns table (request_id uuid, ledger_id text, debtor_email text, creditor_name text, amount numeric, claim_token uuid)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select sr.id
    from public.settlement_requests sr
    join public.ledger_members debtor on debtor.id = sr.from_member_id
    where sr.status = 'requested'
      and sr.reminder_count < 3
      and debtor.is_active = true
      and debtor.email is not null
      and (sr.reminder_claimed_at is null
           or sr.reminder_claimed_at <= now() - interval '15 minutes')
      and (
        (sr.reminder_count = 0
          and sr.requested_at is not null
          and sr.requested_at <= now() - interval '3 days')
        or (sr.reminder_count between 1 and 2
          and sr.last_reminder_at is not null
          and sr.last_reminder_at <= now() - interval '7 days')
      )
    order by sr.requested_at
    limit greatest(coalesce(batch_limit, 200), 0)
    for update of sr skip locked
  ),
  claimed as (
    update public.settlement_requests sr
    set reminder_claimed_at = now(),
        reminder_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where sr.id = t.id
    returning sr.id as request_id,
              sr.ledger_id as ledger_id,
              sr.from_member_id as debtor_id,
              sr.to_member_id as creditor_id,
              sr.amount as amount,
              sr.reminder_claim_token as claim_token
  )
  select c.request_id,
         c.ledger_id,
         lower(debtor.email) as debtor_email,
         creditor.name as creditor_name,
         c.amount,
         c.claim_token
  from claimed c
  left join public.ledger_members debtor on debtor.id = c.debtor_id
  left join public.ledger_members creditor on creditor.id = c.creditor_id;
end;
$$;

revoke all on function public.claim_due_payment_reminders(integer) from public;
revoke all on function public.claim_due_payment_reminders(integer) from anon;
revoke all on function public.claim_due_payment_reminders(integer) from authenticated;
grant execute on function public.claim_due_payment_reminders(integer) to service_role;

-- ── confirm_close_reminders(jsonb): token-gated confirm + outcome in metadata ────────
drop function if exists public.confirm_close_reminders(uuid[]);
create or replace function public.confirm_close_reminders(confirmations jsonb)
returns integer
language sql
security definer
set search_path = public
as $$
  with input as (
    select (elem ->> 'id')::uuid as period_id,
           (elem ->> 'token')::uuid as claim_token,
           (elem ->> 'outcome') as outcome
    from jsonb_array_elements(coalesce(confirmations, '[]'::jsonb)) as elem
    where (elem ->> 'outcome') in ('delivered', 'suppressed_no_device', 'muted')
  ),
  confirmed as (
    update public.settlement_periods sp
    set last_close_reminder_at = now(),
        close_reminder_claimed_at = null,
        close_reminder_claim_token = null,
        updated_at = now()
    from input i
    where sp.id = i.period_id
      and sp.close_reminder_claimed_at is not null
      and sp.close_reminder_claim_token = i.claim_token
    returning sp.id as period_id, sp.ledger_id as ledger_id, sp.label as label, i.outcome as outcome
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    )
    select c.ledger_id, 'close_reminder_sent', 'Lukkepåmindelse sendt', '',
           null, null,
           jsonb_build_object(
             'period_id', c.period_id,
             'label', c.label,
             'outcome', c.outcome
           )
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_close_reminders(jsonb) from public;
revoke all on function public.confirm_close_reminders(jsonb) from anon;
revoke all on function public.confirm_close_reminders(jsonb) from authenticated;
grant execute on function public.confirm_close_reminders(jsonb) to service_role;

-- ── confirm_payment_reminders(jsonb): token-gated confirm + outcome in metadata ──────
drop function if exists public.confirm_payment_reminders(uuid[]);
create or replace function public.confirm_payment_reminders(confirmations jsonb)
returns integer
language sql
security definer
set search_path = public
as $$
  with input as (
    select (elem ->> 'id')::uuid as request_id,
           (elem ->> 'token')::uuid as claim_token,
           (elem ->> 'outcome') as outcome
    from jsonb_array_elements(coalesce(confirmations, '[]'::jsonb)) as elem
    where (elem ->> 'outcome') in ('delivered', 'suppressed_no_device', 'muted')
  ),
  confirmed as (
    update public.settlement_requests sr
    set reminder_count = sr.reminder_count + 1,
        last_reminder_at = now(),
        reminder_claimed_at = null,
        reminder_claim_token = null,
        updated_at = now()
    from input i
    where sr.id = i.request_id
      and sr.reminder_claimed_at is not null
      and sr.reminder_claim_token = i.claim_token
    returning sr.id as request_id,
              sr.ledger_id as ledger_id,
              sr.from_member_id as debtor_id,
              sr.to_member_id as creditor_id,
              sr.amount as amount,
              sr.reminder_count as reminder_count,
              i.outcome as outcome
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    )
    select c.ledger_id, 'payment_reminder_sent', 'Betalingspåmindelse sendt', '',
           null, null,
           jsonb_build_object(
             'settlement_request_id', c.request_id,
             'from_member_id', c.debtor_id,
             'to_member_id', c.creditor_id,
             'amount', c.amount,
             'reminder_count', c.reminder_count,
             'outcome', c.outcome
           )
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_payment_reminders(jsonb) from public;
revoke all on function public.confirm_payment_reminders(jsonb) from anon;
revoke all on function public.confirm_payment_reminders(jsonb) from authenticated;
grant execute on function public.confirm_payment_reminders(jsonb) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('106_reminder_outcomes_claim_token',
        'Reminder outcome states + per-lease claim token (GV-265): settlement_requests.reminder_claim_token / settlement_periods.close_reminder_claim_token added; claim_due_payment_reminders / claim_due_close_reminders re-declared off 102 (dropped + recreated) to stamp gen_random_uuid() into the token and return a trailing claim_token uuid. confirm_payment_reminders / confirm_close_reminders change signature from (uuid[]) to (confirmations jsonb) = [{"id","token","outcome"}]; a row confirms only when its lease is live AND the stored token matches (stale worker can no longer confirm a newer lease), and the outcome (delivered / suppressed_no_device / muted) is recorded in the ledger_events metadata as "outcome". Confirm clears both the lease and the token. Failed sends are still never confirmed (retry path unchanged). service_role only.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();


-- ══════════════════════════════════════════════════════════════════════════
-- Migration 107: repairs split per workspace rule (GVM-307) — mirror
-- ══════════════════════════════════════════════════════════════════════════
-- ── Workspace rule column ────────────────────────────────────────────────────
-- Default 'ligeligt' so applying this migration begins folding repairs equally for
-- every workspace; an operator/admin can switch to efter_koersel or deles_ikke.
alter table public.ledgers
  add column if not exists repairs_split_mode text not null default 'ligeligt'
    check (repairs_split_mode in ('efter_koersel', 'ligeligt', 'deles_ikke'));

-- ── update_ledger_settings: accept repairs_split_mode ────────────────────────
-- Re-declared off migration 078 (newest prior body) with ONE new trailing param,
-- repairs_split_mode_value, validated against the three modes and written via the
-- same coalesce-patch path as settlement_mode. Adding a parameter changes the
-- signature, so the old 4-arg function is dropped first (create-or-replace cannot
-- widen a signature); the new param defaults to null, so existing 4-arg callers
-- resolve to this one function with no ambiguity.
drop function if exists public.update_ledger_settings(text, text, jsonb, jsonb);

create or replace function public.update_ledger_settings(
  target_ledger_id text,
  settlement_mode_value text default null,
  expense_split_defaults_value jsonb default null,
  vehicle_info_value jsonb default null,
  repairs_split_mode_value text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can update workspace settings' using errcode = '42501';
  end if;

  if settlement_mode_value is not null
     and settlement_mode_value not in ('monthly', 'running') then
    raise exception 'Invalid settlement mode' using errcode = '22023';
  end if;

  if repairs_split_mode_value is not null
     and repairs_split_mode_value not in ('efter_koersel', 'ligeligt', 'deles_ikke') then
    raise exception 'Invalid repairs split mode' using errcode = '22023';
  end if;

  update public.ledgers set
    settlement_mode        = coalesce(settlement_mode_value, settlement_mode),
    expense_split_defaults = coalesce(expense_split_defaults_value, expense_split_defaults),
    vehicle_info           = coalesce(vehicle_info_value, vehicle_info),
    repairs_split_mode     = coalesce(repairs_split_mode_value, repairs_split_mode),
    updated_at             = now()
  where id = target_ledger_id;
end;
$$;

revoke all on function public.update_ledger_settings(text, text, jsonb, jsonb, text) from public;
revoke all on function public.update_ledger_settings(text, text, jsonb, jsonb, text) from anon;
grant execute on function public.update_ledger_settings(text, text, jsonb, jsonb, text) to authenticated;

-- ── calculate_period_settlement: fold repairs per workspace mode ─────────────
-- Re-declared off migration 070 (the newest prior definition — 083 only
-- re-grants; 087/101/104 re-declare close/upsert, not this). The trips/fuel/
-- expense math is byte-identical to 070; the ONLY additions are the repairs CTEs
-- (period_repairs / repair_weights / repair_weight_totals / repair_share /
-- repair_paid), the repair_paid/repair_share per_member columns + totalRepairs,
-- and repairPaid/repairShare/net folding repairs in. deles_ikke or a null mode
-- yields no period_repairs, so net is unchanged.
create or replace function public.calculate_period_settlement(
  target_ledger_id text,
  target_period_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_operator_context()
     and not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can calculate settlements' using errcode = '42501';
  end if;

  with active_members as (
    select lm.id, lm.name
    from public.ledger_members lm
    where lm.ledger_id = target_ledger_id
      and lm.is_active = true
  ),
  live_trips as (
    select t.id,
           t.driver_member_id,
           greatest(t.end_km - t.start_km, 0)::numeric as km
    from public.trips t
    where t.ledger_id = target_ledger_id
      and t.period_id = target_period_id
      and t.deleted_at is null
  ),
  trip_assignees as (
    select lt.id as trip_id,
           lt.km,
           coalesce(
             valid_participants.member_ids,
             case when driver_check.id is not null then array[lt.driver_member_id] end
           ) as assignees
    from live_trips lt
    left join lateral (
      select array_agg(distinct tp.member_id) as member_ids
      from public.trip_participants tp
      join active_members am on am.id = tp.member_id
      where tp.trip_id = lt.id
    ) valid_participants on true
    left join active_members driver_check on driver_check.id = lt.driver_member_id
  ),
  km_shares as (
    select shared.member_id,
           ta.km / array_length(ta.assignees, 1) as share_km
    from trip_assignees ta
    cross join lateral unnest(ta.assignees) as shared(member_id)
    where ta.assignees is not null
      and array_length(ta.assignees, 1) > 0
  ),
  member_km as (
    -- Unrounded per-member km, reused both for the settlement km and as the
    -- usage-split weight (the client weights usage on raw km).
    select ks.member_id, sum(ks.share_km) as km_sum
    from km_shares ks
    group by ks.member_id
  ),
  fuel_paid as (
    select fp.payer_member_id as member_id,
           sum(fp.amount)::numeric as paid
    from public.fuel_payments fp
    where fp.ledger_id = target_ledger_id
      and fp.period_id = target_period_id
      and fp.deleted_at is null
      and fp.payer_member_id is not null
    group by fp.payer_member_id
  ),
  ledger_defaults as (
    select l.expense_split_defaults as defaults
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  repairs_mode as (
    -- The workspace rule that governs repair folding (GVM-307). null (old row,
    -- pre-107) behaves like deles_ikke: the mode filter below excludes every
    -- repair, matching a client that has no mode field to read.
    select l.repairs_split_mode as mode
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  period_bounds as (
    -- Repairs are date-scoped (no period_id): a repair counts in the period whose
    -- [opened_at, closed_at) date window contains repair_date. The settling period
    -- is still open here (closed_at null), so its window has no upper bound.
    select sp.opened_at, sp.closed_at
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
  ),
  period_expenses as (
    -- Live expenses in this period whose payer is an active member (an expense
    -- with no active payer is skipped entirely, matching the client).
    select we.id,
           we.amount_dkk,
           we.paid_by_member_id,
           we.split_config,
           coalesce(nullif(we.split_rule, ''),
                    (ld.defaults ->> we.category),
                    'equal') as rule
    from public.workspace_expenses we
    cross join ledger_defaults ld
    join active_members payer on payer.id = we.paid_by_member_id
    where we.ledger_id = target_ledger_id
      and we.period_id = target_period_id
      and we.deleted_at is null
      and we.amount_dkk > 0
  ),
  expense_weights as (
    select pe.id as expense_id,
           pe.amount_dkk,
           am.id as member_id,
           case pe.rule
             when 'usage'  then coalesce(mk.km_sum, 0)
             when 'custom' then coalesce((pe.split_config ->> am.id::text)::numeric, 0)
             else 1::numeric
           end as weight
    from period_expenses pe
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  expense_weight_totals as (
    select expense_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from expense_weights
    group by expense_id
  ),
  expense_share as (
    select ew.member_id,
           sum(
             case when ewt.total_weight > 0
                  then round(ew.amount_dkk * ew.weight / ewt.total_weight, 2)
                  else round(ew.amount_dkk / ewt.member_count, 2)
             end
           ) as share
    from expense_weights ew
    join expense_weight_totals ewt using (expense_id)
    group by ew.member_id
  ),
  expense_paid as (
    select pe.paid_by_member_id as member_id, sum(pe.amount_dkk)::numeric as paid
    from period_expenses pe
    group by pe.paid_by_member_id
  ),
  period_repairs as (
    -- Repairs folded per the workspace mode (GVM-307). Only efter_koersel /
    -- ligeligt fold; deles_ikke (or a null mode) yields no rows. The logger
    -- (created_by_member_id) is treated as the payer (v1); a repair whose payer is
    -- not an active member is skipped entirely, exactly like an expense.
    select vr.id,
           vr.cost_dkk,
           vr.created_by_member_id,
           rm.mode
    from public.vehicle_repairs vr
    cross join repairs_mode rm
    cross join period_bounds pb
    join active_members payer on payer.id = vr.created_by_member_id
    where vr.ledger_id = target_ledger_id
      and vr.deleted_at is null
      and vr.cost_dkk > 0
      and rm.mode in ('efter_koersel', 'ligeligt')
      and vr.repair_date >= pb.opened_at::date
      and (pb.closed_at is null or vr.repair_date < pb.closed_at::date)
  ),
  repair_weights as (
    -- efter_koersel weights by each member's raw km (like the expense usage rule);
    -- ligeligt weights everyone equally. Zero total weight (efter_koersel with no
    -- km) falls back to an equal split below, matching the client.
    select pr.id as repair_id,
           pr.cost_dkk,
           am.id as member_id,
           case when pr.mode = 'efter_koersel' then coalesce(mk.km_sum, 0)
                else 1::numeric end as weight
    from period_repairs pr
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  repair_weight_totals as (
    select repair_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from repair_weights
    group by repair_id
  ),
  repair_share as (
    select rw.member_id,
           sum(
             case when rwt.total_weight > 0
                  then round(rw.cost_dkk * rw.weight / rwt.total_weight, 2)
                  else round(rw.cost_dkk / rwt.member_count, 2)
             end
           ) as share
    from repair_weights rw
    join repair_weight_totals rwt using (repair_id)
    group by rw.member_id
  ),
  repair_paid as (
    select pr.created_by_member_id as member_id, sum(pr.cost_dkk)::numeric as paid
    from period_repairs pr
    group by pr.created_by_member_id
  ),
  per_member as (
    select am.id,
           am.name,
           round(coalesce(mk.km_sum, 0), 2) as km,
           round(coalesce(f.paid, 0), 2) as fuel_paid,
           round(coalesce(xp.paid, 0), 2) as expense_paid,
           round(coalesce(xs.share, 0), 2) as expense_share,
           round(coalesce(rp.paid, 0), 2) as repair_paid,
           round(coalesce(rs.share, 0), 2) as repair_share
    from active_members am
    left join member_km mk on mk.member_id = am.id
    left join fuel_paid f on f.member_id = am.id
    left join expense_paid xp on xp.member_id = am.id
    left join expense_share xs on xs.member_id = am.id
    left join repair_paid rp on rp.member_id = am.id
    left join repair_share rs on rs.member_id = am.id
  ),
  totals as (
    select coalesce(sum(pm.km), 0) as total_km,
           coalesce(sum(pm.fuel_paid), 0) as total_paid,
           coalesce(sum(pm.expense_paid), 0) as total_expenses,
           coalesce(sum(pm.repair_paid), 0) as total_repairs
    from per_member pm
  )
  select jsonb_build_object(
    'totalKm', t.total_km,
    'totalPaid', t.total_paid,
    'totalExpenses', t.total_expenses,
    'totalRepairs', t.total_repairs,
    'fuelRate', case when t.total_km > 0 then round(t.total_paid / t.total_km, 2) else 0 end,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pm.id,
        'name', pm.name,
        'km', pm.km,
        'fuelPaid', pm.fuel_paid,
        'expensePaid', pm.expense_paid,
        'expenseShare', pm.expense_share,
        'repairPaid', pm.repair_paid,
        'repairShare', pm.repair_share,
        'tripCost', case when t.total_km > 0 then round(pm.km * (t.total_paid / t.total_km), 2) else 0 end,
        'net', case when t.total_km > 0
                    then round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - round(pm.km * (t.total_paid / t.total_km), 2) - pm.expense_share - pm.repair_share, 2)
                    else round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - pm.expense_share - pm.repair_share, 2) end
      ) order by pm.id::text collate "C")
      from per_member pm
    ), '[]'::jsonb)
  )
  into result
  from totals t;

  return result;
end;
$$;

revoke all on function public.calculate_period_settlement(text, uuid) from public;
revoke all on function public.calculate_period_settlement(text, uuid) from anon;
grant execute on function public.calculate_period_settlement(text, uuid) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('107_repairs_split_mode',
        'Repairs split per workspace rule (GVM-307). ledgers.repairs_split_mode (efter_koersel|ligeligt|deles_ikke, default ligeligt). calculate_period_settlement re-declared off 070 folds vehicle_repairs per mode: the logger (created_by_member_id) is credited as payer (v1, no paid_by column), each active member debited their split share (efter_koersel = km weights, ligeligt = equal, deles_ikke/null = excluded); repairs are date-scoped by repair_date within the period''s [opened_at, closed_at) window. update_ledger_settings re-declared off 078 (4-arg dropped, new trailing repairs_split_mode_value param, validated). Client settlement-calc.ts mirrors the math; both verified against a shared fixture (see header).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ══════════════════════════════════════════════════════════════════════════
-- Migration 108: repair payer + largest-remainder splits + repair validation
-- (GV-269) — mirror (function bodies byte-identical for the GV-175 equivalence
-- check; last definition wins on replay, so this drop+recreate leaves the same
-- end state as a fresh install running every migration).
-- ══════════════════════════════════════════════════════════════════════════
-- ── Repair payer column + backfill ──────────────────────────────────────────────
alter table public.vehicle_repairs
  add column if not exists paid_by_member_id uuid references public.ledger_members(id);

update public.vehicle_repairs
set paid_by_member_id = created_by_member_id
where paid_by_member_id is null;

-- ── insert_repair: payer param + financial validation ───────────────────────────
-- Re-declared off migration 105. Mirrors the "Creators and admins can insert
-- repairs" RLS policy: any active member may log a repair, always CREATED BY
-- themselves; the PAYER defaults to the actor but may be any active member of
-- the workspace (any-member attribution, decided 2026-07-10).
drop function public.insert_repair(text, date, text, numeric, integer, text);

create or replace function public.insert_repair(
  target_ledger_id text,
  repair_date_value date,
  description_value text,
  cost_dkk_value numeric,
  odo_km_value integer default null,
  workshop text default null,
  paid_by_member_id_value uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  resolved_payer_member_id uuid;
  clean_description text;
  clean_workshop text;
  result_id uuid;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can log repairs' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  clean_description := nullif(btrim(description_value), '');
  if clean_description is null then
    raise exception 'Repair description is required' using errcode = '22023';
  end if;
  if length(clean_description) > 500 then
    raise exception 'Repair description must be 500 characters or fewer' using errcode = '22023';
  end if;

  -- Repairs are financial records (GVM-307 folds them into the settlement), so a
  -- missing or non-positive cost is rejected rather than coalesced to 0.
  if cost_dkk_value is null or cost_dkk_value <= 0 then
    raise exception 'Repair cost must be greater than zero' using errcode = '22023';
  end if;

  if odo_km_value is not null and odo_km_value < 0 then
    raise exception 'Odometer reading cannot be negative' using errcode = '22023';
  end if;

  if repair_date_value is not null
     and (repair_date_value < date '2000-01-01'
          or repair_date_value > current_date + interval '1 year') then
    raise exception 'Repair date is out of range' using errcode = '22023';
  end if;

  clean_workshop := nullif(btrim(workshop), '');
  if clean_workshop is not null and length(clean_workshop) > 120 then
    raise exception 'Workshop name must be 120 characters or fewer' using errcode = '22023';
  end if;

  -- Payer: null means the actor paid. A named payer must be an ACTIVE member of
  -- THIS workspace — an inactive or foreign member is rejected, mirroring how the
  -- settlement skips repairs whose payer is not active.
  if paid_by_member_id_value is not null then
    if not exists (
      select 1
      from public.ledger_members lm
      where lm.id = paid_by_member_id_value
        and lm.ledger_id = target_ledger_id
        and lm.is_active = true
    ) then
      raise exception 'Payer must be an active member of this workspace' using errcode = '22023';
    end if;
  end if;
  resolved_payer_member_id := coalesce(paid_by_member_id_value, actor_member_id);

  insert into public.vehicle_repairs (
    ledger_id, repair_date, description, cost_dkk, odo_km, workshop,
    created_by_member_id, paid_by_member_id
  ) values (
    target_ledger_id,
    coalesce(repair_date_value, current_date),
    clean_description,
    round(cost_dkk_value, 2),
    odo_km_value,
    clean_workshop,
    actor_member_id,
    resolved_payer_member_id
  )
  returning id into result_id;

  return jsonb_build_object('id', result_id);
end;
$$;

revoke all on function public.insert_repair(text, date, text, numeric, integer, text, uuid) from public;
revoke all on function public.insert_repair(text, date, text, numeric, integer, text, uuid) from anon;
grant execute on function public.insert_repair(text, date, text, numeric, integer, text, uuid) to authenticated;

-- ── calculate_period_settlement: LR splits + repair payer + created_at scoping ──
-- Re-declared off migration 107 (the newest prior definition). Trips/fuel CTEs
-- are byte-identical to 107; expense_share and repair_share now distribute via
-- the largest-remainder chain (expense_cents/expense_lr, repair_cents/repair_lr),
-- period_repairs/repair_paid credit coalesce(paid_by_member_id,
-- created_by_member_id), and repairs scope by created_at (GV-269).
create or replace function public.calculate_period_settlement(
  target_ledger_id text,
  target_period_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing settlement period id' using errcode = '22023';
  end if;

  if not public.is_operator_context()
     and not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can calculate settlements' using errcode = '42501';
  end if;

  with active_members as (
    select lm.id, lm.name
    from public.ledger_members lm
    where lm.ledger_id = target_ledger_id
      and lm.is_active = true
  ),
  live_trips as (
    select t.id,
           t.driver_member_id,
           greatest(t.end_km - t.start_km, 0)::numeric as km
    from public.trips t
    where t.ledger_id = target_ledger_id
      and t.period_id = target_period_id
      and t.deleted_at is null
  ),
  trip_assignees as (
    select lt.id as trip_id,
           lt.km,
           coalesce(
             valid_participants.member_ids,
             case when driver_check.id is not null then array[lt.driver_member_id] end
           ) as assignees
    from live_trips lt
    left join lateral (
      select array_agg(distinct tp.member_id) as member_ids
      from public.trip_participants tp
      join active_members am on am.id = tp.member_id
      where tp.trip_id = lt.id
    ) valid_participants on true
    left join active_members driver_check on driver_check.id = lt.driver_member_id
  ),
  km_shares as (
    select shared.member_id,
           ta.km / array_length(ta.assignees, 1) as share_km
    from trip_assignees ta
    cross join lateral unnest(ta.assignees) as shared(member_id)
    where ta.assignees is not null
      and array_length(ta.assignees, 1) > 0
  ),
  member_km as (
    -- Unrounded per-member km, reused both for the settlement km and as the
    -- usage-split weight (the client weights usage on raw km).
    select ks.member_id, sum(ks.share_km) as km_sum
    from km_shares ks
    group by ks.member_id
  ),
  fuel_paid as (
    select fp.payer_member_id as member_id,
           sum(fp.amount)::numeric as paid
    from public.fuel_payments fp
    where fp.ledger_id = target_ledger_id
      and fp.period_id = target_period_id
      and fp.deleted_at is null
      and fp.payer_member_id is not null
    group by fp.payer_member_id
  ),
  ledger_defaults as (
    select l.expense_split_defaults as defaults
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  repairs_mode as (
    -- The workspace rule that governs repair folding (GVM-307). null (old row,
    -- pre-107) behaves like deles_ikke: the mode filter below excludes every
    -- repair, matching a client that has no mode field to read.
    select l.repairs_split_mode as mode
    from public.ledgers l
    where l.id = target_ledger_id
  ),
  period_bounds as (
    -- Repairs have no period_id: a repair counts in the period whose
    -- [opened_at, closed_at) window contains its created_at — the moment it was
    -- LOGGED (GV-269; repair_date is display-only and may lie far in the past).
    -- The settling period is still open here (closed_at null), so its window has
    -- no upper bound.
    select sp.opened_at, sp.closed_at
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
  ),
  period_expenses as (
    -- Live expenses in this period whose payer is an active member (an expense
    -- with no active payer is skipped entirely, matching the client).
    select we.id,
           we.amount_dkk,
           we.paid_by_member_id,
           we.split_config,
           coalesce(nullif(we.split_rule, ''),
                    (ld.defaults ->> we.category),
                    'equal') as rule
    from public.workspace_expenses we
    cross join ledger_defaults ld
    join active_members payer on payer.id = we.paid_by_member_id
    where we.ledger_id = target_ledger_id
      and we.period_id = target_period_id
      and we.deleted_at is null
      and we.amount_dkk > 0
  ),
  expense_weights as (
    select pe.id as expense_id,
           pe.amount_dkk,
           am.id as member_id,
           case pe.rule
             when 'usage'  then coalesce(mk.km_sum, 0)
             when 'custom' then coalesce((pe.split_config ->> am.id::text)::numeric, 0)
             else 1::numeric
           end as weight
    from period_expenses pe
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  expense_weight_totals as (
    select expense_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from expense_weights
    group by expense_id
  ),
  expense_cents as (
    -- Largest-remainder split, step 1 (GV-269): per expense, work in integer
    -- oere and compute each member's exact (unrounded) share of them. A
    -- non-positive total weight falls back to equal weights, matching the
    -- pre-108 fallback and the client.
    select ew.expense_id,
           ew.member_id,
           round(ew.amount_dkk * 100) as total_cents,
           round(ew.amount_dkk * 100)
             * (case when ewt.total_weight > 0 then ew.weight else 1 end)
             / (case when ewt.total_weight > 0 then ewt.total_weight else ewt.member_count end)
             as exact_cents
    from expense_weights ew
    join expense_weight_totals ewt using (expense_id)
  ),
  expense_lr as (
    -- Step 2: floor every share, then hand the leftover oere (R = total oere -
    -- sum of floors, 0 <= R < member count) to the R members with the largest
    -- remainders; ties break on member id ascending (uuid byte order = its
    -- canonical text order), matching the client tie-break. Every expense's
    -- shares now sum EXACTLY to its amount.
    select ec.member_id,
           floor(ec.exact_cents)
             + case when row_number() over (
                      partition by ec.expense_id
                      order by ec.exact_cents - floor(ec.exact_cents) desc, ec.member_id asc
                    ) <= ec.total_cents - sum(floor(ec.exact_cents)) over (partition by ec.expense_id)
                    then 1 else 0 end
             as share_cents
    from expense_cents ec
  ),
  expense_share as (
    select el.member_id,
           sum(el.share_cents) / 100.0 as share
    from expense_lr el
    group by el.member_id
  ),
  expense_paid as (
    select pe.paid_by_member_id as member_id, sum(pe.amount_dkk)::numeric as paid
    from period_expenses pe
    group by pe.paid_by_member_id
  ),
  period_repairs as (
    -- Repairs folded per the workspace mode (GVM-307). Only efter_koersel /
    -- ligeligt fold; deles_ikke (or a null mode) yields no rows. The payer is
    -- paid_by_member_id, falling back to created_by_member_id for pre-108 rows
    -- (GV-269); a repair whose payer is not an active member is skipped
    -- entirely, exactly like an expense. Scoped by created_at (timestamps, no
    -- ::date truncation) within the period's [opened_at, closed_at) window.
    select vr.id,
           vr.cost_dkk,
           coalesce(vr.paid_by_member_id, vr.created_by_member_id) as payer_member_id,
           rm.mode
    from public.vehicle_repairs vr
    cross join repairs_mode rm
    cross join period_bounds pb
    join active_members payer on payer.id = coalesce(vr.paid_by_member_id, vr.created_by_member_id)
    where vr.ledger_id = target_ledger_id
      and vr.deleted_at is null
      and vr.cost_dkk > 0
      and rm.mode in ('efter_koersel', 'ligeligt')
      and vr.created_at >= pb.opened_at
      and (pb.closed_at is null or vr.created_at < pb.closed_at)
  ),
  repair_weights as (
    -- efter_koersel weights by each member's raw km (like the expense usage rule);
    -- ligeligt weights everyone equally. Zero total weight (efter_koersel with no
    -- km) falls back to an equal split below, matching the client.
    select pr.id as repair_id,
           pr.cost_dkk,
           am.id as member_id,
           case when pr.mode = 'efter_koersel' then coalesce(mk.km_sum, 0)
                else 1::numeric end as weight
    from period_repairs pr
    cross join active_members am
    left join member_km mk on mk.member_id = am.id
  ),
  repair_weight_totals as (
    select repair_id, sum(weight) as total_weight, count(*)::numeric as member_count
    from repair_weights
    group by repair_id
  ),
  repair_cents as (
    -- Largest-remainder split for repairs — identical to the expense chain above
    -- (GV-269).
    select rw.repair_id,
           rw.member_id,
           round(rw.cost_dkk * 100) as total_cents,
           round(rw.cost_dkk * 100)
             * (case when rwt.total_weight > 0 then rw.weight else 1 end)
             / (case when rwt.total_weight > 0 then rwt.total_weight else rwt.member_count end)
             as exact_cents
    from repair_weights rw
    join repair_weight_totals rwt using (repair_id)
  ),
  repair_lr as (
    select rc.member_id,
           floor(rc.exact_cents)
             + case when row_number() over (
                      partition by rc.repair_id
                      order by rc.exact_cents - floor(rc.exact_cents) desc, rc.member_id asc
                    ) <= rc.total_cents - sum(floor(rc.exact_cents)) over (partition by rc.repair_id)
                    then 1 else 0 end
             as share_cents
    from repair_cents rc
  ),
  repair_share as (
    select rl.member_id,
           sum(rl.share_cents) / 100.0 as share
    from repair_lr rl
    group by rl.member_id
  ),
  repair_paid as (
    select pr.payer_member_id as member_id, sum(pr.cost_dkk)::numeric as paid
    from period_repairs pr
    group by pr.payer_member_id
  ),
  per_member as (
    select am.id,
           am.name,
           round(coalesce(mk.km_sum, 0), 2) as km,
           round(coalesce(f.paid, 0), 2) as fuel_paid,
           round(coalesce(xp.paid, 0), 2) as expense_paid,
           round(coalesce(xs.share, 0), 2) as expense_share,
           round(coalesce(rp.paid, 0), 2) as repair_paid,
           round(coalesce(rs.share, 0), 2) as repair_share
    from active_members am
    left join member_km mk on mk.member_id = am.id
    left join fuel_paid f on f.member_id = am.id
    left join expense_paid xp on xp.member_id = am.id
    left join expense_share xs on xs.member_id = am.id
    left join repair_paid rp on rp.member_id = am.id
    left join repair_share rs on rs.member_id = am.id
  ),
  totals as (
    select coalesce(sum(pm.km), 0) as total_km,
           coalesce(sum(pm.fuel_paid), 0) as total_paid,
           coalesce(sum(pm.expense_paid), 0) as total_expenses,
           coalesce(sum(pm.repair_paid), 0) as total_repairs
    from per_member pm
  )
  select jsonb_build_object(
    'totalKm', t.total_km,
    'totalPaid', t.total_paid,
    'totalExpenses', t.total_expenses,
    'totalRepairs', t.total_repairs,
    'fuelRate', case when t.total_km > 0 then round(t.total_paid / t.total_km, 2) else 0 end,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pm.id,
        'name', pm.name,
        'km', pm.km,
        'fuelPaid', pm.fuel_paid,
        'expensePaid', pm.expense_paid,
        'expenseShare', pm.expense_share,
        'repairPaid', pm.repair_paid,
        'repairShare', pm.repair_share,
        'tripCost', case when t.total_km > 0 then round(pm.km * (t.total_paid / t.total_km), 2) else 0 end,
        'net', case when t.total_km > 0
                    then round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - round(pm.km * (t.total_paid / t.total_km), 2) - pm.expense_share - pm.repair_share, 2)
                    else round(pm.fuel_paid + pm.expense_paid + pm.repair_paid - pm.expense_share - pm.repair_share, 2) end
      ) order by pm.id::text collate "C")
      from per_member pm
    ), '[]'::jsonb)
  )
  into result
  from totals t;

  return result;
end;
$$;

revoke all on function public.calculate_period_settlement(text, uuid) from public;
revoke all on function public.calculate_period_settlement(text, uuid) from anon;
grant execute on function public.calculate_period_settlement(text, uuid) to authenticated;

-- ── Register migration ──────────────────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('108_repair_payer_and_lr_splits',
        'Repair payer + largest-remainder splits + repair validation (GV-269). vehicle_repairs.paid_by_member_id added (backfilled to created_by_member_id; settlement reads the coalesce). insert_repair re-declared off 105 (6-arg dropped, trailing paid_by_member_id_value uuid param) with financial validation: trimmed description required <= 500 chars, cost required > 0 (rounded to 2 decimals), odometer >= 0, repair_date within [2000-01-01, today + 1 year], workshop <= 120 chars, payer must be an active member of the workspace. calculate_period_settlement re-declared off 107: expense_share and repair_share now use per-item largest-remainder distribution in integer oere (floor + remainder rank, ties by member id ascending) so every item''s shares sum exactly to its amount; repairs credit coalesce(paid_by_member_id, created_by_member_id) and scope by created_at within the period''s [opened_at, closed_at) window instead of repair_date. Mirrored by the mobile settlement engine (GVM-309).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 109: notification snooze + quiet hours (GVM-286) ──────────────────
-- Verbatim from 109_notification_snooze_quiet_hours.sql: snooze_until (one-shot
-- pause) + quiet hours (recurring nightly window, Europe/Copenhagen, default 22->7)
-- on notification_preferences; get/set RPCs re-declared off 095 with the new
-- columns/params. Timezone math lives in the govehlo-web push filter; this stores
-- raw hours only.
alter table public.notification_preferences
  add column if not exists snooze_until timestamptz,
  add column if not exists quiet_hours_enabled boolean not null default false,
  add column if not exists quiet_start_hour smallint not null default 22,
  add column if not exists quiet_end_hour smallint not null default 7;

alter table public.notification_preferences
  drop constraint if exists notification_preferences_quiet_start_hour_check;
alter table public.notification_preferences
  add constraint notification_preferences_quiet_start_hour_check
  check (quiet_start_hour >= 0 and quiet_start_hour <= 23);

alter table public.notification_preferences
  drop constraint if exists notification_preferences_quiet_end_hour_check;
alter table public.notification_preferences
  add constraint notification_preferences_quiet_end_hour_check
  check (quiet_end_hour >= 0 and quiet_end_hour <= 23);

comment on table public.notification_preferences is
  'Per-user push notification controls. Three category toggles (activity/payments/periods, GVM-119, default all-on) plus snooze_until (one-shot pause) and quiet hours (recurring nightly window, Europe/Copenhagen, default 22->7, GVM-286). Read by the govehlo-web push hooks (service role) to skip a recipient who has muted a category, is snoozed, or is inside their quiet window.';

-- get_notification_preferences: return type changes (adds snooze + quiet columns), so
-- drop and recreate. Re-declared off migration 095 (the newest prior definition). A
-- missing row still defaults every category on, snooze null, quiet disabled at 22->7.
drop function if exists public.get_notification_preferences();
create function public.get_notification_preferences()
returns table (
  activity_enabled boolean,
  payments_enabled boolean,
  periods_enabled boolean,
  snooze_until timestamptz,
  quiet_hours_enabled boolean,
  quiet_start_hour smallint,
  quiet_end_hour smallint
)
language sql
stable
security definer
set search_path = public
as $$
  select
    coalesce(np.activity_enabled, true),
    coalesce(np.payments_enabled, true),
    coalesce(np.periods_enabled, true),
    np.snooze_until,
    coalesce(np.quiet_hours_enabled, false),
    coalesce(np.quiet_start_hour, 22::smallint),
    coalesce(np.quiet_end_hour, 7::smallint)
  from (select auth.uid() as uid) me
  left join public.notification_preferences np on np.user_id = me.uid;
$$;

revoke all on function public.get_notification_preferences() from public;
grant execute on function public.get_notification_preferences() to authenticated;

-- set_notification_preferences: signature changes (adds trailing snooze + quiet
-- params), so drop the (boolean,boolean,boolean) version and recreate. Re-declared off
-- migration 095. Params are suffixed *_value so they never collide with the columns of
-- the same name (PL/pgSQL ON CONFLICT shadowing guard).
drop function if exists public.set_notification_preferences(boolean, boolean, boolean);
create function public.set_notification_preferences(
  activity boolean,
  payments boolean,
  periods boolean,
  snooze_until_value timestamptz default null,
  quiet_hours_enabled_value boolean default false,
  quiet_start_hour_value smallint default 22,
  quiet_end_hour_value smallint default 7
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Notification preferences require a signed-in user' using errcode = '42501';
  end if;
  if quiet_start_hour_value is null or quiet_start_hour_value < 0 or quiet_start_hour_value > 23 then
    raise exception 'quiet_start_hour must be between 0 and 23' using errcode = '22023';
  end if;
  if quiet_end_hour_value is null or quiet_end_hour_value < 0 or quiet_end_hour_value > 23 then
    raise exception 'quiet_end_hour must be between 0 and 23' using errcode = '22023';
  end if;
  if coalesce(quiet_hours_enabled_value, false) and quiet_start_hour_value = quiet_end_hour_value then
    raise exception 'quiet hours start and end must differ when enabled' using errcode = '22023';
  end if;
  if snooze_until_value is not null
     and (snooze_until_value <= now() - interval '1 minute'
          or snooze_until_value > now() + interval '30 days') then
    raise exception 'snooze_until must be in the future and at most 30 days out' using errcode = '22023';
  end if;
  insert into public.notification_preferences (
    user_id, activity_enabled, payments_enabled, periods_enabled,
    snooze_until, quiet_hours_enabled, quiet_start_hour, quiet_end_hour, updated_at
  )
  values (
    v_uid,
    coalesce(activity, true),
    coalesce(payments, true),
    coalesce(periods, true),
    snooze_until_value,
    coalesce(quiet_hours_enabled_value, false),
    quiet_start_hour_value,
    quiet_end_hour_value,
    now()
  )
  on conflict (user_id) do update
  set activity_enabled = excluded.activity_enabled,
      payments_enabled = excluded.payments_enabled,
      periods_enabled = excluded.periods_enabled,
      snooze_until = excluded.snooze_until,
      quiet_hours_enabled = excluded.quiet_hours_enabled,
      quiet_start_hour = excluded.quiet_start_hour,
      quiet_end_hour = excluded.quiet_end_hour,
      updated_at = now();
end;
$$;

revoke all on function public.set_notification_preferences(boolean, boolean, boolean, timestamptz, boolean, smallint, smallint) from public;
grant execute on function public.set_notification_preferences(boolean, boolean, boolean, timestamptz, boolean, smallint, smallint) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('109_notification_snooze_quiet_hours',
        'Notification snooze + quiet hours (GVM-286) — notification_preferences gains snooze_until (one-shot pause) + quiet_hours_enabled/quiet_start_hour/quiet_end_hour (recurring nightly window, Europe/Copenhagen, default 22->7, hours 0..23). get/set RPCs re-declared off 095 with the new columns/params; set validates hours, enabled start<>end, and snooze null-or-future <=30 days. Both controls suppress ALL push categories in the govehlo-web hooks (instant drop, scheduled defer).')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Sweep: generate_all_due_recurring_expenses (service role) ─────────────────
-- Per-ledger body mirrors generate_due_recurring_expenses verbatim; iterates every ledger
-- with a due active template and materialises occurrences into that ledger's open period
-- with the same idempotence key, so client + scheduler never double-generate (GV-272).
create or replace function public.generate_all_due_recurring_expenses(
  batch_limit integer default 200
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  due_ledger record;
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  ledger_generated integer;
  total_generated integer := 0;
  ledgers_touched integer := 0;
  ledgers_scanned integer := 0;
begin
  for due_ledger in
    select distinct r.ledger_id
    from public.recurring_expenses r
    where r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
    order by r.ledger_id
    limit greatest(coalesce(batch_limit, 200), 0)
  loop
    ledgers_scanned := ledgers_scanned + 1;

    -- Materialise into the ledger's open period. If none is open (a period close
    -- briefly precedes the next open), skip this ledger this run; the next tick catches
    -- up. FOR SHARE serializes against a concurrent close (which exclusively locks the
    -- period row).
    select sp.id into open_period_id
    from public.settlement_periods sp
    where sp.ledger_id = due_ledger.ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    order by sp.opened_at desc
    limit 1
    for share of sp;

    if open_period_id is null then
      open_period_id := null;
      continue;
    end if;

    ledger_generated := 0;

    for tmpl in
      select *
      from public.recurring_expenses r
      where r.ledger_id = due_ledger.ledger_id
        and r.is_active
        and r.deleted_at is null
        and r.next_due_date <= current_date
      order by r.next_due_date
      for update skip locked
    loop
      due_date := tmpl.next_due_date;
      template_count := 0;

      while due_date <= current_date loop
        insert into public.workspace_expenses (
          ledger_id, period_id, category, description, amount_dkk, expense_date,
          split_rule, split_config, paid_by_member_id, created_by_member_id,
          recurring_expense_id, occurrence_date
        ) values (
          due_ledger.ledger_id,
          open_period_id,
          tmpl.category,
          tmpl.description,
          tmpl.amount_dkk,
          due_date,
          tmpl.split_rule,
          tmpl.split_config,
          tmpl.paid_by_member_id,
          tmpl.created_by_member_id,
          tmpl.id,
          due_date
        )
        on conflict (recurring_expense_id, occurrence_date)
          where recurring_expense_id is not null do nothing
        returning id into inserted_id;

        if inserted_id is not null then
          template_count := template_count + 1;
        end if;
        inserted_id := null;

        due_date := (case tmpl.cadence
          when 'monthly' then due_date + interval '1 month'
          when 'quarterly' then due_date + interval '3 months'
          when 'semiannual' then due_date + interval '6 months'
          when 'yearly' then due_date + interval '1 year'
          else due_date + interval '1 month'
        end)::date;
      end loop;

      update public.recurring_expenses
        set next_due_date = due_date, last_generated_at = now(), updated_at = now()
      where id = tmpl.id;

      if template_count > 0 then
        insert into public.ledger_events (
          ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
        ) values (
          due_ledger.ledger_id,
          'expense_recurring_added',
          'Fast udgift tilføjet',
          coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
            || ' blev automatisk tilføjet og delt.',
          null,
          null,
          jsonb_build_object(
            'category', tmpl.category,
            'recurring_expense_id', tmpl.id,
            'count', template_count
          )
        );
        ledger_generated := ledger_generated + template_count;
      end if;
    end loop;

    if ledger_generated > 0 then
      ledgers_touched := ledgers_touched + 1;
      total_generated := total_generated + ledger_generated;
    end if;

    open_period_id := null;
  end loop;

  return jsonb_build_object(
    'generated', total_generated,
    'ledgers_touched', ledgers_touched,
    'ledgers_scanned', ledgers_scanned
  );
end;
$$;

revoke execute on function public.generate_all_due_recurring_expenses(integer) from public;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from anon;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from authenticated;
grant execute on function public.generate_all_due_recurring_expenses(integer) to service_role;

