create or replace function public.owner_workspace_overview_page(
  p_limit integer default 100,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'p_limit must be between 1 and 200' using errcode = '22023';
  end if;
  if p_offset is null or p_offset < 0 or p_offset > 100000 then
    raise exception 'p_offset must be between 0 and 100000' using errcode = '22023';
  end if;

  with page as (
    select l.id, l.slug, l.name, l.created_at, l.updated_at, l.deleted_at
    from public.ledgers l
    order by l.created_at asc, l.id asc
    limit p_limit
    offset p_offset
  ),
  member_stats as (
    select lm.ledger_id,
           count(*)::integer as member_count,
           count(*) filter (where lm.role in ('admin', 'owner'))::integer as admin_count,
           count(*) filter (where lm.role = 'owner')::integer as owner_count,
           count(*) filter (where lm.role = 'admin')::integer as role_admin_count,
           count(*) filter (where lm.role not in ('owner', 'admin'))::integer as role_member_count,
           (array_agg(
             lm.email
             order by case lm.role when 'owner' then 0 when 'admin' then 1 else 2 end,
                      lm.created_at asc,
                      lm.id asc
           ) filter (where lm.email is not null))[1] as contact_email
    from public.ledger_members lm
    join page p on p.id = lm.ledger_id
    where lm.is_active = true
    group by lm.ledger_id
  ),
  open_periods as (
    select sp.ledger_id, true as has_open_period, max(sp.label) as open_period_label
    from public.settlement_periods sp
    join page p on p.id = sp.ledger_id
    where sp.status = 'open'
    group by sp.ledger_id
  ),
  request_stats as (
    select sr.ledger_id,
           count(*) filter (where sr.status = 'requested')::integer as stale_requests
    from public.settlement_requests sr
    join page p on p.id = sr.ledger_id
    group by sr.ledger_id
  ),
  activity_stats as (
    select oal.ledger_id,
           max(oal.created_at) as last_activity_at,
           count(*) filter (
             where oal.ok = false
               and oal.created_at >= now() - interval '7 days'
           )::integer as error_count_7d
    from public.owner_activity_log oal
    join page p on p.id = oal.ledger_id
    group by oal.ledger_id
  ),
  overview as (
    select p.*,
           coalesce(ms.member_count, 0) as member_count,
           coalesce(ms.admin_count, 0) as admin_count,
           coalesce(ms.owner_count, 0) as owner_count,
           coalesce(ms.role_admin_count, 0) as role_admin_count,
           coalesce(ms.role_member_count, 0) as role_member_count,
           coalesce(ms.contact_email, '') as contact_email,
           coalesce(op.has_open_period, false) as has_open_period,
           coalesce(op.open_period_label, '') as open_period_label,
           coalesce(rs.stale_requests, 0) as stale_requests,
           coalesce(ast.error_count_7d, 0) as error_count_7d,
           coalesce(ast.last_activity_at, p.updated_at) as last_activity_at
    from page p
    left join member_stats ms on ms.ledger_id = p.id
    left join open_periods op on op.ledger_id = p.id
    left join request_stats rs on rs.ledger_id = p.id
    left join activity_stats ast on ast.ledger_id = p.id
  )
  select jsonb_build_object(
    'totalWorkspaces', (select count(*) from public.ledgers),
    'workspaces', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', o.id,
        'name', coalesce(o.name, o.id),
        'slug', coalesce(o.slug, ''),
        'ownerEmail', o.contact_email,
        'memberCount', o.member_count,
        'adminCount', o.admin_count,
        'roles', concat_ws(', ',
          case when o.owner_count > 0 then o.owner_count || ' owner' || case when o.owner_count = 1 then '' else 's' end end,
          case when o.role_admin_count > 0 then o.role_admin_count || ' admin' || case when o.role_admin_count = 1 then '' else 's' end end,
          case when o.role_member_count > 0 then o.role_member_count || ' member' || case when o.role_member_count = 1 then '' else 's' end end
        ),
        'createdAt', o.created_at,
        'deletedAt', o.deleted_at,
        'lastActivityAt', o.last_activity_at,
        'health', jsonb_build_object(
          'openPeriod', o.has_open_period,
          'openPeriodLabel', o.open_period_label,
          'staleRequests', o.stale_requests,
          'errorCount7d', o.error_count_7d,
          'status', case
            when o.error_count_7d > 0 then 'error'
            when o.stale_requests > 0 then 'warning'
            else 'ok'
          end
        )
      ) order by o.created_at asc, o.id asc
    ), '[]'::jsonb)
  ) into result
  from overview o;

  return result;
end;
$$;

revoke all on function public.owner_workspace_overview_page(integer, integer) from public;
revoke all on function public.owner_workspace_overview_page(integer, integer) from anon;
revoke all on function public.owner_workspace_overview_page(integer, integer) from authenticated;
grant execute on function public.owner_workspace_overview_page(integer, integer) to service_role;

create or replace function public.run_operational_retention(
  p_stale_push_days integer default 180,
  p_dry_run boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_stale_tokens integer := 0;
  v_expired_events integer := 0;
  v_deleted_messages integer := 0;
  v_deleted_bookings integer := 0;
  v_deleted_recurring_templates integer := 0;
  v_deleted_trips integer := 0;
  v_deleted_fuel_payments integer := 0;
  v_deleted_workspace_expenses integer := 0;
  v_deleted_vehicle_repairs integer := 0;
  v_deleted_owner_activity integer := 0;
  v_purged_workspaces integer := 0;
  v_short_cutoff timestamptz := now() - interval '90 days';
  v_financial_cutoff timestamptz := date_trunc('year', now()) - interval '5 years';
  v_audit_cutoff timestamptz := now() - interval '24 months';
  v_workspace_cutoff timestamptz := now() - interval '90 days';
begin
  if p_stale_push_days is null or p_stale_push_days < 30 or p_stale_push_days > 3650 then
    raise exception 'p_stale_push_days must be between 30 and 3650' using errcode = '22023';
  end if;
  if p_dry_run is null then
    raise exception 'p_dry_run must not be null' using errcode = '22023';
  end if;

  if p_dry_run then
    select count(*) into v_stale_tokens from public.expo_push_tokens
    where updated_at < now() - make_interval(days => p_stale_push_days);
    select count(*) into v_expired_events from public.ledger_events
    where expires_at is not null and expires_at < now();
    select count(*) into v_deleted_messages from public.messages where deleted_at < v_short_cutoff;
    select count(*) into v_deleted_bookings from public.car_bookings where deleted_at < v_short_cutoff;
    select count(*) into v_deleted_recurring_templates from public.recurring_expenses where deleted_at < v_short_cutoff;
    select count(*) into v_deleted_trips from public.trips where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_fuel_payments from public.fuel_payments where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_workspace_expenses from public.workspace_expenses where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_vehicle_repairs from public.vehicle_repairs where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_owner_activity from public.owner_activity_log where created_at < v_audit_cutoff;
    select count(*) into v_purged_workspaces from public.ledgers where deleted_at < v_workspace_cutoff;
  else
    with purged as (delete from public.expo_push_tokens where updated_at < now() - make_interval(days => p_stale_push_days) returning 1)
      select count(*) into v_stale_tokens from purged;
    with purged as (delete from public.ledger_events where expires_at is not null and expires_at < now() returning 1)
      select count(*) into v_expired_events from purged;
    with purged as (delete from public.messages where deleted_at < v_short_cutoff returning 1)
      select count(*) into v_deleted_messages from purged;
    with purged as (delete from public.car_bookings where deleted_at < v_short_cutoff returning 1)
      select count(*) into v_deleted_bookings from purged;
    with purged as (delete from public.recurring_expenses where deleted_at < v_short_cutoff returning 1)
      select count(*) into v_deleted_recurring_templates from purged;

    -- Closed-period entry triggers deliberately freeze accounting history. The
    -- account-deletion path already uses this transaction-local gate for GDPR
    -- scrubs; enable it only inside this service-role-only function and only
    -- around tombstones that have outlived the accounting retention window.
    perform set_config('govehlo.pii_scrub', '1', true);
    with purged as (delete from public.trips where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_trips from purged;
    with purged as (delete from public.fuel_payments where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_fuel_payments from purged;
    with purged as (delete from public.workspace_expenses where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_workspace_expenses from purged;
    with purged as (delete from public.vehicle_repairs where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_vehicle_repairs from purged;

    -- GV-316: purge workspaces whose operator decommission tombstone has
    -- outlived the 90-day grace window. On delete cascade removes every child
    -- row; the closed-period locks stand aside for a whole-workspace teardown
    -- (settlement_periods delete first). Kept inside the pii_scrub gate for
    -- parity with the financial-row purges above.
    with purged as (delete from public.ledgers where deleted_at < v_workspace_cutoff returning 1)
      select count(*) into v_purged_workspaces from purged;
    perform set_config('govehlo.pii_scrub', '', true);
    with purged as (delete from public.owner_activity_log where created_at < v_audit_cutoff returning 1)
      select count(*) into v_deleted_owner_activity from purged;
  end if;

  return jsonb_build_object(
    'staleExpoPushTokens', v_stale_tokens,
    'expiredLedgerEvents', v_expired_events,
    'deletedMessages', v_deleted_messages,
    'deletedBookings', v_deleted_bookings,
    'deletedRecurringTemplates', v_deleted_recurring_templates,
    'deletedTrips', v_deleted_trips,
    'deletedFuelPayments', v_deleted_fuel_payments,
    'deletedWorkspaceExpenses', v_deleted_workspace_expenses,
    'deletedVehicleRepairs', v_deleted_vehicle_repairs,
    'deletedOwnerActivity', v_deleted_owner_activity,
    'purgedWorkspaces', v_purged_workspaces,
    'dryRun', p_dry_run,
    'staleDays', p_stale_push_days,
    'shortRetentionDays', 90,
    'financialRetentionYears', 5,
    'auditRetentionMonths', 24,
    'workspaceGraceDays', 90,
    'ranAt', now()
  );
end;
$$;

revoke all on function public.run_operational_retention(integer, boolean) from public;
revoke all on function public.run_operational_retention(integer, boolean) from anon;
revoke all on function public.run_operational_retention(integer, boolean) from authenticated;
grant execute on function public.run_operational_retention(integer, boolean) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '132_workspace_lifecycle',
  'Operator workspace decommission lifecycle (GV-316): ledgers.deleted_at tombstone + partial index; is_ledger_member / is_ledger_admin / current_ledger_member_id gated on deleted_at is null so a soft-deleted workspace is invisible and read-only to members; service-role-only admin_soft_delete_workspace / admin_restore_workspace (idempotent, Danish ledger_events notification, system actor); owner_workspace_overview_page surfaces deletedAt so the operator can still see and badge tombstoned workspaces; run_operational_retention purges workspaces past the 90-day grace window (cascade) and reports purgedWorkspaces. Inactivity never auto-deletes a workspace.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 133: harden the workspace-lifecycle RPCs (GV-328) ───────────────
create or replace function public.admin_soft_delete_workspace(p_ledger_id text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
  v_deleted_at timestamptz;
  v_now timestamptz := now();
begin
  -- GV-328 (b): lock the ledger row so concurrent lifecycle calls serialize. A
  -- second caller blocks here until the first commits, then reads the fresh
  -- deleted_at and takes the idempotent no-op branch below instead of both
  -- passing the state check and emitting duplicate decommission events.
  select l.name, l.deleted_at
    into v_name, v_deleted_at
  from public.ledgers l
  where l.id = p_ledger_id
  for update;

  if not found then
    raise exception 'Workspace % does not exist', p_ledger_id using errcode = '22023';
  end if;

  -- GV-328 idempotency contract: a repeat soft-delete of an already-tombstoned
  -- workspace is a NO-OP, not an error. Echo the ORIGINAL tombstone with
  -- alreadyApplied=true and emit NO second decommission event.
  if v_deleted_at is not null then
    return jsonb_build_object('id', p_ledger_id, 'deletedAt', v_deleted_at, 'graceDays', 90, 'alreadyApplied', true);
  end if;

  update public.ledgers l
  set deleted_at = v_now,
      updated_at = v_now
  where l.id = p_ledger_id;

  insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
  values (
    p_ledger_id,
    'workspace_decommissioned',
    'Workspacet er nedlagt',
    'Workspacet ' || coalesce(nullif(btrim(v_name), ''), p_ledger_id) || ' er nedlagt af operatøren; data slettes permanent efter 90 dage.',
    null,
    null,
    jsonb_build_object('decommissioned_at', v_now, 'grace_days', 90)
  );

  return jsonb_build_object('id', p_ledger_id, 'deletedAt', v_now, 'graceDays', 90, 'alreadyApplied', false);
end;
$$;

create or replace function public.admin_restore_workspace(p_ledger_id text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
  v_deleted_at timestamptz;
  v_now timestamptz := now();
  v_grace_cutoff timestamptz := now() - interval '90 days';
begin
  -- GV-328 (b): lock the ledger row so concurrent lifecycle calls serialize (see
  -- admin_soft_delete_workspace). The second caller reads the fresh state and
  -- takes the idempotent no-op branch instead of emitting a duplicate event.
  select l.name, l.deleted_at
    into v_name, v_deleted_at
  from public.ledgers l
  where l.id = p_ledger_id
  for update;

  if not found then
    raise exception 'Workspace % does not exist', p_ledger_id using errcode = '22023';
  end if;

  -- GV-328 idempotency contract: restoring a workspace that is already live is a
  -- NO-OP (alreadyApplied=true, restoredAt=null, no restore event), not an error.
  if v_deleted_at is null then
    return jsonb_build_object('id', p_ledger_id, 'restoredAt', null, 'alreadyApplied', true);
  end if;

  -- GV-328 (a): enforce the 90-day grace window. Once the tombstone has outlived
  -- it the workspace is purge-pending — run_operational_retention is entitled to
  -- delete it permanently at any moment, and the notification already promised
  -- members permanent deletion after 90 days — so restore must FAIL rather than
  -- resurrect data past its deletion date, even if the nightly sweep has not run
  -- yet. This is a genuinely invalid transition: raise a clean Danish message
  -- with the distinct errcode 'GV328' so the console can badge it specifically.
  if v_deleted_at < v_grace_cutoff then
    raise exception 'Gendannelsesfristen på 90 dage er udløbet' using errcode = 'GV328';
  end if;

  update public.ledgers l
  set deleted_at = null,
      updated_at = v_now
  where l.id = p_ledger_id;

  insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
  values (
    p_ledger_id,
    'workspace_restored',
    'Workspacet er gendannet',
    'Workspacet ' || coalesce(nullif(btrim(v_name), ''), p_ledger_id) || ' er gendannet af operatøren og er tilgængeligt igen.',
    null,
    null,
    jsonb_build_object('restored_at', v_now)
  );

  return jsonb_build_object('id', p_ledger_id, 'restoredAt', v_now, 'alreadyApplied', false);
end;
$$;

revoke all on function public.admin_soft_delete_workspace(text) from public;
revoke all on function public.admin_soft_delete_workspace(text) from anon;
revoke all on function public.admin_soft_delete_workspace(text) from authenticated;
grant execute on function public.admin_soft_delete_workspace(text) to service_role;

revoke all on function public.admin_restore_workspace(text) from public;
revoke all on function public.admin_restore_workspace(text) from anon;
revoke all on function public.admin_restore_workspace(text) from authenticated;
grant execute on function public.admin_restore_workspace(text) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '133_workspace_lifecycle_hardening',
  'Harden the workspace-lifecycle RPCs (GV-328): admin_soft_delete_workspace / admin_restore_workspace now take select ... for update on the ledgers row before the state check so concurrent calls serialize (no duplicate lifecycle events); admin_restore_workspace enforces the 90-day grace window and raises errcode GV328 (''Gendannelsesfristen på 90 dage er udløbet'') once the tombstone is purge-pending; repeated soft-delete of a tombstoned workspace and restore of a live workspace are now honest no-ops (alreadyApplied=true, no second event) instead of mislabelled idempotency errors, while a missing workspace stays 22023.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

create or replace function public.get_my_decommissioned_workspaces()
returns table (
  ledger_id text,
  name text,
  deleted_at timestamptz,
  purge_after timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  -- Reproduces is_ledger_member's membership conditions (migration 132) via an
  -- EXISTS against public.ledger_members, but selects only tombstoned workspaces
  -- (`l.deleted_at is not null`) instead of live ones. The EXISTS keeps exactly
  -- one row per workspace and every column is fully qualified for the ambiguity
  -- guard. purge_after = deleted_at + 90 days matches the retention sweep.
  select
    l.id as ledger_id,
    l.name as name,
    l.deleted_at as deleted_at,
    (l.deleted_at + interval '90 days') as purge_after
  from public.ledgers l
  where l.deleted_at is not null
    and exists (
      select 1
      from public.ledger_members lm
      where lm.ledger_id = l.id
        and lm.is_active = true
        and lm.email is not null
        and lower(lm.email) = public.current_user_email()
    );
$$;

grant execute on function public.get_my_decommissioned_workspaces() to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '134_decommissioned_workspace_notices',
  'Durable in-app decommission notice (GV-330): read-only SECURITY DEFINER get_my_decommissioned_workspaces() returns (ledger_id, name, deleted_at, purge_after) for every tombstoned workspace the caller still belongs to. It reproduces is_ledger_member''s membership conditions except the deleted_at gate (requiring deleted_at is not null) so members keep a durable notice after migration 132 revokes their read access; purge_after is deleted_at + 90 days, matching run_operational_retention. Read-only, writes nothing; granted to authenticated.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

revoke all on function public.get_my_decommissioned_workspaces() from public;
revoke all on function public.get_my_decommissioned_workspaces() from anon;
grant execute on function public.get_my_decommissioned_workspaces() to authenticated;

drop function if exists public.admin_soft_delete_workspace(text);

create function public.admin_soft_delete_workspace(
  p_ledger_id text,
  p_ack_export_offered boolean default null,
  p_ack_no_legal_hold boolean default null,
  p_operator_email text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text;
  v_deleted_at timestamptz;
  v_now timestamptz := now();
begin
  -- GV-328 (b): lock the ledger row so concurrent lifecycle calls serialize. A
  -- second caller blocks here until the first commits, then reads the fresh
  -- deleted_at and takes the idempotent no-op branch below instead of both
  -- passing the state check and emitting duplicate decommission events.
  select l.name, l.deleted_at
    into v_name, v_deleted_at
  from public.ledgers l
  where l.id = p_ledger_id
  for update;

  if not found then
    raise exception 'Workspace % does not exist', p_ledger_id using errcode = '22023';
  end if;

  -- GV-328 idempotency contract: a repeat soft-delete of an already-tombstoned
  -- workspace is a NO-OP, not an error. Echo the ORIGINAL tombstone with
  -- alreadyApplied=true and emit NO second decommission event. Nothing new happens,
  -- so this path deliberately requires NO acknowledgements and writes NO attestation.
  if v_deleted_at is not null then
    return jsonb_build_object('id', p_ledger_id, 'deletedAt', v_deleted_at, 'graceDays', 90, 'alreadyApplied', true);
  end if;

  -- GV-333: a NEW decommission deliberately OVERRIDES the 5-year financial-retention
  -- window (docs/gdpr/retention.md), so the operator must actively attest both
  -- pre-decommission checklist points. Require both strictly true, or reject with a
  -- Danish message under a DISTINCT errcode 'GV333' (not the missing-workspace 22023)
  -- so the console can surface it as a 400 rather than the residual 409 conflict.
  -- Nothing is tombstoned or journaled on this path.
  if p_ack_export_offered is not true or p_ack_no_legal_hold is not true then
    raise exception 'Nedlæggelse kræver bekræftelse af begge tjeklistepunkter (dataeksport tilbudt og ingen legal hold)' using errcode = 'GV333';
  end if;

  update public.ledgers l
  set deleted_at = v_now,
      updated_at = v_now
  where l.id = p_ledger_id;

  insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
  values (
    p_ledger_id,
    'workspace_decommissioned',
    'Workspacet er nedlagt',
    'Workspacet ' || coalesce(nullif(btrim(v_name), ''), p_ledger_id) || ' er nedlagt af operatøren; data slettes permanent efter 90 dage.',
    null,
    null,
    jsonb_build_object('decommissioned_at', v_now, 'grace_days', 90)
  );

  -- GV-333: durable, atomic attestation. Committed in the SAME transaction as the
  -- tombstone so a decommission can NEVER happen without the acknowledgements being
  -- retained. ledger_id is NULL (console-level, migration 048) ON PURPOSE: it keeps
  -- this row OUT of the ON DELETE CASCADE that fires when run_operational_retention
  -- purges the workspace at 90 days, so the attestation outlives the workspace and
  -- is governed by owner_activity_log's own 24-month retention class. The workspace
  -- identity is preserved in workspace_label + metadata.ledgerId; the action label
  -- and 'owner' actor_role match what govehlo-web's recordOwnerActivity() writes for
  -- this route, and metadata.source='rpc' distinguishes this durable row from the
  -- fail-soft withOwnerAudit route log. No tokens/PII beyond the operator email.
  insert into public.owner_activity_log (
    ledger_id, workspace_label, actor_email, actor_role,
    route, action, result_code, status_code, ok, summary, metadata
  ) values (
    null,
    coalesce(nullif(btrim(v_name), ''), p_ledger_id),
    p_operator_email,
    'owner',
    'rpc:admin_soft_delete_workspace',
    'owner.workspace.decommission',
    'OK',
    200,
    true,
    'decommission attestation',
    jsonb_build_object(
      'acknowledgements', jsonb_build_object('exportOffered', true, 'noLegalHold', true),
      'source', 'rpc',
      'ledgerId', p_ledger_id
    )
  );

  return jsonb_build_object('id', p_ledger_id, 'deletedAt', v_now, 'graceDays', 90, 'alreadyApplied', false);
end;
$$;

revoke all on function public.admin_soft_delete_workspace(text, boolean, boolean, text) from public;
revoke all on function public.admin_soft_delete_workspace(text, boolean, boolean, text) from anon;
revoke all on function public.admin_soft_delete_workspace(text, boolean, boolean, text) from authenticated;
grant execute on function public.admin_soft_delete_workspace(text, boolean, boolean, text) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '135_workspace_decommission_attestation',
  'Decommission grants hardening + atomic attestation (GV-333): revoke the implicit PUBLIC/anon EXECUTE on get_my_decommissioned_workspaces() left by migration 134 (authenticated only); admin_soft_delete_workspace now takes trailing p_ack_export_offered / p_ack_no_legal_hold / p_operator_email params, REQUIRES both acks strictly true on the path that performs a NEW soft-delete (else raises Danish errcode ''GV333''), and writes ONE durable owner_activity_log attestation row in the same transaction with a NULL ledger_id so it survives the 90-day workspace-purge cascade (identity kept in workspace_label + metadata; source=rpc). The idempotent alreadyApplied no-op requires no acks and writes no attestation. Row lock, 22023 missing-workspace guard, Danish ledger_events notice and service-role-only grant carried over unchanged from migration 133.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();
-- Migration 136: atomic booking-trip fuel completion (GV-334)
--
-- A booking-linked trip was persisted before its required refuel was reviewed.
-- Dismissing or interrupting the second screen therefore left the booking looking
-- complete while the tank model and settlement were missing the fuel event. Store
-- an explicit resolution on the trip and provide one idempotent command that saves
-- the trip plus an optional real fuel payment in the same transaction.

alter table public.trips
  add column if not exists fuel_resolution text;

alter table public.trips
  add column if not exists completion_fuel_legacy_id text;

alter table public.trips
  drop constraint if exists trips_fuel_resolution_check;

alter table public.trips
  add constraint trips_fuel_resolution_check check (
    fuel_resolution is null
    or fuel_resolution in ('logged', 'deferred', 'not_refuelled', 'not_needed')
  );

create index if not exists trips_deferred_fuel_resolution_idx
  on public.trips (ledger_id, updated_at)
  where deleted_at is null and fuel_resolution = 'deferred';

-- Direct/RLS writes must not claim a logged refuel unless the referenced active
-- fuel payment exists in the same workspace. Non-logged states carry no key.
create or replace function public.enforce_trip_fuel_resolution()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.deleted_at is not null then
    return new;
  end if;

  if new.fuel_resolution = 'logged' then
    if nullif(new.completion_fuel_legacy_id, '') is null then
      raise exception 'Logged trip fuel requires a fuel idempotency key' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.fuel_payments fp
      where fp.ledger_id = new.ledger_id
        and fp.legacy_id = new.completion_fuel_legacy_id
        and fp.deleted_at is null
    ) then
      raise exception 'Logged trip fuel must reference an active fuel payment in the same ledger'
        using errcode = '23514';
    end if;
  elsif new.completion_fuel_legacy_id is not null then
    raise exception 'Only logged trip fuel may reference a fuel payment' using errcode = '23514';
  end if;

  return new;
end;
$$;

revoke all on function public.enforce_trip_fuel_resolution() from public;
revoke all on function public.enforce_trip_fuel_resolution() from anon;
revoke all on function public.enforce_trip_fuel_resolution() from authenticated;

drop trigger if exists enforce_trip_fuel_resolution_trigger on public.trips;
create trigger enforce_trip_fuel_resolution_trigger
before insert or update of fuel_resolution, completion_fuel_legacy_id, ledger_id, deleted_at
on public.trips
for each row execute function public.enforce_trip_fuel_resolution();

-- Retiring the linked fuel record reopens the durable follow-up instead of leaving
-- the trip falsely marked as resolved. Hard workspace purges delete both rows and
-- do not need this soft-delete repair path.
create or replace function public.reopen_trip_fuel_resolution_on_payment_retire()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.deleted_at is null and new.deleted_at is not null and old.legacy_id is not null then
    update public.trips t
    set fuel_resolution = 'deferred',
        completion_fuel_legacy_id = null,
        updated_at = now()
    where t.ledger_id = old.ledger_id
      and t.completion_fuel_legacy_id = old.legacy_id
      and t.deleted_at is null;
  end if;
  return new;
end;
$$;

revoke all on function public.reopen_trip_fuel_resolution_on_payment_retire() from public;
revoke all on function public.reopen_trip_fuel_resolution_on_payment_retire() from anon;
revoke all on function public.reopen_trip_fuel_resolution_on_payment_retire() from authenticated;

drop trigger if exists reopen_trip_fuel_resolution_on_payment_retire_trigger on public.fuel_payments;
create trigger reopen_trip_fuel_resolution_on_payment_retire_trigger
after update of deleted_at on public.fuel_payments
for each row execute function public.reopen_trip_fuel_resolution_on_payment_retire();

create or replace function public.complete_booking_trip_with_fuel(
  target_ledger_id text,
  target_open_period_id uuid,
  target_booking_id uuid,
  legacy_trip_id text,
  booking_driver_member_id uuid,
  trip_date_value date,
  start_km_value numeric,
  end_km_value numeric,
  note_value text,
  participant_member_ids uuid[],
  fuel_resolution_value text,
  fuel_legacy_id text default null,
  fuel_payer_member_id uuid default null,
  fuel_payment_date_value date default null,
  fuel_amount_value numeric default null,
  fuel_currency_value text default 'DKK',
  fuel_liters_value numeric default null,
  fuel_price_per_liter_value numeric default null,
  fuel_odometer_value numeric default null,
  fuel_station_name_value text default null,
  fuel_station_brand_value text default null,
  fuel_station_lat_value numeric default null,
  fuel_station_lng_value numeric default null,
  fuel_full_tank_value boolean default false,
  trip_event_title text default null,
  trip_event_body text default null,
  fuel_event_title text default null,
  fuel_event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  trip_result jsonb;
  fuel_result jsonb := null;
  saved_trip_id uuid;
  saved_fuel_id uuid := null;
  existing_fuel_resolution text;
  existing_fuel_legacy_id text;
  effective_fuel_legacy_id text;
  fuel_payload_present boolean;
begin
  if fuel_resolution_value is null
     or fuel_resolution_value not in ('logged', 'deferred', 'not_refuelled', 'not_needed') then
    raise exception 'Invalid trip fuel resolution' using errcode = '22023';
  end if;

  fuel_payload_present :=
    nullif(fuel_legacy_id, '') is not null
    or fuel_payer_member_id is not null
    or fuel_payment_date_value is not null
    or fuel_amount_value is not null
    or fuel_liters_value is not null
    or fuel_price_per_liter_value is not null
    or fuel_odometer_value is not null
    or nullif(fuel_station_name_value, '') is not null
    or nullif(fuel_station_brand_value, '') is not null
    or fuel_station_lat_value is not null
    or fuel_station_lng_value is not null
    or coalesce(fuel_full_tank_value, false)
    or coalesce(nullif(fuel_currency_value, ''), 'DKK') <> 'DKK';

  if fuel_resolution_value = 'logged' then
    if nullif(fuel_legacy_id, '') is null
       or fuel_payer_member_id is null
       or fuel_payment_date_value is null
       or fuel_amount_value is null
       or fuel_amount_value <= 0 then
      raise exception 'Logged trip fuel requires a key, payer, date, and positive amount'
        using errcode = '22023';
    end if;
  elsif fuel_payload_present then
    raise exception 'Fuel details are only accepted when the resolution is logged'
      using errcode = '22023';
  end if;

  -- This command inherits the booking lock, actor/driver/date checks, open-period
  -- lock, participant validation, and trip idempotency from migration 123.
  trip_result := public.upsert_booking_trip_with_participants(
    target_ledger_id,
    target_open_period_id,
    target_booking_id,
    legacy_trip_id,
    booking_driver_member_id,
    trip_date_value,
    start_km_value,
    end_km_value,
    note_value,
    participant_member_ids,
    trip_event_title,
    trip_event_body
  );

  saved_trip_id := nullif(trip_result ->> 'trip_id', '')::uuid;
  if saved_trip_id is null then
    raise exception 'Booking completion did not return a trip id' using errcode = '40001';
  end if;

  select t.fuel_resolution, t.completion_fuel_legacy_id
    into existing_fuel_resolution, existing_fuel_legacy_id
    from public.trips t
    where t.id = saved_trip_id
      and t.ledger_id = target_ledger_id
      and t.deleted_at is null
    for update of t;

  if not found then
    raise exception 'Booking completion trip was not found' using errcode = '40001';
  end if;

  -- A delayed pre-refuel replay must never downgrade a fuel payment already logged
  -- by a newer attempt. The trip RPC remains free to reconcile odometer/participants.
  if existing_fuel_resolution = 'logged'
     and existing_fuel_legacy_id is not null
     and fuel_resolution_value <> 'logged' then
    return trip_result || jsonb_build_object(
      'fuel_resolution', 'logged',
      'fuel_id', (
        select fp.id
        from public.fuel_payments fp
        where fp.ledger_id = target_ledger_id
          and fp.legacy_id = existing_fuel_legacy_id
          and fp.deleted_at is null
        limit 1
      ),
      'reused_existing_fuel', true
    );
  end if;

  if fuel_resolution_value = 'logged' then
    -- Once a completion has a linked fuel key, all retries reuse it even if another
    -- device supplies a different local key. The booking lock serializes this read.
    effective_fuel_legacy_id := coalesce(
      nullif(existing_fuel_legacy_id, ''),
      nullif(fuel_legacy_id, '')
    );

    fuel_result := public.upsert_fuel_payment(
      target_ledger_id,
      target_open_period_id,
      effective_fuel_legacy_id,
      fuel_payer_member_id,
      fuel_payment_date_value,
      fuel_amount_value,
      coalesce(nullif(fuel_currency_value, ''), 'DKK'),
      fuel_liters_value,
      fuel_price_per_liter_value,
      fuel_odometer_value,
      fuel_station_name_value,
      fuel_station_brand_value,
      fuel_station_lat_value,
      fuel_station_lng_value,
      null,
      null,
      coalesce(fuel_full_tank_value, false),
      fuel_event_title,
      fuel_event_body
    );

    saved_fuel_id := nullif(fuel_result ->> 'fuel_id', '')::uuid;
    if saved_fuel_id is null then
      raise exception 'Booking completion did not return a fuel id' using errcode = '40001';
    end if;

    update public.trips t
    set fuel_resolution = 'logged',
        completion_fuel_legacy_id = effective_fuel_legacy_id,
        updated_at = now()
    where t.id = saved_trip_id
      and t.ledger_id = target_ledger_id;
  else
    update public.trips t
    set fuel_resolution = fuel_resolution_value,
        completion_fuel_legacy_id = null,
        updated_at = now()
    where t.id = saved_trip_id
      and t.ledger_id = target_ledger_id;
  end if;

  if not found then
    raise exception 'Booking completion could not persist its fuel resolution' using errcode = '40001';
  end if;

  return trip_result || jsonb_build_object(
    'fuel_resolution', fuel_resolution_value,
    'fuel_id', saved_fuel_id,
    'reused_existing_fuel', existing_fuel_legacy_id is not null
  );
end;
$$;

revoke all on function public.complete_booking_trip_with_fuel(
  text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text,
  text, uuid, date, numeric, text, numeric, numeric, numeric, text, text,
  numeric, numeric, boolean, text, text, text, text
) from public;
revoke all on function public.complete_booking_trip_with_fuel(
  text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text,
  text, uuid, date, numeric, text, numeric, numeric, numeric, text, text,
  numeric, numeric, boolean, text, text, text, text
) from anon;
grant execute on function public.complete_booking_trip_with_fuel(
  text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text,
  text, uuid, date, numeric, text, numeric, numeric, numeric, text, text,
  numeric, numeric, boolean, text, text, text, text
) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '136_atomic_booking_fuel_completion',
  'Atomic booking-trip fuel completion (GV-334): add durable trip fuel-resolution state and an idempotent command that atomically saves a booking-linked trip with an optional real fuel payment.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();
-- Migration 137: immutable settlement event history (GV-336)
--
-- ledger_events is a short-lived activity/realtime stream, not an audit log. Keep a
-- narrow, append-only settlement history that survives activity retention and records
-- every lifecycle edge at the database boundary, regardless of which RPC performs it.
-- The table intentionally excludes amounts, evidence notes, emails, push tokens, and
-- arbitrary metadata. Clients can join the canonical request for current details.

create table if not exists public.settlement_request_events (
  id uuid primary key default gen_random_uuid(),
  settlement_request_id uuid not null references public.settlement_requests(id) on delete cascade,
  ledger_id text not null references public.ledgers(id) on delete cascade,
  event_type text not null check (event_type in (
    'calculated',
    'requested',
    'marked_paid',
    'confirmed',
    'disputed',
    'cancelled',
    'reopened',
    'payment_reminder_sent',
    'confirmation_reminder_sent'
  )),
  from_status text check (
    from_status is null or from_status in ('open', 'requested', 'paid_pending', 'paid', 'cancelled')
  ),
  to_status text check (
    to_status is null or to_status in ('open', 'requested', 'paid_pending', 'paid', 'cancelled')
  ),
  actor_member_id uuid references public.ledger_members(id) on delete set null,
  reminder_number integer check (reminder_number is null or reminder_number > 0),
  occurred_at timestamptz not null,
  event_source text not null default 'live' check (event_source in ('live', 'legacy_backfill')),
  recorded_at timestamptz not null default now()
);

create index if not exists settlement_request_events_request_time_idx
  on public.settlement_request_events (settlement_request_id, occurred_at, id);

create index if not exists settlement_request_events_ledger_time_idx
  on public.settlement_request_events (ledger_id, occurred_at desc, id);

alter table public.settlement_request_events enable row level security;

drop policy if exists "Ledger members can read settlement request events"
  on public.settlement_request_events;
create policy "Ledger members can read settlement request events"
  on public.settlement_request_events
  for select
  using (public.is_ledger_member(ledger_id));

revoke all on table public.settlement_request_events from public;
revoke all on table public.settlement_request_events from anon;
revoke all on table public.settlement_request_events from authenticated;
revoke all on table public.settlement_request_events from service_role;
grant select on table public.settlement_request_events to authenticated;
grant select on table public.settlement_request_events to service_role;

-- Preserve only timestamps that the legacy row actually knows. In particular, do
-- not invent a dispute time from updated_at or infer claim/confirmation actors:
-- admins and retired auto-confirm paths mean the party ids are not reliable actors.
insert into public.settlement_request_events (
  settlement_request_id, ledger_id, event_type, from_status, to_status,
  actor_member_id, occurred_at, event_source
)
select sr.id, sr.ledger_id, 'calculated', null, 'open', null, sr.created_at, 'legacy_backfill'
from public.settlement_requests sr
where not exists (
  select 1 from public.settlement_request_events e
  where e.settlement_request_id = sr.id and e.event_type = 'calculated'
);

insert into public.settlement_request_events (
  settlement_request_id, ledger_id, event_type, from_status, to_status,
  actor_member_id, occurred_at, event_source
)
select sr.id, sr.ledger_id, 'requested', 'open', 'requested',
       sr.requested_by_member_id, sr.requested_at, 'legacy_backfill'
from public.settlement_requests sr
where sr.requested_at is not null
  and not exists (
    select 1 from public.settlement_request_events e
    where e.settlement_request_id = sr.id and e.event_type = 'requested'
  );

insert into public.settlement_request_events (
  settlement_request_id, ledger_id, event_type, from_status, to_status,
  actor_member_id, occurred_at, event_source
)
select sr.id, sr.ledger_id, 'marked_paid', 'requested', 'paid_pending',
       null, sr.paid_claimed_at, 'legacy_backfill'
from public.settlement_requests sr
where sr.paid_claimed_at is not null
  and not exists (
    select 1 from public.settlement_request_events e
    where e.settlement_request_id = sr.id and e.event_type = 'marked_paid'
  );

insert into public.settlement_request_events (
  settlement_request_id, ledger_id, event_type, from_status, to_status,
  actor_member_id, occurred_at, event_source
)
select sr.id, sr.ledger_id, 'confirmed',
       case when sr.paid_claimed_at is null then 'requested' else 'paid_pending' end,
       'paid',
       null, sr.paid_at, 'legacy_backfill'
from public.settlement_requests sr
where sr.paid_at is not null
  and not exists (
    select 1 from public.settlement_request_events e
    where e.settlement_request_id = sr.id and e.event_type = 'confirmed'
  );

insert into public.settlement_request_events (
  settlement_request_id, ledger_id, event_type, from_status, to_status,
  actor_member_id, reminder_number, occurred_at, event_source
)
select sr.id, sr.ledger_id, 'payment_reminder_sent', sr.status, sr.status,
       null, sr.reminder_count, sr.last_reminder_at, 'legacy_backfill'
from public.settlement_requests sr
where sr.last_reminder_at is not null
  and sr.reminder_count > 0
  and not exists (
    select 1 from public.settlement_request_events e
    where e.settlement_request_id = sr.id and e.event_type = 'payment_reminder_sent'
  );

insert into public.settlement_request_events (
  settlement_request_id, ledger_id, event_type, from_status, to_status,
  actor_member_id, occurred_at, event_source
)
select sr.id, sr.ledger_id, 'confirmation_reminder_sent', sr.status, sr.status,
       null, sr.last_confirm_reminder_at, 'legacy_backfill'
from public.settlement_requests sr
where sr.last_confirm_reminder_at is not null
  and not exists (
    select 1 from public.settlement_request_events e
    where e.settlement_request_id = sr.id and e.event_type = 'confirmation_reminder_sent'
  );

create or replace function public.record_settlement_request_event()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  safe_actor_member_id uuid;
begin
  safe_actor_member_id := public.current_ledger_member_id(new.ledger_id);

  if tg_op = 'INSERT' then
    insert into public.settlement_request_events (
      settlement_request_id, ledger_id, event_type, from_status, to_status,
      actor_member_id, occurred_at
    ) values (
      new.id, new.ledger_id, 'calculated', null, 'open',
      safe_actor_member_id, new.created_at
    );

    if new.status = 'requested' and new.requested_at is not null then
      insert into public.settlement_request_events (
        settlement_request_id, ledger_id, event_type, from_status, to_status,
        actor_member_id, occurred_at
      ) values (
        new.id, new.ledger_id, 'requested', 'open', 'requested',
        coalesce(safe_actor_member_id, new.requested_by_member_id), new.requested_at
      );
    end if;

    return new;
  end if;

  if old.status = 'paid_pending' and new.status = 'requested' then
    insert into public.settlement_request_events (
      settlement_request_id, ledger_id, event_type, from_status, to_status,
      actor_member_id, occurred_at
    ) values (
      new.id, new.ledger_id, 'disputed', old.status, new.status,
      safe_actor_member_id, now()
    );
  elsif new.status = 'requested'
        and (old.status is distinct from new.status or old.requested_at is distinct from new.requested_at) then
    insert into public.settlement_request_events (
      settlement_request_id, ledger_id, event_type, from_status, to_status,
      actor_member_id, occurred_at
    ) values (
      new.id, new.ledger_id, 'requested', old.status, new.status,
      coalesce(safe_actor_member_id, new.requested_by_member_id), coalesce(new.requested_at, now())
    );
  elsif old.status is distinct from new.status then
    insert into public.settlement_request_events (
      settlement_request_id, ledger_id, event_type, from_status, to_status,
      actor_member_id, occurred_at
    ) values (
      new.id,
      new.ledger_id,
      case new.status
        when 'paid_pending' then 'marked_paid'
        when 'paid' then 'confirmed'
        when 'cancelled' then 'cancelled'
        when 'open' then 'reopened'
      end,
      old.status,
      new.status,
      safe_actor_member_id,
      case new.status
        when 'paid_pending' then coalesce(new.paid_claimed_at, now())
        when 'paid' then coalesce(new.paid_at, now())
        else now()
      end
    );
  end if;

  if new.reminder_count > old.reminder_count
     and new.last_reminder_at is distinct from old.last_reminder_at then
    insert into public.settlement_request_events (
      settlement_request_id, ledger_id, event_type, from_status, to_status,
      actor_member_id, reminder_number, occurred_at
    ) values (
      new.id, new.ledger_id, 'payment_reminder_sent', new.status, new.status,
      null, new.reminder_count, coalesce(new.last_reminder_at, now())
    );
  end if;

  if new.last_confirm_reminder_at is distinct from old.last_confirm_reminder_at
     and new.last_confirm_reminder_at is not null then
    insert into public.settlement_request_events (
      settlement_request_id, ledger_id, event_type, from_status, to_status,
      actor_member_id, occurred_at
    ) values (
      new.id, new.ledger_id, 'confirmation_reminder_sent', new.status, new.status,
      null, new.last_confirm_reminder_at
    );
  end if;

  return new;
end;
$$;

revoke all on function public.record_settlement_request_event() from public;
revoke all on function public.record_settlement_request_event() from anon;
revoke all on function public.record_settlement_request_event() from authenticated;
revoke all on function public.record_settlement_request_event() from service_role;

drop trigger if exists record_settlement_request_event_trigger
  on public.settlement_requests;
create trigger record_settlement_request_event_trigger
after insert or update on public.settlement_requests
for each row execute function public.record_settlement_request_event();

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '137_settlement_event_history',
  'Add a privacy-minimised, append-only settlement event history with exact lifecycle/reminder timestamps, workspace-scoped read RLS, and database-triggered capture across every write path.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();
-- Migration 138: vehicle incidents + photos (GVM-396)
--
-- A shared-car damage & incident log. Members record what happened to the car
-- (dents, scrapes, breakdowns, insurance matters) with an incident date, an
-- optional odometer, an optional link to the booking or trip it happened on, a
-- repair-status lifecycle, an optional free-text insurance claim number
-- (skadenummer), and optional photos. Every write goes through a security-definer
-- RPC so the SAME membership + identity gates apply no matter which client calls
-- them, and create + status-change log a ledger_events row -- that is what drives
-- the activity feed and cross-client live sync (migration 051/052 pattern).
--
-- Identity policy (GV-253): the reporter is always resolved from the caller, never
-- trusted from a param, and only a workspace admin OR the incident's reporter may
-- edit an incident (kept strict for v1 -- that covers driver + every other field).
--
-- Photos live in a PRIVATE Supabase Storage bucket, workspace-scoped by the leading
-- path segment (<ledger_id>/<incident_id>/<uuid>.<ext>). The photo ROWS are
-- registered through add_incident_photo / delete_incident_photo, so the database is
-- the authority on who may attach or detach a photo; the storage.objects policies
-- are workspace-level defense-in-depth on top.
--
-- STORAGE COMPATIBILITY -- READ BEFORE EDITING. The `storage` schema only exists in
-- a real Supabase project. The CI guards (schema-equivalence replay, role matrix,
-- db-types) run in a PLAIN Postgres container with NO storage schema. So EVERY
-- storage statement below (the bucket row + the storage.objects policies) is wrapped
-- in a `do $$ begin if exists (storage schema) then ... end if; end $$;` guard: in
-- plain Postgres the guard is false and nothing storage-related runs (both replays
-- stay identical and pass); in prod the guard is true and the real bucket + policies
-- are created. The storage half therefore ONLY takes effect when this SQL is applied
-- in the real Supabase SQL Editor.

-- ── 1. Incident table ────────────────────────────────────────────────────────
create table if not exists public.vehicle_incidents (
  id uuid primary key default gen_random_uuid(),
  ledger_id text not null references public.ledgers(id) on delete cascade,
  reporter_member_id uuid references public.ledger_members(id) on delete set null,
  driver_member_id uuid references public.ledger_members(id) on delete set null,
  booking_id uuid references public.car_bookings(id) on delete set null,
  trip_id uuid references public.trips(id) on delete set null,
  incident_date date not null,
  odometer integer check (odometer is null or odometer > 0),
  title text not null,
  description text not null,
  repair_status text not null default 'open'
    check (repair_status in ('open', 'under_repair', 'repaired', 'closed')),
  insurance_ref text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists vehicle_incidents_ledger_date_idx
  on public.vehicle_incidents (ledger_id, incident_date desc, id);

create index if not exists vehicle_incidents_ledger_status_idx
  on public.vehicle_incidents (ledger_id, repair_status);

create index if not exists vehicle_incidents_booking_idx
  on public.vehicle_incidents (booking_id) where booking_id is not null;

create index if not exists vehicle_incidents_trip_idx
  on public.vehicle_incidents (trip_id) where trip_id is not null;

alter table public.vehicle_incidents enable row level security;

drop policy if exists "Ledger members can read vehicle incidents"
  on public.vehicle_incidents;
create policy "Ledger members can read vehicle incidents"
  on public.vehicle_incidents
  for select
  using (public.is_ledger_member(ledger_id));

-- Reads for workspace members only; all writes go through the RPCs below.
revoke all on table public.vehicle_incidents from public;
revoke all on table public.vehicle_incidents from anon;
revoke all on table public.vehicle_incidents from authenticated;
revoke all on table public.vehicle_incidents from service_role;
grant select on table public.vehicle_incidents to authenticated;
grant select on table public.vehicle_incidents to service_role;

-- ── 2. Incident photos table ─────────────────────────────────────────────────
create table if not exists public.vehicle_incident_photos (
  id uuid primary key default gen_random_uuid(),
  incident_id uuid not null references public.vehicle_incidents(id) on delete cascade,
  ledger_id text not null references public.ledgers(id) on delete cascade,
  storage_path text not null unique,
  created_by_member_id uuid references public.ledger_members(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists vehicle_incident_photos_incident_idx
  on public.vehicle_incident_photos (incident_id, created_at, id);

alter table public.vehicle_incident_photos enable row level security;

drop policy if exists "Ledger members can read vehicle incident photos"
  on public.vehicle_incident_photos;
create policy "Ledger members can read vehicle incident photos"
  on public.vehicle_incident_photos
  for select
  using (public.is_ledger_member(ledger_id));

-- Reads for workspace members only; inserts/deletes go through the photo RPCs.
revoke all on table public.vehicle_incident_photos from public;
revoke all on table public.vehicle_incident_photos from anon;
revoke all on table public.vehicle_incident_photos from authenticated;
revoke all on table public.vehicle_incident_photos from service_role;
grant select on table public.vehicle_incident_photos to authenticated;
grant select on table public.vehicle_incident_photos to service_role;

-- ── 3. Write RPCs ────────────────────────────────────────────────────────────
-- Create an incident. Any active workspace member may log one; the reporter is
-- resolved from the caller (current_ledger_member_id), never a param. Follows the
-- 051/052 activity-event pattern: the client supplies event_title/event_body and
-- the RPC writes one ledger_events row on create so the feed + realtime light up.
create or replace function public.log_vehicle_incident(
  target_ledger_id text,
  incident_date_value date,
  title_value text,
  description_value text,
  driver_member_id_value uuid default null,
  booking_id_value uuid default null,
  trip_id_value uuid default null,
  odometer_value integer default null,
  repair_status_value text default 'open',
  insurance_ref_value text default null,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_member_id uuid;
  v_incident_id uuid;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can log incidents' using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  if nullif(btrim(title_value), '') is null then
    raise exception 'Incident title is required' using errcode = '22023';
  end if;

  if nullif(btrim(description_value), '') is null then
    raise exception 'Incident description is required' using errcode = '22023';
  end if;

  if repair_status_value is null
     or repair_status_value not in ('open', 'under_repair', 'repaired', 'closed') then
    raise exception 'Invalid repair status' using errcode = '22023';
  end if;

  if odometer_value is not null and odometer_value <= 0 then
    raise exception 'Odometer must be positive' using errcode = '22023';
  end if;

  -- member_belongs_to_ledger(null, ...) is true, so this also allows "no driver".
  if not public.member_belongs_to_ledger(driver_member_id_value, target_ledger_id) then
    raise exception 'Incident driver must belong to this ledger' using errcode = '23514';
  end if;

  if booking_id_value is not null and not exists (
    select 1 from public.car_bookings cb
    where cb.id = booking_id_value and cb.ledger_id = target_ledger_id
  ) then
    raise exception 'Linked booking must belong to this ledger' using errcode = '22023';
  end if;

  if trip_id_value is not null and not exists (
    select 1 from public.trips t
    where t.id = trip_id_value and t.ledger_id = target_ledger_id
  ) then
    raise exception 'Linked trip must belong to this ledger' using errcode = '22023';
  end if;

  insert into public.vehicle_incidents (
    ledger_id, reporter_member_id, driver_member_id, booking_id, trip_id,
    incident_date, odometer, title, description, repair_status, insurance_ref
  ) values (
    target_ledger_id, v_actor_member_id, driver_member_id_value, booking_id_value, trip_id_value,
    incident_date_value, odometer_value, btrim(title_value), btrim(description_value),
    repair_status_value, nullif(btrim(insurance_ref_value), '')
  )
  returning id into v_incident_id;

  if nullif(event_title, '') is not null then
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id, 'incident_logged', event_title, coalesce(event_body, ''),
      v_actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
      jsonb_build_object('incident_id', v_incident_id)
    );
  end if;

  return jsonb_build_object(
    'incident_id', v_incident_id,
    'ledger_id', target_ledger_id
  );
end;
$$;

revoke all on function public.log_vehicle_incident(text, date, text, text, uuid, uuid, uuid, integer, text, text, text, text) from public;
grant execute on function public.log_vehicle_incident(text, date, text, text, uuid, uuid, uuid, integer, text, text, text, text) to authenticated;

-- Edit an incident. GV-253, kept strict for v1: only a workspace admin OR the
-- incident's original reporter may edit ANY field (driver + everything else). Null
-- args mean "leave unchanged"; non-null args replace. When the client supplies an
-- event_title (typically on a status change) the RPC logs a ledger_events row so
-- the change reaches the feed + live sync.
create or replace function public.update_vehicle_incident(
  target_incident_id uuid,
  title_value text default null,
  description_value text default null,
  repair_status_value text default null,
  insurance_ref_value text default null,
  driver_member_id_value uuid default null,
  incident_date_value date default null,
  odometer_value integer default null,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_incident public.vehicle_incidents%rowtype;
  v_actor_member_id uuid;
  v_new_status text;
  v_status_changed boolean;
begin
  if target_incident_id is null then
    raise exception 'Missing incident id' using errcode = '22023';
  end if;

  select * into v_incident
  from public.vehicle_incidents vi
  where vi.id = target_incident_id;

  if v_incident.id is null then
    raise exception 'Incident was not found' using errcode = '22023';
  end if;

  v_actor_member_id := public.current_ledger_member_id(v_incident.ledger_id);
  if v_actor_member_id is null then
    raise exception 'Only workspace members can edit incidents' using errcode = '42501';
  end if;

  if not (
    public.is_ledger_admin(v_incident.ledger_id)
    or coalesce(v_incident.reporter_member_id = v_actor_member_id, false)
  ) then
    raise exception 'Only the incident reporter or a workspace admin can edit this incident' using errcode = '42501';
  end if;

  if repair_status_value is not null
     and repair_status_value not in ('open', 'under_repair', 'repaired', 'closed') then
    raise exception 'Invalid repair status' using errcode = '22023';
  end if;

  if odometer_value is not null and odometer_value <= 0 then
    raise exception 'Odometer must be positive' using errcode = '22023';
  end if;

  if driver_member_id_value is not null
     and not public.member_belongs_to_ledger(driver_member_id_value, v_incident.ledger_id) then
    raise exception 'Incident driver must belong to this ledger' using errcode = '23514';
  end if;

  v_new_status := coalesce(repair_status_value, v_incident.repair_status);
  v_status_changed := v_new_status is distinct from v_incident.repair_status;

  update public.vehicle_incidents vi
  set title = coalesce(nullif(btrim(title_value), ''), vi.title),
      description = coalesce(nullif(btrim(description_value), ''), vi.description),
      repair_status = v_new_status,
      insurance_ref = case
        when insurance_ref_value is null then vi.insurance_ref
        else nullif(btrim(insurance_ref_value), '')
      end,
      driver_member_id = coalesce(driver_member_id_value, vi.driver_member_id),
      incident_date = coalesce(incident_date_value, vi.incident_date),
      odometer = coalesce(odometer_value, vi.odometer),
      updated_at = now()
  where vi.id = target_incident_id;

  if nullif(event_title, '') is not null then
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      v_incident.ledger_id, 'incident_updated', event_title, coalesce(event_body, ''),
      v_actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
      jsonb_build_object('incident_id', target_incident_id, 'repair_status', v_new_status, 'status_changed', v_status_changed)
    );
  end if;

  return jsonb_build_object(
    'incident_id', target_incident_id,
    'ledger_id', v_incident.ledger_id,
    'repair_status', v_new_status,
    'status_changed', v_status_changed
  );
end;
$$;

revoke all on function public.update_vehicle_incident(uuid, text, text, text, text, uuid, date, integer, text, text) from public;
grant execute on function public.update_vehicle_incident(uuid, text, text, text, text, uuid, date, integer, text, text) to authenticated;

-- Register a photo against an incident. Any workspace member may attach a photo to
-- an incident in their own workspace. The storage_path MUST live under the
-- incident's own <ledger_id>/<incident_id>/ prefix, so a member cannot register a
-- row that points at another workspace's or incident's object.
create or replace function public.add_incident_photo(
  p_incident_id uuid,
  p_storage_path text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_incident public.vehicle_incidents%rowtype;
  v_actor_member_id uuid;
  v_expected_prefix text;
  v_photo_id uuid;
begin
  if p_incident_id is null then
    raise exception 'Missing incident id' using errcode = '22023';
  end if;

  if nullif(btrim(p_storage_path), '') is null then
    raise exception 'Missing storage path' using errcode = '22023';
  end if;

  select * into v_incident
  from public.vehicle_incidents vi
  where vi.id = p_incident_id;

  if v_incident.id is null then
    raise exception 'Incident was not found' using errcode = '22023';
  end if;

  if not public.is_ledger_member(v_incident.ledger_id) then
    raise exception 'Only ledger members can attach incident photos' using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(v_incident.ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- Path convention: <ledger_id>/<incident_id>/<uuid>.<ext>. Compare the literal
  -- prefix (no LIKE -- ledger ids can contain '_', a LIKE wildcard).
  v_expected_prefix := v_incident.ledger_id || '/' || p_incident_id::text || '/';
  if left(p_storage_path, length(v_expected_prefix)) <> v_expected_prefix then
    raise exception 'Storage path must live under the incident''s workspace/incident prefix' using errcode = '22023';
  end if;

  insert into public.vehicle_incident_photos (
    incident_id, ledger_id, storage_path, created_by_member_id
  ) values (
    p_incident_id, v_incident.ledger_id, p_storage_path, v_actor_member_id
  )
  returning id into v_photo_id;

  return jsonb_build_object(
    'photo_id', v_photo_id,
    'incident_id', p_incident_id,
    'ledger_id', v_incident.ledger_id
  );
end;
$$;

revoke all on function public.add_incident_photo(uuid, text) from public;
grant execute on function public.add_incident_photo(uuid, text) to authenticated;

-- Delete a registered incident photo. Only a workspace admin or the member who
-- uploaded it may delete it. The storage object itself is cleaned up by the client
-- (and the storage.objects delete policy gates that to workspace members); THIS row
-- is the authority on who may detach a photo.
create or replace function public.delete_incident_photo(
  p_photo_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_photo public.vehicle_incident_photos%rowtype;
  v_actor_member_id uuid;
begin
  if p_photo_id is null then
    raise exception 'Missing photo id' using errcode = '22023';
  end if;

  select * into v_photo
  from public.vehicle_incident_photos vip
  where vip.id = p_photo_id;

  if v_photo.id is null then
    raise exception 'Incident photo was not found' using errcode = '22023';
  end if;

  v_actor_member_id := public.current_ledger_member_id(v_photo.ledger_id);
  if v_actor_member_id is null then
    raise exception 'Only ledger members can delete incident photos' using errcode = '42501';
  end if;

  if not (
    public.is_ledger_admin(v_photo.ledger_id)
    or coalesce(v_photo.created_by_member_id = v_actor_member_id, false)
  ) then
    raise exception 'Only the photo uploader or a workspace admin can delete this photo' using errcode = '42501';
  end if;

  delete from public.vehicle_incident_photos vip where vip.id = p_photo_id;

  return jsonb_build_object(
    'photo_id', p_photo_id,
    'incident_id', v_photo.incident_id,
    'ledger_id', v_photo.ledger_id
  );
end;
$$;

revoke all on function public.delete_incident_photo(uuid) from public;
grant execute on function public.delete_incident_photo(uuid) to authenticated;

-- ── 4. Supabase Storage (PROD-ONLY; see the STORAGE COMPATIBILITY note above) ──
-- Guarded on the `storage` schema existing so plain-Postgres CI replays skip it
-- entirely and only the real Supabase project materialises the private bucket +
-- workspace-scoped object policies.
do $$
begin
  if exists (select 1 from information_schema.schemata where schema_name = 'storage') then
    -- Private bucket, 5 MiB cap, images only.
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values (
      'incident-photos', 'incident-photos', false, 5242880,
      array['image/jpeg', 'image/png', 'image/webp']
    )
    on conflict (id) do update set
      public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

    -- Workspace-scoped access: the first path segment is the ledger id
    -- (<ledger_id>/<incident_id>/<uuid>.<ext>), gated through is_ledger_member.
    drop policy if exists "Incident photos are readable by workspace members" on storage.objects;
    create policy "Incident photos are readable by workspace members"
      on storage.objects for select to authenticated
      using (
        bucket_id = 'incident-photos'
        and public.is_ledger_member((storage.foldername(name))[1])
      );

    drop policy if exists "Incident photos are writable by workspace members" on storage.objects;
    create policy "Incident photos are writable by workspace members"
      on storage.objects for insert to authenticated
      with check (
        bucket_id = 'incident-photos'
        and public.is_ledger_member((storage.foldername(name))[1])
      );

    -- Creator-only delete cannot be expressed purely in a storage.objects policy
    -- (the uploader identity lives in public.vehicle_incident_photos, and
    -- delete_incident_photo is the row-level authority). Storage deletes are gated
    -- to workspace members here as defense-in-depth; the RPC enforces creator/admin.
    drop policy if exists "Incident photos are deletable by workspace members" on storage.objects;
    create policy "Incident photos are deletable by workspace members"
      on storage.objects for delete to authenticated
      using (
        bucket_id = 'incident-photos'
        and public.is_ledger_member((storage.foldername(name))[1])
      );
  end if;
end
$$;

-- ── 5. GDPR: extend delete_my_account (re-declared off migration 111) ──────────
-- Re-declared off migration 111 (its newest prior definition -- GV-202 rule). The
-- ONLY change is one added step inside the per-membership loop: detach this account
-- from workspace-owned incident photos. The incident rows themselves keep their
-- reporter/driver references pointing at THIS member row, which the loop already
-- anonymizes in place (name -> 'Slettet medlem', email -> null) -- identical to how
-- trips.driver_member_id and every other retained membership reference is handled,
-- so no incident PII survives. Photos belong to the workspace (they die with the
-- incident or the workspace via cascade), so deletion only detaches their authorship.
create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := public.current_user_email();
  v_member record;
  v_old_name text;
  v_first_name text;
  v_anon_name text;
  v_suffix integer;
  v_no_other_active boolean;
  v_successor record;
  v_ledgers_scrubbed integer := 0;
  v_ledgers_deleted integer := 0;
  v_admins_promoted integer := 0;
begin
  if v_uid is null or v_email is null then
    raise exception 'Account deletion requires a signed-in user' using errcode = '42501';
  end if;

  -- Let the settlement lock trigger (GV-199) know these writes are GDPR PII
  -- scrubs, not settlement edits, so its closed-period rejection stands aside.
  -- Transaction-local, so it clears automatically at commit/rollback.
  perform set_config('govehlo.pii_scrub', '1', true);

  for v_member in
    select lm.id, lm.ledger_id, lm.name, lm.role, lm.is_active
    from public.ledger_members lm
    where lm.email is not null
      and lower(lm.email) = v_email
  loop
    v_old_name := v_member.name;
    v_first_name := split_part(v_old_name, ' ', 1);

    -- No other active member left? The workspace dies with this account: nobody
    -- could ever access it again, so full deletion is the cleanest erasure.
    -- Every child table references ledgers(id) with on delete cascade.
    select not exists (
      select 1
      from public.ledger_members lm2
      where lm2.ledger_id = v_member.ledger_id
        and lm2.is_active = true
        and lm2.id <> v_member.id
    ) into v_no_other_active;
    if v_no_other_active then
      delete from public.ledgers l where l.id = v_member.ledger_id;
      v_ledgers_deleted := v_ledgers_deleted + 1;
      continue;
    end if;

    -- Admin succession: never leave a live workspace admin-less. Promote the
    -- longest-standing active member and say so in the feed (system actor).
    if v_member.is_active and v_member.role = 'admin' and not exists (
      select 1
      from public.ledger_members lm3
      where lm3.ledger_id = v_member.ledger_id
        and lm3.is_active = true
        and lm3.role = 'admin'
        and lm3.id <> v_member.id
    ) then
      select lm4.id, lm4.name
      into v_successor
      from public.ledger_members lm4
      where lm4.ledger_id = v_member.ledger_id
        and lm4.is_active = true
        and lm4.id <> v_member.id
      order by lm4.created_at asc, lm4.id asc
      limit 1;

      update public.ledger_members lm5
      set role = 'admin', updated_at = now()
      where lm5.id = v_successor.id;

      insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata)
      values (
        v_member.ledger_id,
        'member_promoted',
        v_successor.name || ' er nu administrator',
        'Automatisk, fordi den tidligere administrator slettede sin konto',
        null,
        null,
        v_successor.id,
        jsonb_build_object('reason', 'account_deleted')
      );
      v_admins_promoted := v_admins_promoted + 1;
    end if;

    -- Per-ledger-unique anonymized name (unique(ledger_id, name) would reject a
    -- second 'Slettet medlem' in the same group).
    v_anon_name := 'Slettet medlem';
    v_suffix := 1;
    while exists (
      select 1
      from public.ledger_members lm6
      where lm6.ledger_id = v_member.ledger_id
        and lm6.name = v_anon_name
        and lm6.id <> v_member.id
    ) loop
      v_suffix := v_suffix + 1;
      v_anon_name := 'Slettet medlem ' || v_suffix;
    end loop;

    -- Authored free text: trip notes are the creator's words, not car facts.
    update public.trips t
    set note = null, updated_at = now()
    where t.ledger_id = v_member.ledger_id
      and t.created_by_member_id = v_member.id
      and t.note is not null;

    -- Bookings: purposes are authored text; future bookings would block the car
    -- for a person who no longer exists.
    update public.car_bookings cb
    set purpose = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.purpose is not null;

    -- Structured fuel stop (migration 063): the from/to labels + lat/lng are the
    -- member's route history — potentially their home address. Null the whole
    -- jsonb; station coords are public, but from/to are personal, so simplest-
    -- correct wins (GV-197).
    update public.car_bookings cb
    set fuel_stop = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.fuel_stop is not null;

    update public.car_bookings cb
    set deleted_at = now(), updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and cb.member_id = v_member.id
      and cb.start_at > now()
      and cb.deleted_at is null;

    -- Chat: blank + soft-delete their messages (the app already filters deleted).
    update public.messages msg
    set body = '', deleted_at = coalesce(msg.deleted_at, now())
    where msg.ledger_id = v_member.ledger_id
      and msg.sender_member_id = v_member.id;

    -- Incident photos (GVM-396): the photos belong to the workspace (they die with
    -- the incident or the workspace via cascade). Only the authorship pointer is
    -- personal, so detach it. The incident rows' own reporter/driver references
    -- are left pointing at this member row, which is anonymized in place below —
    -- exactly like trips.driver_member_id and every other retained reference.
    update public.vehicle_incident_photos vip
    set created_by_member_id = null
    where vip.ledger_id = v_member.ledger_id
      and vip.created_by_member_id = v_member.id;

    -- Feed events: drop stored emails and replace the member's name inside titles
    -- and bodies they authored or are targeted by. Events self-expire after 30
    -- days, so this is belt-and-braces on top of bounded retention. Very short
    -- first names (< 3 chars) are skipped for the substring pass — the collision
    -- risk with unrelated words outweighs the residual exposure.
    if char_length(v_first_name) < 3 then
      v_first_name := v_old_name;
    end if;
    update public.ledger_events ev
    set actor_email = case when ev.actor_member_id = v_member.id then null else ev.actor_email end,
        target_email = case when ev.target_member_id = v_member.id then null else ev.target_email end,
        title = replace(replace(ev.title, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem'),
        body = replace(replace(ev.body, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem')
    where ev.ledger_id = v_member.ledger_id
      and (ev.actor_member_id = v_member.id or ev.target_member_id = v_member.id);

    -- Archived snapshots: closed periods keep their maths, but the name fields
    -- inside people[] / settlements[] must stop identifying the person. The
    -- entry fingerprint (migration 054) covers trip/fuel ids only, never names,
    -- so this rewrite cannot invalidate any integrity check.
    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{people}',
      (
        select coalesce(jsonb_agg(
          case when person ->> 'id' = v_member.id::text
            then jsonb_set(person, '{name}', to_jsonb(v_anon_name))
            else person
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(sp.snapshot_json -> 'people') as person
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'people') = 'array';

    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{settlements}',
      (
        select coalesce(jsonb_agg(
          case when settled ->> 'toId' = v_member.id::text
            then jsonb_set(settled, '{toName}', to_jsonb(v_anon_name))
            else settled
          end
        ), '[]'::jsonb)
        from (
          select case when raw ->> 'fromId' = v_member.id::text
            then jsonb_set(raw, '{fromName}', to_jsonb(v_anon_name))
            else raw
          end as settled
          from jsonb_array_elements(sp.snapshot_json -> 'settlements') as raw
        ) as renamed
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'settlements') = 'array';

    -- Invites addressed to this email in this ledger.
    update public.ledger_invites li
    set invited_email = null, updated_at = now()
    where li.ledger_id = v_member.ledger_id
      and lower(coalesce(li.invited_email, '')) = v_email;

    -- Finally the member row itself. Role drops to 'member' (succession above
    -- already ensured another admin exists when one was needed). last_seen_at is
    -- nulled too (GVM-66): activity metadata must not outlive the account.
    update public.ledger_members lm7
    set name = v_anon_name,
        email = null,
        mobilepay_phone = null,
        role = 'member',
        is_active = false,
        last_seen_at = null,
        updated_at = now()
    where lm7.id = v_member.id;

    -- Feed transparency, in app voice, without re-publishing the old name.
    insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
    values (
      v_member.ledger_id,
      'member_deleted',
      'Et medlem slettede sin konto',
      v_anon_name || ' er anonymiseret. Gruppens regnskab er uændret.',
      null,
      null,
      jsonb_build_object('member_id', v_member.id)
    );

    v_ledgers_scrubbed := v_ledgers_scrubbed + 1;
  end loop;

  -- Cross-ledger cleanup keyed by identity rather than membership.
  delete from public.push_subscriptions ps
  where lower(ps.user_email) = v_email;

  delete from public.ledger_onboarding_rate_limits rl
  where lower(rl.actor_email) = v_email;

  update public.owner_activity_log oal
  set actor_email = null, actor_user_id = null
  where oal.actor_user_id = v_uid
     or lower(coalesce(oal.actor_email, '')) = v_email;

  -- Push tokens die with the account (migration 057): match by user id and by
  -- the scrubbed email so nothing keeps addressing this person's devices.
  delete from public.expo_push_tokens ept
  where ept.user_id = v_uid
     or lower(ept.email) = v_email;


  -- Purge this user's notification preferences (GV-229). No PII (three booleans
  -- + a uuid), but data minimisation says don't leave an orphaned row behind.
  delete from public.notification_preferences np where np.user_id = v_uid;

  -- Kill the credentials last: cascades sessions/identities, frees the email for
  -- a fresh sign-up. The caller's JWT stays technically valid until expiry but no
  -- longer matches any member (email scrubbed), so RLS yields nothing.
  delete from auth.users au where au.id = v_uid;

  return jsonb_build_object(
    'ledgers_scrubbed', v_ledgers_scrubbed,
    'ledgers_deleted', v_ledgers_deleted,
    'admins_promoted', v_admins_promoted
  );
end;
$$;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '138_vehicle_incidents',
  'Vehicle incidents + photos (GVM-396): workspace-scoped damage/incident log (vehicle_incidents) with an optional booking/trip link, repair-status lifecycle, optional skadenummer, and private-bucket photos (vehicle_incident_photos). Reads via is_ledger_member RLS; writes only through security-definer RPCs (log/update incident, add/delete photo) that gate on membership + the GV-253 admin-or-reporter identity policy and log ledger_events. Storage bucket + storage.objects policies are guarded on the storage schema so plain-Postgres CI replays skip them. delete_my_account re-declared off 111 to detach incident-photo authorship.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 139: Harden incident-photo Storage authorization (GV-348)
--
-- Migration 138 made the bucket private, but its object policies were broader than
-- the RPC contract: any workspace member could upload an arbitrary object below the
-- ledger prefix or delete another member's object directly through Storage. Keep
-- member reads, while binding uploads to a real incident and direct deletes to the
-- uploader or a workspace admin.

do $$
begin
  if exists (select 1 from information_schema.schemata where schema_name = 'storage') then
    drop policy if exists "Incident photos are writable by workspace members" on storage.objects;
    create policy "Incident photos are writable by workspace members"
      on storage.objects for insert to authenticated
      with check (
        bucket_id = 'incident-photos'
        and cardinality(storage.foldername(name)) = 2
        and public.is_ledger_member((storage.foldername(name))[1])
        and exists (
          select 1
          from public.vehicle_incidents vi
          where vi.ledger_id = (storage.foldername(name))[1]
            and vi.id::text = (storage.foldername(name))[2]
        )
      );

    drop policy if exists "Incident photos are deletable by workspace members" on storage.objects;
    create policy "Incident photos are deletable by workspace members"
      on storage.objects for delete to authenticated
      using (
        bucket_id = 'incident-photos'
        and public.is_ledger_member((storage.foldername(name))[1])
        and (
          owner_id::text = auth.uid()::text
          or public.is_ledger_admin((storage.foldername(name))[1])
        )
      );
  end if;
end
$$;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '139_incident_photo_storage_hardening',
  'Restricts incident-photo Storage uploads to existing incidents in the same ledger and direct object deletion to the uploader or a ledger admin; member read access remains unchanged.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 140: durable late-entry carry-over for locked settlement periods
--
-- A payment request freezes the current period so the amount cannot move while
-- members pay. Previously that also rejected every late trip, fuel receipt,
-- expense, and repair. The app could simultaneously require a deferred receipt
-- and prohibit saving it.
--
-- Keep the frozen-period invariant, but accept NEW financial entries into one
-- hidden queued successor period. When close_settlement_period inserts the next
-- open period, an AFTER INSERT trigger atomically moves the queued rows into it.
-- Existing rows in the frozen period remain immutable. This makes late entries
-- durable on the server without changing requested amounts or relying on one
-- device's local outbox.

alter table public.settlement_periods
  drop constraint if exists settlement_periods_status_check;

alter table public.settlement_periods
  add constraint settlement_periods_status_check
  check (status in ('open', 'queued', 'closed'));

create unique index if not exists one_queued_settlement_period_per_ledger
  on public.settlement_periods (ledger_id)
  where status = 'queued';

create or replace function public.ensure_settlement_carryover_period(
  p_ledger_id text,
  p_source_period_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_period_id uuid;
begin
  if p_ledger_id is null or p_ledger_id = '' or p_source_period_id is null then
    raise exception 'Missing ledger or source settlement period' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.settlement_periods sp
    where sp.id = p_source_period_id
      and sp.ledger_id = p_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
  ) then
    raise exception 'Carry-over source must be the ledger''s open settlement period'
      using errcode = '22023';
  end if;

  -- One queue per ledger. The advisory lock makes the read/create sequence safe
  -- when several members save late entries at the same time.
  perform pg_advisory_xact_lock(hashtext(p_ledger_id || ':settlement-carryover'));

  select sp.id
    into v_period_id
    from public.settlement_periods sp
    where sp.ledger_id = p_ledger_id
      and sp.status = 'queued'
    limit 1;

  if v_period_id is null then
    insert into public.settlement_periods (ledger_id, status, label, opened_at)
    values (p_ledger_id, 'queued', 'Næste periode', now())
    returning id into v_period_id;
  end if;

  return v_period_id;
end;
$$;

revoke all on function public.ensure_settlement_carryover_period(text, uuid) from public;
revoke all on function public.ensure_settlement_carryover_period(text, uuid) from anon;
revoke all on function public.ensure_settlement_carryover_period(text, uuid) from authenticated;

-- Re-declared off migration 121. New live INSERTS aimed at a locked open period
-- are rebound to the queued successor before the existing settlement-lock trigger
-- runs. UPDATE/DELETE still check both old and new periods exactly as before.
create or replace function public.enforce_settlement_entry_period_boundary()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  old_period_id uuid;
  new_period_id uuid;
  old_ledger_id text;
  new_ledger_id text;
  period_row record;
  v_rule_lock boolean;
  v_new_is_live boolean := false;
begin
  if coalesce(current_setting('govehlo.pii_scrub', true), '') = '1' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_table_name = 'trip_participants' then
    if tg_op in ('UPDATE', 'DELETE') then
      select t.period_id, t.ledger_id into old_period_id, old_ledger_id
      from public.trips t
      where t.id = old.trip_id;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      select t.period_id, t.ledger_id into new_period_id, new_ledger_id
      from public.trips t
      where t.id = new.trip_id;
    end if;
  elsif tg_table_name = 'vehicle_repairs' then
    if tg_op in ('UPDATE', 'DELETE') then
      old_period_id := old.period_id;
      old_ledger_id := old.ledger_id;
      if old_period_id is null then
        select sp.id into old_period_id
        from public.settlement_periods sp
        where sp.ledger_id = old.ledger_id
          and old.created_at >= sp.opened_at
          and (sp.closed_at is null or old.created_at < sp.closed_at)
        order by sp.opened_at desc
        limit 1;
      end if;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      new_period_id := new.period_id;
      new_ledger_id := new.ledger_id;
      v_new_is_live := new.deleted_at is null;
    end if;
  else
    if tg_op in ('UPDATE', 'DELETE') then
      old_period_id := old.period_id;
      old_ledger_id := old.ledger_id;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      new_period_id := new.period_id;
      new_ledger_id := new.ledger_id;
      v_new_is_live := new.deleted_at is null;
    end if;
  end if;

  if tg_table_name <> 'trip_participants'
     and tg_op = 'INSERT'
     and new_period_id is null then
    select sp.id into new_period_id
    from public.settlement_periods sp
    where sp.ledger_id = new_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    order by sp.opened_at desc
    limit 1;

    if new_period_id is null then
      raise exception 'No open settlement period exists for this ledger'
        using errcode = '22023';
    end if;
    new.period_id := new_period_id;
  end if;

  -- A live INSERT is the only operation allowed to cross the freeze boundary.
  -- It is assigned to a separate period, so the requested amount and close
  -- fingerprint of the frozen period cannot change. Tombstone inserts retain
  -- the ordinary path and do not create an otherwise empty successor queue.
  if tg_table_name <> 'trip_participants'
     and tg_op = 'INSERT'
     and v_new_is_live
     and new_period_id is not null then
    -- Serialize the classification with close_settlement_period. Without this
    -- source-row lock, a direct INSERT could create/find the queue just before a
    -- concurrent close promoted and deleted it, then fail its FK after the BEFORE
    -- trigger returned. RPC writers already take this lock; direct RLS writes need
    -- the same guarantee here at the table boundary.
    perform 1
    from public.settlement_periods sp
    where sp.id = new_period_id
      and sp.ledger_id = new_ledger_id
    for share of sp;

    select l.rule_lock_period_after_payment
      into v_rule_lock
      from public.ledgers l
      where l.id = new_ledger_id;

    if v_rule_lock is not false
       and public.settlement_entry_is_locked(new_ledger_id, new_period_id) then
      new_period_id := public.ensure_settlement_carryover_period(new_ledger_id, new_period_id);
      new.period_id := new_period_id;
    end if;
  end if;

  for period_row in
    select sp.id, sp.ledger_id, sp.status, sp.closed_at
    from public.settlement_periods sp
    where sp.id in (old_period_id, new_period_id)
    order by sp.id
    for share of sp
  loop
    if (period_row.id = old_period_id and period_row.ledger_id is distinct from old_ledger_id)
       or (period_row.id = new_period_id and period_row.ledger_id is distinct from new_ledger_id) then
      raise exception 'Settlement entry period must belong to the same ledger as the entry'
        using errcode = '23514';
    end if;

    if period_row.status = 'closed' or period_row.closed_at is not null then
      raise exception
        'This settlement period is closed -- entries can no longer be added or changed.'
        using errcode = '22023';
    end if;
  end loop;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

revoke all on function public.enforce_settlement_entry_period_boundary() from public;
revoke all on function public.enforce_settlement_entry_period_boundary() from anon;
revoke all on function public.enforce_settlement_entry_period_boundary() from authenticated;

-- Repair rows gained period_id in migration 114, but the old repair guard still
-- used created_at and never applied the requested-payment lock. Prefer the bound
-- period, retain the timestamp fallback for legacy rows, and freeze settlement-
-- bearing edits in the same way as trips/fuel/expenses.
create or replace function public.enforce_repair_period_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_period_closed boolean := false;
  v_guard boolean := tg_op = 'DELETE';
  v_rule_lock boolean;
begin
  if coalesce(current_setting('govehlo.pii_scrub', true), '') = '1' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if old.period_id is not null then
    select (sp.status = 'closed' or sp.closed_at is not null)
      into v_period_closed
      from public.settlement_periods sp
      where sp.id = old.period_id
        and sp.ledger_id = old.ledger_id;
  else
    select exists (
      select 1
      from public.settlement_periods sp
      where sp.ledger_id = old.ledger_id
        and sp.closed_at is not null
        and old.created_at >= sp.opened_at
        and old.created_at < sp.closed_at
    ) into v_period_closed;
  end if;

  if v_period_closed then
    raise exception
      'This repair belongs to a closed settlement period and can no longer be edited or deleted.'
      using errcode = '22023';
  end if;

  if tg_op = 'UPDATE' then
    v_guard := (new.cost_dkk is distinct from old.cost_dkk)
            or (new.paid_by_member_id is distinct from old.paid_by_member_id)
            or (new.period_id is distinct from old.period_id)
            or (new.deleted_at is distinct from old.deleted_at);
  end if;

  select l.rule_lock_period_after_payment
    into v_rule_lock
    from public.ledgers l
    where l.id = old.ledger_id;

  if v_guard and v_rule_lock is not false
     and public.settlement_entry_is_locked(old.ledger_id, old.period_id) then
    raise exception
      'This settlement period is locked because a payment has been requested or paid. New repairs are saved for the next period; existing repairs cannot be changed.'
      using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

revoke all on function public.enforce_repair_period_lock() from public;
revoke all on function public.enforce_repair_period_lock() from anon;
revoke all on function public.enforce_repair_period_lock() from authenticated;

-- close_settlement_period always INSERTS the next open row after freezing the
-- current one. Promote queued rows in that same transaction, keeping the close
-- RPC, its fingerprint checks, and its returned open_period_id unchanged.
create or replace function public.promote_settlement_carryover_entries()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_queued_period_id uuid;
begin
  if new.status <> 'open' or new.closed_at is not null then
    return new;
  end if;

  select sp.id
    into v_queued_period_id
    from public.settlement_periods sp
    where sp.ledger_id = new.ledger_id
      and sp.status = 'queued'
    for update of sp;

  if v_queued_period_id is null then
    return new;
  end if;

  update public.trips
     set period_id = new.id
   where period_id = v_queued_period_id;

  update public.fuel_payments
     set period_id = new.id
   where period_id = v_queued_period_id;

  update public.workspace_expenses
     set period_id = new.id
   where period_id = v_queued_period_id;

  update public.vehicle_repairs
     set period_id = new.id
   where period_id = v_queued_period_id;

  delete from public.settlement_periods
   where id = v_queued_period_id
     and status = 'queued';

  return new;
end;
$$;

revoke all on function public.promote_settlement_carryover_entries() from public;
revoke all on function public.promote_settlement_carryover_entries() from anon;
revoke all on function public.promote_settlement_carryover_entries() from authenticated;

drop trigger if exists promote_settlement_carryover_on_open on public.settlement_periods;
create trigger promote_settlement_carryover_on_open
after insert on public.settlement_periods
for each row execute function public.promote_settlement_carryover_entries();

-- Resolve an already-saved deferred booking receipt without replaying/moving the
-- original trip. The fuel INSERT is automatically queued by the boundary trigger
-- above when the current period is locked; only fixed, non-financial workflow
-- metadata is updated on the original trip, including when it is already closed.
create or replace function public.complete_deferred_booking_fuel(
  target_ledger_id text,
  target_open_period_id uuid,
  target_trip_id uuid,
  fuel_legacy_id text,
  fuel_payer_member_id uuid,
  fuel_payment_date_value date,
  fuel_amount_value numeric,
  fuel_currency_value text default 'DKK',
  fuel_liters_value numeric default null,
  fuel_price_per_liter_value numeric default null,
  fuel_odometer_value numeric default null,
  fuel_station_name_value text default null,
  fuel_station_brand_value text default null,
  fuel_station_lat_value numeric default null,
  fuel_station_lng_value numeric default null,
  fuel_full_tank_value boolean default false,
  fuel_event_title text default null,
  fuel_event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_member_id uuid;
  v_trip record;
  v_fuel_result jsonb;
  v_saved_fuel_id uuid;
begin
  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can complete deferred fuel entries'
      using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member'
      using errcode = '42501';
  end if;

  if target_trip_id is null then
    raise exception 'Missing deferred trip id' using errcode = '22023';
  end if;

  select t.id, t.driver_member_id, t.fuel_resolution, t.completion_fuel_legacy_id
    into v_trip
    from public.trips t
    where t.id = target_trip_id
      and t.ledger_id = target_ledger_id
      and t.booking_id is not null
      and t.deleted_at is null
    for update of t;

  if not found then
    raise exception 'Deferred booking trip was not found' using errcode = '22023';
  end if;

  if not (public.is_ledger_admin(target_ledger_id) or v_trip.driver_member_id = v_actor_member_id) then
    raise exception 'Only the trip driver or a ledger admin can complete its deferred fuel entry'
      using errcode = '42501';
  end if;

  if v_trip.fuel_resolution = 'logged' and v_trip.completion_fuel_legacy_id is not null then
    return jsonb_build_object(
      'trip_id', v_trip.id,
      'fuel_resolution', 'logged',
      'fuel_id', (
        select fp.id
        from public.fuel_payments fp
        where fp.ledger_id = target_ledger_id
          and fp.legacy_id = v_trip.completion_fuel_legacy_id
          and fp.deleted_at is null
        limit 1
      ),
      'reused_existing_fuel', true
    );
  end if;

  if v_trip.fuel_resolution <> 'deferred' then
    raise exception 'Trip does not have a deferred fuel entry' using errcode = '22023';
  end if;

  v_fuel_result := public.upsert_fuel_payment(
    target_ledger_id,
    target_open_period_id,
    fuel_legacy_id,
    fuel_payer_member_id,
    fuel_payment_date_value,
    fuel_amount_value,
    coalesce(nullif(fuel_currency_value, ''), 'DKK'),
    fuel_liters_value,
    fuel_price_per_liter_value,
    fuel_odometer_value,
    fuel_station_name_value,
    fuel_station_brand_value,
    fuel_station_lat_value,
    fuel_station_lng_value,
    null,
    null,
    coalesce(fuel_full_tank_value, false),
    fuel_event_title,
    fuel_event_body
  );

  v_saved_fuel_id := nullif(v_fuel_result ->> 'fuel_id', '')::uuid;
  if v_saved_fuel_id is null then
    raise exception 'Deferred fuel completion did not return a fuel id'
      using errcode = '40001';
  end if;

  -- The original trip may have become historical before the driver found the
  -- receipt. Reuse the existing transaction-local metadata scrub bypass for this
  -- one fixed-column UPDATE: neither field participates in settlement maths or
  -- the archived fingerprint, and enforce_trip_fuel_resolution still proves the
  -- linked fuel row exists. No caller-controlled SQL runs while the flag is set.
  perform set_config('govehlo.pii_scrub', '1', true);

  update public.trips t
  set fuel_resolution = 'logged',
      completion_fuel_legacy_id = fuel_legacy_id,
      updated_at = now()
  where t.id = target_trip_id
    and t.ledger_id = target_ledger_id
    and t.fuel_resolution = 'deferred';

  if not found then
    raise exception 'Deferred fuel completion could not update the trip'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'trip_id', target_trip_id,
    'fuel_resolution', 'logged',
    'fuel_id', v_saved_fuel_id,
    'reused_existing_fuel', false
  );
end;
$$;

revoke all on function public.complete_deferred_booking_fuel(
  text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric,
  text, text, numeric, numeric, boolean, text, text
) from public;
revoke all on function public.complete_deferred_booking_fuel(
  text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric,
  text, text, numeric, numeric, boolean, text, text
) from anon;
grant execute on function public.complete_deferred_booking_fuel(
  text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric,
  text, text, numeric, numeric, boolean, text, text
) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '140_late_entry_carryover',
  'Durable late-entry carry-over: new trips, fuel, expenses, recurring materializations, and repairs saved during a requested/paid lock are bound to one queued successor period and promoted atomically when close creates the next open period. Existing frozen entries remain immutable; repair lock/scoping now follows period_id.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 141: unblock period close, restore the repair retention rule, and remove the settlement_periods update policy (GV-358/GV-359/GV-351)
--
-- Three defects that all land on the settlement-period boundary.
--
-- GV-358 — closing a period became impossible. Migration 140 added
-- "(new.period_id is distinct from old.period_id)" to enforce_repair_period_lock's
-- guard set plus a requested/paid lock check. close_settlement_period's own
-- cleanup UPDATE (added in 114) binds legacy repairs carrying period_id IS NULL to
-- the period right before it closes, so it trips that guard:
-- settlement_entry_is_locked(ledger, NULL) falls back to the ledger's OPEN period,
-- and at close time a requested/paid/paid_pending request always exists because
-- rule_require_requests_before_close demands one — so every close aborted with
-- 42501 and a message about repairs. close_settlement_period does not set
-- govehlo.pii_scrub, and SECURITY DEFINER does not bypass triggers.
--
-- GV-359 — migration 140 re-declared enforce_repair_period_lock from migration
-- 112's body instead of migration 131's, its newest prior definition, silently
-- dropping 131's row-age retention carve-out. run_operational_retention could
-- still purge repair tombstones because it sets the scrub flag, but the standalone
-- age rule that 131 deliberately made flag-independent was gone.
--
-- GV-351 — "Ledger admins can update periods" (migration 005) was never dropped.
-- Migration 099 removed only the sibling INSERT policy, on the stated grounds that
-- every legitimate write is SECURITY DEFINER. The surviving UPDATE policy let any
-- workspace admin PATCH settlement_periods directly through PostgREST: flipping
-- the open period to 'closed' bricks the workspace (no snapshot, no event, no
-- successor open period, and 099 removed the INSERT policy so nothing can create
-- one), the reverse write thaws archived history away from its frozen snapshot,
-- and post-140 flipping a 'queued' row to 'open' yields two open periods and makes
-- the lock predicate non-deterministic.
--
-- Composition note (the lesson of GV-359): public.enforce_repair_period_lock below
-- is composed from migration 140's body VERBATIM plus migration 131's row-age
-- carve-out, so it carries both 140's carry-over behaviour and 131's retention
-- behaviour. public.close_settlement_period_unlocked below is migration 114's body
-- verbatim (renamed by migration 117, never re-declared since) with only the
-- repair-stamping UPDATE changed. Always state the ancestry here — 140's header
-- did not, and that is exactly how the drift went unnoticed.

-- ── GV-359 + GV-358: enforce_repair_period_lock ───────────────────────────────
-- 140 verbatim, with 131's retention carve-out restored ahead of the scrub gate.
create or replace function public.enforce_repair_period_lock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_period_closed boolean := false;
  v_guard boolean := tg_op = 'DELETE';
  v_rule_lock boolean;
begin
  -- Restored from migration 131 (GV-359). Migration 112 freezes repairs that
  -- belong to closed periods, including hard DELETE. Keep that invariant for the
  -- full accounting window, then permit only an already-soft-deleted tombstone
  -- outside the approved window to be purged. This rule is intrinsic to the row
  -- age, so it cannot be bypassed by setting a session flag; ordinary
  -- closed-period edits and deletes remain rejected.
  if tg_op = 'DELETE'
     and old.deleted_at is not null
     and old.deleted_at < date_trunc('year', now()) - interval '5 years' then
    return old;
  end if;

  if coalesce(current_setting('govehlo.pii_scrub', true), '') = '1' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if old.period_id is not null then
    select (sp.status = 'closed' or sp.closed_at is not null)
      into v_period_closed
      from public.settlement_periods sp
      where sp.id = old.period_id
        and sp.ledger_id = old.ledger_id;
  else
    select exists (
      select 1
      from public.settlement_periods sp
      where sp.ledger_id = old.ledger_id
        and sp.closed_at is not null
        and old.created_at >= sp.opened_at
        and old.created_at < sp.closed_at
    ) into v_period_closed;
  end if;

  if v_period_closed then
    raise exception
      'This repair belongs to a closed settlement period and can no longer be edited or deleted.'
      using errcode = '22023';
  end if;

  if tg_op = 'UPDATE' then
    v_guard := (new.cost_dkk is distinct from old.cost_dkk)
            or (new.paid_by_member_id is distinct from old.paid_by_member_id)
            or (new.period_id is distinct from old.period_id)
            or (new.deleted_at is distinct from old.deleted_at);
  end if;

  select l.rule_lock_period_after_payment
    into v_rule_lock
    from public.ledgers l
    where l.id = old.ledger_id;

  if v_guard and v_rule_lock is not false
     and public.settlement_entry_is_locked(old.ledger_id, old.period_id) then
    raise exception
      'This settlement period is locked because a payment has been requested or paid. New repairs are saved for the next period; existing repairs cannot be changed.'
      using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

revoke all on function public.enforce_repair_period_lock() from public;
revoke all on function public.enforce_repair_period_lock() from anon;
revoke all on function public.enforce_repair_period_lock() from authenticated;

-- ── GV-358: close_settlement_period_unlocked ──────────────────────────────────
-- Migration 114's close body (renamed to *_unlocked by migration 117, which kept
-- the public close_settlement_period wrapper that takes the FOR UPDATE row lock
-- and then calls this function). Re-declared here verbatim except for the repair
-- stamping UPDATE, which now runs inside the transaction-local scrub bypass so the
-- 140 repair guard stops rejecting close's own cleanup write. The wrapper, the
-- signature, the integrity gate, the require-requests coverage, the duplicate
-- guard, the close/open pair, the event and the grants are unchanged.
create or replace function public.close_settlement_period_unlocked(
  target_ledger_id text,
  target_period_id uuid,
  period_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  snapshot_fingerprint text;
  server_fingerprint text;
  computed jsonb;
  computed_person jsonb;
  snapshot_person jsonb;
  snapshot_flow numeric;
  duplicate_period_id uuid;
  closed_period_id uuid;
  new_open_period_id uuid;
  requested_closed_at timestamptz;
  lock_acquired boolean;
  v_rule_require_requests boolean;
  v_settlement jsonb;
  v_missing_settlements integer := 0;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_period_id is null then
    raise exception 'Missing open settlement period id' using errcode = '22023';
  end if;

  if period_snapshot is null or jsonb_typeof(period_snapshot) <> 'object' then
    raise exception 'Period snapshot must be a JSON object' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can close settlement periods' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- Guard before taking the advisory lock. Older frontend builds and health probes
  -- may call this RPC with a fake or already-closed period id. Reject those
  -- immediately so they cannot queue behind the lock and burn database CPU.
  if not exists (
    select 1
    from public.settlement_periods sp
    where sp.id = target_period_id
      and sp.ledger_id = target_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
  ) then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '22023';
  end if;

  lock_acquired := pg_try_advisory_xact_lock(hashtext(target_ledger_id));
  if lock_acquired is not true then
    raise exception 'Another settlement close is already in progress for this ledger' using errcode = '55P03';
  end if;

  -- ── Integrity gate (GVM-112) ──────────────────────────────────────────────
  -- (a) Entry set: the snapshot's fingerprint must equal the one recomputed
  -- from the live rows. In-flight writers hold FOR SHARE on the period row, so
  -- by the time this runs the row set is stable for the transaction.
  snapshot_fingerprint := nullif(period_snapshot->>'entryFingerprint', '');
  server_fingerprint := public.calculate_period_entry_fingerprint(target_ledger_id, target_period_id);

  if snapshot_fingerprint is not null and snapshot_fingerprint <> server_fingerprint then
    raise exception 'Entries changed since this close was prepared. Refresh the app and try closing again.'
      using errcode = '23514';
  end if;

  -- (b) Amounts: per-member figures within 0.02 kr, totals within 0.05 kr.
  computed := public.calculate_period_settlement(target_ledger_id, target_period_id);

  if abs(coalesce((period_snapshot->>'totalKm')::numeric, 0) - (computed->>'totalKm')::numeric) > 0.05
     or abs(coalesce((period_snapshot->>'totalPaid')::numeric, 0) - (computed->>'totalPaid')::numeric) > 0.05 then
    raise exception 'Snapshot totals do not match the server calculation. Refresh the app and try closing again.'
      using errcode = '23514';
  end if;

  for computed_person in
    select value from jsonb_array_elements(computed->'people')
  loop
    select p.value
      into snapshot_person
      from jsonb_array_elements(coalesce(period_snapshot->'people', '[]'::jsonb)) as p(value)
      where p.value->>'id' = computed_person->>'id'
      limit 1;

    if abs(coalesce((snapshot_person->>'km')::numeric, 0) - (computed_person->>'km')::numeric) > 0.02
       or abs(coalesce((snapshot_person->>'fuelPaid')::numeric, 0) - (computed_person->>'fuelPaid')::numeric) > 0.02
       or abs(coalesce((snapshot_person->>'net')::numeric, 0) - (computed_person->>'net')::numeric) > 0.02 then
      raise exception 'Snapshot member amounts do not match the server calculation. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;

    -- (c) The archived settlements must actually move each member's net:
    -- outflow - inflow ~= -net for every member.
    select coalesce(sum((s.value->>'amount')::numeric) filter (where s.value->>'fromId' = computed_person->>'id'), 0)
         - coalesce(sum((s.value->>'amount')::numeric) filter (where s.value->>'toId' = computed_person->>'id'), 0)
      into snapshot_flow
      from jsonb_array_elements(coalesce(period_snapshot->'settlements', '[]'::jsonb)) as s(value);

    if abs(snapshot_flow + (computed_person->>'net')::numeric) > 0.05 then
      raise exception 'Snapshot settlements do not match the member balances. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;
  end loop;

  -- Snapshot-only members (left the ledger between fetch and close) must carry
  -- no money, otherwise the archive would hide a real balance.
  for snapshot_person in
    select value from jsonb_array_elements(coalesce(period_snapshot->'people', '[]'::jsonb))
  loop
    if not exists (
      select 1 from jsonb_array_elements(computed->'people') as c(value)
      where c.value->>'id' = snapshot_person->>'id'
    ) and abs(coalesce((snapshot_person->>'net')::numeric, 0)) > 0.02 then
      raise exception 'Snapshot includes a member the server no longer recognizes. Refresh the app and try closing again.'
        using errcode = '23514';
    end if;
  end loop;
  -- ── End integrity gate ────────────────────────────────────────────────────

  -- ── FIX 2 (GV-253 / GVM-278): require requests before close ────────────────
  -- rule_require_requests_before_close (migration 098) shipped stored-only — this
  -- is its first database enforcement. When the workspace flag is NOT an explicit
  -- false, every settlement pair that moves money must already have a request row
  -- for this period in a requested-or-later state (status not 'open'/'cancelled').
  -- The period_snapshot settlements are safe to read here: integrity gate (c) just
  -- proved they reconcile each member's server-computed net, so they ARE the real
  -- outstanding pairs. A settlement_requests row is keyed by period + payer
  -- (from_member_id) + recipient (to_member_id), matching the snapshot fromId/toId.
  select l.rule_require_requests_before_close
    into v_rule_require_requests
    from public.ledgers l
    where l.id = target_ledger_id;

  if v_rule_require_requests is not false then
    for v_settlement in
      select value from jsonb_array_elements(coalesce(period_snapshot->'settlements', '[]'::jsonb))
    loop
      if coalesce((v_settlement->>'amount')::numeric, 0) > 0
         and not exists (
           select 1
           from public.settlement_requests sr
           where sr.period_id = target_period_id
             and sr.from_member_id = (v_settlement->>'fromId')::uuid
             and sr.to_member_id = (v_settlement->>'toId')::uuid
             and sr.status not in ('open', 'cancelled')
             and sr.amount = round((v_settlement->>'amount')::numeric, 2)
         ) then
        v_missing_settlements := v_missing_settlements + 1;
      end if;
    end loop;

    if v_missing_settlements > 0 then
      raise exception
        'All settlements must be requested at their current amounts before this period can be closed. Request or update the outstanding payments and try again.'
        using errcode = '42501';
    end if;
  end if;
  -- ── End require-requests-before-close ──────────────────────────────────────

  if snapshot_fingerprint is not null then
    select sp.id into duplicate_period_id
    from public.settlement_periods sp
    where sp.ledger_id = target_ledger_id
      and sp.status = 'closed'
      and sp.snapshot_json->>'entryFingerprint' = snapshot_fingerprint
    limit 1;

    if duplicate_period_id is not null then
      raise exception 'This settlement period snapshot has already been closed' using errcode = '23505';
    end if;
  end if;

  begin
    requested_closed_at := coalesce((period_snapshot->>'closedAt')::timestamptz, now());
  exception when others then
    requested_closed_at := now();
  end;

  -- GV-277: bind this period's remaining legacy null-period repairs to it BEFORE
  -- the period flips to closed, so period_id is authoritative for every repair
  -- once the period is closed. A stamped repair already carries period_id from
  -- insert_repair; only pre-114 rows are updated here, matched by the same
  -- created_at window the settlement/fingerprint use.
  --
  -- GV-358: since migration 140 the repair guard ALSO rejects a period_id change
  -- while the period is locked by a requested or paid settlement -- and close
  -- cannot legally run without those requests when
  -- rule_require_requests_before_close is on, so this statement rejected the
  -- close it belongs to. Reuse the transaction-local metadata bypass exactly as
  -- migration 140 does for trip workflow metadata: it is opened for this single
  -- server-authored statement and closed again immediately, no caller-controlled
  -- SQL runs while it is set, and the write only records the period a legacy
  -- repair already belonged to by created_at -- no amount, payer or membership
  -- changes, so neither the archived snapshot nor the fingerprint can move.
  perform set_config('govehlo.pii_scrub', '1', true);

  update public.vehicle_repairs vr
  set period_id = target_period_id
  from public.settlement_periods sp
  where sp.id = target_period_id
    and sp.ledger_id = target_ledger_id
    and vr.ledger_id = target_ledger_id
    and vr.period_id is null
    and vr.deleted_at is null
    and vr.created_at >= sp.opened_at
    and vr.created_at < requested_closed_at;

  perform set_config('govehlo.pii_scrub', '', true);

  update public.settlement_periods sp
  set status = 'closed',
      label = coalesce(nullif(period_snapshot->>'label', ''), sp.label, 'Closed period'),
      closed_at = requested_closed_at,
      closed_by_member_id = actor_member_id,
      snapshot_json = period_snapshot,
      updated_at = now()
  where sp.id = target_period_id
    and sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  returning sp.id into closed_period_id;

  if closed_period_id is null then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '40001';
  end if;

  -- FIX 3 (GV-253): label the freshly opened period in Danish to match the app's
  -- own period labels (client formats da-DK month+year; demo data uses 'Juni
  -- 2026'). to_char(..., 'Month') only speaks English, so index a Danish month
  -- array by the current month and capitalize, e.g. 'Juli 2026'. Deterministic and
  -- server-clock based; the client overwrites this with its own snapshot label when
  -- it later closes, so it only shows while this is the current period.
  insert into public.settlement_periods (ledger_id, status, label, opened_at)
  values (
    target_ledger_id,
    'open',
    (array['Januar','Februar','Marts','April','Maj','Juni','Juli','August','September','Oktober','November','December'])[extract(month from now())::int]
      || ' ' || to_char(now(), 'YYYY'),
    now()
  )
  returning id into new_open_period_id;

  -- Activity feed + realtime nudge (GVM-247): closing a period writes a
  -- ledger_events row so every other member's client (subscribed to
  -- ledger_events) refetches immediately — otherwise the close only reaches them
  -- on a manual refresh. metadata carries both period ids for the feed/routing.
  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id, 'period_closed', 'Periode lukket', 'En ny periode er klar.',
    actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
    jsonb_build_object('closed_period_id', closed_period_id, 'open_period_id', new_open_period_id)
  );

  return jsonb_build_object(
    'closed_period_id', closed_period_id,
    'open_period_id', new_open_period_id,
    'closed_by_member_id', actor_member_id,
    'closed_at', requested_closed_at,
    'entry_fingerprint', snapshot_fingerprint
  );
end;
$$;

revoke all on function public.close_settlement_period_unlocked(text, uuid, jsonb) from public;
revoke all on function public.close_settlement_period_unlocked(text, uuid, jsonb) from anon;
revoke all on function public.close_settlement_period_unlocked(text, uuid, jsonb) from authenticated;

-- ── GV-351: settlement_periods is not client-writable ─────────────────────────
-- Every legitimate settlement_periods write is a SECURITY DEFINER RPC
-- (close_settlement_period, ensure_settlement_carryover_period, the owner
-- integrity batch), which runs as the function owner and is unaffected by client
-- policies or client grants. Every client reference is SELECT-only: govehlo-mobile
-- src/store/ledger-data-gateway.ts and src/lib/data-export.ts, govehlo-web
-- functions/api/public/km-rate.js, functions/api/owner/workspace/[id].js and
-- admin/admin.js. So the update policy has no legitimate caller.
drop policy if exists "Ledger admins can update periods" on public.settlement_periods;

-- Production policy NAMES have drifted from the migration files before (migration
-- 103 / PR #117 had to sweep pg_policies to actually clean prod), so pair the
-- by-name drop with a dynamic sweep: any UPDATE policy on this table is removed
-- whatever it happens to be called. SELECT policies are deliberately left alone --
-- both clients read this table -- which is also why policies declared FOR ALL are
-- not swept blind here; none exist, and dropping one would silently remove read
-- access.
do $$
declare
  v_policy record;
begin
  for v_policy in
    select policyname
    from pg_policies
    where schemaname = 'public'
      and tablename = 'settlement_periods'
      and cmd = 'UPDATE'
  loop
    execute format('drop policy %I on public.settlement_periods', v_policy.policyname);
  end loop;
end
$$;

-- Defence in depth, so a policy re-added by mistake still cannot be exercised over
-- PostgREST. This deliberately revokes only the write privileges rather than the
-- vehicle_incidents-style blanket "revoke all" + "grant select": settlement_periods
-- is read by the authenticated clients AND by service-role endpoints, so a blanket
-- revoke would risk the read paths (and any future service-role write) for no
-- additional protection against the JWT-driven writes this fixes.
revoke insert, update, delete on table public.settlement_periods from authenticated;
revoke insert, update, delete on table public.settlement_periods from anon;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '141_close_guard_retention_and_period_lockdown',
  'GV-358: close_settlement_period_unlocked (off 114) wraps its legacy-repair period_id stamping UPDATE in the transaction-local govehlo.pii_scrub bypass so migration 140''s repair guard no longer rejects close''s own cleanup write and aborts every period close. GV-359: enforce_repair_period_lock re-declared from 140''s body (its newest prior definition) with migration 131''s row-age GDPR carve-out restored, so it carries both the carry-over lock and the five-accounting-year retention rule. GV-351: the never-dropped "Ledger admins can update periods" policy on settlement_periods is dropped by name and by a dynamic pg_policies sweep (prod name drift), and insert/update/delete are revoked from anon and authenticated; all legitimate writes are SECURITY DEFINER and every client reference is SELECT-only.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── generate_due_recurring_expenses — materialise even while the period is locked ─
-- Re-declared off migration 116 (its newest prior definition). Body is 116 verbatim
-- minus the GV-281 lock short-circuit; the period-boundary trigger now rebinds the
-- insert into the queued carry-over period instead.
create or replace function public.generate_due_recurring_expenses(
  target_ledger_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  total_generated integer := 0;
  -- Bound the per-template catch-up so one stale template can't materialise an
  -- unbounded backlog in a single run; the remainder catches up on later runs
  -- (GV-274). Same value in generate_all_due_recurring_expenses (the scheduler).
  max_catchup_occurrences constant integer := 24;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can generate recurring expenses' using errcode = '42501';
  end if;

  -- Materialise into the ledger's open period. If none is open (should not happen
  -- after bootstrap, but a period close briefly precedes the next open), do
  -- nothing this run; the next call catches up. FOR SHARE serializes against a
  -- concurrent close (which exclusively locks the period row).
  select sp.id into open_period_id
  from public.settlement_periods sp
  where sp.ledger_id = target_ledger_id
    and sp.status = 'open'
    and sp.closed_at is null
  order by sp.opened_at desc
  limit 1
  for share of sp;

  if open_period_id is null then
    return jsonb_build_object('generated', 0, 'reason', 'no_open_period');
  end if;

  -- GV-360: no entry-lock short-circuit here. GV-281's guard returned
  -- {generated:0, reason:'locked'} to avoid a 42501 from enforce_settlement_entry_lock,
  -- but migration 140 made that exception unreachable for this insert:
  -- assert_settlement_period_boundary_expenses (migration 121) fires first — it sorts
  -- before enforce_settlement_entry_lock_expenses — and rebinds a live INSERT aimed at
  -- a locked open period into the queued carry-over period. A recurring occurrence now
  -- carries over exactly like a manually logged expense instead of being deferred.

  for tmpl in
    select *
    from public.recurring_expenses r
    where r.ledger_id = target_ledger_id
      and r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
    order by r.next_due_date
    for update skip locked
  loop
    due_date := tmpl.next_due_date;
    template_count := 0;
    occurrences := 0;

    while due_date <= current_date and occurrences < max_catchup_occurrences loop
      insert into public.workspace_expenses (
        ledger_id, period_id, category, description, amount_dkk, expense_date,
        split_rule, split_config, paid_by_member_id, created_by_member_id,
        recurring_expense_id, occurrence_date
      ) values (
        target_ledger_id,
        open_period_id,
        tmpl.category,
        tmpl.description,
        tmpl.amount_dkk,
        due_date,
        tmpl.split_rule,
        tmpl.split_config,
        tmpl.paid_by_member_id,
        tmpl.created_by_member_id,
        tmpl.id,
        due_date
      )
      on conflict (recurring_expense_id, occurrence_date)
        where recurring_expense_id is not null do nothing
      returning id into inserted_id;

      if inserted_id is not null then
        template_count := template_count + 1;
      end if;
      inserted_id := null;
      occurrences := occurrences + 1;

      due_date := (case tmpl.cadence
        when 'monthly' then due_date + interval '1 month'
        when 'quarterly' then due_date + interval '3 months'
        when 'semiannual' then due_date + interval '6 months'
        when 'yearly' then due_date + interval '1 year'
        else due_date + interval '1 month'
      end)::date;
    end loop;

    update public.recurring_expenses
      set next_due_date = due_date, last_generated_at = now(), updated_at = now()
    where id = tmpl.id;

    if template_count > 0 then
      insert into public.ledger_events (
        ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
      ) values (
        target_ledger_id,
        'expense_recurring_added',
        'Fast udgift tilføjet',
        coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
          || ' blev automatisk tilføjet og delt.',
        null,
        null,
        jsonb_build_object(
          'category', tmpl.category,
          'recurring_expense_id', tmpl.id,
          'count', template_count
        )
      );
      total_generated := total_generated + template_count;
    end if;
  end loop;

  return jsonb_build_object('generated', total_generated);
end;
$$;

revoke all on function public.generate_due_recurring_expenses(text) from public;
revoke all on function public.generate_due_recurring_expenses(text) from anon;
grant execute on function public.generate_due_recurring_expenses(text) to authenticated;

-- ── generate_all_due_recurring_expenses — same carry-over, failure isolation kept ─
-- Re-declared off migration 116 (its newest prior definition). Body is 116 verbatim
-- minus the GV-281 per-ledger lock skip. The per-ledger BEGIN/EXCEPTION subtransaction,
-- the ledgers_skipped/first_error keys, and the GDPR-safe SQLSTATE-only reporting all
-- stay. Service-role only (grants restated).
create or replace function public.generate_all_due_recurring_expenses(
  batch_limit integer default 200
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  due_ledger record;
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  ledger_generated integer;
  total_generated integer := 0;
  ledgers_touched integer := 0;
  ledgers_scanned integer := 0;
  -- Ledgers rolled back on an unexpected error; first_error_code holds the FIRST
  -- failure's SQLSTATE only. GV-281 also counted entry-locked ledgers here; GV-360
  -- removed that deferral, so this is now purely the per-ledger failure counter. The
  -- key stays in the return contract either way — /api/hooks/recurring-generate in
  -- govehlo-web reads it.
  ledgers_skipped integer := 0;
  first_error_code text := null;
  -- Same per-template catch-up bound as generate_due_recurring_expenses (GV-274).
  max_catchup_occurrences constant integer := 24;
begin
  for due_ledger in
    -- Only ledgers with a due active template (with an active payer, GV-277) AND an
    -- open period to receive it, oldest debt first, so no-open-period ledgers never
    -- occupy a batch slot and the most overdue ledger is caught up first under
    -- batch_limit (GV-274). Entry-locked ledgers are neither excluded here nor skipped
    -- in the loop any more (GV-360): their occurrences are materialised, and the
    -- period-boundary trigger rebinds them into the queued carry-over period.
    select r.ledger_id
    from public.recurring_expenses r
    where r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
      and exists (
        select 1
        from public.settlement_periods sp
        where sp.ledger_id = r.ledger_id
          and sp.status = 'open'
          and sp.closed_at is null
      )
    group by r.ledger_id
    order by min(r.next_due_date) asc, r.ledger_id
    limit greatest(coalesce(batch_limit, 200), 0)
  loop
    ledgers_scanned := ledgers_scanned + 1;

    -- GV-281: isolate each ledger in its own subtransaction so one bad ledger (a lock
    -- race, an unexpected constraint) can never abort the whole sweep again. On error
    -- we roll THIS ledger back (the exception block does this automatically), count it
    -- in ledgers_skipped, remember the first SQLSTATE (code only — no row values, GDPR),
    -- and CONTINUE with the next ledger.
    begin
      -- Materialise into the ledger's open period. If none is open (a period close
      -- briefly precedes the next open), skip this ledger this run; the next tick catches
      -- up. FOR SHARE serializes against a concurrent close (which exclusively locks the
      -- period row).
      select sp.id into open_period_id
      from public.settlement_periods sp
      where sp.ledger_id = due_ledger.ledger_id
        and sp.status = 'open'
        and sp.closed_at is null
      order by sp.opened_at desc
      limit 1
      for share of sp;

      if open_period_id is null then
        open_period_id := null;
        continue;
      end if;

      -- GV-360: no entry-lock deferral here either. The insert below targets the open
      -- period; when that period is entry-locked, migration 121's
      -- assert_settlement_period_boundary_expenses trigger rebinds the row into the
      -- queued carry-over period (migration 140) before the entry-lock trigger runs, so
      -- the 42501 GV-281 defended against can no longer be raised on this path.

      ledger_generated := 0;

      for tmpl in
        select *
        from public.recurring_expenses r
        where r.ledger_id = due_ledger.ledger_id
          and r.is_active
          and r.deleted_at is null
          and r.next_due_date <= current_date
          and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
        order by r.next_due_date
        for update skip locked
      loop
        due_date := tmpl.next_due_date;
        template_count := 0;
        occurrences := 0;

        while due_date <= current_date and occurrences < max_catchup_occurrences loop
          insert into public.workspace_expenses (
            ledger_id, period_id, category, description, amount_dkk, expense_date,
            split_rule, split_config, paid_by_member_id, created_by_member_id,
            recurring_expense_id, occurrence_date
          ) values (
            due_ledger.ledger_id,
            open_period_id,
            tmpl.category,
            tmpl.description,
            tmpl.amount_dkk,
            due_date,
            tmpl.split_rule,
            tmpl.split_config,
            tmpl.paid_by_member_id,
            tmpl.created_by_member_id,
            tmpl.id,
            due_date
          )
          on conflict (recurring_expense_id, occurrence_date)
            where recurring_expense_id is not null do nothing
          returning id into inserted_id;

          if inserted_id is not null then
            template_count := template_count + 1;
          end if;
          inserted_id := null;
          occurrences := occurrences + 1;

          due_date := (case tmpl.cadence
            when 'monthly' then due_date + interval '1 month'
            when 'quarterly' then due_date + interval '3 months'
            when 'semiannual' then due_date + interval '6 months'
            when 'yearly' then due_date + interval '1 year'
            else due_date + interval '1 month'
          end)::date;
        end loop;

        update public.recurring_expenses
          set next_due_date = due_date, last_generated_at = now(), updated_at = now()
        where id = tmpl.id;

        if template_count > 0 then
          insert into public.ledger_events (
            ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
          ) values (
            due_ledger.ledger_id,
            'expense_recurring_added',
            'Fast udgift tilføjet',
            coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
              || ' blev automatisk tilføjet og delt.',
            null,
            null,
            jsonb_build_object(
              'category', tmpl.category,
              'recurring_expense_id', tmpl.id,
              'count', template_count
            )
          );
          ledger_generated := ledger_generated + template_count;
        end if;
      end loop;

      if ledger_generated > 0 then
        ledgers_touched := ledgers_touched + 1;
        total_generated := total_generated + ledger_generated;
      end if;

      open_period_id := null;
    exception when others then
      -- Roll this ledger back (the subtransaction does this automatically) and keep
      -- sweeping. Record the first failure's SQLSTATE only — never message text or row
      -- values (GDPR).
      ledgers_skipped := ledgers_skipped + 1;
      if first_error_code is null then
        get stacked diagnostics first_error_code = returned_sqlstate;
      end if;
      open_period_id := null;
    end;
  end loop;

  return jsonb_build_object(
    'generated', total_generated,
    'ledgers_touched', ledgers_touched,
    'ledgers_scanned', ledgers_scanned,
    'ledgers_skipped', ledgers_skipped,
    'first_error', first_error_code
  );
end;
$$;

revoke execute on function public.generate_all_due_recurring_expenses(integer) from public;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from anon;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from authenticated;
grant execute on function public.generate_all_due_recurring_expenses(integer) to service_role;

-- ── Register migration ──────────────────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('142_recurring_generation_carryover',
        'Recurring expense materialisations carry over into the queued settlement period during a lock instead of being deferred (GV-360). Both generators re-declared off migration 116 (their newest prior definition) with only the GV-281 entry-lock short-circuits deleted: generate_due_recurring_expenses no longer returns {generated:0, reason:''locked''}, and generate_all_due_recurring_expenses no longer skips and counts entry-locked ledgers. Migration 121''s assert_settlement_period_boundary_expenses trigger fires before enforce_settlement_entry_lock_expenses and, since migration 140, rebinds a live INSERT aimed at a locked open period into the queued carry-over period — so a recurring occurrence now behaves exactly like a manually logged expense during a payment freeze. Everything else is 116 verbatim: the no_open_period early return, FOR SHARE on the open period, FOR UPDATE SKIP LOCKED on templates, the 24-occurrence catch-up cap, the per-ledger BEGIN/EXCEPTION subtransaction, the SQLSTATE-only first_error (GDPR), the ledgers_skipped key (still counts per-ledger error rollbacks, read by /api/hooks/recurring-generate), and all grants/revokes.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── fuel_ledger_healthcheck — stop enumerating a function this migration removes ─
-- Re-declared off migration 037 (its newest prior definition). The body is 037
-- VERBATIM apart from a single deleted line: the ('production_activity_reset') entry
-- in critical_rpc_names. Without this, the diagnostic would report the RPC dropped
-- below as a missing critical RPC forever. The grant is tightened afterwards — the
-- healthcheck has no client caller and is run by the owner in the SQL Editor.
create or replace function public.fuel_ledger_healthcheck(target_ledger_id text default 'main-car')
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  with critical_rpc_names(rpc_name) as (
    values
      ('close_settlement_period'),
      ('upsert_trip_with_participants'),
      ('upsert_fuel_payment'),
      ('upsert_car_booking'),
      ('soft_delete_car_booking'),
      ('upsert_settlement_request_status'),
      ('upsert_ledger_member_admin'),
      ('set_ledger_member_active_admin'),
      ('update_own_ledger_member_profile'),
      ('check_ledger_invite_email'),
      ('purge_generated_test_rows'),
      ('preview_retention_cleanup'),
      ('run_retention_cleanup'),
      ('upsert_test_lab_report'),
      ('list_my_ledgers'),
      ('create_private_ledger_workspace'),
      ('create_ledger_invite'),
      ('enforce_onboarding_rate_limit'),
      ('redeem_ledger_invite'),
      ('revoke_ledger_invite'),
      ('apply_payment_status_action')
  ),
  critical_rpc_status as (
    select jsonb_object_agg(
      rpc_name,
      exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = rpc_name
      )
      order by rpc_name
    ) as critical_rpcs
    from critical_rpc_names
  ),
  expected_schema_migrations(migration_id) as (
    values
      ('001_initial_schema'),
