-- ── generate_all_due_recurring_expenses — count the no-open-period ledgers ──────
-- Re-declared off migration 142 (its newest prior definition; 110/112/114/116 came
-- before it). The body is 142 VERBATIM plus one counter: the previously silent bare
-- `continue` now increments ledgers_no_open_period, and that key joins the returned
-- JSON. Everything else is untouched — the candidate scan, the per-ledger
-- BEGIN/EXCEPTION subtransaction, the 24-occurrence catch-up cap, the SQLSTATE-only
-- first_error (GDPR), the GV-360 carry-over behaviour, and every existing return key
-- including ledgers_skipped, which stays purely the per-ledger failure counter.
-- Service-role only (grants restated).
create or replace function public.generate_all_due_recurring_expenses(
  batch_limit integer default 200
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  due_ledger record;
  open_period_id uuid;
  tmpl record;
  due_date date;
  inserted_id uuid;
  template_count integer;
  occurrences integer;
  ledger_generated integer;
  total_generated integer := 0;
  ledgers_touched integer := 0;
  ledgers_scanned integer := 0;
  -- Ledgers rolled back on an unexpected error; first_error_code holds the FIRST
  -- failure's SQLSTATE only. GV-281 also counted entry-locked ledgers here; GV-360
  -- removed that deferral, so this is now purely the per-ledger failure counter. The
  -- key stays in the return contract either way — /api/hooks/recurring-generate in
  -- govehlo-web reads it.
  ledgers_skipped integer := 0;
  -- GV-362: ledgers walked away from because their open period vanished between the
  -- candidate scan (which already requires one to exist) and the FOR SHARE re-read —
  -- a close that committed in the gap. Kept apart from ledgers_skipped, which since
  -- GV-360 means "rolled back on an error" and nothing else; merging the two would
  -- leave the sweep unable to tell a quiet run from a run that silently skipped work.
  -- Before GV-362 the branch below incremented nothing at all (the bare `continue`
  -- dates to migration 116 and survived 142).
  ledgers_no_open_period integer := 0;
  first_error_code text := null;
  -- Same per-template catch-up bound as generate_due_recurring_expenses (GV-274).
  max_catchup_occurrences constant integer := 24;
begin
  for due_ledger in
    -- Only ledgers with a due active template (with an active payer, GV-277) AND an
    -- open period to receive it, oldest debt first, so no-open-period ledgers never
    -- occupy a batch slot and the most overdue ledger is caught up first under
    -- batch_limit (GV-274). Entry-locked ledgers are neither excluded here nor skipped
    -- in the loop any more (GV-360): their occurrences are materialised, and the
    -- period-boundary trigger rebinds them into the queued carry-over period.
    select r.ledger_id
    from public.recurring_expenses r
    where r.is_active
      and r.deleted_at is null
      and r.next_due_date <= current_date
      and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
      and exists (
        select 1
        from public.settlement_periods sp
        where sp.ledger_id = r.ledger_id
          and sp.status = 'open'
          and sp.closed_at is null
      )
    group by r.ledger_id
    order by min(r.next_due_date) asc, r.ledger_id
    limit greatest(coalesce(batch_limit, 200), 0)
  loop
    ledgers_scanned := ledgers_scanned + 1;

    -- GV-281: isolate each ledger in its own subtransaction so one bad ledger (a lock
    -- race, an unexpected constraint) can never abort the whole sweep again. On error
    -- we roll THIS ledger back (the exception block does this automatically), count it
    -- in ledgers_skipped, remember the first SQLSTATE (code only — no row values, GDPR),
    -- and CONTINUE with the next ledger.
    begin
      -- Materialise into the ledger's open period. If none is open (a period close
      -- briefly precedes the next open), skip this ledger this run; the next tick catches
      -- up. FOR SHARE serializes against a concurrent close (which exclusively locks the
      -- period row).
      select sp.id into open_period_id
      from public.settlement_periods sp
      where sp.ledger_id = due_ledger.ledger_id
        and sp.status = 'open'
        and sp.closed_at is null
      order by sp.opened_at desc
      limit 1
      for share of sp;

      if open_period_id is null then
        -- GV-362: count it instead of leaving the run silent. The candidate scan
        -- above requires an open period, so landing here means a close beat us to it;
        -- the next tick catches this ledger up.
        ledgers_no_open_period := ledgers_no_open_period + 1;
        open_period_id := null;
        continue;
      end if;

      -- GV-360: no entry-lock deferral here either. The insert below targets the open
      -- period; when that period is entry-locked, migration 121's
      -- assert_settlement_period_boundary_expenses trigger rebinds the row into the
      -- queued carry-over period (migration 140) before the entry-lock trigger runs, so
      -- the 42501 GV-281 defended against can no longer be raised on this path.

      ledger_generated := 0;

      for tmpl in
        select *
        from public.recurring_expenses r
        where r.ledger_id = due_ledger.ledger_id
          and r.is_active
          and r.deleted_at is null
          and r.next_due_date <= current_date
          and public.member_is_active_in_ledger(r.paid_by_member_id, r.ledger_id)
        order by r.next_due_date
        for update skip locked
      loop
        due_date := tmpl.next_due_date;
        template_count := 0;
        occurrences := 0;

        while due_date <= current_date and occurrences < max_catchup_occurrences loop
          insert into public.workspace_expenses (
            ledger_id, period_id, category, description, amount_dkk, expense_date,
            split_rule, split_config, paid_by_member_id, created_by_member_id,
            recurring_expense_id, occurrence_date
          ) values (
            due_ledger.ledger_id,
            open_period_id,
            tmpl.category,
            tmpl.description,
            tmpl.amount_dkk,
            due_date,
            tmpl.split_rule,
            tmpl.split_config,
            tmpl.paid_by_member_id,
            tmpl.created_by_member_id,
            tmpl.id,
            due_date
          )
          on conflict (recurring_expense_id, occurrence_date)
            where recurring_expense_id is not null do nothing
          returning id into inserted_id;

          if inserted_id is not null then
            template_count := template_count + 1;
          end if;
          inserted_id := null;
          occurrences := occurrences + 1;

          due_date := (case tmpl.cadence
            when 'monthly' then due_date + interval '1 month'
            when 'quarterly' then due_date + interval '3 months'
            when 'semiannual' then due_date + interval '6 months'
            when 'yearly' then due_date + interval '1 year'
            else due_date + interval '1 month'
          end)::date;
        end loop;

        update public.recurring_expenses
          set next_due_date = due_date, last_generated_at = now(), updated_at = now()
        where id = tmpl.id;

        if template_count > 0 then
          insert into public.ledger_events (
            ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
          ) values (
            due_ledger.ledger_id,
            'expense_recurring_added',
            'Fast udgift tilføjet',
            coalesce(nullif(tmpl.description, ''), initcap(tmpl.category))
              || ' blev automatisk tilføjet og delt.',
            null,
            null,
            jsonb_build_object(
              'category', tmpl.category,
              'recurring_expense_id', tmpl.id,
              'count', template_count
            )
          );
          ledger_generated := ledger_generated + template_count;
        end if;
      end loop;

      if ledger_generated > 0 then
        ledgers_touched := ledgers_touched + 1;
        total_generated := total_generated + ledger_generated;
      end if;

      open_period_id := null;
    exception when others then
      -- Roll this ledger back (the subtransaction does this automatically) and keep
      -- sweeping. Record the first failure's SQLSTATE only — never message text or row
      -- values (GDPR).
      ledgers_skipped := ledgers_skipped + 1;
      if first_error_code is null then
        get stacked diagnostics first_error_code = returned_sqlstate;
      end if;
      open_period_id := null;
    end;
  end loop;

  return jsonb_build_object(
    'generated', total_generated,
    'ledgers_touched', ledgers_touched,
    'ledgers_scanned', ledgers_scanned,
    'ledgers_skipped', ledgers_skipped,
    'ledgers_no_open_period', ledgers_no_open_period,
    'first_error', first_error_code
  );
end;
$$;

revoke execute on function public.generate_all_due_recurring_expenses(integer) from public;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from anon;
revoke execute on function public.generate_all_due_recurring_expenses(integer) from authenticated;
grant execute on function public.generate_all_due_recurring_expenses(integer) to service_role;

-- ── Register migration ──────────────────────────────────────────────────────────
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('143_drop_production_reset_and_sweep_visibility',
        'GV-361: production_activity_reset(text) is dropped. It deleted every settlement_request, trip_participant, trip, fuel_payment, car_booking and settlement_period for a ledger behind nothing but is_ledger_admin — no confirmation token, no undo — and had been unusable since migrations 120/121 made enforce_settlement_entry_lock reject its DELETEs on any ledger with a closed period, while never clearing workspace_expenses or vehicle_repairs. No client calls it. fuel_ledger_healthcheck is re-declared off migration 037 (its newest prior definition), byte-identical except for the deleted (''production_activity_reset'') entry in critical_rpc_names, so the diagnostic does not report the removed RPC as missing; its own grant is revoked from anon and authenticated (owner-only, SQL Editor). EXECUTE is also revoked from anon and authenticated on eleven more functions with no caller in either client, each verified against govehlo-mobile and govehlo-web (discounting the vendored generated types) and against the SQL for in-body callers: the SECURITY DEFINER-only helpers hash_ledger_invite_code, normalize_ledger_slug and enforce_onboarding_rate_limit, and the uncalled RPCs apply_payment_status_action, check_ledger_invite_email, create_ledger_invite, revoke_ledger_invite, update_own_ledger_member_profile, upsert_test_lab_report, purge_generated_test_rows and fuel_ledger_healthcheck. All stay defined. Three verified-unused functions deliberately keep their grant: is_operator_context (an RLS-shaped predicate, and prod policies are known to drift from these files), and calculate_period_entry_fingerprint and set_ledger_member_active_admin (both are called as authenticated by this repo''s own RLS role-matrix guard, both are already gated — member/operator and admin respectively — and both are strictly weaker than an RPC that keeps its grant). GV-362: generate_all_due_recurring_expenses re-declared off migration 142 (its newest prior definition), 142 verbatim plus a ledgers_no_open_period counter on the previously silent bare-continue branch, and that key added to the returned JSON. ledgers_skipped stays purely the per-ledger failure counter it became in 142, and every pre-existing key keeps its meaning for /api/hooks/recurring-generate.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 144: close a deferred booking-fuel entry as not_refuelled (GVM-428) ──
--
-- Mirrors supabase/migrations/144_close_deferred_booking_fuel.sql byte-identically
-- (the equivalence check diffs function bodies, comments included).

create or replace function public.close_deferred_booking_fuel(
  target_ledger_id text,
  target_trip_id uuid,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_member_id uuid;
  v_actor_email text;
  v_trip record;
begin
  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can close deferred fuel entries'
      using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member'
      using errcode = '42501';
  end if;

  if target_trip_id is null then
    raise exception 'Missing deferred trip id' using errcode = '22023';
  end if;

  select t.id, t.driver_member_id, t.created_by_member_id, t.fuel_resolution,
         t.completion_fuel_legacy_id
    into v_trip
    from public.trips t
    where t.id = target_trip_id
      and t.ledger_id = target_ledger_id
      and t.booking_id is not null
      and t.deleted_at is null
    for update of t;

  if not found then
    raise exception 'Deferred booking trip was not found' using errcode = '22023';
  end if;

  -- SECURITY DEFINER bypasses RLS, so the gate lives here. Creator OR driver OR
  -- admin (GV-253): the creator is whoever tapped "registrerer den senere", the
  -- driver is who the follow-up nags, and an admin can always unstick a workspace.
  if not (
    public.is_ledger_admin(target_ledger_id)
    or v_trip.driver_member_id = v_actor_member_id
    or v_trip.created_by_member_id = v_actor_member_id
  ) then
    raise exception 'Only the trip driver, its creator, or a ledger admin can close its deferred fuel entry'
      using errcode = '42501';
  end if;

  -- Idempotent: a replay (double tap, offline retry, two devices) finds the entry
  -- already closed and reports that instead of failing or logging a second event.
  if v_trip.fuel_resolution = 'not_refuelled' then
    return jsonb_build_object(
      'trip_id', v_trip.id,
      'fuel_resolution', 'not_refuelled',
      'already_closed', true
    );
  end if;

  -- Someone else (or an earlier queued write) found the receipt first. A close must
  -- never demolish a real, linked fuel payment — report the winning state instead.
  if v_trip.fuel_resolution = 'logged' and v_trip.completion_fuel_legacy_id is not null then
    return jsonb_build_object(
      'trip_id', v_trip.id,
      'fuel_resolution', 'logged',
      'fuel_id', (
        select fp.id
        from public.fuel_payments fp
        where fp.ledger_id = target_ledger_id
          and fp.legacy_id = v_trip.completion_fuel_legacy_id
          and fp.deleted_at is null
        limit 1
      ),
      'already_closed', false
    );
  end if;

  if v_trip.fuel_resolution <> 'deferred' then
    raise exception 'Trip does not have a deferred fuel entry' using errcode = '22023';
  end if;

  -- The trip may have become historical (even closed) before the driver gave up on
  -- the receipt — which is exactly the case this RPC exists for. Reuse migration
  -- 140's transaction-local metadata scrub bypass for this one fixed-column UPDATE:
  -- fuel_resolution participates in neither the settlement maths nor the archived
  -- fingerprint, no fuel row is created or removed, and enforce_trip_fuel_resolution
  -- still validates the result. No caller-controlled SQL runs while the flag is set,
  -- and it is cleared again before the event insert.
  perform set_config('govehlo.pii_scrub', '1', true);

  update public.trips t
  set fuel_resolution = 'not_refuelled',
      completion_fuel_legacy_id = null,
      updated_at = now()
  where t.id = target_trip_id
    and t.ledger_id = target_ledger_id
    and t.fuel_resolution = 'deferred';

  if not found then
    raise exception 'Deferred fuel close could not update the trip'
      using errcode = '40001';
  end if;

  perform set_config('govehlo.pii_scrub', '', true);

  -- Cross-client live sync IS a ledger_events insert: without this row the other
  -- members' devices keep the stale 'deferred' trip and go on nagging.
  if nullif(event_title, '') is not null then
    v_actor_email := nullif(lower(coalesce(auth.jwt() ->> 'email', '')), '');
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id, 'trip_fuel_closed', event_title, coalesce(event_body, ''),
      v_actor_member_id, v_actor_email,
      jsonb_build_object('trip_id', target_trip_id)
    );
  end if;

  return jsonb_build_object(
    'trip_id', target_trip_id,
    'fuel_resolution', 'not_refuelled',
    'already_closed', false
  );
end;
$$;

revoke all on function public.close_deferred_booking_fuel(text, uuid, text, text) from public;
revoke all on function public.close_deferred_booking_fuel(text, uuid, text, text) from anon;
grant execute on function public.close_deferred_booking_fuel(text, uuid, text, text) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '144_close_deferred_booking_fuel',
  'Close a deferred booking-fuel entry as not_refuelled (GVM-428): new close_deferred_booking_fuel(text, uuid, text, text) gives the "Jeg tankede — registrerer den senere" state a second exit that needs no amount and no litres, so a mistaken tap or a lost receipt stops nagging Home, Log and the Afregn pre-request warning forever. Gated to the trip driver, its creator, or a ledger admin; idempotent on replay; never demolishes an already-logged fuel payment; writes a trip_fuel_closed ledger_event so other devices live-sync.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 145: suspend a deactivated member's recurring templates on the path the clients actually use (GV-373) ──
--
-- Mirrors supabase/migrations/145_member_upsert_recurring_suspension.sql byte-identically
-- (the equivalence check diffs function bodies, comments included).
create or replace function public.upsert_ledger_member_admin(
  target_ledger_id text default 'main-car',
  target_member_id uuid default null,
  member_name text default null,
  member_email text default null,
  member_mobilepay_phone text default null,
  member_role text default 'member',
  member_is_active boolean default true
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  existing_member public.ledger_members%rowtype;
  saved_member_id uuid;
  normalized_email text := nullif(lower(trim(coalesce(member_email, ''))), '');
  normalized_role text := case when member_role = 'admin' then 'admin' else 'member' end;
  active_admin_count integer := 0;
  suspended_count integer := 0;
  suspended_names text;
begin
  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can manage members' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not identify the current ledger admin' using errcode = '42501';
  end if;

  if nullif(trim(coalesce(member_name, '')), '') is null then
    raise exception 'Member name is required' using errcode = '23502';
  end if;

  if normalized_email is null then
    raise exception 'Member login email is required' using errcode = '23502';
  end if;

  -- Invite-only onboarding: this RPC may only update existing members. New members
  -- join by redeeming a workspace invite (redeem_ledger_invite), which enforces
  -- consent, expiry, max-uses, and rate limits. Reject creating a brand-new member
  -- row (null target_member_id) for everyone, including the app owner.
  if target_member_id is null then
    raise exception 'New members join by redeeming a workspace invite; member management can only update existing members' using errcode = '42501';
  end if;

  select * into existing_member
  from public.ledger_members
  where id = target_member_id and ledger_id = target_ledger_id
  for update;

  if existing_member.id is null then
    raise exception 'Member does not belong to this ledger' using errcode = '23503';
  end if;

  if existing_member.id = actor_member_id and (member_is_active is false or normalized_role <> 'admin') then
    raise exception 'Admins cannot demote or deactivate themselves' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtext(target_ledger_id || ':member-admin'));

  update public.ledger_members
  set name = trim(member_name),
      email = normalized_email,
      mobilepay_phone = nullif(trim(coalesce(member_mobilepay_phone, '')), ''),
      role = normalized_role,
      is_active = coalesce(member_is_active, true),
      updated_at = now()
  where id = target_member_id and ledger_id = target_ledger_id
  returning id into saved_member_id;

  select count(*) into active_admin_count
  from public.ledger_members
  where ledger_id = target_ledger_id and is_active = true and role = 'admin';

  if active_admin_count < 1 then
    raise exception 'At least one active admin is required' using errcode = '23514';
  end if;

  -- GV-373: on the active -> inactive TRANSITION, suspend every recurring template
  -- the member fronts. existing_member holds the pre-update row (it is selected
  -- before the update above), so this reads the real transition rather than the
  -- payload's is_active — a name or phone edit on an already-inactive member carries
  -- is_active = false too, and must stay a no-op. That gate is also the idempotency
  -- guarantee: a replayed deactivation finds the member already inactive, does
  -- nothing, and writes no second event.
  --
  -- Left active, a suspended-payer template would keep LOOKING live in Udgifter while
  -- the generators skip it (they gate on member_is_active_in_ledger, unchanged here),
  -- and the group would never be told. The event is what lights up the client half of
  -- this contract: the Activity-feed CTA and the Expenses badge from GVM-330.
  if existing_member.is_active is true and coalesce(member_is_active, true) is false then
    with suspended as (
      update public.recurring_expenses re
      set is_active = false, updated_at = now()
      where re.ledger_id = target_ledger_id
        and re.paid_by_member_id = target_member_id
        and re.is_active = true
        and re.deleted_at is null
      returning re.description, re.category
    )
    select count(*),
           string_agg(coalesce(nullif(btrim(s.description), ''), initcap(s.category)),
                      ', ' order by coalesce(nullif(btrim(s.description), ''), initcap(s.category)))
      into suspended_count, suspended_names
      from suspended s;

    if suspended_count > 0 then
      insert into public.ledger_events (
        ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata
      ) values (
        target_ledger_id,
        'recurring_suspended',
        'Faste udgifter sat på pause',
        coalesce(existing_member.name, 'Et medlem')
          || ' blev deaktiveret, så deres faste udgifter blev sat på pause: '
          || suspended_names
          || '. Vælg en ny betaler eller slet dem.',
        actor_member_id,
        nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
        target_member_id,
        jsonb_build_object('deactivated_member_id', target_member_id, 'suspended_count', suspended_count)
      );
    end if;
  end if;

  -- Re-activation is deliberately NOT symmetric: bringing a member back does not
  -- resume anything. Auto-resuming would be a money surprise on two counts. The feed
  -- told the group these were paused and nothing would say they restarted; and the
  -- generators catch up on missed occurrences (bounded at max_catchup_occurrences =
  -- 24 since GV-274), so a template paused for months would materialise its whole
  -- backlog as real charges the moment the member was re-activated — money nobody
  -- asked for, from a tap that only said "this person is back".
  --
  -- The resolution path is an explicit admin action that already ships: GVM-330's
  -- reassignment sheet repoints the payer and flips is_active back on through the
  -- ordinary upsert_recurring_expense write. Re-activating the original member simply
  -- makes the template stop being flagged as payer-orphaned (the client keys that off
  -- the payer being absent from the active roster) while it stays paused until
  -- someone deliberately resumes it. That is the same end state migration 114 leaves,
  -- so both deactivation paths continue to behave identically.

  return saved_member_id;
end;
$$;

revoke execute on function public.upsert_ledger_member_admin(text, uuid, text, text, text, text, boolean) from public;
grant execute on function public.upsert_ledger_member_admin(text, uuid, text, text, text, text, boolean) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '145_member_upsert_recurring_suspension',
  'upsert_ledger_member_admin re-declared off 042: on the active -> inactive transition it suspends every recurring template the member pays for and writes the recurring_suspended ledger_events row, closing GV-373. Migration 114 put that behaviour on set_ledger_member_active_admin, which no client calls — both clients deactivate through this RPC''s is_active parameter (migration 143''s notes say so), so GV-277 never fired in production and GVM-330''s reassignment CTA/badge stayed dark. Not a money bug: both generators already skip inactive-payer templates via member_is_active_in_ledger and are untouched; the defect was a stale is_active in Udgifter plus a missing feed entry. Unlike 114 this gates on the TRANSITION (pre-update is_active) rather than the payload value, because this RPC is the full-member upsert the clients also call for name/email/phone/role edits, which carry the current is_active along; that gate is also what makes a replay silent. Event copy is byte-identical to 114''s so both writers render the same card. Re-activation deliberately does not resume templates (backlog catch-up would be a money surprise); resolution stays GVM-330''s explicit reassignment.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 146: acknowledge a booked syn so the reminder stops for the whole workspace (GVM-442) ──
--
-- Mirrors supabase/migrations/146_acknowledge_inspection_booking.sql byte-identically
-- (the equivalence check diffs function bodies, comments included).
create or replace function public.acknowledge_inspection_booking(
  target_ledger_id text,
  acknowledged_inspection_date date,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_member_id uuid;
  v_actor_email text;
  v_actor_first text;
  v_syn_date date;
  v_previous_ack date;
  v_title text;
  v_body text;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can acknowledge a booked inspection'
      using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member'
      using errcode = '42501';
  end if;

  -- Lock the workspace row: two devices acknowledging at once must not interleave
  -- into a half-written marker (a date with nobody's name against it).
  select nullif(l.vehicle_info ->> 'next_inspection_date', '')::date,
         nullif(l.vehicle_info ->> 'syn_booked_for', '')::date
    into v_syn_date, v_previous_ack
    from public.ledgers l
    where l.id = target_ledger_id
    for update;

  if not found then
    raise exception 'Workspace was not found' using errcode = '22023';
  end if;

  v_actor_email := nullif(lower(coalesce(auth.jwt() ->> 'email', '')), '');

  select split_part(coalesce(nullif(btrim(m.name), ''), 'Nogen'), ' ', 1)
    into v_actor_first
    from public.ledger_members m
    where m.id = v_actor_member_id;
  v_actor_first := coalesce(v_actor_first, 'Nogen');

  -- ── Clear the acknowledgement (null date) ──────────────────────────────────────
  if acknowledged_inspection_date is null then
    -- Idempotent: nothing acknowledged means nothing to clear, so no write and no
    -- second event.
    if v_previous_ack is null then
      return jsonb_build_object(
        'acknowledged_for', null,
        'acknowledged_by_member_id', null,
        'changed', false
      );
    end if;

    update public.ledgers l
    set vehicle_info = l.vehicle_info
          - 'syn_booked_for'
          - 'syn_booked_at'
          - 'syn_booked_by_member_id',
        updated_at = now()
    where l.id = target_ledger_id;

    v_title := coalesce(nullif(btrim(event_title), ''), v_actor_first || ' fjernede syn-bookingen');
    v_body := coalesce(nullif(btrim(event_body), ''), 'Påmindelsen om syn er tilbage.');

    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id,
      'vehicle_inspection_booking_cleared',
      v_title,
      v_body,
      v_actor_member_id,
      v_actor_email,
      jsonb_build_object('inspection_date', v_previous_ack::text)
    );

    return jsonb_build_object(
      'acknowledged_for', null,
      'acknowledged_by_member_id', null,
      'changed', true
    );
  end if;

  -- ── Acknowledge the current inspection date ───────────────────────────────────
  if v_syn_date is null then
    raise exception 'This workspace has no next inspection date to acknowledge'
      using errcode = '22023';
  end if;

  -- The ack names its date, so it may only ever name the CURRENT one. A stale client,
  -- or a register refresh that landed in between, would otherwise silence a date
  -- nobody is being reminded about — or park an ack the live date later grows into.
  if acknowledged_inspection_date <> v_syn_date then
    raise exception 'The acknowledged inspection date is not this workspace''s next inspection date'
      using errcode = '22023';
  end if;

  -- Idempotent: a replay (double tap, offline retry, a second device) finds the same
  -- date already acknowledged and writes neither a marker nor a second event.
  if v_previous_ack = acknowledged_inspection_date then
    return jsonb_build_object(
      'acknowledged_for', acknowledged_inspection_date::text,
      'acknowledged_by_member_id',
        nullif((select l.vehicle_info ->> 'syn_booked_by_member_id'
                from public.ledgers l where l.id = target_ledger_id), ''),
      'changed', false
    );
  end if;

  update public.ledgers l
  set vehicle_info = l.vehicle_info || jsonb_build_object(
        'syn_booked_for', acknowledged_inspection_date::text,
        'syn_booked_at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'syn_booked_by_member_id', v_actor_member_id::text
      ),
      updated_at = now()
  where l.id = target_ledger_id;

  v_title := coalesce(nullif(btrim(event_title), ''), v_actor_first || ' har booket synet');
  v_body := coalesce(
    nullif(btrim(event_body), ''),
    'Syn senest ' || to_char(v_syn_date, 'DD-MM-YYYY') || '. Påmindelsen er slået fra indtil da.'
  );

  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id,
    'vehicle_inspection_booked',
    v_title,
    v_body,
    v_actor_member_id,
    v_actor_email,
    jsonb_build_object('inspection_date', acknowledged_inspection_date::text)
  );

  return jsonb_build_object(
    'acknowledged_for', acknowledged_inspection_date::text,
    'acknowledged_by_member_id', v_actor_member_id::text,
    'changed', true
  );
end;
$$;

revoke all on function public.acknowledge_inspection_booking(text, date, text, text) from public;
revoke all on function public.acknowledge_inspection_booking(text, date, text, text) from anon;
grant execute on function public.acknowledge_inspection_booking(text, date, text, text) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '146_acknowledge_inspection_booking',
  'Acknowledge a booked syn so Home''s syn_due reminder stops for the WHOLE workspace (GVM-442): new member-callable acknowledge_inspection_booking(text, date, text, text) stamps syn_booked_for / syn_booked_at / syn_booked_by_member_id into the existing ledgers.vehicle_info jsonb, beside next_inspection_date and the GVM-443/446 member-confirmed ejerafgift keys. Gated on is_ledger_member, not is_ledger_admin — booking an inspection is not an administrative act, and admin-gating would recreate the ticket''s bug (the person who booked could not tell the others), which is also why update_ledger_settings could not be reused. The ack names WHICH date it acknowledges, so it is self-invalidating: a new next_inspection_date stops matching and the reminder returns with no reset logic; an ack for any other date is rejected. A null date clears the acknowledgement, so a mistaken tap or a cancelled garage slot cannot leave the group with no syn reminder. Both paths are idempotent (a replay writes no second event) and both write a ledger_events row unconditionally — cross-client live sync IS that insert (migration 087 lesson), so an omitted event_title falls back to server-composed Danish copy rather than skipping it.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ── Migration 147: retire ten dead RPCs and the legacy push_subscriptions table ──
-- Mirrored from supabase/migrations/147_retire_dead_rpcs_and_legacy_push_subscriptions.sql.
-- Last definition wins on replay, so the create-or-replace blocks below supersede every
-- earlier definition in this file and the drops remove the objects those earlier blocks
-- created. Function bodies are byte-identical to the migration, in-body comments included.

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1. fuel_ledger_healthcheck -- stop asking for what step 3 removes  (GV-383/GV-311)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Re-declared off migration 143 (its newest prior definition -- the GV-202 rule; an
-- equivalence check structurally cannot catch drift introduced by an intermediate
-- definition, so the base has to be the highest-numbered one). The body is 143
-- VERBATIM apart from four deletions, all of them entries naming objects this
-- migration removes:
--
--   a. critical_rpc_names loses its ten dead entries, 21 -> 11. What survives is the
--      list of RPCs a client can actually reach, which is what a "critical RPC"
--      diagnostic was ever supposed to mean.
--   b. expected_tables loses ('push_subscriptions').
--   c. expected_columns loses ('push_subscriptions', 'user_email').
--   d. workspace_readiness.invite_onboarding_ready loses its create_ledger_invite,
--      revoke_ledger_invite and check_ledger_invite_email existence probes. It keeps
--      the ledger_invites TABLE probe and the redeem_ledger_invite probe, which is
--      now exactly what "invite onboarding is ready" means: members still join by
--      redeeming a join code (migration 045), which is what superseded these three.
--
-- NOTHING ELSE CHANGES -- in particular expected_schema_migrations is left exactly as
-- migration 143 left it. It is a frozen list ending at 037 and it is the SUBJECT of
-- GV-392 below, not a target: editing it here would move the very strings whose
-- accidental presence was masking the missing tracker rows.
create or replace function public.fuel_ledger_healthcheck(target_ledger_id text default 'main-car')
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  with critical_rpc_names(rpc_name) as (
    values
      ('close_settlement_period'),
      ('upsert_trip_with_participants'),
      ('upsert_fuel_payment'),
      ('upsert_car_booking'),
      ('soft_delete_car_booking'),
      ('upsert_settlement_request_status'),
      ('upsert_ledger_member_admin'),
      ('list_my_ledgers'),
      ('create_private_ledger_workspace'),
      ('enforce_onboarding_rate_limit'),
      ('redeem_ledger_invite')
  ),
  critical_rpc_status as (
    select jsonb_object_agg(
      rpc_name,
      exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = rpc_name
      )
      order by rpc_name
    ) as critical_rpcs
    from critical_rpc_names
  ),
  expected_schema_migrations(migration_id) as (
    values
      ('001_initial_schema'),
      ('002_auth_helpers'),
      ('003_payment_booking_guards'),
      ('004_period_close_and_admin_rpcs'),
      ('005_rls_policies'),
      ('006_realtime_ledger_events'),
      ('007_security_health_rpc'),
      ('008_scheduled_reminder_rpcs'),
      ('009_retention_privacy_cleanup'),
      ('010_trip_transaction_rpc'),
      ('011_booking_transaction_rpcs'),
      ('012_admin_tools_guardrails'),
      ('013_fuel_payment_rpc'),
      ('014_rpc_health_visibility'),
      ('015_test_lab_report_store'),
      ('016_realtime_publication_health'),
      ('017_healthcheck_rpc_detection_fix'),
      ('018_realtime_publication_cleanup'),
      ('019_immutable_test_lab_report_history'),
      ('020_bootstrap_lock'),
      ('021_cloud_test_lab_report_retention'),
      ('022_settlement_request_transaction_rpc'),
      ('023_schema_migration_tracking'),
      ('024_schema_drift_healthcheck'),
      ('025_workspace_foundation'),
      ('026_invite_onboarding_foundation'),
      ('027_invite_code_generation_pgcrypto_fix'),
      ('028_invite_code_hash_pgcrypto_fix'),
      ('029_invite_redeem_return_ambiguity_fix'),
      ('030_onboarding_abuse_rate_limits'),
      ('031_payment_status_action_rpc'),
      ('032_security_health_current_migration_expectations'),
      ('033_onboarding_rate_limit_scope_key_alignment'),
      ('034_invite_rate_limit_actor_email_ambiguity_fix'),
      ('035_sql_ambiguity_guardrail'),
      ('036_invite_profile_setup'),
      ('037_invite_email_preflight')
  ),
  migration_status as (
    select
      (select max(migration_id) from expected_schema_migrations) as latest_expected,
      (select max(migration_id) from public.fuel_ledger_schema_migrations) as latest_applied,
      coalesce((
        select jsonb_agg(e.migration_id order by e.migration_id)
        from expected_schema_migrations e
        where not exists (
          select 1
          from public.fuel_ledger_schema_migrations m
          where m.migration_id = e.migration_id
        )
      ), '[]'::jsonb) as missing_migrations,
      coalesce((
        select jsonb_agg(m.migration_id order by m.migration_id)
        from public.fuel_ledger_schema_migrations m
        where not exists (
          select 1
          from expected_schema_migrations e
          where e.migration_id = m.migration_id
        )
      ), '[]'::jsonb) as extra_migrations
  ),
  expected_tables(table_name) as (
    values
      ('ledgers'),
      ('ledger_members'),
      ('ledger_invites'),
      ('ledger_onboarding_rate_limits'),
      ('trips'),
      ('trip_participants'),
      ('fuel_payments'),
      ('car_bookings'),
      ('settlement_requests'),
      ('settlement_periods'),
      ('ledger_events'),
      ('test_lab_reports'),
      ('fuel_ledger_schema_migrations')
  ),
  missing_tables as (
    select coalesce(jsonb_agg(format('public.%I', table_name) order by table_name), '[]'::jsonb) as items
    from expected_tables et
    where not exists (
      select 1
      from information_schema.tables t
      where t.table_schema = 'public'
        and t.table_name = et.table_name
    )
  ),
  expected_columns(table_name, column_name) as (
    values
      ('ledgers', 'id'),
      ('ledgers', 'slug'),
      ('ledgers', 'name'),
      ('ledgers', 'created_by_member_id'),
      ('ledgers', 'is_public_signup_enabled'),
      ('ledgers', 'invite_required'),
      ('ledgers', 'bootstrap_locked_at'),
      ('ledger_members', 'ledger_id'),
      ('ledger_members', 'email'),
      ('ledger_members', 'role'),
      ('ledger_members', 'is_active'),
      ('ledger_invites', 'ledger_id'),
      ('ledger_invites', 'invite_code_hash'),
      ('ledger_invites', 'role'),
      ('ledger_invites', 'invited_email'),
      ('ledger_invites', 'max_uses'),
      ('ledger_invites', 'uses_count'),
      ('ledger_invites', 'expires_at'),
      ('ledger_invites', 'revoked_at'),
      ('ledger_onboarding_rate_limits', 'action'),
      ('ledger_onboarding_rate_limits', 'scope_key'),
      ('ledger_onboarding_rate_limits', 'window_started_at'),
      ('ledger_onboarding_rate_limits', 'attempts'),
      ('trips', 'ledger_id'),
      ('trips', 'driver_member_id'),
      ('trip_participants', 'trip_id'),
      ('trip_participants', 'member_id'),
      ('fuel_payments', 'ledger_id'),
      ('fuel_payments', 'payer_member_id'),
      ('car_bookings', 'ledger_id'),
      ('car_bookings', 'member_id'),
      ('settlement_requests', 'ledger_id'),
      ('settlement_requests', 'status'),
      ('settlement_periods', 'ledger_id'),
      ('ledger_events', 'ledger_id'),
      ('ledger_events', 'event_type'),
      ('test_lab_reports', 'report_payload'),
      ('fuel_ledger_schema_migrations', 'migration_id')
  ),
  missing_columns as (
    select coalesce(jsonb_agg(format('public.%I.%I', table_name, column_name) order by table_name, column_name), '[]'::jsonb) as items
    from expected_columns ec
    where not exists (
      select 1
      from information_schema.columns c
      where c.table_schema = 'public'
        and c.table_name = ec.table_name
        and c.column_name = ec.column_name
    )
  ),
  expected_policies(table_name, policy_name) as (
    values
      ('ledgers', 'Ledger members can read ledgers'),
      ('ledger_members', 'Ledger members can read members'),
      ('ledger_invites', 'Ledger admins can read invites'),
      ('ledger_invites', 'Ledger admins can update invites'),
      ('trips', 'Ledger members can read trips'),
      ('trip_participants', 'Ledger members can read trip participants'),
      ('fuel_payments', 'Ledger members can read fuel payments'),
      ('car_bookings', 'Ledger members can read car bookings'),
      ('settlement_requests', 'Ledger members can read settlement requests'),
      ('ledger_events', 'Ledger members can read ledger events'),
      ('test_lab_reports', 'Ledger members can read test lab reports'),
      ('fuel_ledger_schema_migrations', 'fuel_ledger_schema_migrations_admin_select')
  ),
  missing_policies as (
    select coalesce(jsonb_agg(format('public.%I:%s', table_name, policy_name) order by table_name, policy_name), '[]'::jsonb) as items
    from expected_policies ep
    where not exists (
      select 1
      from pg_policies pp
      where pp.schemaname = 'public'
        and pp.tablename = ep.table_name
        and pp.policyname = ep.policy_name
    )
  ),
  schema_drift_status as (
    select
      missing_tables.items as missing_tables,
      missing_columns.items as missing_columns,
      missing_policies.items as missing_policies,
      jsonb_array_length(missing_tables.items) = 0
        and jsonb_array_length(missing_columns.items) = 0
        and jsonb_array_length(missing_policies.items) = 0 as ok
    from missing_tables, missing_columns, missing_policies
  ),
  workspace_status as (
    select jsonb_build_object(
      'ok', true,
      'public_signup_default', false,
      'invite_required_default', true,
      'main_ledger_id', target_ledger_id,
      'workspace_foundation_ready',
        exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'ledgers' and column_name = 'slug')
        and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'list_my_ledgers')
        and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'create_private_ledger_workspace'),
      'invite_onboarding_ready',
        exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'ledger_invites')
        and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'redeem_ledger_invite'),
      'abuse_rate_limit_ready',
        exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'ledger_onboarding_rate_limits')
        and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'enforce_onboarding_rate_limit')
    ) as payload
  )
  select jsonb_build_object(
    'ok', true,
    'ledger_id', target_ledger_id,
    'close_settlement_period_exists',
      exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = 'close_settlement_period'
      ),
    'critical_rpcs', critical_rpc_status.critical_rpcs,
    'schema_migrations', jsonb_build_object(
      'table', 'public.fuel_ledger_schema_migrations',
      'latest_expected', migration_status.latest_expected,
      'latest_applied', migration_status.latest_applied,
      'missing_migrations', migration_status.missing_migrations,
      'extra_migrations', migration_status.extra_migrations,
      'ok', jsonb_array_length(migration_status.missing_migrations) = 0
    ),
    'schema_drift', jsonb_build_object(
      'ok', schema_drift_status.ok,
      'missing_tables', schema_drift_status.missing_tables,
      'missing_columns', schema_drift_status.missing_columns,
      'missing_policies', schema_drift_status.missing_policies
    ),
    'workspace_readiness', workspace_status.payload,
    'realtime_publication', jsonb_build_object(
      'publication', 'supabase_realtime',
      'recommended_tables', jsonb_build_array('public.ledger_events'),
      'tables', coalesce((
        select jsonb_agg(format('%I.%I', schemaname, tablename) order by schemaname, tablename)
        from pg_publication_tables
        where pubname = 'supabase_realtime'
          and schemaname = 'public'
      ), '[]'::jsonb),
      'extra_tables', coalesce((
        select jsonb_agg(format('%I.%I', schemaname, tablename) order by schemaname, tablename)
        from pg_publication_tables
        where pubname = 'supabase_realtime'
          and schemaname = 'public'
          and tablename <> 'ledger_events'
      ), '[]'::jsonb),
      'ledger_events_enabled', exists (
        select 1
        from pg_publication_tables
        where pubname = 'supabase_realtime'
          and schemaname = 'public'
          and tablename = 'ledger_events'
      )
    ),
    'checked_at', now()
  )
  from critical_rpc_status, migration_status, schema_drift_status, workspace_status;
$$;

-- `create or replace` preserves the existing ACL, so 143's revokes survive it; they
-- are repeated by name because that is the only way to read this file and know the
-- diagnostic is still owner-only. No client calls it; the owner runs it in the SQL
-- Editor and owns the function, so owner access is unaffected.
revoke all on function public.fuel_ledger_healthcheck(text) from public;
revoke all on function public.fuel_ledger_healthcheck(text) from anon;
revoke all on function public.fuel_ledger_healthcheck(text) from authenticated;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2. delete_my_account -- stop scrubbing a table step 4 removes          (GV-311)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Re-declared off migration 138 (its newest prior definition -- the GV-202 rule).
-- Every definition in between was checked: 056 -> 057 -> 071 -> 072 -> 096 -> 111 ->
-- 138, and 138 is the highest. The body is 138 VERBATIM apart from the deletion of
-- one two-line statement:
--
--     delete from public.push_subscriptions ps
--     where lower(ps.user_email) = v_email;
--
-- GDPR is unaffected, and that is the point: the statement is dropped because the
-- TABLE is dropped in step 4, which erases every row in it for every user at once --
-- strictly more deletion than the per-account scrub achieved. The account's real push
-- identity lives in expo_push_tokens (migration 057) and that delete is untouched,
-- three statements further down. push_subscriptions is the legacy Web Push
-- subscription store from the retired PWA runtime (archived at tag
-- legacy-runtime-final); the React Native app has never written to it.
--
-- The "Cross-ledger cleanup keyed by identity rather than membership" comment stays --
-- it introduces the ledger_onboarding_rate_limits and owner_activity_log statements
-- that follow, not only the removed one.
create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := public.current_user_email();
  v_member record;
  v_old_name text;
  v_first_name text;
  v_anon_name text;
  v_suffix integer;
  v_no_other_active boolean;
  v_successor record;
  v_ledgers_scrubbed integer := 0;
  v_ledgers_deleted integer := 0;
  v_admins_promoted integer := 0;
begin
  if v_uid is null or v_email is null then
    raise exception 'Account deletion requires a signed-in user' using errcode = '42501';
  end if;

  -- Let the settlement lock trigger (GV-199) know these writes are GDPR PII
  -- scrubs, not settlement edits, so its closed-period rejection stands aside.
  -- Transaction-local, so it clears automatically at commit/rollback.
  perform set_config('govehlo.pii_scrub', '1', true);

  for v_member in
    select lm.id, lm.ledger_id, lm.name, lm.role, lm.is_active
    from public.ledger_members lm
    where lm.email is not null
      and lower(lm.email) = v_email
  loop
    v_old_name := v_member.name;
    v_first_name := split_part(v_old_name, ' ', 1);

    -- No other active member left? The workspace dies with this account: nobody
    -- could ever access it again, so full deletion is the cleanest erasure.
    -- Every child table references ledgers(id) with on delete cascade.
    select not exists (
      select 1
      from public.ledger_members lm2
      where lm2.ledger_id = v_member.ledger_id
        and lm2.is_active = true
        and lm2.id <> v_member.id
    ) into v_no_other_active;
    if v_no_other_active then
      delete from public.ledgers l where l.id = v_member.ledger_id;
      v_ledgers_deleted := v_ledgers_deleted + 1;
      continue;
    end if;

    -- Admin succession: never leave a live workspace admin-less. Promote the
    -- longest-standing active member and say so in the feed (system actor).
    if v_member.is_active and v_member.role = 'admin' and not exists (
      select 1
      from public.ledger_members lm3
      where lm3.ledger_id = v_member.ledger_id
        and lm3.is_active = true
        and lm3.role = 'admin'
        and lm3.id <> v_member.id
    ) then
      select lm4.id, lm4.name
      into v_successor
      from public.ledger_members lm4
      where lm4.ledger_id = v_member.ledger_id
        and lm4.is_active = true
        and lm4.id <> v_member.id
      order by lm4.created_at asc, lm4.id asc
      limit 1;

      update public.ledger_members lm5
      set role = 'admin', updated_at = now()
      where lm5.id = v_successor.id;

      insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata)
      values (
        v_member.ledger_id,
        'member_promoted',
        v_successor.name || ' er nu administrator',
        'Automatisk, fordi den tidligere administrator slettede sin konto',
        null,
        null,
        v_successor.id,
        jsonb_build_object('reason', 'account_deleted')
      );
      v_admins_promoted := v_admins_promoted + 1;
    end if;

    -- Per-ledger-unique anonymized name (unique(ledger_id, name) would reject a
    -- second 'Slettet medlem' in the same group).
    v_anon_name := 'Slettet medlem';
    v_suffix := 1;
    while exists (
      select 1
      from public.ledger_members lm6
      where lm6.ledger_id = v_member.ledger_id
        and lm6.name = v_anon_name
        and lm6.id <> v_member.id
    ) loop
      v_suffix := v_suffix + 1;
      v_anon_name := 'Slettet medlem ' || v_suffix;
    end loop;

    -- Authored free text: trip notes are the creator's words, not car facts.
    update public.trips t
    set note = null, updated_at = now()
    where t.ledger_id = v_member.ledger_id
      and t.created_by_member_id = v_member.id
      and t.note is not null;

    -- Bookings: purposes are authored text; future bookings would block the car
    -- for a person who no longer exists.
    update public.car_bookings cb
    set purpose = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.purpose is not null;

    -- Structured fuel stop (migration 063): the from/to labels + lat/lng are the
    -- member's route history — potentially their home address. Null the whole
    -- jsonb; station coords are public, but from/to are personal, so simplest-
    -- correct wins (GV-197).
    update public.car_bookings cb
    set fuel_stop = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.fuel_stop is not null;

    update public.car_bookings cb
    set deleted_at = now(), updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and cb.member_id = v_member.id
      and cb.start_at > now()
      and cb.deleted_at is null;

    -- Chat: blank + soft-delete their messages (the app already filters deleted).
    update public.messages msg
    set body = '', deleted_at = coalesce(msg.deleted_at, now())
    where msg.ledger_id = v_member.ledger_id
      and msg.sender_member_id = v_member.id;

    -- Incident photos (GVM-396): the photos belong to the workspace (they die with
    -- the incident or the workspace via cascade). Only the authorship pointer is
    -- personal, so detach it. The incident rows' own reporter/driver references
    -- are left pointing at this member row, which is anonymized in place below —
    -- exactly like trips.driver_member_id and every other retained reference.
    update public.vehicle_incident_photos vip
    set created_by_member_id = null
    where vip.ledger_id = v_member.ledger_id
      and vip.created_by_member_id = v_member.id;

    -- Feed events: drop stored emails and replace the member's name inside titles
    -- and bodies they authored or are targeted by. Events self-expire after 30
    -- days, so this is belt-and-braces on top of bounded retention. Very short
    -- first names (< 3 chars) are skipped for the substring pass — the collision
    -- risk with unrelated words outweighs the residual exposure.
    if char_length(v_first_name) < 3 then
      v_first_name := v_old_name;
    end if;
    update public.ledger_events ev
    set actor_email = case when ev.actor_member_id = v_member.id then null else ev.actor_email end,
        target_email = case when ev.target_member_id = v_member.id then null else ev.target_email end,
        title = replace(replace(ev.title, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem'),
        body = replace(replace(ev.body, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem')
    where ev.ledger_id = v_member.ledger_id
      and (ev.actor_member_id = v_member.id or ev.target_member_id = v_member.id);

    -- Archived snapshots: closed periods keep their maths, but the name fields
    -- inside people[] / settlements[] must stop identifying the person. The
    -- entry fingerprint (migration 054) covers trip/fuel ids only, never names,
    -- so this rewrite cannot invalidate any integrity check.
    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{people}',
      (
        select coalesce(jsonb_agg(
          case when person ->> 'id' = v_member.id::text
            then jsonb_set(person, '{name}', to_jsonb(v_anon_name))
            else person
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(sp.snapshot_json -> 'people') as person
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'people') = 'array';

    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{settlements}',
      (
        select coalesce(jsonb_agg(
          case when settled ->> 'toId' = v_member.id::text
            then jsonb_set(settled, '{toName}', to_jsonb(v_anon_name))
            else settled
          end
        ), '[]'::jsonb)
        from (
          select case when raw ->> 'fromId' = v_member.id::text
            then jsonb_set(raw, '{fromName}', to_jsonb(v_anon_name))
            else raw
          end as settled
          from jsonb_array_elements(sp.snapshot_json -> 'settlements') as raw
        ) as renamed
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'settlements') = 'array';

    -- Invites addressed to this email in this ledger.
    update public.ledger_invites li
    set invited_email = null, updated_at = now()
    where li.ledger_id = v_member.ledger_id
      and lower(coalesce(li.invited_email, '')) = v_email;

    -- Finally the member row itself. Role drops to 'member' (succession above
    -- already ensured another admin exists when one was needed). last_seen_at is
    -- nulled too (GVM-66): activity metadata must not outlive the account.
    update public.ledger_members lm7
    set name = v_anon_name,
        email = null,
        mobilepay_phone = null,
        role = 'member',
        is_active = false,
        last_seen_at = null,
        updated_at = now()
    where lm7.id = v_member.id;

    -- Feed transparency, in app voice, without re-publishing the old name.
    insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
    values (
      v_member.ledger_id,
      'member_deleted',
      'Et medlem slettede sin konto',
      v_anon_name || ' er anonymiseret. Gruppens regnskab er uændret.',
      null,
      null,
      jsonb_build_object('member_id', v_member.id)
    );

    v_ledgers_scrubbed := v_ledgers_scrubbed + 1;
  end loop;

  -- Cross-ledger cleanup keyed by identity rather than membership.
  delete from public.ledger_onboarding_rate_limits rl
  where lower(rl.actor_email) = v_email;

  update public.owner_activity_log oal
  set actor_email = null, actor_user_id = null
  where oal.actor_user_id = v_uid
     or lower(coalesce(oal.actor_email, '')) = v_email;

  -- Push tokens die with the account (migration 057): match by user id and by
  -- the scrubbed email so nothing keeps addressing this person's devices.
  delete from public.expo_push_tokens ept
  where ept.user_id = v_uid
     or lower(ept.email) = v_email;


  -- Purge this user's notification preferences (GV-229). No PII (three booleans
  -- + a uuid), but data minimisation says don't leave an orphaned row behind.
  delete from public.notification_preferences np where np.user_id = v_uid;

  -- Kill the credentials last: cascades sessions/identities, frees the email for
  -- a fresh sign-up. The caller's JWT stays technically valid until expiry but no
  -- longer matches any member (email scrubbed), so RLS yields nothing.
  delete from auth.users au where au.id = v_uid;

  return jsonb_build_object(
    'ledgers_scrubbed', v_ledgers_scrubbed,
    'ledgers_deleted', v_ledgers_deleted,
    'admins_promoted', v_admins_promoted
  );
end;
$$;

-- `create or replace` preserves the ACL (the grant dates from 056, re-asserted by
-- 083). Restated by name so this file is readable on its own, and so anon is denied
-- explicitly rather than by inheritance.
revoke all on function public.delete_my_account() from public;
revoke all on function public.delete_my_account() from anon;
grant execute on function public.delete_my_account() to authenticated;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 3. Drop the ten dead functions                                          (GV-383)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Every one of these is superseded, and the successor is named. `if exists` keeps
-- each statement idempotent on replay and on a database where it was already removed
-- by hand.
--
-- Superseded by migration 045's workspace join codes (resolve_ledger_invite /
-- redeem_ledger_invite / rotate_workspace_join_code):
drop function if exists public.create_ledger_invite(text, text, text, integer, integer);
drop function if exists public.revoke_ledger_invite(text, uuid);
drop function if exists public.check_ledger_invite_email(text, text);

-- Superseded by upsert_ledger_member_admin, which is what both clients call. This is
-- the function GV-277 built the recurring-suspension feature on while production
-- deactivated through the other one; migration 145 moved that behaviour across.
drop function if exists public.set_ledger_member_active_admin(text, uuid, boolean);

-- Superseded by set_member_name + update_own_ledger_member_mobilepay:
drop function if exists public.update_own_ledger_member_profile(text, text, text);

-- Superseded by transition_settlement_request_status:
drop function if exists public.apply_payment_status_action(text, uuid, uuid, uuid, numeric, text, text, text, text, text, jsonb, text[]);

-- Superseded by run_operational_retention (migration 131's GDPR retention policy).
-- These two are also the last readers of push_subscriptions besides delete_my_account,
-- so they must go before the table does.
drop function if exists public.preview_retention_cleanup(text, integer, integer, integer, integer);
drop function if exists public.run_retention_cleanup(text, integer, integer, integer, integer);

-- Orphaned with the legacy PWA runtime (removed from main in GV-266, archived at tag
-- legacy-runtime-final). The test_lab_reports TABLE and its immutable-history trigger
-- stay; only these two writers go.
drop function if exists public.upsert_test_lab_report(text, text, jsonb);
drop function if exists public.purge_generated_test_rows(text, boolean);

-- ═══════════════════════════════════════════════════════════════════════════════
-- 4. Drop the legacy push_subscriptions table                             (GV-311)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- The Web Push subscription store from the retired PWA. Verified against the replayed
-- catalog: no foreign key points AT it, it is not in the supabase_realtime
-- publication, and after steps 2 and 3 no function reads or writes it. Its own FK
-- (member_id -> ledger_members) and its four owner-scoped RLS policies go with it.
-- Native push has lived in expo_push_tokens since migration 057.
--
-- GDPR: this deletes the last stored Web Push endpoints, which are personal data.
-- That is a reduction in retained personal data, not a loss of a deletion path --
-- see step 2.
drop table if exists public.push_subscriptions;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 5. Backfill three tracker rows the consolidated schema never inserted   (GV-392)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- SEPARATE CONCERN from steps 1-4. It shares this file only because it shares a
-- release, and it is written here rather than only in supabase-schema.sql so that any
-- database bootstrapped from the consolidated schema self-heals when this migration
-- is applied.
--
-- Replaying supabase/migrations/*.sql produced 146 rows in
-- fuel_ledger_schema_migrations; replaying supabase-schema.sql produced 143. All three
-- of these migrations insert their own id in their own migration file, but the
-- consolidated schema had no INSERT for any of them -- so a fresh install booted
-- reporting three missing migrations against itself.
--
-- WHY NO GUARD CAUGHT IT, which is the part worth writing down: the mirror check in
-- tools/test-migrations.mjs was `consolidatedSchema.includes(migrationId)`, a bare
-- substring test. The only occurrences of these three strings in supabase-schema.sql
-- were inside fuel_ledger_healthcheck's own expected_schema_migrations VALUES list.
-- The substring satisfying the mirror guard WAS the expectation list of the drift
-- detector that would have reported the failure. check-schema-equivalence.mjs cannot
-- see it either -- tracker rows are data and it dumps schema-only, deliberately.
--
-- Both halves are fixed in this commit: the three INSERTs are added to
-- supabase-schema.sql where they belong, and the mirror check now requires a real
-- tracker INSERT statement (tools/lib/tracker-insert-scan.mjs) rather than any
-- substring, so a description string or an expectation list can never satisfy it
-- again. tools/test-retired-rpcs-functional.sh asserts the row count from the
-- consolidated schema as a standing regression test.
--
-- Idempotent, and a no-op in production, where all three were applied years of
-- migrations ago.
insert into public.fuel_ledger_schema_migrations (migration_id, description)
values
  ('024_schema_drift_healthcheck', 'Schema drift detection in fuel_ledger_healthcheck.'),
  ('033_onboarding_rate_limit_scope_key_alignment', 'Aligns onboarding rate-limit scope keys.'),
  ('036_invite_profile_setup', 'Invite profile setup during redemption.')
on conflict (migration_id) do nothing;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '147_retire_dead_rpcs_and_legacy_push_subscriptions',
  'GV-383: drops ten functions with no caller anywhere -- create_ledger_invite, revoke_ledger_invite and check_ledger_invite_email (superseded by migration 045 join codes), set_ledger_member_active_admin (superseded by upsert_ledger_member_admin, the RPC both clients actually call; migration 145 moved GV-277''s recurring-suspension behaviour across), update_own_ledger_member_profile (superseded by set_member_name + update_own_ledger_member_mobilepay), apply_payment_status_action (superseded by transition_settlement_request_status), preview_retention_cleanup and run_retention_cleanup (superseded by run_operational_retention), and upsert_test_lab_report + purge_generated_test_rows (orphaned with the legacy PWA runtime). Each was verified against the REPLAYED Postgres 17 catalog rather than migration text -- zero in-SQL callers, zero RLS policy references, zero trigger bindings, zero defaults/constraints/indexes/views, and zero client call sites in govehlo-mobile or govehlo-web once the vendored generated types are discounted, searching both indirection conventions (the sbRpc string-literal lookup table and the unquoted PostgREST /rest/v1/rpc/<name> path). enforce_onboarding_rate_limit is deliberately NOT dropped despite sitting in critical_rpc_names with no client caller: it has five live in-SQL callers. ledger_invites (the table) is deliberately NOT dropped: migration 143 left the legacy invite path write-closed, but resolve_ledger_invite and redeem_ledger_invite still read it and delete_my_account still updates it -- write-closed is not dead. test_lab_reports (the table) stays too. ORDER IS LOAD-BEARING: fuel_ledger_healthcheck is re-declared FIRST, off migration 143 (its newest prior definition), byte-identical except for four deletions -- the ten dead entries in critical_rpc_names (21 -> 11), (''push_subscriptions'') in expected_tables, (''push_subscriptions'', ''user_email'') in expected_columns, and the create_ledger_invite/revoke_ledger_invite/check_ledger_invite_email probes in workspace_readiness.invite_onboarding_ready -- so the operator diagnostic does not report as missing the objects it is itself the only thing still asking for. Its expected_schema_migrations list is untouched. GV-311: delete_my_account re-declared off migration 138 (its newest prior definition), 138 verbatim minus the two-line push_subscriptions scrub, then public.push_subscriptions is dropped -- the legacy Web Push store from the retired PWA runtime, with no inbound foreign key, no realtime publication membership and no remaining reader. Dropping the table deletes strictly more personal data than the per-account scrub did; native push identity lives in expo_push_tokens (migration 057) and that scrub is untouched. GV-392: backfills the 024_schema_drift_healthcheck, 033_onboarding_rate_limit_scope_key_alignment and 036_invite_profile_setup tracker rows, which supabase-schema.sql never inserted (146 rows from the migrations, 143 from the consolidated schema), so a fresh install booted reporting its own drift. Nothing caught it because tools/test-migrations.mjs mirrored by bare substring and the only occurrences of those ids in the consolidated schema were inside fuel_ledger_healthcheck''s own expected_schema_migrations list -- the substring satisfying the guard was the expectation list of the drift detector that would have reported it; check-schema-equivalence cannot see it either because tracker rows are data and it dumps schema-only. The mirror check now requires a real tracker INSERT (tools/lib/tracker-insert-scan.mjs).'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 148 mirror: anon-revoke convention applied backwards            (GV-380)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Convention only. Supabase bootstraps ALTER DEFAULT PRIVILEGES ... GRANT EXECUTE ON
-- FUNCTIONS TO anon, authenticated, service_role in schema public, so every function
-- is created with an EXPLICIT anon ACL entry that `revoke ... from public` never
-- touches. These 34 security-definer functions still carried it. No body, no
-- signature, no authenticated/service_role grant changes -- see
-- supabase/migrations/148_anon_execute_revoke_convention.sql for the full reasoning
-- and for why current_user_email() and is_valid_payment_status_transition() are
-- deliberately excluded.
revoke execute on function public.add_incident_photo(uuid, text) from anon;
revoke execute on function public.can_manage_car_booking(uuid) from anon;
revoke execute on function public.can_manage_fuel_payment(uuid) from anon;
revoke execute on function public.can_manage_trip(uuid) from anon;
revoke execute on function public.current_ledger_member_id(text) from anon;
revoke execute on function public.delete_incident_photo(uuid) from anon;
revoke execute on function public.delete_push_token(text) from anon;
revoke execute on function public.emit_inspection_due_event(text) from anon;
revoke execute on function public.enforce_identity_reassignment() from anon;
revoke execute on function public.enforce_settlement_request_integrity() from anon;
revoke execute on function public.get_notification_preferences() from anon;
revoke execute on function public.is_ledger_admin(text) from anon;
revoke execute on function public.is_ledger_member(text) from anon;
revoke execute on function public.lock_ledger_bootstrap_when_admin_email_attached() from anon;
revoke execute on function public.log_vehicle_incident(text, date, text, text, uuid, uuid, uuid, integer, text, text, text, text) from anon;
revoke execute on function public.member_belongs_to_ledger(uuid, text) from anon;
revoke execute on function public.member_is_active_in_ledger(uuid, text) from anon;
revoke execute on function public.prevent_overlapping_car_bookings() from anon;
revoke execute on function public.set_notification_preferences(boolean, boolean, boolean, timestamptz, boolean, smallint, smallint, boolean) from anon;
revoke execute on function public.settlement_entry_is_locked(text, uuid) from anon;
revoke execute on function public.soft_delete_car_booking(text, text) from anon;
revoke execute on function public.soft_delete_recurring_expense(text, uuid) from anon;
revoke execute on function public.soft_delete_workspace_expense(text, uuid) from anon;
revoke execute on function public.touch_member_presence(text) from anon;
revoke execute on function public.update_ledger_insurance(text, text, text, text, date, numeric, numeric, text, text) from anon;
revoke execute on function public.update_ledger_vehicle(text, text, jsonb, text, timestamptz, text, numeric, numeric, text, text, text) from anon;
revoke execute on function public.update_vehicle_incident(uuid, text, text, text, text, uuid, date, integer, text, text) from anon;
revoke execute on function public.upsert_car_booking(text, text, uuid, timestamptz, timestamptz, text, text, text, jsonb) from anon;
revoke execute on function public.upsert_fuel_payment(text, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, numeric, numeric, numeric, numeric, boolean, text, text) from anon;
revoke execute on function public.upsert_ledger_member_admin(text, uuid, text, text, text, text, boolean) from anon;
revoke execute on function public.upsert_push_token(text, text) from anon;
revoke execute on function public.upsert_settlement_request_status(text, uuid, uuid, uuid, numeric, text, text, text[], text) from anon;
revoke execute on function public.upsert_trip_with_participants(text, uuid, text, uuid, date, numeric, numeric, text, uuid[], text, text) from anon;
revoke execute on function public.upsert_workspace_expense(text, uuid, uuid, text, text, numeric, date, text, jsonb, uuid, text, text) from anon;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '148_anon_execute_revoke_convention',
  'GV-380: applies the explicit anon-revoke convention (migrations 114/144/146) backwards to the 34 security-definer functions in public that still carried EXECUTE for anon. Nothing else changes -- no body, no signature, no authenticated or service_role grant. The ticket assumed "revoke from public" already covered anon in production and that only a plain-Postgres replay differed; that is wrong. Supabase''s bootstrap sets ALTER DEFAULT PRIVILEGES ... GRANT EXECUTE ON FUNCTIONS TO anon, authenticated, service_role in schema public, so every function is created with an explicit anon ACL entry that a PUBLIC revoke does not touch -- which is exactly why tools/test-rls-role-matrix.mjs installs those same default privileges. Verified against a replayed Postgres 17 catalog rather than migration text (later migrations revoke as well as grant, so the corpus is not the end state): both replay paths -- all migration files, and supabase-schema.sql -- produced an identical ACL end state in which 36 of 103 public functions were still anon-executable. Behaviour-neutral, checked three ways: every policy referencing one of these helpers is declared "to authenticated" so anon never evaluates it (the five policies without a role scope call only auth.uid(), or sit on tables anon has no grant on, where the table check fires first); trigger functions check EXECUTE at CREATE TRIGGER, not at fire time, which migrations 120/123/137 already relied on; and nested calls from inside another security-definer body run as the owner. current_user_email() and is_valid_payment_status_transition() are deliberately left alone -- they are security invoker and the only two functions still holding a PUBLIC grant, so revoking anon would be a no-op and revoking PUBLIC is a different, behaviour-changing ticket.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 149 mirror: the API throttle counter stops storing e-mail    (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- owner_api_rate_limits.actor_email (created above, migration 049) held every
-- user's verified address in clear text with no reader, no retention sweep and no
-- erasure path. It is replaced here by a peppered digest rather than dropped -- the
-- limiter must still tell actors apart -- and the two missing paths are added.
-- Section 3 renames the column the create table above still declares as actor_email,
-- which is what makes this append equivalent to a full migration replay. See
-- supabase/migrations/149_rate_limit_actor_pseudonymisation.sql for the reasoning.
-- ═══════════════════════════════════════════════════════════════════════════════
-- 1. The pepper                                                          (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- One row, one column that matters. Generated per database, so the digests in
-- owner_api_rate_limits are unlinkable to an address for anyone who cannot read this
-- table -- and nobody can: RLS is on with no policy, and every grant is revoked
-- including service_role, so the only access left is the table owner's, i.e. the
-- security-definer functions below.

create table if not exists public.rate_limit_actor_pepper (
  id boolean primary key default true check (id),
  pepper text not null default encode(extensions.gen_random_bytes(32), 'hex'),
  created_at timestamptz not null default now()
);

comment on table public.rate_limit_actor_pepper is
  'Single-row secret used to key the actor digests in owner_api_rate_limits (GV-385). Never expose it: no policy, no grant, service_role included. Rotating the value is safe -- it only resets throttle buckets.';

alter table public.rate_limit_actor_pepper enable row level security;

revoke all on public.rate_limit_actor_pepper from public;
revoke all on public.rate_limit_actor_pepper from anon;
revoke all on public.rate_limit_actor_pepper from authenticated;
revoke all on public.rate_limit_actor_pepper from service_role;

insert into public.rate_limit_actor_pepper (id) values (true)
on conflict (id) do nothing;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2. The digest helper                                                   (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Same normalisation the limiter always applied (lower + btrim) so an address maps to
-- one bucket however it is typed. security definer because the pepper is unreadable
-- otherwise; no grant to anyone, since both callers are themselves security-definer
-- functions running as the owner. Follows migration 028's hash_ledger_invite_code
-- shape, with the pepper added -- an invite code carries its own entropy, an e-mail
-- address does not.

create or replace function public.hash_rate_limit_actor(actor_email text)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select encode(
    extensions.digest(
      lower(btrim(coalesce(actor_email, ''))) || (select p.pepper from public.rate_limit_actor_pepper p where p.id),
      'sha256'
    ),
    'hex'
  );
$$;

revoke all on function public.hash_rate_limit_actor(text) from public;
revoke all on function public.hash_rate_limit_actor(text) from anon;
revoke all on function public.hash_rate_limit_actor(text) from authenticated;
revoke all on function public.hash_rate_limit_actor(text) from service_role;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 3. Replace the address with its digest, in place                       (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- RENAME rather than add-and-drop: the unique constraint (actor, action, window) and
-- owner_api_rate_limits_actor_idx follow the column automatically, so live throttle
-- state survives the migration instead of every user getting a fresh allowance. The
-- guard makes the whole step idempotent -- on a re-run the column is already
-- actor_hash and the digests must NOT be hashed a second time.

do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'owner_api_rate_limits'
      and column_name = 'actor_email'
  ) then
    alter table public.owner_api_rate_limits rename column actor_email to actor_hash;
    update public.owner_api_rate_limits arl
    set actor_hash = public.hash_rate_limit_actor(arl.actor_hash);
  end if;
end $$;

comment on table public.owner_api_rate_limits is
  'Fixed-window request counts for the owner API and the /api/mobile/* proxies (GV-156, GV-204). Service-role only. Rows are ephemeral throttle state, not an audit trail (see owner_activity_log) -- and since GV-385 they are pseudonymous: the actor is a peppered digest, run_operational_retention purges rows older than 30 days, and delete_my_account erases the caller''s.';

comment on column public.owner_api_rate_limits.actor_hash is
  'Peppered sha256 of the normalised actor e-mail (GV-385). Discriminates callers for throttling; identifies none of them. Was actor_email, in clear text, until migration 149.';

-- ═══════════════════════════════════════════════════════════════════════════════
-- 4. The limiter writes the digest                                       (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Re-declared off migration 100 (its newest prior definition), verbatim except for the
-- hashing. #variable_conflict use_column stays: the 42702 that migration 100 fixed came
-- from the actor_email parameter shadowing the same-named column in the ON CONFLICT
-- target, and while THAT collision is gone with the rename, the RETURNS TABLE column
-- `attempts` still shadows the table's, which is what the pragma resolves. Parameter
-- names are unchanged on purpose -- the Cloudflare Functions call this RPC with named
-- JSON parameters and renaming any of them would break that contract.

create or replace function public.check_owner_rate_limit(
  actor_email text,
  limit_action text default 'owner.api',
  max_attempts integer default 60,
  window_seconds integer default 60
)
returns table (
  allowed boolean,
  attempts integer,
  limit_value integer,
  retry_after_seconds integer
)
language plpgsql
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  safe_email text := nullif(lower(btrim(coalesce(actor_email, ''))), '');
  safe_actor text;
  safe_action text := coalesce(nullif(btrim(coalesce(limit_action, '')), ''), 'owner.api');
  safe_max integer := greatest(coalesce(max_attempts, 60), 1);
  safe_window integer := greatest(coalesce(window_seconds, 60), 1);
  window_start timestamptz;
  current_attempts integer;
begin
  if safe_email is null then
    raise exception 'actor_email is required for owner rate limiting' using errcode = 'P0001';
  end if;

  -- GV-385: the counter stores a keyed digest of the actor, never the address
  -- itself. Hashing here rather than at the caller keeps the RPC's JSON parameter
  -- contract (actor_email / limit_action / max_attempts / window_seconds) exactly as
  -- the Cloudflare Functions send it, so no client changes with this migration.
  safe_actor := public.hash_rate_limit_actor(safe_email);

  -- Fixed window aligned to safe_window-second boundaries from the epoch.
  window_start := to_timestamp(floor(extract(epoch from now()) / safe_window) * safe_window);

  insert into public.owner_api_rate_limits (actor_hash, action, window_started_at, attempts, last_attempt_at)
  values (safe_actor, safe_action, window_start, 1, now())
  on conflict (actor_hash, action, window_started_at)
  do update set attempts = public.owner_api_rate_limits.attempts + 1,
               last_attempt_at = now()
  returning public.owner_api_rate_limits.attempts into current_attempts;

  return query
  select
    current_attempts <= safe_max,
    current_attempts,
    safe_max,
    greatest(0, ceil(extract(epoch from (window_start + make_interval(secs => safe_window) - now())))::integer);
end;
$$;

revoke all on function public.check_owner_rate_limit(text, text, integer, integer) from public;
revoke all on function public.check_owner_rate_limit(text, text, integer, integer) from anon;
revoke all on function public.check_owner_rate_limit(text, text, integer, integer) from authenticated;
grant execute on function public.check_owner_rate_limit(text, text, integer, integer) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 5. Retention: counters expire                                          (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Re-declared off migration 132 (its newest prior definition -- 131 is NOT it; 132
-- added the GV-316 workspace purge, and basing on 131 quietly reverted it, which the
-- role matrix caught in three cases), verbatim plus a twelfth table. The sweep already
-- runs daily; it simply never looked here.

create or replace function public.run_operational_retention(
  p_stale_push_days integer default 180,
  p_dry_run boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_stale_tokens integer := 0;
  v_expired_events integer := 0;
  v_deleted_messages integer := 0;
  v_deleted_bookings integer := 0;
  v_deleted_recurring_templates integer := 0;
  v_deleted_trips integer := 0;
  v_deleted_fuel_payments integer := 0;
  v_deleted_workspace_expenses integer := 0;
  v_deleted_vehicle_repairs integer := 0;
  v_deleted_owner_activity integer := 0;
  v_purged_workspaces integer := 0;
  v_deleted_rate_limit_counters integer := 0;
  v_short_cutoff timestamptz := now() - interval '90 days';
  v_financial_cutoff timestamptz := date_trunc('year', now()) - interval '5 years';
  v_audit_cutoff timestamptz := now() - interval '24 months';
  v_workspace_cutoff timestamptz := now() - interval '90 days';
  -- GV-385: throttle counters are working state, not history. The longest window any
  -- caller configures is a day, and the two admin readers (owner/ocr-telemetry and
  -- owner/external-usage) both look back 7 days, so 30 days is already generous.
  v_rate_limit_cutoff timestamptz := now() - interval '30 days';
begin
  if p_stale_push_days is null or p_stale_push_days < 30 or p_stale_push_days > 3650 then
    raise exception 'p_stale_push_days must be between 30 and 3650' using errcode = '22023';
  end if;
  if p_dry_run is null then
    raise exception 'p_dry_run must not be null' using errcode = '22023';
  end if;

  if p_dry_run then
    select count(*) into v_stale_tokens from public.expo_push_tokens
    where updated_at < now() - make_interval(days => p_stale_push_days);
    select count(*) into v_expired_events from public.ledger_events
    where expires_at is not null and expires_at < now();
    select count(*) into v_deleted_messages from public.messages where deleted_at < v_short_cutoff;
    select count(*) into v_deleted_bookings from public.car_bookings where deleted_at < v_short_cutoff;
    select count(*) into v_deleted_recurring_templates from public.recurring_expenses where deleted_at < v_short_cutoff;
    select count(*) into v_deleted_trips from public.trips where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_fuel_payments from public.fuel_payments where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_workspace_expenses from public.workspace_expenses where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_vehicle_repairs from public.vehicle_repairs where deleted_at < v_financial_cutoff;
    select count(*) into v_deleted_owner_activity from public.owner_activity_log where created_at < v_audit_cutoff;
    select count(*) into v_deleted_rate_limit_counters from public.owner_api_rate_limits where window_started_at < v_rate_limit_cutoff;
    select count(*) into v_purged_workspaces from public.ledgers where deleted_at < v_workspace_cutoff;
  else
    with purged as (delete from public.expo_push_tokens where updated_at < now() - make_interval(days => p_stale_push_days) returning 1)
      select count(*) into v_stale_tokens from purged;
    with purged as (delete from public.ledger_events where expires_at is not null and expires_at < now() returning 1)
      select count(*) into v_expired_events from purged;
    with purged as (delete from public.messages where deleted_at < v_short_cutoff returning 1)
      select count(*) into v_deleted_messages from purged;
    with purged as (delete from public.car_bookings where deleted_at < v_short_cutoff returning 1)
      select count(*) into v_deleted_bookings from purged;
    with purged as (delete from public.recurring_expenses where deleted_at < v_short_cutoff returning 1)
      select count(*) into v_deleted_recurring_templates from purged;

    -- Closed-period entry triggers deliberately freeze accounting history. The
    -- account-deletion path already uses this transaction-local gate for GDPR
    -- scrubs; enable it only inside this service-role-only function and only
    -- around tombstones that have outlived the accounting retention window.
    perform set_config('govehlo.pii_scrub', '1', true);
    with purged as (delete from public.trips where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_trips from purged;
    with purged as (delete from public.fuel_payments where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_fuel_payments from purged;
    with purged as (delete from public.workspace_expenses where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_workspace_expenses from purged;
    with purged as (delete from public.vehicle_repairs where deleted_at < v_financial_cutoff returning 1)
      select count(*) into v_deleted_vehicle_repairs from purged;

    -- GV-316: purge workspaces whose operator decommission tombstone has
    -- outlived the 90-day grace window. On delete cascade removes every child
    -- row; the closed-period locks stand aside for a whole-workspace teardown
    -- (settlement_periods delete first). Kept inside the pii_scrub gate for
    -- parity with the financial-row purges above.
    with purged as (delete from public.ledgers where deleted_at < v_workspace_cutoff returning 1)
      select count(*) into v_purged_workspaces from purged;
    perform set_config('govehlo.pii_scrub', '', true);
    with purged as (delete from public.owner_activity_log where created_at < v_audit_cutoff returning 1)
      select count(*) into v_deleted_owner_activity from purged;
    with purged as (delete from public.owner_api_rate_limits where window_started_at < v_rate_limit_cutoff returning 1)
      select count(*) into v_deleted_rate_limit_counters from purged;
  end if;

  return jsonb_build_object(
    'staleExpoPushTokens', v_stale_tokens,
    'expiredLedgerEvents', v_expired_events,
    'deletedMessages', v_deleted_messages,
    'deletedBookings', v_deleted_bookings,
    'deletedRecurringTemplates', v_deleted_recurring_templates,
    'deletedTrips', v_deleted_trips,
    'deletedFuelPayments', v_deleted_fuel_payments,
    'deletedWorkspaceExpenses', v_deleted_workspace_expenses,
    'deletedVehicleRepairs', v_deleted_vehicle_repairs,
    'deletedOwnerActivity', v_deleted_owner_activity,
    'purgedWorkspaces', v_purged_workspaces,
    'deletedRateLimitCounters', v_deleted_rate_limit_counters,
    'dryRun', p_dry_run,
    'staleDays', p_stale_push_days,
    'shortRetentionDays', 90,
    'financialRetentionYears', 5,
    'auditRetentionMonths', 24,
    'workspaceGraceDays', 90,
    'rateLimitRetentionDays', 30,
    'ranAt', now()
  );
end;
$$;

revoke all on function public.run_operational_retention(integer, boolean) from public;
revoke all on function public.run_operational_retention(integer, boolean) from anon;
revoke all on function public.run_operational_retention(integer, boolean) from authenticated;
grant execute on function public.run_operational_retention(integer, boolean) to service_role;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 6. Erasure: deletion reaches the counter                               (GV-385)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Re-declared off migration 147 (its newest prior definition), verbatim plus one
-- delete, placed with the other cross-ledger cleanups that key on identity rather than
-- membership -- next to its sibling, ledger_onboarding_rate_limits, which has been
-- cleaned up there all along.

create or replace function public.delete_my_account()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_email text := public.current_user_email();
  v_member record;
  v_old_name text;
  v_first_name text;
  v_anon_name text;
  v_suffix integer;
  v_no_other_active boolean;
  v_successor record;
  v_ledgers_scrubbed integer := 0;
  v_ledgers_deleted integer := 0;
  v_admins_promoted integer := 0;
begin
  if v_uid is null or v_email is null then
    raise exception 'Account deletion requires a signed-in user' using errcode = '42501';
  end if;

  -- Let the settlement lock trigger (GV-199) know these writes are GDPR PII
  -- scrubs, not settlement edits, so its closed-period rejection stands aside.
  -- Transaction-local, so it clears automatically at commit/rollback.
  perform set_config('govehlo.pii_scrub', '1', true);

  for v_member in
    select lm.id, lm.ledger_id, lm.name, lm.role, lm.is_active
    from public.ledger_members lm
    where lm.email is not null
      and lower(lm.email) = v_email
  loop
    v_old_name := v_member.name;
    v_first_name := split_part(v_old_name, ' ', 1);

    -- No other active member left? The workspace dies with this account: nobody
    -- could ever access it again, so full deletion is the cleanest erasure.
    -- Every child table references ledgers(id) with on delete cascade.
    select not exists (
      select 1
      from public.ledger_members lm2
      where lm2.ledger_id = v_member.ledger_id
        and lm2.is_active = true
        and lm2.id <> v_member.id
    ) into v_no_other_active;
    if v_no_other_active then
      delete from public.ledgers l where l.id = v_member.ledger_id;
      v_ledgers_deleted := v_ledgers_deleted + 1;
      continue;
    end if;

    -- Admin succession: never leave a live workspace admin-less. Promote the
    -- longest-standing active member and say so in the feed (system actor).
    if v_member.is_active and v_member.role = 'admin' and not exists (
      select 1
      from public.ledger_members lm3
      where lm3.ledger_id = v_member.ledger_id
        and lm3.is_active = true
        and lm3.role = 'admin'
        and lm3.id <> v_member.id
    ) then
      select lm4.id, lm4.name
      into v_successor
      from public.ledger_members lm4
      where lm4.ledger_id = v_member.ledger_id
        and lm4.is_active = true
        and lm4.id <> v_member.id
      order by lm4.created_at asc, lm4.id asc
      limit 1;

      update public.ledger_members lm5
      set role = 'admin', updated_at = now()
      where lm5.id = v_successor.id;

      insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, target_member_id, metadata)
      values (
        v_member.ledger_id,
        'member_promoted',
        v_successor.name || ' er nu administrator',
        'Automatisk, fordi den tidligere administrator slettede sin konto',
        null,
        null,
        v_successor.id,
        jsonb_build_object('reason', 'account_deleted')
      );
      v_admins_promoted := v_admins_promoted + 1;
    end if;

    -- Per-ledger-unique anonymized name (unique(ledger_id, name) would reject a
    -- second 'Slettet medlem' in the same group).
    v_anon_name := 'Slettet medlem';
    v_suffix := 1;
    while exists (
      select 1
      from public.ledger_members lm6
      where lm6.ledger_id = v_member.ledger_id
        and lm6.name = v_anon_name
        and lm6.id <> v_member.id
    ) loop
      v_suffix := v_suffix + 1;
      v_anon_name := 'Slettet medlem ' || v_suffix;
    end loop;

    -- Authored free text: trip notes are the creator's words, not car facts.
    update public.trips t
    set note = null, updated_at = now()
    where t.ledger_id = v_member.ledger_id
      and t.created_by_member_id = v_member.id
      and t.note is not null;

    -- Bookings: purposes are authored text; future bookings would block the car
    -- for a person who no longer exists.
    update public.car_bookings cb
    set purpose = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.purpose is not null;

    -- Structured fuel stop (migration 063): the from/to labels + lat/lng are the
    -- member's route history — potentially their home address. Null the whole
    -- jsonb; station coords are public, but from/to are personal, so simplest-
    -- correct wins (GV-197).
    update public.car_bookings cb
    set fuel_stop = null, updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and (cb.member_id = v_member.id or cb.created_by_member_id = v_member.id)
      and cb.fuel_stop is not null;

    update public.car_bookings cb
    set deleted_at = now(), updated_at = now()
    where cb.ledger_id = v_member.ledger_id
      and cb.member_id = v_member.id
      and cb.start_at > now()
      and cb.deleted_at is null;

    -- Chat: blank + soft-delete their messages (the app already filters deleted).
    update public.messages msg
    set body = '', deleted_at = coalesce(msg.deleted_at, now())
    where msg.ledger_id = v_member.ledger_id
      and msg.sender_member_id = v_member.id;

    -- Incident photos (GVM-396): the photos belong to the workspace (they die with
    -- the incident or the workspace via cascade). Only the authorship pointer is
    -- personal, so detach it. The incident rows' own reporter/driver references
    -- are left pointing at this member row, which is anonymized in place below —
    -- exactly like trips.driver_member_id and every other retained reference.
    update public.vehicle_incident_photos vip
    set created_by_member_id = null
    where vip.ledger_id = v_member.ledger_id
      and vip.created_by_member_id = v_member.id;

    -- Feed events: drop stored emails and replace the member's name inside titles
    -- and bodies they authored or are targeted by. Events self-expire after 30
    -- days, so this is belt-and-braces on top of bounded retention. Very short
    -- first names (< 3 chars) are skipped for the substring pass — the collision
    -- risk with unrelated words outweighs the residual exposure.
    if char_length(v_first_name) < 3 then
      v_first_name := v_old_name;
    end if;
    update public.ledger_events ev
    set actor_email = case when ev.actor_member_id = v_member.id then null else ev.actor_email end,
        target_email = case when ev.target_member_id = v_member.id then null else ev.target_email end,
        title = replace(replace(ev.title, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem'),
        body = replace(replace(ev.body, v_old_name, 'Slettet medlem'), v_first_name, 'Slettet medlem')
    where ev.ledger_id = v_member.ledger_id
      and (ev.actor_member_id = v_member.id or ev.target_member_id = v_member.id);

    -- Archived snapshots: closed periods keep their maths, but the name fields
    -- inside people[] / settlements[] must stop identifying the person. The
    -- entry fingerprint (migration 054) covers trip/fuel ids only, never names,
    -- so this rewrite cannot invalidate any integrity check.
    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{people}',
      (
        select coalesce(jsonb_agg(
          case when person ->> 'id' = v_member.id::text
            then jsonb_set(person, '{name}', to_jsonb(v_anon_name))
            else person
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(sp.snapshot_json -> 'people') as person
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'people') = 'array';

    update public.settlement_periods sp
    set snapshot_json = jsonb_set(
      sp.snapshot_json,
      '{settlements}',
      (
        select coalesce(jsonb_agg(
          case when settled ->> 'toId' = v_member.id::text
            then jsonb_set(settled, '{toName}', to_jsonb(v_anon_name))
            else settled
          end
        ), '[]'::jsonb)
        from (
          select case when raw ->> 'fromId' = v_member.id::text
            then jsonb_set(raw, '{fromName}', to_jsonb(v_anon_name))
            else raw
          end as settled
          from jsonb_array_elements(sp.snapshot_json -> 'settlements') as raw
        ) as renamed
      )
    )
    where sp.ledger_id = v_member.ledger_id
      and sp.snapshot_json is not null
      and jsonb_typeof(sp.snapshot_json -> 'settlements') = 'array';

    -- Invites addressed to this email in this ledger.
    update public.ledger_invites li
    set invited_email = null, updated_at = now()
    where li.ledger_id = v_member.ledger_id
      and lower(coalesce(li.invited_email, '')) = v_email;

    -- Finally the member row itself. Role drops to 'member' (succession above
    -- already ensured another admin exists when one was needed). last_seen_at is
    -- nulled too (GVM-66): activity metadata must not outlive the account.
    update public.ledger_members lm7
    set name = v_anon_name,
        email = null,
        mobilepay_phone = null,
        role = 'member',
        is_active = false,
        last_seen_at = null,
        updated_at = now()
    where lm7.id = v_member.id;

    -- Feed transparency, in app voice, without re-publishing the old name.
    insert into public.ledger_events (ledger_id, event_type, title, body, actor_member_id, actor_email, metadata)
    values (
      v_member.ledger_id,
      'member_deleted',
      'Et medlem slettede sin konto',
      v_anon_name || ' er anonymiseret. Gruppens regnskab er uændret.',
      null,
      null,
      jsonb_build_object('member_id', v_member.id)
    );

    v_ledgers_scrubbed := v_ledgers_scrubbed + 1;
  end loop;

  -- Cross-ledger cleanup keyed by identity rather than membership.
  delete from public.ledger_onboarding_rate_limits rl
  where lower(rl.actor_email) = v_email;

  -- The owner/mobile API throttle counter (migration 049; pseudonymised by this
  -- migration). The row no longer holds an address, but its key is still DERIVED from
  -- one, so article 17 reaches it: recompute the same keyed digest and delete. Without
  -- this line the only thing that ever removed it would be the 30-day sweep.
  delete from public.owner_api_rate_limits arl
  where arl.actor_hash = public.hash_rate_limit_actor(v_email);

  update public.owner_activity_log oal
  set actor_email = null, actor_user_id = null
  where oal.actor_user_id = v_uid
     or lower(coalesce(oal.actor_email, '')) = v_email;

  -- Push tokens die with the account (migration 057): match by user id and by
  -- the scrubbed email so nothing keeps addressing this person's devices.
  delete from public.expo_push_tokens ept
  where ept.user_id = v_uid
     or lower(ept.email) = v_email;


  -- Purge this user's notification preferences (GV-229). No PII (three booleans
  -- + a uuid), but data minimisation says don't leave an orphaned row behind.
  delete from public.notification_preferences np where np.user_id = v_uid;

  -- Kill the credentials last: cascades sessions/identities, frees the email for
  -- a fresh sign-up. The caller's JWT stays technically valid until expiry but no
  -- longer matches any member (email scrubbed), so RLS yields nothing.
  delete from auth.users au where au.id = v_uid;

  return jsonb_build_object(
    'ledgers_scrubbed', v_ledgers_scrubbed,
    'ledgers_deleted', v_ledgers_deleted,
    'admins_promoted', v_admins_promoted
  );
end;
$$;

-- `create or replace` preserves the ACL (the grant dates from 056, re-asserted by
-- 083). Restated by name so this file is readable on its own, and so anon is denied
-- explicitly rather than by inheritance.
revoke all on function public.delete_my_account() from public;
revoke all on function public.delete_my_account() from anon;
grant execute on function public.delete_my_account() to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '149_rate_limit_actor_pseudonymisation',
  'GV-385: owner_api_rate_limits.actor_email stored every user''s verified e-mail in clear text, forever, with no reader, no retention sweep and no reference from delete_my_account. Six of its seven writers are ordinary users, not operators -- the /api/mobile/* proxies all route through checkUserRate() in govehlo-web functions/api/_auth.js, which reuses this owner-named limiter. Correction to the ticket: the table has TWO readers, not one (owner/ocr-telemetry.js GV-231 and owner/external-usage.js GV-239), but neither reads the actor -- both select only (action, attempts, window_started_at) and aggregate by action over 7 days, so the ticket''s conclusion stands and the fix costs no reader anything. The limiter needs to tell actors apart, not to know who they are, so the column is REPLACED rather than dropped: dropping it would collapse every caller into one bucket and turn a per-user limit into a global one. actor_email is renamed to actor_hash in place -- keeping the (actor, action, window) unique key, its index and all live throttle state -- and the values are digested with a per-database pepper held in a new single-row table that has RLS on, no policy and every grant revoked including service_role, so only the owner (i.e. the security-definer functions) can read it. The pepper is the point: an unsalted sha256 of an e-mail is reversed by hashing the known user list, which would leave the admin console able to re-identify every row. check_owner_rate_limit is re-declared off migration 100 (its newest prior definition), verbatim except that it hashes internally, so its named-JSON parameter contract is untouched and NO govehlo-web change ships with this migration; #variable_conflict use_column stays because the RETURNS TABLE column attempts still shadows the table''s even though the actor_email collision migration 100 fixed is gone. Because a pepper is a pseudonym and not an erasure, both paths the ticket asked for are added too: run_operational_retention (re-declared off 132 -- its NEWEST prior definition, not 131, which predates the GV-316 workspace purge; the first attempt based on 131 reverted it and the role matrix failed three cases) purges counters older than 30 days -- the longest configured window is a day and both admin readers look back 7 -- reporting deletedRateLimitCounters, and delete_my_account (re-declared off 147) deletes the caller''s rows by recomputing the digest, next to the sibling ledger_onboarding_rate_limits cleanup it sits beside.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 150 mirror: push-target RPCs keep e-mails and tokens out of URLs (GV-398)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- The last two sites GV-389 could not close from the web repo. A PostgREST GET or
-- DELETE takes its filter in the query string and nowhere else, so the only shape
-- that carries the arguments in a request BODY is an RPC -- and a URL reaches the
-- Cloudflare edge log and Supabase's gateway log while a body does not. Both values
-- are personal data: an address, and an Expo push token because it identifies a
-- device. Deliberately a plain lookup with no category parameter; see
-- supabase/migrations/150_push_target_rpcs.sql for that reasoning and for the
-- lower-casing fix that comes with it. Service-role only, anon and authenticated
-- revoked explicitly per migration 148.

-- ── resolve_push_targets: the targeted-recipient lookup, arguments in the body ─────
-- Returns one row per registered device for the given addresses. Same two columns the
-- URL select asked for and in the same order, so the caller's row shape is unchanged:
-- `token` for the send, `user_id` for the mute/snooze/quiet filter that stays in the
-- web repo. A NULL or empty array returns no rows — never every device.
create or replace function public.resolve_push_targets(p_emails text[])
returns table (token text, user_id uuid)
language sql
stable
security definer
set search_path = public
as $$
  select ept.token, ept.user_id
  from public.expo_push_tokens ept
  where lower(ept.email) = any (
    select distinct lower(btrim(candidate))
    from unnest(coalesce(p_emails, array[]::text[])) as candidate
    where nullif(btrim(candidate), '') is not null
  );
$$;

revoke all on function public.resolve_push_targets(text[]) from public;
revoke all on function public.resolve_push_targets(text[]) from anon;
revoke all on function public.resolve_push_targets(text[]) from authenticated;
grant execute on function public.resolve_push_targets(text[]) to service_role;

-- ── prune_push_tokens: delete the devices Expo reported DeviceNotRegistered ────────
-- Returns the number of rows actually deleted. The URL DELETE returned nothing usable
-- (Prefer: return=minimal), so the caller could not tell a successful prune from a
-- silently mismatched token list; a count is free here and makes that observable
-- without logging a single token.
create or replace function public.prune_push_tokens(p_tokens text[])
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_deleted integer := 0;
begin
  delete from public.expo_push_tokens ept
  where ept.token = any (
    select distinct btrim(candidate)
    from unnest(coalesce(p_tokens, array[]::text[])) as candidate
    where nullif(btrim(candidate), '') is not null
  );
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

revoke all on function public.prune_push_tokens(text[]) from public;
revoke all on function public.prune_push_tokens(text[]) from anon;
revoke all on function public.prune_push_tokens(text[]) from authenticated;
grant execute on function public.prune_push_tokens(text[]) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '150_push_target_rpcs',
  'GV-398: two service-role-only RPCs so the push engine stops writing personal data into request lines. resolve_push_targets(text[]) returns (token, user_id) for a set of member addresses and prune_push_tokens(text[]) deletes the devices Expo reported DeviceNotRegistered, returning a count. Both replace a PostgREST query-string filter in govehlo-web functions/api/_push.js (resolveTokensWithMuteState''s GET expo_push_tokens?email=in.(...) and pruneTokens'' DELETE ?token=in.(...)) -- the last two sites GV-389 could not close, because a GET/DELETE filter only travels in the URL and the only body-carrying shape PostgREST offers is an RPC. A URL reaches the Cloudflare edge log and Supabase''s gateway log; a POST body does not. Deliberately a plain lookup with NO category parameter: the mute/snooze/quiet filter also serves the operator broadcast, which has no email list at all, so moving it into SQL for one caller would fork it into two implementations whose disagreement would be a silently undelivered push -- and an accepted-and-ignored parameter is exactly what migration 151 removes next door. resolve_push_targets also lower-cases BOTH sides of the address comparison, fixing a silent drop: upsert_push_token stores current_user_email() verbatim, so a capitalised address never matched the lower-cased in.() list and its owner missed every targeted push. Service-role only, with anon and authenticated revoked explicitly per migration 148.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 151 mirror: erase + drop the precise refuel position          (GV-400)
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- Server half of GVM-456/457. fuel_payments.station_lat/station_lng are nulled and
-- then dropped (migration 062's erase plus 071's drop, in one step now that the
-- client has already stopped writing), acknowledge_inspection_booking stops stamping
-- syn_booked_at, and the accepted-and-ignored coordinate parameters leave
-- upsert_fuel_payment, complete_booking_trip_with_fuel and
-- complete_deferred_booking_fuel. The drop-then-create statements below are what make
-- this append equivalent to a full migration replay: the earlier definitions in this
-- file still declare the wider signatures, and a create-or-replace at a different
-- arity would leave both overloads live. The create table fuel_payments block near
-- the top of this file still declares station_lat/station_lng; section 6 removes
-- them, exactly as migration 071 did for user_lat/user_lng. See
-- supabase/migrations/151_drop_fuel_station_coordinates.sql for the full reasoning.

-- ═══════════════════════════════════════════════════════════════════════════════════
-- 1. upsert_fuel_payment — re-declared off migration 071, minus four dead params
-- ═══════════════════════════════════════════════════════════════════════════════════

drop function if exists public.upsert_fuel_payment(text, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, numeric, numeric, numeric, numeric, boolean, text, text);

create or replace function public.upsert_fuel_payment(
  target_ledger_id text,
  target_open_period_id uuid,
  legacy_fuel_id text,
  payer_member_id uuid,
  payment_date_value date,
  amount_value numeric,
  currency_value text,
  liters_value numeric,
  price_per_liter_value numeric,
  odometer_value numeric,
  station_name_value text,
  station_brand_value text,
  full_tank_value boolean,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_member_id uuid;
  locked_period_id uuid;
  saved_fuel_id uuid;
  existing_fuel record;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if target_open_period_id is null then
    raise exception 'Missing open settlement period id' using errcode = '22023';
  end if;

  if legacy_fuel_id is null or legacy_fuel_id = '' then
    raise exception 'Missing legacy fuel id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can save fuel payments' using errcode = '42501';
  end if;

  actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member' using errcode = '42501';
  end if;

  -- Take a SHARED row lock on the open period (GVM-112): close_settlement_period
  -- UPDATEs this row (exclusive row lock), so an in-flight write and a close
  -- serialize here — either this entry commits first and the close's server-side
  -- recompute sees it, or the close commits first and this check finds no open
  -- period and fails cleanly.
  select sp.id
    into locked_period_id
    from public.settlement_periods sp
    where sp.id = target_open_period_id
      and sp.ledger_id = target_ledger_id
      and sp.status = 'open'
      and sp.closed_at is null
    for share of sp;

  if locked_period_id is null then
    raise exception 'Open settlement period was not found or was already closed' using errcode = '22023';
  end if;

  if payer_member_id is null or not public.member_belongs_to_ledger(payer_member_id, target_ledger_id) then
    raise exception 'Fuel payer must be an active member of this ledger' using errcode = '23514';
  end if;

  if amount_value is null or amount_value < 0 then
    raise exception 'Fuel amount must be zero or greater' using errcode = '23514';
  end if;

  if liters_value is not null and liters_value < 0 then
    raise exception 'Fuel liters must be zero or greater' using errcode = '23514';
  end if;

  if price_per_liter_value is not null and price_per_liter_value < 0 then
    raise exception 'Fuel price per liter must be zero or greater' using errcode = '23514';
  end if;

  perform pg_advisory_xact_lock(hashtext(target_ledger_id || ':fuel:' || legacy_fuel_id));

  select *
    into existing_fuel
  from public.fuel_payments
  where ledger_id = target_ledger_id
    and legacy_id = legacy_fuel_id
  for update;

  if existing_fuel.id is not null and not (
    public.is_ledger_admin(target_ledger_id)
    or existing_fuel.created_by_member_id = actor_member_id
    or existing_fuel.payer_member_id = actor_member_id
  ) then
    raise exception 'Only the fuel creator, payer, or a ledger admin can update this fuel payment' using errcode = '42501';
  end if;

  if existing_fuel.id is null and not (
    public.is_ledger_admin(target_ledger_id)
    or payer_member_id = actor_member_id
  ) then
    raise exception 'Only the fuel payer or a ledger admin can create this fuel payment' using errcode = '42501';
  end if;

  -- GDPR data minimisation (GV-186 / GV-196 / GV-400): no position is stored with a
  -- refuel any more. The driver's own coordinates went in migration 071 and the
  -- STATION's follow here — migration 062 kept those for a map view that was never
  -- built, so the purpose they were justified by has no implementation. The four
  -- accepted-and-ignored coordinate params are gone from the signature with them;
  -- station_name and station_brand still record WHERE, just not to seven decimals.
  insert into public.fuel_payments (
    legacy_id,
    ledger_id,
    period_id,
    payer_member_id,
    payment_date,
    amount,
    currency,
    liters,
    price_per_liter,
    odometer,
    station_name,
    station_brand,
    full_tank,
    created_by_member_id,
    deleted_at,
    updated_at
  ) values (
    legacy_fuel_id,
    target_ledger_id,
    target_open_period_id,
    payer_member_id,
    payment_date_value,
    amount_value,
    coalesce(nullif(currency_value, ''), 'DKK'),
    liters_value,
    price_per_liter_value,
    odometer_value,
    nullif(station_name_value, ''),
    nullif(station_brand_value, ''),
    coalesce(full_tank_value, false),
    actor_member_id,
    null,
    now()
  )
  on conflict (ledger_id, legacy_id) do update set
    period_id = excluded.period_id,
    payer_member_id = excluded.payer_member_id,
    payment_date = excluded.payment_date,
    amount = excluded.amount,
    currency = excluded.currency,
    liters = excluded.liters,
    price_per_liter = excluded.price_per_liter,
    odometer = excluded.odometer,
    station_name = excluded.station_name,
    station_brand = excluded.station_brand,
    full_tank = excluded.full_tank,
    deleted_at = null,
    updated_at = now()
  returning id into saved_fuel_id;

  -- Activity feed event, on create only (GVM-84).
  if existing_fuel.id is null and nullif(event_title, '') is not null then
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id, 'fuel_created', event_title, coalesce(event_body, ''),
      actor_member_id, nullif(lower(coalesce(auth.jwt() ->> 'email', '')), ''),
      jsonb_build_object('fuel_id', saved_fuel_id)
    );
  end if;

  return jsonb_build_object(
    'fuel_id', saved_fuel_id,
    'ledger_id', target_ledger_id,
    'legacy_id', legacy_fuel_id
  );
end;
$$;

-- DROP + CREATE resets the ACL, so both halves are restated: anon and authenticated
-- are named explicitly (migration 148) and only authenticated is granted back.
revoke all on function public.upsert_fuel_payment(text, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, boolean, text, text) from public;
revoke all on function public.upsert_fuel_payment(text, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, boolean, text, text) from anon;
grant execute on function public.upsert_fuel_payment(text, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, boolean, text, text) to authenticated;

-- ═══════════════════════════════════════════════════════════════════════════════════
-- 2. complete_booking_trip_with_fuel — re-declared off migration 136
-- ═══════════════════════════════════════════════════════════════════════════════════

drop function if exists public.complete_booking_trip_with_fuel(text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, numeric, numeric, boolean, text, text, text, text);

create or replace function public.complete_booking_trip_with_fuel(
  target_ledger_id text,
  target_open_period_id uuid,
  target_booking_id uuid,
  legacy_trip_id text,
  booking_driver_member_id uuid,
  trip_date_value date,
  start_km_value numeric,
  end_km_value numeric,
  note_value text,
  participant_member_ids uuid[],
  fuel_resolution_value text,
  fuel_legacy_id text default null,
  fuel_payer_member_id uuid default null,
  fuel_payment_date_value date default null,
  fuel_amount_value numeric default null,
  fuel_currency_value text default 'DKK',
  fuel_liters_value numeric default null,
  fuel_price_per_liter_value numeric default null,
  fuel_odometer_value numeric default null,
  fuel_station_name_value text default null,
  fuel_station_brand_value text default null,
  fuel_full_tank_value boolean default false,
  trip_event_title text default null,
  trip_event_body text default null,
  fuel_event_title text default null,
  fuel_event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  trip_result jsonb;
  fuel_result jsonb := null;
  saved_trip_id uuid;
  saved_fuel_id uuid := null;
  existing_fuel_resolution text;
  existing_fuel_legacy_id text;
  effective_fuel_legacy_id text;
  fuel_payload_present boolean;
begin
  if fuel_resolution_value is null
     or fuel_resolution_value not in ('logged', 'deferred', 'not_refuelled', 'not_needed') then
    raise exception 'Invalid trip fuel resolution' using errcode = '22023';
  end if;

  fuel_payload_present :=
    nullif(fuel_legacy_id, '') is not null
    or fuel_payer_member_id is not null
    or fuel_payment_date_value is not null
    or fuel_amount_value is not null
    or fuel_liters_value is not null
    or fuel_price_per_liter_value is not null
    or fuel_odometer_value is not null
    or nullif(fuel_station_name_value, '') is not null
    or nullif(fuel_station_brand_value, '') is not null
    or coalesce(fuel_full_tank_value, false)
    or coalesce(nullif(fuel_currency_value, ''), 'DKK') <> 'DKK';

  if fuel_resolution_value = 'logged' then
    if nullif(fuel_legacy_id, '') is null
       or fuel_payer_member_id is null
       or fuel_payment_date_value is null
       or fuel_amount_value is null
       or fuel_amount_value <= 0 then
      raise exception 'Logged trip fuel requires a key, payer, date, and positive amount'
        using errcode = '22023';
    end if;
  elsif fuel_payload_present then
    raise exception 'Fuel details are only accepted when the resolution is logged'
      using errcode = '22023';
  end if;

  -- This command inherits the booking lock, actor/driver/date checks, open-period
  -- lock, participant validation, and trip idempotency from migration 123.
  trip_result := public.upsert_booking_trip_with_participants(
    target_ledger_id,
    target_open_period_id,
    target_booking_id,
    legacy_trip_id,
    booking_driver_member_id,
    trip_date_value,
    start_km_value,
    end_km_value,
    note_value,
    participant_member_ids,
    trip_event_title,
    trip_event_body
  );

  saved_trip_id := nullif(trip_result ->> 'trip_id', '')::uuid;
  if saved_trip_id is null then
    raise exception 'Booking completion did not return a trip id' using errcode = '40001';
  end if;

  select t.fuel_resolution, t.completion_fuel_legacy_id
    into existing_fuel_resolution, existing_fuel_legacy_id
    from public.trips t
    where t.id = saved_trip_id
      and t.ledger_id = target_ledger_id
      and t.deleted_at is null
    for update of t;

  if not found then
    raise exception 'Booking completion trip was not found' using errcode = '40001';
  end if;

  -- A delayed pre-refuel replay must never downgrade a fuel payment already logged
  -- by a newer attempt. The trip RPC remains free to reconcile odometer/participants.
  if existing_fuel_resolution = 'logged'
     and existing_fuel_legacy_id is not null
     and fuel_resolution_value <> 'logged' then
    return trip_result || jsonb_build_object(
      'fuel_resolution', 'logged',
      'fuel_id', (
        select fp.id
        from public.fuel_payments fp
        where fp.ledger_id = target_ledger_id
          and fp.legacy_id = existing_fuel_legacy_id
          and fp.deleted_at is null
        limit 1
      ),
      'reused_existing_fuel', true
    );
  end if;

  if fuel_resolution_value = 'logged' then
    -- Once a completion has a linked fuel key, all retries reuse it even if another
    -- device supplies a different local key. The booking lock serializes this read.
    effective_fuel_legacy_id := coalesce(
      nullif(existing_fuel_legacy_id, ''),
      nullif(fuel_legacy_id, '')
    );

    fuel_result := public.upsert_fuel_payment(
      target_ledger_id,
      target_open_period_id,
      effective_fuel_legacy_id,
      fuel_payer_member_id,
      fuel_payment_date_value,
      fuel_amount_value,
      coalesce(nullif(fuel_currency_value, ''), 'DKK'),
      fuel_liters_value,
      fuel_price_per_liter_value,
      fuel_odometer_value,
      fuel_station_name_value,
      fuel_station_brand_value,
      coalesce(fuel_full_tank_value, false),
      fuel_event_title,
      fuel_event_body
    );

    saved_fuel_id := nullif(fuel_result ->> 'fuel_id', '')::uuid;
    if saved_fuel_id is null then
      raise exception 'Booking completion did not return a fuel id' using errcode = '40001';
    end if;

    update public.trips t
    set fuel_resolution = 'logged',
        completion_fuel_legacy_id = effective_fuel_legacy_id,
        updated_at = now()
    where t.id = saved_trip_id
      and t.ledger_id = target_ledger_id;
  else
    update public.trips t
    set fuel_resolution = fuel_resolution_value,
        completion_fuel_legacy_id = null,
        updated_at = now()
    where t.id = saved_trip_id
      and t.ledger_id = target_ledger_id;
  end if;

  if not found then
    raise exception 'Booking completion could not persist its fuel resolution' using errcode = '40001';
  end if;

  return trip_result || jsonb_build_object(
    'fuel_resolution', fuel_resolution_value,
    'fuel_id', saved_fuel_id,
    'reused_existing_fuel', existing_fuel_legacy_id is not null
  );
end;
$$;

revoke all on function public.complete_booking_trip_with_fuel(
  text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text,
  text, uuid, date, numeric, text, numeric, numeric, numeric, text, text,
  boolean, text, text, text, text
) from public;
revoke all on function public.complete_booking_trip_with_fuel(
  text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text,
  text, uuid, date, numeric, text, numeric, numeric, numeric, text, text,
  boolean, text, text, text, text
) from anon;
grant execute on function public.complete_booking_trip_with_fuel(
  text, uuid, uuid, text, uuid, date, numeric, numeric, text, uuid[], text,
  text, uuid, date, numeric, text, numeric, numeric, numeric, text, text,
  boolean, text, text, text, text
) to authenticated;

-- ═══════════════════════════════════════════════════════════════════════════════════
-- 3. complete_deferred_booking_fuel — re-declared off migration 140
-- ═══════════════════════════════════════════════════════════════════════════════════

drop function if exists public.complete_deferred_booking_fuel(text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric, text, text, numeric, numeric, boolean, text, text);

-- Resolve an already-saved deferred booking receipt without replaying/moving the
-- original trip. The fuel INSERT is automatically queued by the boundary trigger
-- from migration 140 when the current period is locked; only fixed, non-financial
-- workflow metadata is updated on the original trip, including when it is already closed.
create or replace function public.complete_deferred_booking_fuel(
  target_ledger_id text,
  target_open_period_id uuid,
  target_trip_id uuid,
  fuel_legacy_id text,
  fuel_payer_member_id uuid,
  fuel_payment_date_value date,
  fuel_amount_value numeric,
  fuel_currency_value text default 'DKK',
  fuel_liters_value numeric default null,
  fuel_price_per_liter_value numeric default null,
  fuel_odometer_value numeric default null,
  fuel_station_name_value text default null,
  fuel_station_brand_value text default null,
  fuel_full_tank_value boolean default false,
  fuel_event_title text default null,
  fuel_event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_member_id uuid;
  v_trip record;
  v_fuel_result jsonb;
  v_saved_fuel_id uuid;
begin
  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can complete deferred fuel entries'
      using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member'
      using errcode = '42501';
  end if;

  if target_trip_id is null then
    raise exception 'Missing deferred trip id' using errcode = '22023';
  end if;

  select t.id, t.driver_member_id, t.fuel_resolution, t.completion_fuel_legacy_id
    into v_trip
    from public.trips t
    where t.id = target_trip_id
      and t.ledger_id = target_ledger_id
      and t.booking_id is not null
      and t.deleted_at is null
    for update of t;

  if not found then
    raise exception 'Deferred booking trip was not found' using errcode = '22023';
  end if;

  if not (public.is_ledger_admin(target_ledger_id) or v_trip.driver_member_id = v_actor_member_id) then
    raise exception 'Only the trip driver or a ledger admin can complete its deferred fuel entry'
      using errcode = '42501';
  end if;

  if v_trip.fuel_resolution = 'logged' and v_trip.completion_fuel_legacy_id is not null then
    return jsonb_build_object(
      'trip_id', v_trip.id,
      'fuel_resolution', 'logged',
      'fuel_id', (
        select fp.id
        from public.fuel_payments fp
        where fp.ledger_id = target_ledger_id
          and fp.legacy_id = v_trip.completion_fuel_legacy_id
          and fp.deleted_at is null
        limit 1
      ),
      'reused_existing_fuel', true
    );
  end if;

  if v_trip.fuel_resolution <> 'deferred' then
    raise exception 'Trip does not have a deferred fuel entry' using errcode = '22023';
  end if;

  v_fuel_result := public.upsert_fuel_payment(
    target_ledger_id,
    target_open_period_id,
    fuel_legacy_id,
    fuel_payer_member_id,
    fuel_payment_date_value,
    fuel_amount_value,
    coalesce(nullif(fuel_currency_value, ''), 'DKK'),
    fuel_liters_value,
    fuel_price_per_liter_value,
    fuel_odometer_value,
    fuel_station_name_value,
    fuel_station_brand_value,
    coalesce(fuel_full_tank_value, false),
    fuel_event_title,
    fuel_event_body
  );

  v_saved_fuel_id := nullif(v_fuel_result ->> 'fuel_id', '')::uuid;
  if v_saved_fuel_id is null then
    raise exception 'Deferred fuel completion did not return a fuel id'
      using errcode = '40001';
  end if;

  -- The original trip may have become historical before the driver found the
  -- receipt. Reuse the existing transaction-local metadata scrub bypass for this
  -- one fixed-column UPDATE: neither field participates in settlement maths or
  -- the archived fingerprint, and enforce_trip_fuel_resolution still proves the
  -- linked fuel row exists. No caller-controlled SQL runs while the flag is set.
  perform set_config('govehlo.pii_scrub', '1', true);

  update public.trips t
  set fuel_resolution = 'logged',
      completion_fuel_legacy_id = fuel_legacy_id,
      updated_at = now()
  where t.id = target_trip_id
    and t.ledger_id = target_ledger_id
    and t.fuel_resolution = 'deferred';

  if not found then
    raise exception 'Deferred fuel completion could not update the trip'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'trip_id', target_trip_id,
    'fuel_resolution', 'logged',
    'fuel_id', v_saved_fuel_id,
    'reused_existing_fuel', false
  );
end;
$$;

revoke all on function public.complete_deferred_booking_fuel(
  text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric,
  text, text, boolean, text, text
) from public;
revoke all on function public.complete_deferred_booking_fuel(
  text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric,
  text, text, boolean, text, text
) from anon;
grant execute on function public.complete_deferred_booking_fuel(
  text, uuid, uuid, text, uuid, date, numeric, text, numeric, numeric, numeric,
  text, text, boolean, text, text
) to authenticated;

-- ═══════════════════════════════════════════════════════════════════════════════════
-- 4. acknowledge_inspection_booking — re-declared off migration 146, minus syn_booked_at
-- ═══════════════════════════════════════════════════════════════════════════════════
--
-- Signature unchanged, so this one is a plain create or replace and no client has to
-- move with it. Two keys remain: syn_booked_for (the acknowledged date, which is what
-- makes the marker self-invalidating) and syn_booked_by_member_id (who, so the group can
-- be told). The acknowledge path subtracts syn_booked_at before merging, so a workspace
-- that still carries one from an earlier acknowledgement loses it on next use even if the
-- one-time cleanup in section 5 is skipped; the clear path already removed it.

create or replace function public.acknowledge_inspection_booking(
  target_ledger_id text,
  acknowledged_inspection_date date,
  event_title text default null,
  event_body text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_member_id uuid;
  v_actor_email text;
  v_actor_first text;
  v_syn_date date;
  v_previous_ack date;
  v_title text;
  v_body text;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only ledger members can acknowledge a booked inspection'
      using errcode = '42501';
  end if;

  v_actor_member_id := public.current_ledger_member_id(target_ledger_id);
  if v_actor_member_id is null then
    raise exception 'Could not match the current user to an active ledger member'
      using errcode = '42501';
  end if;

  -- Lock the workspace row: two devices acknowledging at once must not interleave
  -- into a half-written marker (a date with nobody's name against it).
  select nullif(l.vehicle_info ->> 'next_inspection_date', '')::date,
         nullif(l.vehicle_info ->> 'syn_booked_for', '')::date
    into v_syn_date, v_previous_ack
    from public.ledgers l
    where l.id = target_ledger_id
    for update;

  if not found then
    raise exception 'Workspace was not found' using errcode = '22023';
  end if;

  v_actor_email := nullif(lower(coalesce(auth.jwt() ->> 'email', '')), '');

  select split_part(coalesce(nullif(btrim(m.name), ''), 'Nogen'), ' ', 1)
    into v_actor_first
    from public.ledger_members m
    where m.id = v_actor_member_id;
  v_actor_first := coalesce(v_actor_first, 'Nogen');

  -- ── Clear the acknowledgement (null date) ──────────────────────────────────────
  if acknowledged_inspection_date is null then
    -- Idempotent: nothing acknowledged means nothing to clear, so no write and no
    -- second event.
    if v_previous_ack is null then
      return jsonb_build_object(
        'acknowledged_for', null,
        'acknowledged_by_member_id', null,
        'changed', false
      );
    end if;

    update public.ledgers l
    set vehicle_info = l.vehicle_info
          - 'syn_booked_for'
          - 'syn_booked_at'
          - 'syn_booked_by_member_id',
        updated_at = now()
    where l.id = target_ledger_id;

    v_title := coalesce(nullif(btrim(event_title), ''), v_actor_first || ' fjernede syn-bookingen');
    v_body := coalesce(nullif(btrim(event_body), ''), 'Påmindelsen om syn er tilbage.');

    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id,
      'vehicle_inspection_booking_cleared',
      v_title,
      v_body,
      v_actor_member_id,
      v_actor_email,
      jsonb_build_object('inspection_date', v_previous_ack::text)
    );

    return jsonb_build_object(
      'acknowledged_for', null,
      'acknowledged_by_member_id', null,
      'changed', true
    );
  end if;

  -- ── Acknowledge the current inspection date ───────────────────────────────────
  if v_syn_date is null then
    raise exception 'This workspace has no next inspection date to acknowledge'
      using errcode = '22023';
  end if;

  -- The ack names its date, so it may only ever name the CURRENT one. A stale client,
  -- or a register refresh that landed in between, would otherwise silence a date
  -- nobody is being reminded about — or park an ack the live date later grows into.
  if acknowledged_inspection_date <> v_syn_date then
    raise exception 'The acknowledged inspection date is not this workspace''s next inspection date'
      using errcode = '22023';
  end if;

  -- Idempotent: a replay (double tap, offline retry, a second device) finds the same
  -- date already acknowledged and writes neither a marker nor a second event.
  if v_previous_ack = acknowledged_inspection_date then
    return jsonb_build_object(
      'acknowledged_for', acknowledged_inspection_date::text,
      'acknowledged_by_member_id',
        nullif((select l.vehicle_info ->> 'syn_booked_by_member_id'
                from public.ledgers l where l.id = target_ledger_id), ''),
      'changed', false
    );
  end if;

  -- GVM-457 / GV-400: no syn_booked_at. The acknowledgement timestamp was stamped on
  -- every ack and read by nothing — "is the upcoming syn booked?" is answered by
  -- syn_booked_for, which names its own date and self-invalidates when the register
  -- writes a new one. Subtracted rather than merely not written, so a workspace still
  -- carrying one from before this migration is cleaned by its next acknowledgement.
  update public.ledgers l
  set vehicle_info = (l.vehicle_info - 'syn_booked_at') || jsonb_build_object(
        'syn_booked_for', acknowledged_inspection_date::text,
        'syn_booked_by_member_id', v_actor_member_id::text
      ),
      updated_at = now()
  where l.id = target_ledger_id;

  v_title := coalesce(nullif(btrim(event_title), ''), v_actor_first || ' har booket synet');
  v_body := coalesce(
    nullif(btrim(event_body), ''),
    'Syn senest ' || to_char(v_syn_date, 'DD-MM-YYYY') || '. Påmindelsen er slået fra indtil da.'
  );

  insert into public.ledger_events (
    ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
  ) values (
    target_ledger_id,
    'vehicle_inspection_booked',
    v_title,
    v_body,
    v_actor_member_id,
    v_actor_email,
    jsonb_build_object('inspection_date', acknowledged_inspection_date::text)
  );

  return jsonb_build_object(
    'acknowledged_for', acknowledged_inspection_date::text,
    'acknowledged_by_member_id', v_actor_member_id::text,
    'changed', true
  );
end;
$$;

revoke all on function public.acknowledge_inspection_booking(text, date, text, text) from public;
revoke all on function public.acknowledge_inspection_booking(text, date, text, text) from anon;
grant execute on function public.acknowledge_inspection_booking(text, date, text, text) to authenticated;

-- ═══════════════════════════════════════════════════════════════════════════════════
-- 5. Erase what is already stored
-- ═══════════════════════════════════════════════════════════════════════════════════
--
-- The point of the ticket. One DO block because govehlo.pii_scrub is transaction-local
-- and the SQL Editor runs each top-level statement in its own transaction; see the
-- header for why the bypass is both necessary and safe here.

do $$
declare
  v_fuel_rows integer := 0;
  v_ledger_rows integer := 0;
begin
  perform set_config('govehlo.pii_scrub', '1', true);

  update public.fuel_payments fp
  set station_lat = null,
      station_lng = null
  where fp.station_lat is not null
     or fp.station_lng is not null;
  get diagnostics v_fuel_rows = row_count;

  update public.ledgers l
  set vehicle_info = l.vehicle_info - 'syn_booked_at'
  where l.vehicle_info ? 'syn_booked_at';
  get diagnostics v_ledger_rows = row_count;

  perform set_config('govehlo.pii_scrub', '', true);

  raise notice 'Migration 151: cleared station coordinates on % fuel row(s) and syn_booked_at on % workspace(s).',
    v_fuel_rows, v_ledger_rows;
end;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════════
-- 6. Drop the columns
-- ═══════════════════════════════════════════════════════════════════════════════════
--
-- With the values already nulled above, this removes the attributes themselves — and
-- with them the direct-write path the fuel_payments RLS insert/update policies would
-- otherwise still allow around the RPC (the same argument migration 071 made for
-- user_lat/user_lng).

alter table public.fuel_payments
  drop column if exists station_lat,
  drop column if exists station_lng;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '151_drop_fuel_station_coordinates',
  'GV-400 (server half of GVM-456/457, client half in govehlo-mobile PR #479): erases and drops the precise refuel position and retires the write-only RPC parameters. fuel_payments.station_lat/station_lng are NULLED first and only then dropped -- a bare DROP COLUMN just marks the attribute dead in the catalogue and leaves the coordinates in the live heap tuples and in every later base backup, so the UPDATE (migration 062''s half) is what actually erases and the DROP (071''s half) is what closes the direct-write path the RLS policies still allow around the RPC. Migration 062 kept these columns for a map-coordinate view that was never built, so the purpose they were justified by has no implementation; station_name/station_brand still record where. The backfill runs in one DO block with the transaction-local govehlo.pii_scrub GUC set, because the closed-period rejection (GV-199, migration 120) and the period-boundary check (121) would otherwise refuse the UPDATE on every fuel row in an already-closed period -- exactly the rows holding the oldest coordinates -- and the bypass is sound because neither column feeds settlement maths or the archived entry fingerprint. acknowledge_inspection_booking (re-declared off 146, signature unchanged) stops stamping syn_booked_at and now subtracts it before merging, so the marker self-heals; the same DO block clears the key from existing workspaces. Finally the accepted-and-ignored coordinate parameters go: upsert_fuel_payment drops user_lat_value/user_lng_value (dead since 071) and station_lat_value/station_lng_value, 19 args to 15, and complete_booking_trip_with_fuel (off 136, 28 to 26) and complete_deferred_booking_fuel (off 140, 18 to 16) drop the fuel_station_lat_value/fuel_station_lng_value they passed through. Arity changes are DROP + CREATE, not CREATE OR REPLACE (migration 063''s pattern) -- replacing with a different arity leaves the old overload live and PostgREST cannot resolve between them -- so the ACLs are restated, anon named explicitly per 148. BREAKING for any client still sending a dropped parameter: PostgREST matches body keys to a signature, so an extra key is PGRST202, not an ignored argument. govehlo-mobile src/lib/supabase-helpers.ts still passes all four coordinate params to upsert_fuel_payment as null; its sibling PR removes them and must ship with this.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 152: soft per-member cap on upcoming bookings — booking_future_cap_per_member
-- + set_booking_future_cap (GVM-434). NULL = off = the default, so an existing workspace
-- is unchanged; deliberately unenforced in the database (the client warns, never blocks).

alter table public.ledgers
  add column if not exists booking_future_cap_per_member integer;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'ledgers_booking_future_cap_check'
  ) then
    alter table public.ledgers
      add constraint ledgers_booking_future_cap_check
      check (booking_future_cap_per_member is null
             or (booking_future_cap_per_member >= 1 and booking_future_cap_per_member <= 50));
  end if;
end $$;

-- ── set_booking_future_cap: admin sets (or clears) the workspace's soft cap ──────
--
-- Its own admin-gated RPC rather than a sixth parameter on update_ledger_settings,
-- for the reason migration 080 gave for set_close_reminder_enabled: that function
-- patches with coalesce, so a NULL parameter means "leave it alone" and there would
-- be no way to express "turn the cap off" at all. Here NULL is a real value.
--
-- Emits a settings_changed event on a REAL change only, exactly as migration 119
-- made the settlement rules do: cross-client live sync IS that insert (migration
-- 087 lesson), and a group deserves to see in the feed that someone changed a rule
-- about their bookings. Setting the same number twice writes an identical row and
-- emits nothing. Danish server copy, overridable by the client for app voice.
create or replace function public.set_booking_future_cap(
  target_ledger_id text,
  cap_value integer,
  event_title text default null,
  event_body text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  old_cap integer;
  actor_id uuid;
  current_actor_email text;
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can change the booking cap.' using errcode = '42501';
  end if;

  -- Reject an unusable number up front rather than letting the check constraint
  -- surface as a raw 23514. 50 upcoming bookings for one member is already far
  -- past anything a nudge could helpfully say.
  if cap_value is not null and (cap_value < 1 or cap_value > 50) then
    raise exception 'Booking cap must be between 1 and 50' using errcode = '22023';
  end if;

  select l.booking_future_cap_per_member
    into old_cap
    from public.ledgers l
    where l.id = target_ledger_id;

  update public.ledgers l
  set booking_future_cap_per_member = cap_value,
      updated_at = now()
  where l.id = target_ledger_id;

  if cap_value is distinct from old_cap then
    actor_id := public.current_ledger_member_id(target_ledger_id);
    current_actor_email := nullif(lower(coalesce(auth.jwt() ->> 'email', '')), '');

    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email, metadata
    ) values (
      target_ledger_id,
      'settings_changed',
      coalesce(nullif(btrim(event_title), ''), 'Bookingloft ændret'),
      coalesce(
        nullif(btrim(event_body), ''),
        case
          when cap_value is null then 'Der er ikke længere et loft over kommende bookinger.'
          when cap_value = 1 then 'Gruppen får nu et blødt praj ved mere end 1 kommende booking pr. person.'
          else 'Gruppen får nu et blødt praj ved mere end ' || cap_value::text
               || ' kommende bookinger pr. person.'
        end
      ),
      actor_id,
      current_actor_email,
      jsonb_build_object(
        'field', 'booking_future_cap_per_member',
        'old', old_cap,
        'new', cap_value
      )
    );
  end if;
end;
$$;

revoke all on function public.set_booking_future_cap(text, integer, text, text) from public;
revoke all on function public.set_booking_future_cap(text, integer, text, text) from anon;
grant execute on function public.set_booking_future_cap(text, integer, text, text) to authenticated;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values ('152_booking_future_cap',
        'Soft per-member cap on upcoming bookings (GVM-434), third slice of the fair-share epic. New nullable ledgers.booking_future_cap_per_member (check: null or 1..50) where NULL means OFF and is the default, so every existing workspace keeps behaving exactly as before and no group starts warning members about bookings they already made. Deliberately UNENFORCED in the database — no trigger, no constraint on car_bookings — because the ticket asks the cap to warn, not block: the client reads the number and shows a non-blocking heads-up in the booking sheet, matching the settled policy that soft warning is the rule and a hard block is reserved for the unambiguously broken case (GVM-413 vs GVM-417). Same stored-but-not-enforced shape as rule_require_requests_before_close (098). Counts BOOKINGS, not booked days: the ticket left that open and flagged that a day-based cap punishes the one long holiday trip, which is the most legitimate long booking a shared car sees. New admin-gated set_booking_future_cap(text, integer, text, text) rather than a sixth update_ledger_settings parameter, because that function coalesce-patches and could therefore never express "clear the cap" (the same reason migration 080 gave set_close_reminder_enabled its own RPC). Writes a settings_changed ledger_event on a real change only (is distinct from, so re-saving the same number emits nothing), with Danish server-composed copy the client may override — the event insert is what live-syncs the rule change to other members (migration 087 lesson). Revokes execute from public and anon explicitly (148 convention), grants authenticated.')
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 153: weekly group digest of work nobody has registered yet (GVM-440)
--
-- If one member never logs their trips, EVERYONE's settlement is wrong. The app has
-- plenty of private nudges (the booking-ended push from migration 124, the Home
-- backlog item from GVM-433) but nothing that makes the gap visible to the group
-- while there is still time to fix it -- the first time the rest of the group learns
-- about it today is the pre-request warning, i.e. the moment it is too late.
--
-- This adds the missing surface as ONE more hook on the existing hourly reminder
-- tick. No new engine: the same claim/lease/token/confirm discipline as migrations
-- 080, 102, 118 and 124, and the same shared Expo sender in govehlo-web.
--
-- ── OWNER DECISION 1: what "mangler at blive registreret" means ────────────────
-- Two signals, and deliberately only two -- they are exactly the pair
-- settlementReadinessIssues() already computes for the pre-request warning
-- (govehlo-mobile src/lib/settlement-readiness.ts), so the digest and the warning
-- can never disagree about what is outstanding:
--
--   1. ENDED BOOKINGS WITH NO REGISTERED TRIP. car_bookings whose end_at has passed,
--      that are marked requires_linked_trip (migration 124 -- pre-123 bookings are
--      excluded because their date-fallback link is not reliable enough to name), and
--      that have no active row in trips.booking_id. Scoped to the OPEN settlement
--      period: a booking that ended before the period opened can no longer move this
--      period's split, so nagging about it is noise.
--
--   2. DEFERRED FUEL RECEIPTS. trips with fuel_resolution = 'deferred' -- "I refuelled,
--      I will register the receipt later". Deliberately NOT period-scoped, for exactly
--      the reason GVM-427 gives: resolving a deferred receipt writes the fuel into the
--      CURRENT open period, so a receipt deferred in period 1 and still outstanding in
--      period 2 changes period 2's split. Filtering by the trip's period would hide the
--      single most likely outstanding case.
--
-- NOT counted, on purpose: an unclosed period (the close reminder from migration 080
-- already owns that, and duplicating it would make the digest the thing people mute),
-- and "a trip that was never booked", which is unknowable -- there is no record of a
-- drive nobody wrote down and no booking to hang it on.
--
-- ── OWNER DECISION 2: cadence ──────────────────────────────────────────────────
-- SUNDAY 18:00-20:59, Europe/Copenhagen. Sunday evening is when the week's driving is
-- over and the person is at home with their phone, and it lands before the typical
-- month-end close rather than after it. The window is three hours wide, not one, so a
-- run that is deferred by quiet hours (GVM-286), a snooze, or a transient Expo failure
-- still gets two more attempts the same evening instead of losing the week. The hour is
-- read in DANISH LOCAL TIME (now() at time zone 'Europe/Copenhagen'), so CET/CEST does
-- not drift the send time twice a year.
--
-- The hook rides the EXISTING hourly cron rather than adding a weekly cron trigger.
-- Two reasons: 165 of every 168 hourly calls return zero rows for the price of one
-- cheap indexed probe, and a weekly trigger has exactly one shot per week -- if that
-- single firing lands during an outage, the digest silently skips a week.
--
-- ── OWNER DECISION 3: opt-out, and its default ─────────────────────────────────
-- weekly_digest_enabled is a WORKSPACE setting (admin-only setter below) and it
-- defaults to TRUE. That is the one genuinely arguable default here, so it is called
-- out rather than buried:
--   * FOR true: the digest only ever fires when there is real unfinished work -- a
--     group that keeps its log current never hears from it at all. It is a
--     transactional nudge about the members' own shared car, not marketing, so
--     markedsføringsloven §10 does not apply and no prior consent is required.
--   * FOR false: it is still an unsolicited weekly push, and those are how people end
--     up switching off notifications for an app entirely.
-- MIGRATIONS ARE APPLIED BY HAND, so this is a live choice: to ship it opt-IN instead,
-- change `default true` to `default false` on the weekly_digest_enabled column BELOW
-- and in the mirrored block in supabase-schema.sql before applying. Nothing else in
-- this migration or in either client depends on which way it goes.
--
-- Independently of the workspace switch, every individual already has three ways out
-- that this reuses for free (govehlo-web functions/api/_push.js): the 'activity'
-- notification category mute (GVM-119), the snooze, and quiet hours (GVM-286).
--
-- ── Double sends ───────────────────────────────────────────────────────────────
-- weekly_digest_sent_at is stamped only by confirm_weekly_digests, and only against a
-- matching one-shot claim token, so a crash between claim and send never marks a
-- workspace as digested. The claim itself takes a 15-minute lease under
-- `for update ... skip locked`, so two overlapping ticks cannot both pick up the same
-- workspace, and the six-day floor on weekly_digest_sent_at means a workspace cannot be
-- digested twice inside one weekend even if its lease expires mid-window.

alter table public.ledgers
  add column if not exists weekly_digest_enabled boolean not null default true,
  add column if not exists weekly_digest_claimed_at timestamptz,
  add column if not exists weekly_digest_claim_token uuid,
  add column if not exists weekly_digest_sent_at timestamptz;

comment on column public.ledgers.weekly_digest_enabled is
  'GVM-440: workspace switch for the weekly "what is still unregistered" digest push. Admin-only via set_weekly_digest_enabled. Per-member opt-outs (activity mute / snooze / quiet hours) apply on top of this and are honoured by the push hook, not here.';

create index if not exists ledgers_weekly_digest_due_idx
  on public.ledgers (weekly_digest_sent_at)
  where weekly_digest_enabled = true;

-- Admin-only workspace switch, mirroring set_close_reminder_enabled (migration 083's
-- grant shape): the digest is about the whole group's bookkeeping, so one member
-- cannot silence it for everyone -- they mute their own notifications instead.
create or replace function public.set_weekly_digest_enabled(
  target_ledger_id text,
  enabled boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if target_ledger_id is null or target_ledger_id = '' then
    raise exception 'Missing ledger id' using errcode = '22023';
  end if;

  if not public.is_ledger_admin(target_ledger_id) then
    raise exception 'Only ledger admins can change reminder settings.' using errcode = '42501';
  end if;

  update public.ledgers l
  set weekly_digest_enabled = coalesce(enabled, true),
      updated_at = now()
  where l.id = target_ledger_id;
end;
$$;

revoke all on function public.set_weekly_digest_enabled(text, boolean) from public;
revoke all on function public.set_weekly_digest_enabled(text, boolean) from anon;
grant execute on function public.set_weekly_digest_enabled(text, boolean) to authenticated;

-- ── claim_due_weekly_digests: engine op for the scheduled push ─────────────────
-- Returns nothing at all outside the Sunday-evening window, which is what makes it
-- safe to hang off the hourly tick. Inside the window it claims every enabled
-- workspace that (a) has outstanding registration work right now and (b) has not been
-- digested in the last six days, stamping a fresh one-shot token per claim.
--
-- `recipients` carries one entry per ACTIVE member with an e-mail, each with that
-- member's OWN outstanding counts, so the push hook can address the person who forgot
-- ("du mangler...") and everyone else with the group total, from a single claim.
-- Members with nothing outstanding are still included -- the point of the digest is
-- that the group sees the gap, not that the forgetful member is singled out.
--
-- Service-role only -- not client-callable.
create or replace function public.claim_due_weekly_digests(
  p_limit integer default 200
)
returns table (
  ledger_id text,
  claim_token uuid,
  missing_trips integer,
  deferred_fuel integer,
  recipients jsonb
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_local timestamp := (now() at time zone 'Europe/Copenhagen');
begin
  -- Sunday (ISO day 7), 18:00-20:59 Danish local time. Outside it there is nothing to
  -- claim and, deliberately, nothing to lock either.
  if extract(isodow from v_local) <> 7
     or extract(hour from v_local) < 18
     or extract(hour from v_local) > 20 then
    return;
  end if;

  return query
  with outstanding as (
    -- Ended bookings in the open period with no registered trip.
    select cb.ledger_id as l_id, cb.member_id as m_id, 'trip'::text as kind
    from public.car_bookings cb
    join public.settlement_periods sp
      on sp.ledger_id = cb.ledger_id
     and sp.status = 'open'
    where cb.deleted_at is null
      and cb.requires_linked_trip = true
      and cb.member_id is not null
      and cb.end_at <= now()
      and cb.end_at >= sp.opened_at
      and not exists (
        select 1
        from public.trips t
        where t.booking_id = cb.id
          and t.deleted_at is null
      )
    union all
    -- Deferred fuel receipts, NOT period-scoped (GVM-427): resolving one writes into
    -- the CURRENT open period regardless of which period its trip sits in.
    select t.ledger_id as l_id, t.driver_member_id as m_id, 'fuel'::text as kind
    from public.trips t
    where t.deleted_at is null
      and t.fuel_resolution = 'deferred'
      and t.booking_id is not null
      and t.driver_member_id is not null
  ),
  scoped as (
    -- Only work owed by a still-active member counts: a departed member's leftovers
    -- are an admin cleanup job, not something to nag the group about every Sunday.
    select o.l_id, o.m_id, o.kind
    from outstanding o
    join public.ledger_members lm
      on lm.id = o.m_id
     and lm.ledger_id = o.l_id
     and lm.is_active = true
  ),
  totals as (
    select s.l_id,
           (count(*) filter (where s.kind = 'trip'))::integer as missing_trips,
           (count(*) filter (where s.kind = 'fuel'))::integer as deferred_fuel
    from scoped s
    group by s.l_id
  ),
  per_member as (
    select s.l_id,
           s.m_id,
           (count(*) filter (where s.kind = 'trip'))::integer as own_trips,
           (count(*) filter (where s.kind = 'fuel'))::integer as own_fuel
    from scoped s
    group by s.l_id, s.m_id
  ),
  target as (
    select l.id
    from public.ledgers l
    join totals tt on tt.l_id = l.id
    where l.weekly_digest_enabled = true
      and (l.weekly_digest_sent_at is null
           or l.weekly_digest_sent_at <= now() - interval '6 days')
      and (l.weekly_digest_claimed_at is null
           or l.weekly_digest_claimed_at <= now() - interval '15 minutes')
    order by l.id
    limit greatest(coalesce(p_limit, 200), 0)
    for update of l skip locked
  ),
  claimed as (
    update public.ledgers l
    set weekly_digest_claimed_at = now(),
        weekly_digest_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where l.id = t.id
    returning l.id as l_id, l.weekly_digest_claim_token as token
  )
  select c.l_id,
         c.token,
         tt.missing_trips,
         tt.deferred_fuel,
         coalesce(
           (select jsonb_agg(
                     jsonb_build_object(
                       'email', lower(lm.email),
                       'own_trips', coalesce(pm.own_trips, 0),
                       'own_fuel', coalesce(pm.own_fuel, 0)
                     )
                     order by lower(lm.email)
                   )
            from public.ledger_members lm
            left join per_member pm
              on pm.l_id = lm.ledger_id
             and pm.m_id = lm.id
            where lm.ledger_id = c.l_id
              and lm.is_active = true
              and lm.email is not null),
           '[]'::jsonb
         ) as recipients
  from claimed c
  join totals tt on tt.l_id = c.l_id;
end;
$$;

revoke all on function public.claim_due_weekly_digests(integer) from public;
revoke all on function public.claim_due_weekly_digests(integer) from anon;
revoke all on function public.claim_due_weekly_digests(integer) from authenticated;
grant execute on function public.claim_due_weekly_digests(integer) to service_role;

-- ── confirm_weekly_digests: the other half of the lease ────────────────────────
-- Stamps weekly_digest_sent_at ONLY for a workspace whose claim token still matches
-- and whose six-day floor still holds, so a stale token from an expired lease cannot
-- retro-confirm a send and a retry inside the window cannot double-stamp. An
-- unconfirmed workspace simply becomes claimable again when its 15-minute lease
-- lapses -- under-sending on a crash, never double-sending.
--
-- Logs one ledger_events row per confirmed workspace: the reminder engines' audit
-- convention (migration 124), and the row is what makes other members' open clients
-- refresh. Counts only -- no e-mail, name, or push copy.
create or replace function public.confirm_weekly_digests(confirmations jsonb)
returns integer
language sql
security definer
set search_path = public
as $$
  with input as (
    select (elem ->> 'id') as ledger_id,
           (elem ->> 'token')::uuid as claim_token,
           (elem ->> 'outcome') as outcome,
           greatest(coalesce((elem ->> 'recipients')::integer, 0), 0) as recipients
    from jsonb_array_elements(coalesce(confirmations, '[]'::jsonb)) as elem
    where (elem ->> 'outcome') in ('delivered', 'suppressed_no_device', 'muted')
  ),
  confirmed as (
    update public.ledgers l
    set weekly_digest_sent_at = now(),
        weekly_digest_claimed_at = null,
        weekly_digest_claim_token = null,
        updated_at = now()
    from input i
    where l.id = i.ledger_id
      and l.weekly_digest_claimed_at is not null
      and l.weekly_digest_claim_token = i.claim_token
      and (l.weekly_digest_sent_at is null
           or l.weekly_digest_sent_at <= now() - interval '6 days')
    returning l.id as ledger_id,
              i.outcome as outcome,
              i.recipients as recipients
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email,
      target_member_id, metadata
    )
    select c.ledger_id,
           'weekly_digest_sent',
           'Ugentligt resumé behandlet',
           '',
           null,
           null,
           null,
           jsonb_build_object('outcome', c.outcome, 'recipients', c.recipients)
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_weekly_digests(jsonb) from public;
revoke all on function public.confirm_weekly_digests(jsonb) from anon;
revoke all on function public.confirm_weekly_digests(jsonb) from authenticated;
grant execute on function public.confirm_weekly_digests(jsonb) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '153_weekly_registration_digest',
  'GVM-440: weekly Sunday-evening group digest of registration work nobody has done yet. Adds the workspace switch weekly_digest_enabled (default true, admin-only via set_weekly_digest_enabled) plus a 15-minute lease/one-shot-token pair of service-role-only RPCs, claim_due_weekly_digests + confirm_weekly_digests, on the same claim-then-confirm-after-send discipline as migrations 080/102/118/124. "Missing" is defined as exactly the two signals settlementReadinessIssues() already computes: ended bookings in the OPEN period with no linked trip (requires_linked_trip only, so pre-123 date-fallback bookings are excluded), and deferred fuel receipts, which are deliberately not period-scoped because resolving one writes into the current open period (GVM-427). The claim returns nothing outside Sunday 18:00-20:59 Europe/Copenhagen, which is what lets it hang off the existing hourly cron instead of needing a weekly trigger with a single yearly-52 shot at firing. Six-day floor on weekly_digest_sent_at plus skip-locked claiming means a workspace cannot be digested twice in one weekend, and a crash between claim and send under-sends rather than double-sends.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 154: pre-departure fuel-stop reminders (GV-405)
--
-- The twin of migration 124. That engine fires AFTER a booking ends ("you drove,
-- register the trip"); this one fires BEFORE a booking starts ("the tank no longer
-- covers your planned route"). In a shared car other members drive between planning
-- and departure, so the fuel stop persisted on the booking encodes a tank level that
-- may be hours and several trips out of date by the time the driver leaves.
--
-- ── Why the tank model is NOT ported ────────────────────────────────────────────
-- The verdict itself is ~20 lines of arithmetic (range minus a 10% reserve versus the
-- planned distance). What is expensive is the three numbers it eats — litersNow,
-- consumption, consumptionSpread — which come out of govehlo-mobile's
-- src/lib/trip-estimate.ts: a tank baseline (migration 092) plus every trip since,
-- minus every fuel log, with self-healing on full-tank overflow. Porting 518 lines of
-- that to PL/pgSQL would create a second model to keep in step forever.
--
-- So the client STAMPS ITS OUTPUT onto the ledger (set_tank_state below) and the server
-- reads the numbers. The arithmetic that IS duplicated — safeConsumption, the reserve
-- fraction, the deadband, the three verdicts — is pinned to the mobile source by
-- tools/test-fuel-stop-verdict-contract.mjs, which replays the exact scenarios of
-- govehlo-mobile/src/lib/__tests__/fuel-stop-revalidation.test.ts against this SQL.
--
-- ── Fail closed, everywhere ─────────────────────────────────────────────────────
-- fuel-stop-revalidation.ts states the principle: "we never nag on data we can't
-- trust". Server-side that means the claim below skips a booking outright when the
-- stamp is missing, when the stored fuel stop is malformed or has no usable distance,
-- and — the important one — when ANY trip or fuel payment for that car is newer than
-- the stamp's watermark. A stale stamp is not a stale nudge; it is no nudge.
--
-- Nothing here is client-callable except set_tank_state. The claim/confirm pair is
-- service_role only, on the same lease + one-shot-token discipline as migrations
-- 080/082/102/118/124/153: claim leases a row for 15 minutes, the sender pushes, and
-- only a confirm carrying the matching token marks it reminded. A crash between the
-- two under-sends rather than double-sends.

-- ── Tank state stamped by the client ────────────────────────────────────────────
-- Sits beside tank_baseline_* (migration 092), which is the ANCHOR the client's model
-- starts from; these five are that model's OUTPUT as of a point in time.
alter table public.ledgers
  add column if not exists tank_state_liters numeric,
  add column if not exists tank_state_as_of timestamptz,
  add column if not exists tank_state_consumption numeric,
  add column if not exists tank_state_consumption_spread numeric,
  add column if not exists tank_state_capacity numeric;

comment on column public.ledgers.tank_state_as_of is
  'Data watermark of the stamped tank state: the newest greatest(created_at, updated_at) across the trips and fuel_payments the client consumed when it computed tank_state_liters. NOT a wall-clock write time — that is what makes set_tank_state''s monotonic check meaningful (a client that has seen less data carries an older watermark and cannot overwrite a fresher stamp) and what claim_due_booking_fuel_reminders compares against to detect a stale stamp.';

-- Record the client's current tank-model output for this car. Called after every trip
-- and fuel write, so it is deliberately cheap: member-gated, no ledger_events row (a
-- mechanical stamp is not a domain event, and one per trip write would spam both the
-- activity feed and the realtime channel that migration 087 wired to it).
--
-- MONOTONIC on as_of: a stamp whose watermark is older than the stored one is a client
-- working from a stale cache, and applying it would move the tank level BACKWARDS. It
-- is refused as a no-op return, not an exception — a losing race is normal and the
-- client must be able to ignore it quietly. Callers read `applied` to tell the two
-- apart. An equal watermark is accepted: same data in, same numbers out, so the write
-- is idempotent.
create or replace function public.set_tank_state(
  target_ledger_id text,
  liters_value numeric,
  as_of_value timestamptz,
  consumption_value numeric,
  spread_value numeric,
  capacity_value numeric
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  saved_as_of timestamptz;
  normalized_spread numeric;
begin
  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only an active workspace member can record tank state' using errcode = '42501';
  end if;

  if as_of_value is null then
    raise exception 'Tank state needs an as-of watermark' using errcode = '23514';
  end if;

  -- A watermark from the future would make every later staleness check pass forever
  -- and could lock out every subsequent stamp. It can only come from a client bug, so
  -- it raises rather than no-ops. One minute of slack absorbs ordinary clock skew.
  if as_of_value > now() + interval '1 minute' then
    raise exception 'Tank state as-of cannot be in the future' using errcode = '23514';
  end if;

  if liters_value is null or liters_value < 0 then
    raise exception 'Tank state litres must be zero or greater' using errcode = '23514';
  end if;

  if consumption_value is null or consumption_value <= 0 then
    raise exception 'Tank state consumption must be greater than zero' using errcode = '23514';
  end if;

  if capacity_value is null or capacity_value <= 0 then
    raise exception 'Tank state capacity must be greater than zero' using errcode = '23514';
  end if;

  -- Mirrors safeConsumption's tolerance in govehlo-mobile/src/lib/refuel-plan.ts: a
  -- non-positive or absent spread collapses to zero rather than being rejected.
  normalized_spread := case when spread_value is not null and spread_value > 0 then spread_value else 0 end;

  select l.tank_state_as_of into saved_as_of
  from public.ledgers l
  where l.id = target_ledger_id;

  if not found then
    raise exception 'Workspace not found' using errcode = '42501';
  end if;

  if saved_as_of is not null and as_of_value < saved_as_of then
    return jsonb_build_object(
      'ledger_id', target_ledger_id,
      'applied', false,
      'reason', 'stale_as_of',
      'stored_as_of', saved_as_of
    );
  end if;

  update public.ledgers l
     set tank_state_liters = liters_value,
         tank_state_as_of = as_of_value,
         tank_state_consumption = consumption_value,
         tank_state_consumption_spread = normalized_spread,
         tank_state_capacity = capacity_value,
         updated_at = now()
   where l.id = target_ledger_id;

  return jsonb_build_object(
    'ledger_id', target_ledger_id,
    'applied', true,
    'tank_state_liters', liters_value,
    'tank_state_as_of', as_of_value
  );
end;
$$;

revoke all on function public.set_tank_state(text, numeric, timestamptz, numeric, numeric, numeric) from public;
revoke all on function public.set_tank_state(text, numeric, timestamptz, numeric, numeric, numeric) from anon;
grant execute on function public.set_tank_state(text, numeric, timestamptz, numeric, numeric, numeric) to authenticated;

-- ── The verdict ─────────────────────────────────────────────────────────────────
-- A line-for-line mirror of revalidateFuelStop in
-- govehlo-mobile/src/lib/fuel-stop-revalidation.ts, which in turn calls planRefuel /
-- safeConsumption in govehlo-mobile/src/lib/refuel-plan.ts. Returns the same three
-- fields that module's result carries, so the contract test can assert on all of them:
--   { "verdict": "holds" | "move-earlier" | "now-needs-stop",
--     "reserveKm": <number|null>, "storedStopKm": <number|null> }
--
-- Not client-callable: it is an internal calculator for the claim below, which is
-- SECURITY DEFINER and therefore reaches it as the function owner.
--
-- On p_stored_fuel_stop ->> 'distanceKm': that value is the EFFECTIVE distance, already
-- doubled for a tur/retur plan (govehlo-mobile/src/screens/Book/EstimateView.tsx passes
-- `effDist` into buildBookingFuelStop, and useTripEstimate.ts computes it as
-- `returnTrip ? distNum * 2 : distNum`). The sibling `returnTrip` flag is presentational
-- metadata for the detail screen's return-leg date and must NOT be applied as a
-- multiplier here — doing so would model a 600 km round trip as 1200 km and push people
-- whose tank is fine. buildFuelStopNudge feeds the same value straight through.
create or replace function public.fuel_stop_revalidation_verdict(
  p_stored_fuel_stop jsonb,
  p_liters_now numeric,
  p_consumption numeric,
  p_consumption_spread numeric,
  p_tank_capacity numeric,
  p_deadband_km numeric
)
returns jsonb
language plpgsql
immutable
set search_path = public
as $$
declare
  -- Fail-closed answer, byte-for-byte the `holds` constant in fuel-stop-revalidation.ts.
  holds constant jsonb := jsonb_build_object('verdict', 'holds', 'reserveKm', null, 'storedStopKm', null);
  distance_km numeric;
  stored_needs_fuel boolean;
  stored_stop_km numeric;
  station_json jsonb;
  cons_safe numeric;
  current_range_km numeric;
  reserve_km numeric;
  km_until_reserve numeric;
  plan_needs_fuel boolean;
  km_until_refuel numeric;
  deadband_km numeric;
  reserve_out jsonb;
begin
  -- Fail closed on anything we can't trust (revalidateFuelStop's opening guards).
  if p_stored_fuel_stop is null or jsonb_typeof(p_stored_fuel_stop) <> 'object' then
    return holds;
  end if;

  -- hasTankState / tankStateSource === 'none' server-side: no stamped numbers, no nudge.
  if p_liters_now is null or p_consumption is null or p_tank_capacity is null then
    return holds;
  end if;

  -- numOrNull: a JSON value that is not a number is not a number. A string "400" fails
  -- this exactly as `typeof v === 'number'` fails it in the TypeScript.
  if jsonb_typeof(p_stored_fuel_stop -> 'distanceKm') = 'number' then
    distance_km := (p_stored_fuel_stop ->> 'distanceKm')::numeric;
  end if;
  if distance_km is null or distance_km <= 0 then
    return holds;
  end if;

  -- storedNeedsFuel = fs.needsFuel === true || fs.station != null
  -- `fs.station != null` in the TypeScript is true for ANY present, non-null value, not
  -- only a well-formed object — and it has to stay that way here. A corrupt `station`
  -- means "the plan claimed a stop"; reading it as "no stop planned" would route a
  -- malformed booking down the now-needs-stop branch instead of failing closed. So the
  -- flag is taken from the RAW value, and only the kmIn lookup below narrows to objects
  -- (mirroring `fs.station?.kmIn`, which yields undefined on a non-object).
  station_json := p_stored_fuel_stop -> 'station';
  stored_needs_fuel := (jsonb_typeof(p_stored_fuel_stop -> 'needsFuel') = 'boolean'
                        and (p_stored_fuel_stop ->> 'needsFuel')::boolean)
                       or (station_json is not null and jsonb_typeof(station_json) <> 'null');
  if station_json is not null and jsonb_typeof(station_json) <> 'object' then
    station_json := null;
  end if;

  -- Where the stored plan said to fill: the station's own position, else the reserve km.
  if station_json is not null and jsonb_typeof(station_json -> 'kmIn') = 'number' then
    stored_stop_km := (station_json ->> 'kmIn')::numeric;
  elsif jsonb_typeof(p_stored_fuel_stop -> 'kmUntilRefuel') = 'number' then
    stored_stop_km := (p_stored_fuel_stop ->> 'kmUntilRefuel')::numeric;
  end if;

  -- A stored stop we can't locate can't be re-validated — fail closed.
  if stored_needs_fuel and stored_stop_km is null then
    return holds;
  end if;

  deadband_km := coalesce(p_deadband_km, 10);

  -- ── planRefuel, recomputed at the CURRENT tank state ──────────────────────────
  -- safeConsumption(consumption, spread) from refuel-plan.ts, ported verbatim: the
  -- SAFETY decision runs at the conservative "thirstier" burn mean + spread (GVM-385),
  -- and a non-positive or absent spread collapses to the mean.
  cons_safe := p_consumption
             + case when p_consumption_spread is not null and p_consumption_spread > 0
                    then p_consumption_spread else 0 end;

  -- planRefuel gates on the MEAN consumption being positive, not the safe one.
  if p_consumption <= 0 then
    plan_needs_fuel := false;
    km_until_refuel := 0;
  else
    current_range_km := (p_liters_now / cons_safe) * 100;
    -- RESERVE_FRACTION = 0.1 in govehlo-mobile/src/lib/refuel-plan.ts — the fraction of
    -- the tank kept as an untouchable reserve. Kept as an explicit literal here rather
    -- than a settings column precisely so the contract test can pin the two together.
    reserve_km := ((p_tank_capacity * 0.1) / cons_safe) * 100;
    km_until_reserve := current_range_km - reserve_km;

    if km_until_reserve >= distance_km then
      -- Comfortably makes it on the current tank.
      plan_needs_fuel := false;
      km_until_refuel := 0;
    else
      plan_needs_fuel := true;
      -- round1() in refuel-plan.ts: Math.round(n * 10) / 10. Every comparison below
      -- uses the ROUNDED figure, exactly as the TypeScript does.
      km_until_refuel := round(greatest(0, least(km_until_reserve, distance_km)), 1);
    end if;
  end if;

  reserve_out := case when plan_needs_fuel then to_jsonb(km_until_refuel) else 'null'::jsonb end;

  if not stored_needs_fuel then
    -- Plan said no stop; does the current level now demand one, with real margin?
    if plan_needs_fuel and km_until_refuel <= distance_km - deadband_km then
      return jsonb_build_object('verdict', 'now-needs-stop', 'reserveKm', reserve_out, 'storedStopKm', null);
    end if;
    return jsonb_build_object('verdict', 'holds', 'reserveKm', reserve_out, 'storedStopKm', null);
  end if;

  -- Stored plan had a stop. Is the reserve now crossed meaningfully before we'd reach it?
  -- (A fuller-than-planned tank — plan_needs_fuel false, or a later crossing — never nags.)
  if plan_needs_fuel and stored_stop_km is not null and stored_stop_km - km_until_refuel >= deadband_km then
    return jsonb_build_object('verdict', 'move-earlier', 'reserveKm', reserve_out, 'storedStopKm', to_jsonb(stored_stop_km));
  end if;
  return jsonb_build_object('verdict', 'holds', 'reserveKm', reserve_out, 'storedStopKm', to_jsonb(stored_stop_km));
end;
$$;

revoke all on function public.fuel_stop_revalidation_verdict(jsonb, numeric, numeric, numeric, numeric, numeric) from public;
revoke all on function public.fuel_stop_revalidation_verdict(jsonb, numeric, numeric, numeric, numeric, numeric) from anon;
revoke all on function public.fuel_stop_revalidation_verdict(jsonb, numeric, numeric, numeric, numeric, numeric) from authenticated;

-- ── Claim / confirm ─────────────────────────────────────────────────────────────
alter table public.car_bookings
  add column if not exists fuel_reminded_at timestamptz,
  add column if not exists fuel_reminder_claimed_at timestamptz,
  add column if not exists fuel_reminder_claim_token uuid;

create index if not exists car_bookings_fuel_reminder_due_idx
  on public.car_bookings (start_at)
  where deleted_at is null
    and fuel_reminded_at is null;

-- Lease the bookings that need a pre-departure fuel-stop push, newest lease wins for
-- 15 minutes. Due-ness is decided HERE rather than in the caller so the endpoint
-- (GV-406) cannot accidentally relax it, and so the whole predicate is one thing to
-- test.
--
-- A booking is due when ALL of these hold:
--   • it starts within the next 3 hours and has not started yet;
--   • it is neither soft-deleted nor cancelled — car_bookings has no status column, so
--     cancellation IS the soft delete (deleted_at), which is what cancel_booking writes;
--   • its workspace is not itself soft-deleted (migration 132) — a decommissioned car
--     must go quiet, and the RLS-side helpers all check this, but this RPC runs as
--     service_role and would otherwise never see it;
--   • the booked member is still active and reachable by email;
--   • it has never been reminded and carries no live lease;
--   • its fuel_stop is an object with a usable numeric distanceKm;
--   • the car has a complete stamped tank state;
--   • NOTHING has happened to the car since that stamp — see below;
--   • and the verdict over the CURRENT tank state is not 'holds'.
--
-- The staleness gate is the fail-closed rule from fuel-stop-revalidation.ts applied to
-- the stamp itself: if any trip or fuel payment for the car is newer than the stamp's
-- watermark, the client's numbers predate real driving or a real fill-up and we do not
-- know the tank level any more. greatest(created_at, updated_at) rather than created_at
-- alone because an EDIT to an old trip, and a soft delete (every soft-delete path in
-- this schema sets deleted_at and updated_at together), invalidate the stamp exactly as
-- a new row does — and deleted rows are deliberately not filtered out for that reason.
create or replace function public.claim_due_booking_fuel_reminders(
  p_limit integer default 200
)
returns table (
  booking_id uuid,
  ledger_id text,
  member_id uuid,
  member_email text,
  verdict text,
  reserve_km numeric,
  stored_stop_km numeric,
  claim_token uuid
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select cb.id as target_booking_id,
           public.fuel_stop_revalidation_verdict(
             cb.fuel_stop,
             l.tank_state_liters,
             l.tank_state_consumption,
             coalesce(l.tank_state_consumption_spread, 0),
             l.tank_state_capacity,
             -- DEFAULT_REVALIDATION_DEADBAND_KM = 10 in
             -- govehlo-mobile/src/lib/fuel-stop-revalidation.ts. Only flag when the
             -- stored stop is at least this far past the new reserve crossing, so
             -- small between-planning drift does not nag.
             10
           ) as target_verdict
    from public.car_bookings cb
    join public.ledger_members lm
      on lm.id = cb.member_id
     and lm.ledger_id = cb.ledger_id
    join public.ledgers l
      on l.id = cb.ledger_id
    where cb.deleted_at is null
      and l.deleted_at is null
      and cb.start_at > now()
      and cb.start_at <= now() + interval '3 hours'
      and cb.fuel_reminded_at is null
      and (cb.fuel_reminder_claimed_at is null
           or cb.fuel_reminder_claimed_at <= now() - interval '15 minutes')
      and lm.is_active = true
      and lm.email is not null
      and jsonb_typeof(cb.fuel_stop) = 'object'
      and jsonb_typeof(cb.fuel_stop -> 'distanceKm') = 'number'
      and (cb.fuel_stop ->> 'distanceKm')::numeric > 0
      and l.tank_state_as_of is not null
      and l.tank_state_liters is not null
      and l.tank_state_consumption is not null
      and l.tank_state_capacity is not null
      and not exists (
        select 1
        from public.trips t
        where t.ledger_id = cb.ledger_id
          and greatest(t.created_at, t.updated_at) > l.tank_state_as_of
      )
      and not exists (
        select 1
        from public.fuel_payments fp
        where fp.ledger_id = cb.ledger_id
          and greatest(fp.created_at, fp.updated_at) > l.tank_state_as_of
      )
      and public.fuel_stop_revalidation_verdict(
            cb.fuel_stop,
            l.tank_state_liters,
            l.tank_state_consumption,
            coalesce(l.tank_state_consumption_spread, 0),
            l.tank_state_capacity,
            10
          ) ->> 'verdict' <> 'holds'
    order by cb.start_at
    limit greatest(coalesce(p_limit, 200), 0)
    for update of cb skip locked
  ),
  claimed as (
    update public.car_bookings cb
    set fuel_reminder_claimed_at = now(),
        fuel_reminder_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where cb.id = t.target_booking_id
    returning cb.id as booking_id,
              cb.ledger_id as ledger_id,
              cb.member_id as member_id,
              cb.fuel_reminder_claim_token as claim_token,
              t.target_verdict as target_verdict
  )
  select c.booking_id,
         c.ledger_id,
         c.member_id,
         lower(lm.email) as member_email,
         c.target_verdict ->> 'verdict' as verdict,
         case when jsonb_typeof(c.target_verdict -> 'reserveKm') = 'number'
              then (c.target_verdict ->> 'reserveKm')::numeric end as reserve_km,
         case when jsonb_typeof(c.target_verdict -> 'storedStopKm') = 'number'
              then (c.target_verdict ->> 'storedStopKm')::numeric end as stored_stop_km,
         c.claim_token
  from claimed c
  join public.ledger_members lm
    on lm.id = c.member_id
   and lm.ledger_id = c.ledger_id;
end;
$$;

revoke all on function public.claim_due_booking_fuel_reminders(integer) from public;
revoke all on function public.claim_due_booking_fuel_reminders(integer) from anon;
revoke all on function public.claim_due_booking_fuel_reminders(integer) from authenticated;
grant execute on function public.claim_due_booking_fuel_reminders(integer) to service_role;

-- Mark the leased bookings reminded, but only for a caller holding the token the claim
-- handed out — the one-shot half of the contract from migration 124. Anything the
-- sender could not deliver is simply left unconfirmed and falls back into the pool when
-- its lease expires.
create or replace function public.confirm_booking_fuel_reminders(confirmations jsonb)
returns integer
language sql
security definer
set search_path = public
as $$
  with input as (
    select (elem ->> 'id')::uuid as booking_id,
           (elem ->> 'token')::uuid as claim_token,
           (elem ->> 'outcome') as outcome
    from jsonb_array_elements(coalesce(confirmations, '[]'::jsonb)) as elem
    where (elem ->> 'outcome') in ('delivered', 'suppressed_no_device', 'muted')
  ),
  confirmed as (
    update public.car_bookings cb
    set fuel_reminded_at = now(),
        fuel_reminder_claimed_at = null,
        fuel_reminder_claim_token = null,
        updated_at = now()
    from input i
    where cb.id = i.booking_id
      and cb.deleted_at is null
      and cb.fuel_reminded_at is null
      and cb.fuel_reminder_claimed_at is not null
      and cb.fuel_reminder_claim_token = i.claim_token
    returning cb.id as booking_id,
              cb.ledger_id as ledger_id,
              cb.member_id as member_id,
              i.outcome as outcome
  ),
  logged as (
    insert into public.ledger_events (
      ledger_id, event_type, title, body, actor_member_id, actor_email,
      target_member_id, metadata
    )
    select c.ledger_id,
           'booking_fuel_reminder_sent',
           'Tankstop-påmindelse behandlet',
           '',
           null,
           null,
           c.member_id,
           jsonb_build_object('booking_id', c.booking_id, 'outcome', c.outcome)
    from confirmed c
    returning 1
  )
  select count(*)::integer from confirmed;
$$;

revoke all on function public.confirm_booking_fuel_reminders(jsonb) from public;
revoke all on function public.confirm_booking_fuel_reminders(jsonb) from anon;
revoke all on function public.confirm_booking_fuel_reminders(jsonb) from authenticated;
grant execute on function public.confirm_booking_fuel_reminders(jsonb) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '154_booking_fuel_stop_reminders',
  'GV-405: pre-departure fuel-stop reminders — the before-departure twin of migration 124''s after-booking trip reminders. Adds ledgers.tank_state_liters/as_of/consumption/consumption_spread/capacity plus the member-gated set_tank_state RPC that writes them: the client stamps the OUTPUT of its 518-line trip-estimate tank model rather than the model being ported to PL/pgSQL, and the stamp is monotonic on a DATA watermark (the newest greatest(created_at, updated_at) across the trips and fuel_payments it consumed), so a client on a stale cache is refused as a quiet no-op instead of moving the tank level backwards. public.fuel_stop_revalidation_verdict mirrors revalidateFuelStop / planRefuel / safeConsumption from govehlo-mobile with RESERVE_FRACTION 0.1 and the 10 km deadband as explicit literals, and is pinned to that TypeScript by tools/test-fuel-stop-verdict-contract.mjs, which replays the mobile vitest scenarios against this SQL. claim_due_booking_fuel_reminders + confirm_booking_fuel_reminders are service-role-only on the 15-minute lease + one-shot-token discipline of migrations 080/082/102/118/124/153, with new car_bookings columns fuel_reminded_at / fuel_reminder_claimed_at / fuel_reminder_claim_token. Due-ness lives in the claim: start_at within the next 3 hours and not yet passed, not soft-deleted (cancellation IS the soft delete — car_bookings has no status column), member active with an email, a fuel_stop object carrying a usable numeric distanceKm (already the effective, tur/retur-doubled distance — the returnTrip flag is presentational and must NOT be applied as a multiplier), a complete tank stamp, and a non-holds verdict. Fail-closed on a stale stamp: any trip or fuel payment newer than tank_state_as_of skips the booking entirely, because we never nag on data we cannot trust.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 155: atomic set_tank_state, a tombstone-blind freshness gate, bounded inputs (GV-411)
--
-- Three defects an external review found in migration 154 (GV-405). 154 is ALREADY
-- APPLIED in production, so it is left untouched and both functions are re-declared
-- here off 154's definitions — the newest prior ones.
--
-- ── A. set_tank_state could write the tank level BACKWARDS ──────────────────────
-- 154 enforced monotonicity as a read-modify-write across three statements: select the
-- stored watermark, compare, then update. A plain select takes no row lock, so two
-- devices stamping at once both read the same pre-state, both pass the comparison, and
-- whichever update commits LAST wins — which may be the one carrying the OLDER
-- watermark. That is exactly the outcome the watermark exists to prevent, and the whole
-- reason it is a data mark rather than a clock reading (see the column comment on
-- ledgers.tank_state_as_of, unchanged here).
--
-- The condition now rides ON the update, so there is a single statement and no window
-- between the read and the write. Under READ COMMITTED a loser that blocks on the
-- winner's row lock re-evaluates the WHERE against the row version the winner
-- committed, sees the fresher watermark, and matches nothing.
--
-- The return contract is unchanged, deliberately: govehlo-mobile reads `applied`
-- (tankStampApplied in src/lib/tank-state-stamp.ts, GVM-480) and treats false as a
-- quiet no-op, and the `stale_as_of` reason plus `stored_as_of` keep their shape. `<=`
-- rather than `<` keeps an equal watermark accepted and the write idempotent: same data
-- in, same numbers out.
--
-- ── B. one soft-deleted trip or fuel row could silence reminders FOREVER ────────
-- 154's freshness gate skipped a booking when any trip or fuel payment for the car was
-- newer than the stamp's watermark, and deliberately did NOT filter tombstones — the
-- reasoning being that a deletion invalidates the stamp exactly as an edit does.
--
-- That reasoning holds only if the client can produce a watermark that covers the
-- deleted row, and it cannot: govehlo-mobile/src/store/ledger-data-gateway.ts fetches
-- trips and fuel payments with `.is('deleted_at', null)`, and the stamp's watermark is
-- the newest greatest(created_at, updated_at) across the rows it LOADED. A soft delete
-- bumps updated_at, so a tombstone is permanently newer than any watermark the client
-- can ever send. `not exists` stays true forever, the claim never returns that booking,
-- and pre-departure reminders die silently for that workspace — no error anywhere —
-- until an active trip or fuel row happens to be created with an even newer stamp.
--
-- So the gate now asks precisely the question the client can answer: is any row the
-- client would have LOADED newer than the watermark?
--
-- The residual, stated honestly: a deletion no longer marks the stamp stale, so between
-- a delete and the next tank-changing write the server may reason from a model that is
-- slightly out of date (it still counts a trip that has been removed). That is far
-- milder than permanent silence and it self-heals — the next trip or fuel write
-- re-stamps the model without the deleted row. The fully robust alternative is a
-- server-derived watermark that includes tombstones (recorded on GV-411); it becomes
-- the right answer if client-side deletion ever ships. Today there is no delete path in
-- the client at all — deletions come from the admin console or the database directly.
--
-- ── C. bounds on the client-supplied numbers ────────────────────────────────────
-- set_tank_state takes litres, capacity, consumption and spread straight from the
-- client's model, and that is by design (GV-405: the model is not ported to PL/pgSQL).
-- Trusting the client is not the same as accepting the absurd, though, so the obvious
-- impossibilities are refused. The envelope is not invented here — it is the one
-- migration 125's update_ledger_fuel_settings already enforces on the very settings
-- columns these numbers are derived from (consumption 0.1–100 L/100 km, capacity
-- 1–500 L), so nothing an honest client can produce is newly rejected:
--
--   • litres ≤ capacity — every branch of buildTripEstimate clamps the modelled level
--     into [0, tankCapacity], so only a hand-rolled call can breach it.
--   • capacity ≤ 500 L and consumption ≤ 100 L/100 km — the upper half of migration
--     125's range. Only the UPPER bounds are added: the existing "> 0" lower bounds
--     stay, so a legacy workspace whose settings predate 125 is not newly refused.
--   • consumption + spread ≤ 100 L/100 km — the spread is the other half of the burn
--     the verdict actually runs on (safeConsumption = consumption + spread), so it is
--     held to the same ceiling as the mean rather than left unbounded.
--
-- Rejections raise, like every other validation in this function — a silent clamp would
-- store numbers the client never computed and nudge people on them.

create or replace function public.set_tank_state(
  target_ledger_id text,
  liters_value numeric,
  as_of_value timestamptz,
  consumption_value numeric,
  spread_value numeric,
  capacity_value numeric
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  saved_as_of timestamptz;
  normalized_spread numeric;
begin
  if not public.is_ledger_member(target_ledger_id) then
    raise exception 'Only an active workspace member can record tank state' using errcode = '42501';
  end if;

  if as_of_value is null then
    raise exception 'Tank state needs an as-of watermark' using errcode = '23514';
  end if;

  -- A watermark from the future would make every later staleness check pass forever
  -- and could lock out every subsequent stamp. It can only come from a client bug, so
  -- it raises rather than no-ops. One minute of slack absorbs ordinary clock skew.
  if as_of_value > now() + interval '1 minute' then
    raise exception 'Tank state as-of cannot be in the future' using errcode = '23514';
  end if;

  if liters_value is null or liters_value < 0 then
    raise exception 'Tank state litres must be zero or greater' using errcode = '23514';
  end if;

  if consumption_value is null or consumption_value <= 0 then
    raise exception 'Tank state consumption must be greater than zero' using errcode = '23514';
  end if;

  if capacity_value is null or capacity_value <= 0 then
    raise exception 'Tank state capacity must be greater than zero' using errcode = '23514';
  end if;

  -- Upper bounds (GV-411), matching migration 125's update_ledger_fuel_settings on the
  -- settings columns these numbers come from. A tank that cannot hold what it is said
  -- to hold, a 5000-litre tank or a 900 L/100 km burn are not model output; they are a
  -- fabricated or corrupt call, and the verdict engine would nudge the whole workspace
  -- on them.
  if liters_value > capacity_value then
    raise exception 'Tank state litres cannot exceed the tank capacity' using errcode = '23514';
  end if;

  if capacity_value > 500 then
    raise exception 'Tank state capacity must be 500 litres or less' using errcode = '23514';
  end if;

  if consumption_value > 100 then
    raise exception 'Tank state consumption must be 100 per 100 km or less' using errcode = '23514';
  end if;

  -- Mirrors safeConsumption's tolerance in govehlo-mobile/src/lib/refuel-plan.ts: a
  -- non-positive or absent spread collapses to zero rather than being rejected.
  normalized_spread := case when spread_value is not null and spread_value > 0 then spread_value else 0 end;

  -- safeConsumption = consumption + spread is the burn the verdict actually plans on,
  -- so the ceiling applies to the sum, not only to the mean.
  if consumption_value + normalized_spread > 100 then
    raise exception 'Tank state consumption plus spread must be 100 per 100 km or less' using errcode = '23514';
  end if;

  -- MONOTONIC on as_of, in ONE statement (GV-411). A stamp whose watermark is older
  -- than the stored one is a client working from a stale cache, and applying it would
  -- move the tank level BACKWARDS. 154 checked that with a separate select, which takes
  -- no row lock: two devices could both pass the check and the older calculation could
  -- commit last. Riding the condition on the update closes that window — under READ
  -- COMMITTED a loser blocked on the winner's row lock re-evaluates this WHERE against
  -- the committed row and matches nothing. `<=` keeps an equal watermark accepted, so
  -- re-sending the same stamp stays idempotent.
  update public.ledgers l
     set tank_state_liters = liters_value,
         tank_state_as_of = as_of_value,
         tank_state_consumption = consumption_value,
         tank_state_consumption_spread = normalized_spread,
         tank_state_capacity = capacity_value,
         updated_at = now()
   where l.id = target_ledger_id
     and (l.tank_state_as_of is null or l.tank_state_as_of <= as_of_value)
  returning l.tank_state_as_of into saved_as_of;

  if found then
    return jsonb_build_object(
      'ledger_id', target_ledger_id,
      'applied', true,
      'tank_state_liters', liters_value,
      'tank_state_as_of', saved_as_of
    );
  end if;

  -- Nothing was updated, which is two different situations: the workspace does not
  -- exist, or a fresher stamp is already stored. Read it back to tell them apart — the
  -- refusal is a no-op return, not an exception, because a losing race is NORMAL (a
  -- queued offline write flushing late) and the client must be able to ignore it
  -- quietly. Callers read `applied` to tell the two apart.
  select l.tank_state_as_of into saved_as_of
  from public.ledgers l
  where l.id = target_ledger_id;

  if not found then
    raise exception 'Workspace not found' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'ledger_id', target_ledger_id,
    'applied', false,
    'reason', 'stale_as_of',
    'stored_as_of', saved_as_of
  );
end;
$$;

revoke all on function public.set_tank_state(text, numeric, timestamptz, numeric, numeric, numeric) from public;
revoke all on function public.set_tank_state(text, numeric, timestamptz, numeric, numeric, numeric) from anon;
grant execute on function public.set_tank_state(text, numeric, timestamptz, numeric, numeric, numeric) to authenticated;

-- Lease the bookings that need a pre-departure fuel-stop push, newest lease wins for
-- 15 minutes. Due-ness is decided HERE rather than in the caller so the endpoint
-- (GV-406) cannot accidentally relax it, and so the whole predicate is one thing to
-- test.
--
-- A booking is due when ALL of these hold:
--   • it starts within the next 3 hours and has not started yet;
--   • it is neither soft-deleted nor cancelled — car_bookings has no status column, so
--     cancellation IS the soft delete (deleted_at), which is what cancel_booking writes;
--   • its workspace is not itself soft-deleted (migration 132) — a decommissioned car
--     must go quiet, and the RLS-side helpers all check this, but this RPC runs as
--     service_role and would otherwise never see it;
--   • the booked member is still active and reachable by email;
--   • it has never been reminded and carries no live lease;
--   • its fuel_stop is an object with a usable numeric distanceKm;
--   • the car has a complete stamped tank state;
--   • NOTHING has happened to the car since that stamp — see below;
--   • and the verdict over the CURRENT tank state is not 'holds'.
--
-- The staleness gate is the fail-closed rule from fuel-stop-revalidation.ts applied to
-- the stamp itself: if any trip or fuel payment for the car is newer than the stamp's
-- watermark, the client's numbers predate real driving or a real fill-up and we do not
-- know the tank level any more. greatest(created_at, updated_at) rather than created_at
-- alone because an EDIT to an old trip invalidates the stamp exactly as a new row does.
--
-- Tombstones are excluded (GV-411, changed from 154). 154 counted soft-deleted rows on
-- the grounds that a deletion invalidates the stamp too — but the client cannot answer
-- that question. ledger-data-gateway.ts loads trips and fuel payments with
-- `.is('deleted_at', null)` and the watermark is the newest greatest(created_at,
-- updated_at) across the rows it LOADED, so a tombstone — whose updated_at is bumped at
-- deletion — is permanently newer than any watermark the client can send. That made
-- this `not exists` permanently true and killed pre-departure reminders for the whole
-- workspace, silently and indefinitely. The gate now compares against exactly the rows
-- the client sees. The residual is that a deletion no longer marks the stamp stale, so
-- until the next tank-changing write the server may still count a removed trip; that
-- self-heals on the next write and is much milder than permanent silence. See the
-- header for the server-derived-watermark alternative and when it becomes right.
create or replace function public.claim_due_booking_fuel_reminders(
  p_limit integer default 200
)
returns table (
  booking_id uuid,
  ledger_id text,
  member_id uuid,
  member_email text,
  verdict text,
  reserve_km numeric,
  stored_stop_km numeric,
  claim_token uuid
)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
  with target as (
    select cb.id as target_booking_id,
           public.fuel_stop_revalidation_verdict(
             cb.fuel_stop,
             l.tank_state_liters,
             l.tank_state_consumption,
             coalesce(l.tank_state_consumption_spread, 0),
             l.tank_state_capacity,
             -- DEFAULT_REVALIDATION_DEADBAND_KM = 10 in
             -- govehlo-mobile/src/lib/fuel-stop-revalidation.ts. Only flag when the
             -- stored stop is at least this far past the new reserve crossing, so
             -- small between-planning drift does not nag.
             10
           ) as target_verdict
    from public.car_bookings cb
    join public.ledger_members lm
      on lm.id = cb.member_id
     and lm.ledger_id = cb.ledger_id
    join public.ledgers l
      on l.id = cb.ledger_id
    where cb.deleted_at is null
      and l.deleted_at is null
      and cb.start_at > now()
      and cb.start_at <= now() + interval '3 hours'
      and cb.fuel_reminded_at is null
      and (cb.fuel_reminder_claimed_at is null
           or cb.fuel_reminder_claimed_at <= now() - interval '15 minutes')
      and lm.is_active = true
      and lm.email is not null
      and jsonb_typeof(cb.fuel_stop) = 'object'
      and jsonb_typeof(cb.fuel_stop -> 'distanceKm') = 'number'
      and (cb.fuel_stop ->> 'distanceKm')::numeric > 0
      and l.tank_state_as_of is not null
      and l.tank_state_liters is not null
      and l.tank_state_consumption is not null
      and l.tank_state_capacity is not null
      and not exists (
        select 1
        from public.trips t
        where t.ledger_id = cb.ledger_id
          and t.deleted_at is null
          and greatest(t.created_at, t.updated_at) > l.tank_state_as_of
      )
      and not exists (
        select 1
        from public.fuel_payments fp
        where fp.ledger_id = cb.ledger_id
          and fp.deleted_at is null
          and greatest(fp.created_at, fp.updated_at) > l.tank_state_as_of
      )
      and public.fuel_stop_revalidation_verdict(
            cb.fuel_stop,
            l.tank_state_liters,
            l.tank_state_consumption,
            coalesce(l.tank_state_consumption_spread, 0),
            l.tank_state_capacity,
            10
          ) ->> 'verdict' <> 'holds'
    order by cb.start_at
    limit greatest(coalesce(p_limit, 200), 0)
    for update of cb skip locked
  ),
  claimed as (
    update public.car_bookings cb
    set fuel_reminder_claimed_at = now(),
        fuel_reminder_claim_token = gen_random_uuid(),
        updated_at = now()
    from target t
    where cb.id = t.target_booking_id
    returning cb.id as booking_id,
              cb.ledger_id as ledger_id,
              cb.member_id as member_id,
              cb.fuel_reminder_claim_token as claim_token,
              t.target_verdict as target_verdict
  )
  select c.booking_id,
         c.ledger_id,
         c.member_id,
         lower(lm.email) as member_email,
         c.target_verdict ->> 'verdict' as verdict,
         case when jsonb_typeof(c.target_verdict -> 'reserveKm') = 'number'
              then (c.target_verdict ->> 'reserveKm')::numeric end as reserve_km,
         case when jsonb_typeof(c.target_verdict -> 'storedStopKm') = 'number'
              then (c.target_verdict ->> 'storedStopKm')::numeric end as stored_stop_km,
         c.claim_token
  from claimed c
  join public.ledger_members lm
    on lm.id = c.member_id
   and lm.ledger_id = c.ledger_id;
end;
$$;

revoke all on function public.claim_due_booking_fuel_reminders(integer) from public;
revoke all on function public.claim_due_booking_fuel_reminders(integer) from anon;
revoke all on function public.claim_due_booking_fuel_reminders(integer) from authenticated;
grant execute on function public.claim_due_booking_fuel_reminders(integer) to service_role;

insert into public.fuel_ledger_schema_migrations (migration_id, description)
values (
  '155_tank_state_atomicity_and_tombstones',
  'GV-411: three fixes to migration 154 (GV-405), which stays untouched because it is already applied in production. (A) set_tank_state is now atomic: 154 enforced its monotonic watermark with a separate select, compare and update, and a plain select takes no row lock — two devices could both pass the check and the OLDER calculation could commit last, moving the tank level backwards, which is precisely what the data watermark exists to prevent. The condition now rides on a single conditional update, so a loser blocked on the winner''s row lock re-evaluates it against the committed row under READ COMMITTED and matches nothing. The return contract is unchanged (applied / stale_as_of / stored_as_of, read by govehlo-mobile per GVM-480) and an equal watermark is still accepted and idempotent. (B) claim_due_booking_fuel_reminders''s freshness gate now ignores soft-deleted trips and fuel payments. 154 counted them deliberately, but the client loads both tables with deleted_at is null and derives its watermark from the rows it loaded, so a tombstone''s bumped updated_at is permanently newer than any watermark the client can produce — the not-exists stayed true forever and pre-departure reminders died silently for that workspace. The gate now asks exactly the question the client can answer; the residual is that a deletion no longer marks the stamp stale, which self-heals on the next tank-changing write. (C) set_tank_state now bounds its client-supplied numbers: litres must not exceed capacity, capacity must be 500 L or less, consumption must be 100 L/100 km or less, and consumption + spread (safeConsumption, the burn the verdict actually plans on) must also be 100 or less. The envelope is migration 125''s update_ledger_fuel_settings range on the very settings columns these numbers derive from, only the upper half, so no honest client output and no pre-125 legacy setting is newly refused; rejections raise like every other validation rather than clamping silently.'
)
on conflict (migration_id) do update
set description = excluded.description,
    applied_at = now();

-- Migration 156: a server-derived tank model revision replaces the client-chosen watermark (GV-415)
--
-- Migrations 154 and 155 are ALREADY APPLIED in production, so both are left untouched
-- and everything here is re-declared off 155's definitions — the newest prior ones.
--
-- ── What was wrong ──────────────────────────────────────────────────────────────
-- The stamped tank state (migration 154) carries a freshness proof the CLIENT chooses:
-- `as_of`, the newest greatest(created_at, updated_at) across the trips and fuel rows it
-- loaded. Migration 155 documented two residuals of that design and an external review
-- then found exactly the same two independently (GV-415, findings 3 and 4):
--
--   1. An EQUAL watermark could overwrite with DIFFERENT numbers. 155's condition is
--      `tank_state_as_of <= as_of_value`, and `<=` is deliberate — a re-sent write from
--      the offline outbox must stay idempotent. But it also lets a second device, an
--      older app version or a hand-rolled client send its own plausible result under the
--      same watermark, and the last writer wins. The contract test covered "same data in,
--      same numbers out"; it did not cover "same watermark, different numbers".
--
--   2. The watermark only covers trips and fuel_payments. Changing the car's consumption
--      or tank capacity (update_ledger_fuel_settings, migration 125) or its tank baseline
--      (set_tank_baseline, migration 092) changes what the model computes but moves NO
--      watermark, so an old and a new basis share one.
--
--   3. A deletion does not invalidate the stamp. 155 made the freshness gate ignore
--      tombstones because a tombstone is permanently newer than any watermark the client
--      can produce (ledger-data-gateway.ts loads both tables with `deleted_at is null`),
--      which had killed pre-departure reminders outright. The honest cost, written into
--      155 line ~44: between an admin correction and the next tank-changing write the
--      server may still be counting a trip that has been removed.
--
-- All three are the same defect wearing three hats: the freshness proof is derived from
-- what the CLIENT can see, and the client cannot see settings, baselines or tombstones.
--
-- ── What replaces it: ledgers.tank_model_revision ───────────────────────────────
-- A plain counter on the workspace, bumped by every write path that changes an input of
-- the tank model, and a second column recording which revision the stored stamp was
-- computed from:
--
--   tank_model_revision  — the server's count of model-input changes. Never decreases.
--   tank_state_revision  — the revision the stored stamp belongs to.
--
-- The freshness gate is then an equality (`tank_state_revision = tank_model_revision`)
-- rather than a timestamp comparison, and finding 3 stops being a special case: the
-- delete path bumps the counter like every other write, so a tombstone marks the stamp
-- stale as a CONSEQUENCE of the general rule rather than as an exception to it.
--
-- A counter rather than a digest, deliberately. A digest over the model inputs would be
-- self-verifying — the client could prove its basis matched — but it must be recomputed
-- over every trip and fuel row on each read, it is exactly as strong as the columns
-- someone remembered to hash, and it cannot be compared for ORDER, which is what tells a
-- late offline flush from a fresh write. A counter is O(1), monotonic, orderable, and its
-- coverage is a list of triggers a reviewer can read.
--
-- ── Where the bump lives: TRIGGERS, not the RPCs ────────────────────────────────
-- Explicit bumps inside each write RPC would miss the writes that do not go through one,
-- and the most important invalidating write in the system is exactly that:
-- govehlo-web/functions/api/owner/workspace/[id]/soft-delete.js PATCHes `deleted_at`
-- straight onto trips and fuel_payments with the service role. That admin correction is
-- the very scenario finding 3 is about. Triggers also cover any future RPC for free,
-- which is the failure mode this repo keeps hitting from the other side (a write path
-- that forgets to log a ledger_event does not push to other members, migration 087).
--
-- The trips/fuel_payments triggers are STATEMENT-level with transition tables, so the
-- set-based soft-delete above costs one bump for the whole PATCH rather than one per row.
--
-- Which UPDATEs count is decided by comparing the two transition rows as jsonb minus an
-- EXCLUDE list, not by a column list on the trigger — partly because Postgres refuses to
-- combine a column list with transition tables at all, but mostly because the exclude list
-- is the safe direction. An include list ("bump for start_km, end_km, trip_date…") fails
-- OPEN: add a column the model reads and forget to list it, and stamps silently stop being
-- invalidated with nothing to notice. An exclude list fails CLOSED — an unlisted column
-- invalidates a stamp that maybe did not need invalidating, and the client re-stamps.
--
-- Two columns are excluded, both pure bookkeeping the tank model cannot see:
--   • period_id — promote_settlement_carryover_on_open (migration 140) re-points it across
--     a whole queued period on every period open. Bumping there would invalidate the stamp
--     for a change that alters no number, and the client would NOT re-stamp for it: its
--     recomputed payload is byte-identical and the mobile service dedupes on the payload,
--     so the reminders would simply stay off.
--   • updated_at — a touch that carries no other change is not a change.
--
-- The ledgers trigger is BEFORE UPDATE on the row itself and only bumps when a model
-- input genuinely changed (`is distinct from`), so a no-op settings save or a re-recorded
-- identical baseline does not invalidate anything.
--
-- SECURITY DEFINER on the statement trigger is load-bearing, not decoration: migration
-- 125 revoked UPDATE on public.ledgers from authenticated, and RLS would filter the bump
-- to zero rows without an error. A silent no-op there would leave the counter frozen and
-- every stamp permanently "fresh" — the whole mechanism dead with nothing failing.
--
-- ── The write path, and how the mobile client keeps working ─────────────────────
-- set_tank_state gains a SEVENTH parameter, `expected_model_revision`: the revision the
-- client read BEFORE computing, sent back with the result. The server applies the stamp
-- only if the workspace is still at that revision, and within one revision only the FIRST
-- stamp wins — a second one carrying different numbers is refused rather than allowed to
-- overwrite (finding 1). An identical re-send stays a quiet success, so the offline
-- outbox is unaffected.
--
-- The six-argument signature STAYS, as an overload, and keeps its own body. govehlo-mobile
-- (GVM-480: src/lib/tank-state-stamp.ts, src/store/ledger-tank-state-service.ts) calls it
-- with six named arguments today and must keep working unchanged until the mobile
-- follow-up ships; PostgREST resolves an RPC by the set of argument NAMES in the body, so
-- six named arguments reach the legacy overload and seven reach the new one, with no
-- ambiguity (the seventh parameter deliberately has NO default — a default would make the
-- six-argument call ambiguous and every existing stamp would start failing).
--
-- The legacy overload is not merely tolerated, it is HARDENED:
--   • it gets finding 1's fix in full — an equal watermark now only applies when the
--     numbers are identical, and differing numbers under the same watermark are refused;
--   • it records tank_state_revision = the workspace's revision at write time, so
--     findings 2 and 3 are fixed for it too, for every bump that happens AFTER its write.
--
-- What it cannot have is the read-compute-write window: a bump landing between the
-- client's read and its write is credited to the stamp. That is why 155's `as_of` gate is
-- KEPT ALONGSIDE the revision gate in claim_due_booking_fuel_reminders rather than
-- replaced by it — for a six-argument caller the as_of comparison is the only thing that
-- still catches a trip or fuel row written inside that window, and dropping it would have
-- made this migration a regression for the only client that exists today. The two gates
-- are complementary: as_of catches what the client could see, the revision catches what
-- it could not.
--
-- Delegating the legacy overload to the new one was considered and rejected: the wrapper
-- would have to read the current revision and pass it, which is precisely the "credit the
-- client with a revision it never saw" move — a device flushing a stale offline write
-- would then have its numbers accepted as fresh, which 155's as_of check refuses today.
--
-- The transition is expand/contract. 156 expands; the mobile follow-up reads
-- ledgers.tank_model_revision, sends it as expected_model_revision, and includes it in
-- tankStampKey's dedupe identity; a later migration contracts by retiring the six-argument
-- overload (migration 147's pattern). Until that lands, one narrow residual exists and is
-- stated rather than hidden: if a soft delete changes the modelled numbers not at all, the
-- mobile service's payload dedupe suppresses the re-stamp, tank_state_revision stays
-- behind and that workspace's pre-departure reminders go quiet until the next real change
-- or the next cold start. That is fail-CLOSED (no nudge) where 155 was fail-open (a nudge
-- computed on a deleted trip), and it disappears entirely once the revision is part of the
-- dedupe key.

-- ── Columns ─────────────────────────────────────────────────────────────────────

alter table public.ledgers
  add column if not exists tank_model_revision bigint not null default 0;

alter table public.ledgers
  add column if not exists tank_state_revision bigint;

comment on column public.ledgers.tank_model_revision is
  'Server-derived revision of the tank model INPUTS: bumped by every write that changes a trip, a fuel payment, the car''s consumption/capacity settings or its tank baseline, including soft deletes and including writes that never touch an RPC (the admin console PATCHes deleted_at directly). Monotonic, never reset. Replaces the client-chosen ledgers.tank_state_as_of watermark as the authoritative freshness proof (GV-415): the client cannot see settings changes, baseline changes or tombstones, so a proof derived from the rows it loaded can never cover them.';

comment on column public.ledgers.tank_state_revision is
  'The tank_model_revision the stored stamp (tank_state_liters and friends) was computed from. The stamp is FRESH exactly while this equals tank_model_revision. Written by set_tank_state: from the client''s own expected_model_revision on the seven-argument signature, or — on the legacy six-argument overload govehlo-mobile still calls — from the workspace''s revision at write time, which cannot account for a bump landing between the client''s read and its write. NULL means a stamp older than migration 156 that was never re-written; migration 156 backfills 0 for the stamps that existed when it ran, so they stay fresh until the first real model change.';

comment on column public.ledgers.tank_state_as_of is
  'Data watermark of the stamped tank state: the newest greatest(created_at, updated_at) across the trips and fuel_payments the client consumed when it computed tank_state_liters. NOT a wall-clock write time. Since GV-415 this is the SECONDARY freshness proof — tank_state_revision is the primary one — and it is kept because it is the only thing that catches a trip or fuel row written between a legacy six-argument caller''s read and its write, a window the server-side revision stamp cannot see. It also still orders two legacy stamps: a client that has seen less data carries an older watermark and cannot overwrite a fresher one.';

-- Every stamp that exists when this migration runs was computed against revision 0 by
-- definition — nothing has bumped the counter yet. Without this backfill the new gate
-- would read every stored stamp as stale the moment 156 is applied and pre-departure
-- reminders would stop for every workspace until each one's app was next opened.
update public.ledgers l
   set tank_state_revision = 0
 where l.tank_state_as_of is not null
   and l.tank_state_revision is null;

-- ── The bump ────────────────────────────────────────────────────────────────────

-- Statement-level, with transition tables, so one PATCH over a whole workspace costs one
-- bump. TG_OP branches because a transition table only exists for the operation its
-- trigger was declared for: PL/pgSQL prepares each SQL statement on first execution of
-- the branch containing it, so the `old_rows` branch is never planned in an INSERT
-- trigger. All three paths are exercised by tools/test-fuel-stop-verdict-contract.mjs
-- (insert, soft delete, hard delete) precisely because that is a property of when
-- statements are planned rather than of the code being read.
--
-- The UPDATE branch is table-agnostic on purpose: trips and fuel_payments share this one
-- function, so the change test is a whole-row jsonb comparison minus the bookkeeping keys
-- rather than a per-table column list. `values (n.ledger_id), (o.ledger_id)` bumps BOTH
-- workspaces when a row moves between them, which is the only way for one statement to
-- change two models at once.
create or replace function public.bump_tank_model_revision()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    update public.ledgers l
       set tank_model_revision = l.tank_model_revision + 1
     where l.id in (select r.ledger_id from new_rows r);
  elsif tg_op = 'DELETE' then
    update public.ledgers l
       set tank_model_revision = l.tank_model_revision + 1
     where l.id in (select r.ledger_id from old_rows r);
  else
    update public.ledgers l
       set tank_model_revision = l.tank_model_revision + 1
     where l.id in (
       select touched.ledger_id
       from new_rows n
       join old_rows o on o.id = n.id
       cross join lateral (values (n.ledger_id), (o.ledger_id)) as touched(ledger_id)
       where (to_jsonb(n) - 'updated_at' - 'period_id')
             is distinct from (to_jsonb(o) - 'updated_at' - 'period_id')
     );
  end if;
  return null;
end;
$$;

revoke all on function public.bump_tank_model_revision() from public;
revoke all on function public.bump_tank_model_revision() from anon;
revoke all on function public.bump_tank_model_revision() from authenticated;

-- Six triggers rather than two: transition tables may only be declared for a trigger with
-- a SINGLE event, so insert, update and delete each need their own.
drop trigger if exists bump_tank_model_revision_trips_insert on public.trips;
create trigger bump_tank_model_revision_trips_insert
after insert on public.trips
referencing new table as new_rows
for each statement execute function public.bump_tank_model_revision();

drop trigger if exists bump_tank_model_revision_trips_update on public.trips;
create trigger bump_tank_model_revision_trips_update
after update on public.trips
referencing old table as old_rows new table as new_rows
for each statement execute function public.bump_tank_model_revision();

drop trigger if exists bump_tank_model_revision_trips_delete on public.trips;
create trigger bump_tank_model_revision_trips_delete
after delete on public.trips
referencing old table as old_rows
for each statement execute function public.bump_tank_model_revision();

drop trigger if exists bump_tank_model_revision_fuel_insert on public.fuel_payments;
create trigger bump_tank_model_revision_fuel_insert
after insert on public.fuel_payments
referencing new table as new_rows
for each statement execute function public.bump_tank_model_revision();

drop trigger if exists bump_tank_model_revision_fuel_update on public.fuel_payments;
